select public.admin_save_lesson($lumi${"id":"mat-sistema-decimal","subject":"matematica","title":"Sistema de numeração decimal","levels":["fund1"],"grade":"1º ao 3º ano","topic":"Números","subtopic":"Valor posicional","aliases":["sistema decimal","unidade dezena centena","valor posicional","valor do algarismo","ordens e classes","milhar","decompor numero","numeros naturais"],"summary":"Entenda unidades, dezenas, centenas e milhares e por que o lugar de cada algarismo muda o seu valor.","intro":"Com apenas dez algarismos (0 a 9) escrevemos qualquer número. O segredo está no lugar de cada um!","objective":"Ler, escrever e decompor números, identificando o valor de cada algarismo pela sua posição.","next":["mat-adicao-subtracao"],"skills":{"agrupamento":"Agrupar de 10 em 10","posicao":"Valor posicional","decomposicao":"Decompor números","leitura":"Ler e escrever números"},"blocks":[{"skill":"agrupamento","title":"Grupos de 10","text":"No nosso sistema, contamos em grupos de 10: 10 unidades formam 1 dezena, 10 dezenas formam 1 centena e 10 centenas formam 1 milhar.","example":"Com 23 palitos você faz 2 montinhos de 10 (2 dezenas) e sobram 3 palitos soltos (3 unidades).","variants":{"simples":"Junte de 10 em 10. Cada montinho de 10 é uma dezena.","exemplo":"Pense em ovos: uma caixa com 10 ovos é uma dezena de ovos. Dez caixas cheias são 100 ovos: uma centena.","passos":"1. Conte os objetos.\n2. Faça grupos de 10 — cada grupo é 1 dezena.\n3. Se juntar 10 grupos de 10, você tem 1 centena.\n4. O que sobrar sem grupo são as unidades."},"id":"b1"},{"skill":"posicao","title":"O lugar muda o valor","text":"O valor de um algarismo depende da posição que ele ocupa. Da direita para a esquerda: unidades, dezenas, centenas, milhares.","example":"Em 352, o 3 vale 300 (3 centenas), o 5 vale 50 (5 dezenas) e o 2 vale 2 unidades.","variants":{"simples":"O mesmo número vale mais quando está mais para a esquerda. O 3 de 352 vale 300!","exemplo":"Em 44, os dois algarismos são iguais, mas o da esquerda vale 40 e o da direita vale 4.","passos":"1. Olhe o algarismo da direita: são as unidades.\n2. O do meio: dezenas (vale 10 vezes mais).\n3. O da esquerda: centenas (vale 100 vezes mais).\n4. Multiplique o algarismo pelo valor da casa."},"id":"b2"},{"skill":"decomposicao","title":"Decompor números","text":"Decompor é separar o número em partes pelo valor de cada algarismo. Assim fica fácil ver quanto cada um vale.","example":"4.726 = 4.000 + 700 + 20 + 6.","variants":{"simples":"Decompor é \"abrir\" o número: 58 = 50 + 8.","exemplo":"Se você tem 1 nota de R$ 100, 2 notas de R$ 10 e 5 moedas de R$ 1, tem 100 + 20 + 5 = R$ 125.","passos":"1. Separe cada algarismo.\n2. Escreva quanto ele vale pela posição.\n3. Some tudo com o sinal +.\n4. Confira: a soma tem que dar o número original."},"id":"b3"},{"skill":"leitura","title":"Ler e escrever números","text":"Para ler um número grande, separamos em grupos de três algarismos a partir da direita (classes). Lemos cada grupo e dizemos o nome da classe: mil, milhão…","example":"12.305 lê-se \"doze mil, trezentos e cinco\". O zero indica que não há dezenas.","variants":{"simples":"O ponto separa os milhares: 3.200 é \"três mil e duzentos\".","exemplo":"No preço de uma bicicleta, R$ 1.250, lemos \"mil duzentos e cinquenta reais\".","passos":"1. Separe de três em três algarismos, da direita para a esquerda.\n2. Leia o grupo da esquerda e diga \"mil\".\n3. Leia o grupo da direita.\n4. Se aparecer zero, é porque aquela casa está vazia."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"agrupamento","prompt":"Quantas unidades formam 1 dezena?","options":["5","10","100","12"],"answer":1,"hints":["Pense em grupos.","Uma dezena é um grupo de…","Dezena lembra \"dez\"."],"explanation":"1 dezena = 10 unidades.","id":"q1"},{"type":"mc","difficulty":1,"skill":"posicao","prompt":"No número 352, quanto vale o algarismo 5?","options":["5","50","500","35"],"answer":1,"hints":["Em que posição está o 5?","Ele está na casa das dezenas.","5 dezenas = 5 × 10."],"explanation":"O 5 está nas dezenas: vale 50.","id":"q2"},{"type":"tf","difficulty":1,"skill":"agrupamento","prompt":"10 dezenas formam 1 centena.","answer":true,"hints":["Quanto é 10 grupos de 10?","10 × 10.","= 100."],"explanation":"Verdadeiro: 10 dezenas = 100 unidades = 1 centena.","id":"q3"},{"type":"fill","difficulty":1,"skill":"decomposicao","prompt":"Complete: 58 = 50 + ____","answers":["8"],"hints":["Separe dezenas e unidades.","58 tem 5 dezenas e algumas unidades.","Quantas unidades sobram depois do 50?"],"explanation":"58 = 50 + 8.","id":"q4"},{"type":"mc","difficulty":2,"skill":"decomposicao","prompt":"Qual é a decomposição de 4.726?","options":["4 + 7 + 2 + 6","4.000 + 700 + 20 + 6","400 + 70 + 26","4.000 + 726 + 6"],"answer":1,"hints":["Cada algarismo vale conforme a posição.","O 4 está nos milhares.","Escreva quanto vale cada algarismo."],"explanation":"4.726 = 4.000 + 700 + 20 + 6.","id":"q5"},{"type":"match","difficulty":2,"skill":"posicao","prompt":"No número 2.839, ligue cada algarismo ao seu valor.","pairs":[["2","2.000"],["8","800"],["3","30"],["9","9"]],"hints":["Comece pela direita: unidades.","Depois dezenas e centenas.","O da esquerda está nos milhares."],"explanation":"2 → 2.000 · 8 → 800 · 3 → 30 · 9 → 9.","id":"q6"},{"type":"mc","difficulty":2,"skill":"leitura","prompt":"Como se lê 12.305?","options":["Doze mil, trezentos e cinco","Mil duzentos e trinta e cinco","Doze mil, trinta e cinco","Cento e vinte e três mil e cinco"],"answer":0,"hints":["Separe: 12 | 305.","O 12 é da classe dos milhares.","Depois leia 305."],"explanation":"12.305 = doze mil, trezentos e cinco.","id":"q7"},{"type":"fill","difficulty":2,"skill":"leitura","prompt":"Escreva com algarismos: \"três mil e quarenta\".","answers":["3040","3.040"],"hints":["São 3 milhares.","Não há centenas.","Há 4 dezenas e nenhuma unidade."],"explanation":"3.040: o zero ocupa a casa das centenas e a das unidades.","id":"q8"},{"type":"order","difficulty":2,"skill":"posicao","prompt":"Coloque os números do MENOR para o MAIOR.","items":["209","290","902","920"],"hints":["Compare primeiro as centenas.","Com centenas iguais, compare as dezenas.","2 centenas é menos que 9 centenas."],"explanation":"209 < 290 < 902 < 920.","id":"q9"},{"type":"tf","difficulty":3,"skill":"posicao","prompt":"Em 505, os dois algarismos 5 valem a mesma coisa.","answer":false,"hints":["Veja a posição de cada 5.","Um está nas centenas e outro nas unidades.","500 é igual a 5?"],"explanation":"Falso: o da esquerda vale 500 e o da direita vale 5.","id":"q10"},{"type":"mc","difficulty":3,"skill":"agrupamento","prompt":"Ana tem 3 caixas com 10 lápis e 7 lápis soltos. Quantos lápis ela tem?","options":["10","37","307","73"],"answer":1,"hints":["Cada caixa é uma dezena.","3 dezenas = 30.","Some os soltos."],"explanation":"3 dezenas + 7 unidades = 37 lápis.","id":"q11"},{"type":"open","difficulty":3,"skill":"posicao","prompt":"Explique por que o 7 em 70 vale mais do que o 7 em 17.","modelAnswer":"Porque no 70 o 7 está na casa das dezenas e vale 70, enquanto no 17 ele está na casa das unidades e vale apenas 7.","keywords":["dezena","unidade","posicao","lugar","casa"],"hints":["Onde está o 7 em cada número?","Um está nas dezenas, outro nas unidades.","Fale da posição (casa) do algarismo."],"explanation":"O valor depende da posição: dezenas valem 10 vezes mais que unidades.","id":"q12"}],"review":["10 unidades = 1 dezena · 10 dezenas = 1 centena · 10 centenas = 1 milhar","O valor do algarismo depende da posição","Decompor: 352 = 300 + 50 + 2","Leia separando de três em três algarismos"],"relatedQuestions":["O que é unidade, dezena e centena?","Como decompor um número?","O que é valor posicional?"],"equivalentQuestions":["o que é dezena","quanto vale uma centena","quantas dezenas tem uma centena","como saber o valor de um algarismo","por que o número muda de valor","como decompor 352","o que significa decompor um número","como escrever número por extenso","como ler números grandes","o que é milhar","quantas unidades tem um milhar","como separar unidade dezena e centena","o que é ordem e classe dos números","para que serve o ponto no número 1.000","como saber qual número é maior","me explica sistema decimal","por que contamos de 10 em 10","o que é algarismo","qual a diferença entre número e algarismo","como montar número com unidades e dezenas","o zero vale alguma coisa no número","como fazer quadro de ordens"],"commonDoubts":[{"q":"Qual a diferença entre número e algarismo?","a":"Algarismos são os símbolos 0 a 9. Números são formados por algarismos: 352 é um número com três algarismos."},{"q":"Se o zero não vale nada, por que escrevê-lo?","a":"O zero marca que aquela casa está vazia. Sem ele, 305 viraria 35 — outro número!"}],"commonErrors":["Achar que um algarismo vale sempre o mesmo, em qualquer posição","Esquecer o zero ao escrever números como 3.040","Ler da esquerda para a direita sem separar as classes"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática — Anos Iniciais","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Portal da Matemática OBMEP — videoaulas e materiais do Ensino Fundamental e Médio","url":"https://portaldaobmep.impa.br/","author":"IMPA / OBMEP","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"mat-adicao-subtracao","subject":"matematica","title":"Adição e subtração","levels":["fund1"],"grade":"1º ao 4º ano","topic":"Operações","subtopic":"Adição e subtração","aliases":["adicao","subtracao","soma","somar","conta de mais","conta de menos","subtrair","emprestar na subtracao","vai um","reserva","troco"],"summary":"Aprenda a somar e subtrair, inclusive com \"vai um\" e \"empresta\", e a usar essas contas no dia a dia.","intro":"Somar é juntar. Subtrair é tirar ou comparar. Vamos ver como fazer as duas contas sem errar.","objective":"Resolver adições e subtrações com e sem reagrupamento e aplicá-las em problemas.","prerequisites":["mat-sistema-decimal"],"next":["mat-multiplicacao"],"skills":{"adicao":"Adição","reagrupar":"Vai um e empréstimo","subtracao":"Subtração","problemas":"Problemas com adição e subtração"},"blocks":[{"skill":"adicao","title":"Somar é juntar","text":"Na adição juntamos quantidades. Os números somados são as parcelas e o resultado é a soma (ou total). A ordem das parcelas não muda a soma.","example":"12 + 5 = 17: 12 figurinhas mais 5 figurinhas dão 17.","variants":{"simples":"Somar é juntar tudo e contar quanto ficou.","exemplo":"Você tem 8 balas e ganha 4. Agora tem 8 + 4 = 12 balas.","passos":"1. Escreva os números um embaixo do outro, unidade embaixo de unidade.\n2. Some a coluna das unidades.\n3. Some a coluna das dezenas.\n4. Escreva o resultado."},"id":"b1"},{"skill":"reagrupar","title":"Vai um e empresta","text":"Quando a soma de uma coluna passa de 9, trocamos 10 unidades por 1 dezena (\"vai um\"). Na subtração, se não dá para tirar, pegamos 1 dezena emprestada, que vira 10 unidades.","example":"48 + 35: 8 + 5 = 13 → escreve 3, vai 1. Depois 4 + 3 + 1 = 8. Resultado: 83.","variants":{"simples":"Passou de 9? Fica o número da direita e o 1 \"vai\" para a próxima coluna.","exemplo":"É como trocar 10 moedas de R$ 1 por uma nota de R$ 10: a quantidade de dinheiro é a mesma.","passos":"1. Some (ou subtraia) as unidades.\n2. Se na soma deu 10 ou mais, escreva só as unidades e leve 1 para as dezenas.\n3. Na subtração, se o de cima é menor, pegue 1 dezena emprestada: ela vale 10 unidades.\n4. Continue nas dezenas lembrando do que foi levado ou emprestado."},"id":"b2"},{"skill":"subtracao","title":"Subtrair é tirar ou comparar","text":"Na subtração tiramos uma quantidade de outra ou descobrimos a diferença entre elas. O resultado se chama diferença (ou resto). Para conferir, somamos o resultado com o número tirado.","example":"52 − 17 = 35. Conferindo: 35 + 17 = 52 ✓.","variants":{"simples":"Subtrair é tirar e ver quanto sobra.","exemplo":"Tinha R$ 20 e gastei R$ 13. Sobraram 20 − 13 = R$ 7 de troco.","passos":"1. Coloque o maior número em cima.\n2. Subtraia as unidades (empreste se precisar).\n3. Subtraia as dezenas.\n4. Confira somando o resultado com o número de baixo."},"id":"b3"},{"skill":"problemas","title":"Qual conta usar?","text":"Palavras como \"juntar\", \"ganhar\", \"total\" indicam adição. \"Tirar\", \"gastar\", \"sobrou\", \"quanto falta\", \"diferença\" indicam subtração.","example":"Pedro tem 15 anos e a irmã tem 9. A diferença de idade é 15 − 9 = 6 anos.","variants":{"simples":"Juntou? É mais. Tirou ou quer saber quanto falta? É menos.","exemplo":"No supermercado: somamos os preços para saber o total e subtraímos do dinheiro para saber o troco.","passos":"1. Leia o problema com calma.\n2. Descubra o que ele pergunta.\n3. Veja se a situação é de juntar (mais) ou tirar/comparar (menos).\n4. Faça a conta e responda com a unidade (balas, reais…)."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"adicao","prompt":"Quanto é 12 + 5?","options":["7","17","15","125"],"answer":1,"hints":["Comece pelo 12.","Conte mais 5.","13, 14, 15, 16…"],"explanation":"12 + 5 = 17.","id":"q1"},{"type":"fill","difficulty":1,"skill":"subtracao","prompt":"Quanto é 20 − 13?","answers":["7"],"hints":["Pense no troco de 20.","Quanto falta de 13 para 20?","13 + ? = 20."],"explanation":"20 − 13 = 7, porque 13 + 7 = 20.","id":"q2"},{"type":"tf","difficulty":1,"skill":"adicao","prompt":"3 + 8 dá o mesmo resultado que 8 + 3.","answer":true,"hints":["A ordem muda a soma?","Faça as duas contas.","As duas dão 11."],"explanation":"Verdadeiro: a ordem das parcelas não altera a soma.","id":"q3"},{"type":"mc","difficulty":2,"skill":"reagrupar","prompt":"Quanto é 48 + 35?","options":["73","83","713","82"],"answer":1,"hints":["8 + 5 passa de 9.","8 + 5 = 13: escreve 3 e vai 1.","4 + 3 + 1 = ?"],"explanation":"8 + 5 = 13 (vai 1); 4 + 3 + 1 = 8. Total 83.","id":"q4"},{"type":"mc","difficulty":2,"skill":"reagrupar","prompt":"Quanto é 52 − 17?","options":["45","35","25","39"],"answer":1,"hints":["2 − 7 não dá: precisa emprestar.","12 − 7 = 5.","Nas dezenas: 4 − 1."],"explanation":"12 − 7 = 5; 4 − 1 = 3. Resultado 35.","id":"q5"},{"type":"fill","difficulty":2,"skill":"subtracao","prompt":"Para conferir 52 − 17 = 35, somamos 35 + 17. O resultado deve ser ____.","answers":["52"],"hints":["A conta de conferir desfaz a subtração.","Some 35 e 17.","Deve voltar ao número inicial."],"explanation":"35 + 17 = 52: a conta está certa.","id":"q6"},{"type":"match","difficulty":2,"skill":"problemas","prompt":"Ligue cada situação à conta certa.","pairs":[["Ganhei mais figurinhas","Adição"],["Gastei parte do dinheiro","Subtração"],["Quanto falta para chegar a 100?","Subtração (quanto falta)"],["Qual o total de alunos das duas turmas?","Adição (total)"]],"hints":["Ganhar e total: juntar.","Gastar: tirar.","Quanto falta: diferença."],"explanation":"Juntar/total → adição · tirar/quanto falta → subtração.","id":"q7"},{"type":"mc","difficulty":2,"skill":"problemas","prompt":"Pedro tem 15 anos e a irmã tem 9. Qual é a diferença de idade?","options":["24 anos","6 anos","5 anos","9 anos"],"answer":1,"hints":["Diferença indica qual conta?","Subtração.","15 − 9."],"explanation":"15 − 9 = 6 anos.","id":"q8"},{"type":"fill","difficulty":3,"skill":"reagrupar","prompt":"Quanto é 305 − 128?","answers":["177"],"hints":["5 − 8 não dá: empreste das dezenas.","As dezenas estão zeradas: empreste das centenas.","305 = 2 centenas + 9 dezenas + 15 unidades."],"explanation":"15 − 8 = 7; 9 − 2 = 7; 2 − 1 = 1 → 177. Confira: 177 + 128 = 305.","id":"q9"},{"type":"mc","difficulty":3,"skill":"problemas","prompt":"Uma escola tem 238 alunos de manhã e 175 à tarde. Quantos alunos tem ao todo?","options":["413","313","403","63"],"answer":0,"hints":["\"Ao todo\" pede adição.","8 + 5 = 13, vai 1.","3 + 7 + 1 = 11, vai 1; 2 + 1 + 1 = 4."],"explanation":"238 + 175 = 413 alunos.","id":"q10"},{"type":"tf","difficulty":3,"skill":"subtracao","prompt":"Na subtração, a ordem dos números não importa: 9 − 4 é igual a 4 − 9.","answer":false,"hints":["Tente tirar 9 de 4 com objetos.","Não dá para tirar 9 de 4 em números naturais.","Na subtração a ordem importa."],"explanation":"Falso: 9 − 4 = 5, mas 4 − 9 não é 5. Na subtração a ordem importa.","id":"q11"},{"type":"open","difficulty":3,"skill":"problemas","prompt":"Invente um problema de subtração sobre troco e resolva.","modelAnswer":"Exemplo: comprei um lanche de R$ 13 e paguei com R$ 20. O troco é 20 − 13 = R$ 7.","keywords":["troco","paguei","custa","sobrou","menos","reais"],"hints":["Pense numa compra.","Quanto custou e quanto você pagou?","O troco é a diferença."],"explanation":"Troco = valor pago − preço.","id":"q12"}],"review":["Adição junta: parcelas → soma","Passou de 9 na coluna: \"vai um\"","Subtração tira ou compara; empreste quando precisar","Confira a subtração somando"],"relatedQuestions":["Como fazer conta de mais com vai um?","Como fazer conta de menos emprestando?","Como saber se é conta de mais ou de menos?"],"equivalentQuestions":["como somar numeros","como fazer conta de mais","o que é vai um","como fazer conta de menos","como subtrair emprestando","por que emprestar na conta de menos","como fazer 52 menos 17","como calcular o troco","como saber quanto falta","o que é diferença na matematica","como conferir uma subtração","o que são parcelas","qual o nome do resultado da soma","como armar a conta de mais","como somar numeros grandes","problema de somar ou subtrair como saber","me explica adição","me explica subtração","nao sei fazer conta de menos","como fazer conta de menos com zero","como calcular o total de duas coisas","soma e subtração exemplo"],"commonDoubts":[{"q":"Por que na conta de menos eu \"empresto\"?","a":"Porque trocamos 1 dezena por 10 unidades. O número continua o mesmo, só está escrito de outra forma para dar para tirar."},{"q":"Como sei se o problema é de mais ou de menos?","a":"Juntar, ganhar, total → mais. Tirar, gastar, sobrar, quanto falta, diferença → menos."}],"commonErrors":["Esquecer de somar o \"vai um\" na coluna seguinte","Tirar o menor do maior dentro da coluna (fazer 7 − 2 em vez de 12 − 7)","Desalinhar unidades e dezenas ao armar a conta"],"formulas":[{"name":"Prova da subtração","expression":"diferença + subtraendo = minuendo","variables":[{"symbol":"minuendo","meaning":"número de onde se tira"},{"symbol":"subtraendo","meaning":"número que se tira"},{"symbol":"diferença","meaning":"resultado"}]}],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática — Anos Iniciais","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Portal da Matemática OBMEP — videoaulas e materiais do Ensino Fundamental e Médio","url":"https://portaldaobmep.impa.br/","author":"IMPA / OBMEP","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"mat-multiplicacao","subject":"matematica","title":"Multiplicação e tabuada","levels":["fund1"],"grade":"2º ao 4º ano","topic":"Operações","subtopic":"Multiplicação","aliases":["multiplicacao","tabuada","vezes","multiplicar","conta de vezes","produto","dobro","triplo"],"summary":"Entenda a multiplicação como soma de parcelas iguais e aprenda truques da tabuada.","intro":"Multiplicar é um jeito rápido de somar números iguais. Vamos descobrir como!","objective":"Compreender a multiplicação como adição de parcelas iguais, usar a tabuada e resolver problemas.","prerequisites":["mat-adicao-subtracao"],"next":["mat-divisao"],"skills":{"conceito":"Multiplicação como soma repetida","tabuada":"Tabuada","propriedades":"Propriedades da multiplicação","problemas":"Problemas com multiplicação"},"blocks":[{"skill":"conceito","title":"Multiplicar é somar parcelas iguais","text":"Quando somamos o mesmo número várias vezes, usamos a multiplicação. 3 × 4 quer dizer \"3 grupos de 4\": 4 + 4 + 4 = 12. Os números multiplicados são os fatores e o resultado é o produto.","example":"Três pacotes com 4 figurinhas cada: 3 × 4 = 12 figurinhas.","variants":{"simples":"Vezes é contar grupos iguais. 2 × 5 são dois grupos de 5 coisas: 10 coisas.","exemplo":"Uma bicicleta tem 2 rodas. 5 bicicletas têm 5 × 2 = 10 rodas.","passos":"1. Descubra quantos grupos existem.\n2. Descubra quantos há em cada grupo.\n3. Multiplique os dois números.\n4. Se quiser conferir, some o grupo tantas vezes quanto indicado."},"id":"b1"},{"skill":"tabuada","title":"Truques da tabuada","text":"Na tabuada do 2, é só dobrar. Na do 10, coloque um zero no fim. Na do 5, os resultados terminam sempre em 0 ou 5. Na do 9, os algarismos do resultado somam 9 (até 9 × 10).","example":"7 × 2 = 14 · 6 × 10 = 60 · 5 × 3 = 15 · 9 × 4 = 36 (3 + 6 = 9).","variants":{"simples":"× 2 é o dobro. × 10 é pôr um zero no fim. × 5 termina em 0 ou 5.","exemplo":"Para saber quantos dedos há em 6 mãos: 6 × 5 = 30.","passos":"1. Veja se o número é 2, 5, 9 ou 10 — use o truque.\n2. Se não souber, troque a ordem (7 × 3 = 3 × 7).\n3. Ou quebre: 7 × 6 = 7 × 5 + 7 = 35 + 7 = 42.\n4. Confira com a soma repetida."},"id":"b2"},{"skill":"propriedades","title":"Regras que ajudam","text":"Trocar a ordem dos fatores não muda o produto: 3 × 4 = 4 × 3. Qualquer número vezes 1 é ele mesmo, e qualquer número vezes 0 é zero.","example":"8 × 1 = 8 · 8 × 0 = 0 · 2 × 9 = 9 × 2 = 18.","variants":{"simples":"3 × 4 e 4 × 3 dão o mesmo: 12. Vezes 1 não muda nada. Vezes 0 dá sempre 0.","exemplo":"3 fileiras de 4 cadeiras ou 4 fileiras de 3: são 12 cadeiras do mesmo jeito.","passos":"1. Se ficar mais fácil, troque a ordem dos fatores.\n2. Viu × 1? O resultado é o próprio número.\n3. Viu × 0? O resultado é 0.\n4. Use isso para conferir contas grandes."},"id":"b3"},{"skill":"problemas","title":"Usando no dia a dia","text":"Para resolver um problema, procure grupos iguais: quantos grupos existem e quantas coisas há em cada grupo. \"Dobro\" é × 2 e \"triplo\" é × 3.","example":"Uma caixa tem 6 ovos. Em 5 caixas há 5 × 6 = 30 ovos.","variants":{"simples":"Pergunte: quantos grupos? Quantos em cada grupo? Depois faça a conta de vezes.","exemplo":"Um ingresso custa R$ 8. Para 4 pessoas: 4 × 8 = R$ 32.","passos":"1. Leia e encontre os grupos iguais.\n2. Anote quantos grupos e quantos por grupo.\n3. Multiplique.\n4. Responda com a unidade (ovos, reais…)."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"conceito","prompt":"4 + 4 + 4 é o mesmo que:","options":["4 × 4","3 × 4","4 + 3","12 × 4"],"answer":1,"hints":["Conte quantas vezes o 4 aparece.","O 4 aparece 3 vezes.","3 grupos de 4."],"explanation":"São 3 parcelas iguais a 4: 3 × 4 = 12.","id":"q1"},{"type":"fill","difficulty":1,"skill":"tabuada","prompt":"Quanto é 7 × 2?","answers":["14"],"hints":["× 2 é o dobro.","Qual é o dobro de 7?","7 + 7."],"explanation":"7 × 2 = 14, o dobro de 7.","id":"q2"},{"type":"mc","difficulty":1,"skill":"tabuada","prompt":"Quanto é 6 × 10?","options":["16","60","600","61"],"answer":1,"hints":["Na tabuada do 10 tem um truque.","Coloque um zero no fim.","6 com um zero."],"explanation":"6 × 10 = 60.","id":"q3"},{"type":"tf","difficulty":1,"skill":"propriedades","prompt":"3 × 5 dá o mesmo resultado que 5 × 3.","answer":true,"hints":["A ordem muda o resultado da multiplicação?","Faça as duas contas.","15 e 15."],"explanation":"Verdadeiro: a ordem dos fatores não altera o produto.","id":"q4"},{"type":"mc","difficulty":2,"skill":"propriedades","prompt":"Quanto é 9 × 0?","options":["9","0","90","1"],"answer":1,"hints":["Pense em 9 grupos com nada dentro.","Quantas coisas há no total?","Nenhuma."],"explanation":"Qualquer número vezes 0 dá 0.","id":"q5"},{"type":"fill","difficulty":2,"skill":"problemas","prompt":"Uma caixa tem 6 ovos. Quantos ovos há em 5 caixas?","answers":["30"],"hints":["Quantos grupos? Quantos em cada?","5 caixas com 6 ovos.","5 × 6."],"explanation":"5 × 6 = 30 ovos.","id":"q6"},{"type":"match","difficulty":2,"skill":"tabuada","prompt":"Ligue cada conta ao resultado.","pairs":[["2 × 8","16"],["5 × 4","20"],["3 × 3","9"],["10 × 7","70"]],"hints":["Comece pela do 10.","5 × 4 termina em 0.","2 × 8 é o dobro de 8."],"explanation":"2 × 8 = 16 · 5 × 4 = 20 · 3 × 3 = 9 · 10 × 7 = 70.","id":"q7"},{"type":"tf","difficulty":2,"skill":"tabuada","prompt":"Todos os resultados da tabuada do 5 terminam em 0 ou 5.","answer":true,"hints":["Teste alguns: 5, 10, 15…","Veja o último algarismo.","Só aparecem 0 e 5."],"explanation":"Verdadeiro: 5, 10, 15, 20, 25…","id":"q8"},{"type":"mc","difficulty":3,"skill":"problemas","prompt":"Uma sala tem 4 fileiras com 7 cadeiras cada. Quantas cadeiras há?","options":["11","28","24","47"],"answer":1,"hints":["São grupos iguais.","4 grupos de 7.","4 × 7."],"explanation":"4 × 7 = 28 cadeiras.","id":"q9"},{"type":"fill","difficulty":3,"skill":"tabuada","prompt":"Quanto é 8 × 7?","answers":["56"],"hints":["Pense em 7 × 8.","7 × 7 = 49.","49 + 7."],"explanation":"8 × 7 = 56.","id":"q10"},{"type":"mc","difficulty":3,"skill":"problemas","prompt":"Ana tem 6 anos. Seu pai tem o quíntuplo da idade dela. Quantos anos tem o pai?","options":["11","30","36","25"],"answer":1,"hints":["Quíntuplo = 5 vezes.","Multiplique a idade de Ana por 5.","6 × 5."],"explanation":"Quíntuplo de 6 = 6 × 5 = 30 anos.","id":"q11"},{"type":"open","difficulty":3,"skill":"conceito","prompt":"Explique com suas palavras por que 3 × 4 = 12, sem usar a tabuada.","modelAnswer":"Porque 3 × 4 significa três grupos de 4 e, somando 4 + 4 + 4, obtemos 12.","keywords":["grupos","soma","somar","4 + 4","vezes"],"hints":["O que \"3 vezes 4\" significa?","Três grupos de quê?","Some esses grupos."],"explanation":"Multiplicar é somar parcelas iguais: 4 + 4 + 4 = 12.","id":"q12"}],"review":["Multiplicar = somar parcelas iguais (fatores → produto)","× 2 é o dobro · × 10 põe um zero","A ordem não muda o resultado","× 1 não muda · × 0 dá zero"],"relatedQuestions":["Como aprender a tabuada?","O que é multiplicar?","Como fazer conta de vezes?"],"equivalentQuestions":["como decorar a tabuada","truque para tabuada","quanto é 7 vezes 8","como fazer conta de vezes","o que significa 3 vezes 4","o que é produto na matematica","o que são fatores da multiplicação","como multiplicar numeros grandes","qualquer numero vezes zero da quanto","a ordem muda na multiplicação","o que é dobro e triplo","como calcular o quíntuplo","tabuada do 9 truque","tabuada do 7 como aprender","como saber quantas coisas tem em varias caixas","problema de multiplicação exemplo","me explica multiplicação","multiplicação é soma repetida","por que 5 vezes 0 da zero","como fazer multiplicação de cabeça","quando usar conta de vezes no problema"],"commonDoubts":[{"q":"Por que qualquer número vezes zero dá zero?","a":"Porque são grupos vazios: 5 × 0 é \"5 grupos de nada\", que dá nada."},{"q":"Não decorei a tabuada. E agora?","a":"Use a soma repetida ou quebre a conta: 7 × 6 = 7 × 5 + 7 = 35 + 7 = 42."}],"commonErrors":["Confundir × 0 com × 1 (8 × 0 é 0, e 8 × 1 é 8)","Somar em vez de multiplicar: fazer 4 + 7 quando o problema pede 4 grupos de 7"],"formulas":[{"name":"Multiplicação","expression":"a × b = produto","variables":[{"symbol":"a","meaning":"número de grupos"},{"symbol":"b","meaning":"quantidade em cada grupo"},{"symbol":"produto","meaning":"total"}],"conditions":"quando os grupos têm o mesmo tamanho"}],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática — Anos Iniciais","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Portal da Matemática OBMEP — videoaulas e materiais do Ensino Fundamental e Médio","url":"https://portaldaobmep.impa.br/","author":"IMPA / OBMEP","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"mat-divisao","subject":"matematica","title":"Divisão","levels":["fund1","fund2"],"grade":"3º ao 5º ano","topic":"Operações","subtopic":"Divisão","aliases":["divisao","dividir","conta de dividir","resto da divisao","dividendo divisor quociente","divisao exata","repartir","metade","terca parte"],"summary":"Aprenda a dividir em partes iguais, entenda o resto e confira a divisão com a multiplicação.","intro":"Dividir é repartir em partes iguais ou descobrir quantas vezes uma quantidade cabe em outra.","objective":"Resolver divisões exatas e não exatas, interpretar o resto e usar a divisão em problemas.","prerequisites":["mat-multiplicacao"],"next":["mat-fracoes","mat-mmc-mdc"],"skills":{"conceito":"Ideia de dividir","termos":"Termos e resto","algoritmo":"Conta de dividir","problemas":"Problemas com divisão"},"blocks":[{"skill":"conceito","title":"Repartir em partes iguais","text":"Dividir é repartir uma quantidade em partes iguais, ou descobrir quantas vezes um número cabe em outro. A divisão é a operação inversa da multiplicação.","example":"12 balas para 3 crianças: 12 ÷ 3 = 4 balas para cada uma, porque 3 × 4 = 12.","variants":{"simples":"Dividir é dar a mesma quantidade para todo mundo.","exemplo":"Uma pizza de 8 pedaços dividida entre 4 amigos: cada um come 8 ÷ 4 = 2 pedaços.","passos":"1. Veja quanto há no total.\n2. Veja em quantas partes vai dividir.\n3. Pergunte: que número vezes as partes dá o total?\n4. Esse número é a resposta."},"id":"b1"},{"skill":"termos","title":"Dividendo, divisor, quociente e resto","text":"Em 17 ÷ 5: 17 é o dividendo, 5 é o divisor, 3 é o quociente e 2 é o resto. Quando o resto é 0, a divisão é exata. O resto é sempre menor que o divisor.","example":"17 ÷ 5 = 3 e sobra 2, porque 5 × 3 + 2 = 17.","variants":{"simples":"O que sobra e não dá para repartir é o resto.","exemplo":"17 figurinhas para 5 amigos: cada um ganha 3 e sobram 2 figurinhas.","passos":"1. Veja quantas vezes o divisor cabe no dividendo.\n2. Multiplique para ver quanto foi usado.\n3. Subtraia: o que sobrar é o resto.\n4. Confira: divisor × quociente + resto = dividendo."},"id":"b2"},{"skill":"algoritmo","title":"A conta armada","text":"Na conta armada dividimos parte por parte, da esquerda para a direita: dividimos, multiplicamos, subtraímos e \"baixamos\" o próximo algarismo.","example":"84 ÷ 4: 8 ÷ 4 = 2; baixa o 4; 4 ÷ 4 = 1. Resultado 21.","variants":{"simples":"Divida um algarismo de cada vez, começando pela esquerda.","exemplo":"Dividir R$ 96 entre 3 pessoas: 9 ÷ 3 = 3 e 6 ÷ 3 = 2 → R$ 32 para cada.","passos":"1. Pegue o primeiro algarismo (ou os dois primeiros, se precisar).\n2. Divida e escreva no quociente.\n3. Multiplique e subtraia.\n4. Baixe o próximo algarismo e repita até acabar."},"id":"b3"},{"skill":"problemas","title":"Quando dividir","text":"Use a divisão quando o problema fala em repartir igualmente, \"cada um\", \"metade\" (÷ 2), \"terça parte\" (÷ 3) ou \"quantos grupos cabem\".","example":"Uma van leva 9 pessoas. Para 30 pessoas: 30 ÷ 9 = 3 e resto 3 → são necessárias 4 vans.","variants":{"simples":"\"Cada um recebe quanto?\" → divide.","exemplo":"Um livro de 60 páginas lido em 5 dias iguais: 60 ÷ 5 = 12 páginas por dia.","passos":"1. Encontre o total e o número de partes.\n2. Divida.\n3. Pense no resto: ele sobra, ou exige mais um grupo?\n4. Responda à pergunta do problema."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"conceito","prompt":"12 balas divididas igualmente entre 3 crianças. Quantas balas cada uma recebe?","options":["3","4","9","36"],"answer":1,"hints":["Que número vezes 3 dá 12?","3 × ? = 12.","3 × 4 = 12."],"explanation":"12 ÷ 3 = 4.","id":"q1"},{"type":"fill","difficulty":1,"skill":"conceito","prompt":"Quanto é 20 ÷ 5?","answers":["4"],"hints":["5 × ? = 20.","Conte de 5 em 5 até 20.","5, 10, 15, 20."],"explanation":"20 ÷ 5 = 4.","id":"q2"},{"type":"tf","difficulty":1,"skill":"termos","prompt":"Numa divisão exata, o resto é zero.","answer":true,"hints":["Exata = não sobra nada.","O que é o resto?","O que sobra."],"explanation":"Verdadeiro.","id":"q3"},{"type":"match","difficulty":2,"skill":"termos","prompt":"Em 17 ÷ 5 = 3, resto 2, ligue cada número ao nome.","pairs":[["17","Dividendo"],["5","Divisor"],["3","Quociente"],["2","Resto"]],"hints":["O que está sendo dividido é o dividendo.","O resultado é o quociente.","O que sobra é o resto."],"explanation":"17 dividendo · 5 divisor · 3 quociente · 2 resto.","id":"q4"},{"type":"mc","difficulty":2,"skill":"algoritmo","prompt":"Quanto é 84 ÷ 4?","options":["12","21","24","41"],"answer":1,"hints":["Comece pelo 8.","8 ÷ 4 = 2; depois 4 ÷ 4.","Junte: 2 e 1."],"explanation":"84 ÷ 4 = 21. Confira: 4 × 21 = 84.","id":"q5"},{"type":"fill","difficulty":2,"skill":"termos","prompt":"Qual é o resto de 17 ÷ 5?","answers":["2"],"hints":["Quantas vezes o 5 cabe no 17?","3 vezes: 15.","17 − 15."],"explanation":"5 × 3 = 15; 17 − 15 = 2.","id":"q6"},{"type":"tf","difficulty":2,"skill":"termos","prompt":"O resto pode ser maior que o divisor.","answer":false,"hints":["Se o resto fosse maior, caberia mais uma vez?","Sim, caberia.","Então a divisão não teria terminado."],"explanation":"Falso: o resto é sempre menor que o divisor.","id":"q7"},{"type":"mc","difficulty":2,"skill":"problemas","prompt":"Um livro de 60 páginas será lido em 5 dias, a mesma quantidade por dia. Quantas páginas por dia?","options":["55","12","15","300"],"answer":1,"hints":["\"A mesma quantidade por dia\" é repartir.","60 ÷ 5.","5 × 12 = 60."],"explanation":"60 ÷ 5 = 12 páginas por dia.","id":"q8"},{"type":"mc","difficulty":3,"skill":"problemas","prompt":"Uma van leva 9 pessoas. Quantas vans são necessárias para 30 pessoas?","options":["3","4","21","270"],"answer":1,"hints":["30 ÷ 9 = 3 e sobra algo.","O resto é 3 pessoas.","Essas 3 pessoas também precisam ir!"],"explanation":"30 ÷ 9 = 3 resto 3: as 3 pessoas que sobram precisam de mais uma van → 4 vans.","id":"q9"},{"type":"fill","difficulty":3,"skill":"algoritmo","prompt":"Quanto é 156 ÷ 12?","answers":["13"],"hints":["12 cabe uma vez em 15.","15 − 12 = 3; baixe o 6: 36.","36 ÷ 12 = 3."],"explanation":"156 ÷ 12 = 13. Confira: 12 × 13 = 156.","id":"q10"},{"type":"order","difficulty":2,"skill":"algoritmo","prompt":"Coloque os passos da conta de dividir na ordem.","items":["Dividir","Multiplicar","Subtrair","Baixar o próximo algarismo"],"hints":["Primeiro vemos quantas vezes cabe.","Depois calculamos quanto foi usado.","Por fim, sobra algo e baixamos o próximo."],"explanation":"Dividir → multiplicar → subtrair → baixar, e repetir.","id":"q11"},{"type":"open","difficulty":3,"skill":"termos","prompt":"Como você confere se 47 ÷ 6 = 7, resto 5, está certo?","modelAnswer":"Multiplico o divisor pelo quociente e somo o resto: 6 × 7 + 5 = 42 + 5 = 47. Como deu o dividendo, está certo.","keywords":["multiplic","resto","soma","47","dividendo"],"hints":["A divisão é o contrário de qual conta?","Multiplique 6 × 7.","Some o resto."],"explanation":"Divisor × quociente + resto = dividendo.","id":"q12"}],"review":["Dividir = repartir igualmente (inverso da multiplicação)","Dividendo ÷ divisor = quociente (+ resto)","Resto é sempre menor que o divisor","Prova: divisor × quociente + resto = dividendo"],"relatedQuestions":["Como fazer conta de dividir?","O que é o resto da divisão?","Como conferir uma divisão?"],"equivalentQuestions":["como dividir numeros","como fazer conta de dividir armada","o que é quociente","o que é dividendo e divisor","o que fazer com o resto","o que é divisão exata","como dividir por 12","como saber quanto cada um recebe","como repartir igualmente","quanto é 84 dividido por 4","como fazer a prova real da divisão","o resto pode ser maior que o divisor","o que é metade de um número","como calcular a terça parte","divisão com resto exemplo","quantas vans preciso problema de divisão","me explica divisão","não sei dividir","dividir é o contrário de multiplicar","como baixar o numero na divisão","divisão com dois algarismos no divisor"],"commonDoubts":[{"q":"Posso dividir por zero?","a":"Não. Não existe número que multiplicado por 0 dê, por exemplo, 5 — por isso a divisão por zero não é definida."},{"q":"O que faço com o resto no problema?","a":"Depende da pergunta: às vezes ele sobra (figurinhas), às vezes exige mais um grupo (vans, ônibus)."}],"commonErrors":["Esquecer de \"baixar\" um algarismo e pular um zero no quociente (ex.: 612 ÷ 6 = 102, não 12)","Deixar resto maior que o divisor","Ignorar o resto em problemas que precisam de mais um grupo"],"formulas":[{"name":"Relação fundamental da divisão","expression":"D = d × q + r","variables":[{"symbol":"D","meaning":"dividendo"},{"symbol":"d","meaning":"divisor (diferente de zero)"},{"symbol":"q","meaning":"quociente"},{"symbol":"r","meaning":"resto (0 ≤ r < d)"}]}],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática — Anos Iniciais","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Portal da Matemática OBMEP — videoaulas e materiais do Ensino Fundamental e Médio","url":"https://portaldaobmep.impa.br/","author":"IMPA / OBMEP","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"mat-formas-geometricas","subject":"matematica","title":"Figuras geométricas planas e espaciais","levels":["fund1"],"grade":"1º ao 5º ano","topic":"Geometria","subtopic":"Figuras planas e sólidos","aliases":["figuras geometricas","formas geometricas","triangulo quadrado retangulo circulo","solidos geometricos","cubo esfera cilindro piramide","faces vertices arestas","poligonos","geometria espacial basica"],"summary":"Reconheça figuras planas (triângulo, quadrado…) e sólidos (cubo, esfera…), com seus lados, faces, vértices e arestas.","intro":"Olhe ao redor: uma janela lembra um retângulo, uma bola é uma esfera. A geometria está em tudo!","objective":"Identificar e classificar figuras planas e sólidos geométricos pelos seus elementos.","next":["mat-area-perimetro","mat-angulos"],"skills":{"planas":"Figuras planas","poligonos":"Polígonos: lados e vértices","solidos":"Sólidos geométricos","elementos":"Faces, arestas e vértices"},"blocks":[{"skill":"planas","title":"Figuras planas","text":"Figuras planas são \"achatadas\": têm comprimento e largura, mas não têm altura. Exemplos: triângulo, quadrado, retângulo e círculo.","example":"O desenho de uma placa de trânsito no papel é uma figura plana.","variants":{"simples":"Plana é a figura que dá para desenhar inteira no papel.","exemplo":"Uma folha de sulfite lembra um retângulo; o fundo de um copo lembra um círculo.","passos":"1. Veja se a figura é \"achatada\".\n2. Conte os lados.\n3. Veja se os lados são retos ou curvos.\n4. Dê o nome: 3 lados triângulo, 4 lados quadrilátero, sem lados retos círculo."},"id":"b1"},{"skill":"poligonos","title":"Polígonos: lados e vértices","text":"Polígonos são figuras planas fechadas formadas só por segmentos de reta (lados). O ponto onde dois lados se encontram é um vértice. O círculo não é polígono, pois não tem lados retos.","example":"Triângulo: 3 lados e 3 vértices. Quadrado: 4 lados iguais e 4 ângulos retos. Pentágono: 5 lados. Hexágono: 6 lados.","variants":{"simples":"Conte os lados: 3 é triângulo, 4 é quadrilátero, 5 é pentágono, 6 é hexágono.","exemplo":"Os favos de mel das abelhas têm formato de hexágono: 6 lados.","passos":"1. Confira se a figura é fechada e tem só lados retos.\n2. Conte os lados.\n3. O número de vértices é igual ao de lados.\n4. Use o nome: tri (3), quadri (4), penta (5), hexa (6)."},"id":"b2"},{"skill":"solidos","title":"Sólidos geométricos","text":"Sólidos (figuras espaciais) têm comprimento, largura e altura: ocupam lugar no espaço. Os que têm só superfícies planas são poliedros (cubo, pirâmide, prisma). Os que têm parte arredondada são corpos redondos (esfera, cilindro, cone).","example":"Um dado é um cubo; uma lata é um cilindro; uma casquinha de sorvete lembra um cone; uma bola é uma esfera.","variants":{"simples":"Sólido é o que dá para pegar na mão, como um dado ou uma bola.","exemplo":"Na cozinha: caixa de leite (prisma), lata de milho (cilindro), laranja (esfera).","passos":"1. Veja se o objeto rola.\n2. Se rola, é corpo redondo (esfera, cilindro, cone).\n3. Se não rola e só tem partes planas, é poliedro.\n4. Compare com os modelos: cubo, prisma, pirâmide."},"id":"b3"},{"skill":"elementos","title":"Faces, arestas e vértices","text":"Nos poliedros, cada superfície plana é uma face, cada \"quina\" onde duas faces se encontram é uma aresta e cada ponta é um vértice. O cubo tem 6 faces, 12 arestas e 8 vértices.","example":"Um dado tem 6 faces (os lados com números), 12 arestas e 8 pontas (vértices).","variants":{"simples":"Face é o lado chato, aresta é a dobra, vértice é a ponta.","exemplo":"Numa caixa de sapato: as tampas e os lados são faces, as dobras são arestas e os cantos são vértices.","passos":"1. Conte as superfícies planas: faces.\n2. Conte as \"linhas\" onde as faces se juntam: arestas.\n3. Conte as pontas: vértices.\n4. Confira no cubo: 6, 12 e 8."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"poligonos","prompt":"Quantos lados tem um triângulo?","options":["2","3","4","5"],"answer":1,"hints":["\"Tri\" quer dizer…","Triciclo tem 3 rodas.","Três."],"explanation":"O triângulo tem 3 lados e 3 vértices.","id":"q1"},{"type":"mc","difficulty":1,"skill":"solidos","prompt":"Uma bola de futebol lembra qual sólido?","options":["Cubo","Cilindro","Esfera","Pirâmide"],"answer":2,"hints":["Ela rola para todos os lados.","Não tem nenhuma parte plana.","É toda redonda."],"explanation":"A bola lembra uma esfera.","id":"q2"},{"type":"tf","difficulty":1,"skill":"poligonos","prompt":"O círculo é um polígono.","answer":false,"hints":["Polígono tem lados retos.","O círculo tem lados retos?","Não, é todo curvo."],"explanation":"Falso: o círculo não tem lados retos, então não é polígono.","id":"q3"},{"type":"match","difficulty":2,"skill":"solidos","prompt":"Ligue o objeto ao sólido que ele lembra.","pairs":[["Dado","Cubo"],["Lata de refrigerante","Cilindro"],["Casquinha de sorvete","Cone"],["Laranja","Esfera"]],"hints":["O dado tem 6 faces iguais.","A lata tem duas bases redondas.","A casquinha tem uma ponta."],"explanation":"Dado–cubo · lata–cilindro · casquinha–cone · laranja–esfera.","id":"q4"},{"type":"fill","difficulty":2,"skill":"elementos","prompt":"Quantas faces tem um cubo?","answers":["6","seis"],"hints":["Pense num dado.","Os números vão de 1 a…","Cada número está numa face."],"explanation":"O cubo tem 6 faces.","id":"q5"},{"type":"mc","difficulty":2,"skill":"poligonos","prompt":"Uma figura plana com 6 lados se chama:","options":["Pentágono","Hexágono","Octógono","Quadrilátero"],"answer":1,"hints":["Pense nos favos de mel.","\"Hexa\" significa 6.","Hexa + gono."],"explanation":"Hexágono: 6 lados.","id":"q6"},{"type":"tf","difficulty":2,"skill":"planas","prompt":"Um quadrado tem 4 lados iguais.","answer":true,"hints":["Compare o quadrado com o retângulo.","No retângulo, os lados podem ser diferentes.","No quadrado, todos são iguais."],"explanation":"Verdadeiro: 4 lados iguais e 4 ângulos retos.","id":"q7"},{"type":"mc","difficulty":2,"skill":"solidos","prompt":"Qual destes sólidos NÃO rola?","options":["Esfera","Cilindro","Cone","Cubo"],"answer":3,"hints":["Corpos redondos rolam.","Quem só tem faces planas não rola.","O dado rola ou tomba?"],"explanation":"O cubo só tem faces planas: não rola.","id":"q8"},{"type":"fill","difficulty":3,"skill":"elementos","prompt":"Quantos vértices (pontas) tem um cubo?","answers":["8","oito"],"hints":["Conte as pontas de cima.","São 4 em cima.","E mais 4 embaixo."],"explanation":"4 em cima + 4 embaixo = 8 vértices.","id":"q9"},{"type":"mc","difficulty":3,"skill":"elementos","prompt":"Quantas arestas tem um cubo?","options":["6","8","12","24"],"answer":2,"hints":["Aresta é a \"dobra\" entre duas faces.","Conte 4 em cima e 4 embaixo.","Mais as 4 que ligam cima e embaixo."],"explanation":"4 + 4 + 4 = 12 arestas.","id":"q10"},{"type":"mc","difficulty":3,"skill":"poligonos","prompt":"Quantos vértices tem um pentágono?","options":["4","5","6","10"],"answer":1,"hints":["Num polígono, vértices e lados são iguais em número.","\"Penta\" = 5.","5 lados → 5 vértices."],"explanation":"Pentágono: 5 lados e 5 vértices.","id":"q11"},{"type":"open","difficulty":3,"skill":"solidos","prompt":"Qual é a diferença entre uma figura plana e um sólido geométrico?","modelAnswer":"A figura plana tem só comprimento e largura e pode ser desenhada inteira no papel. O sólido tem também altura: ocupa lugar no espaço, como um dado ou uma bola.","keywords":["altura","espaco","papel","plana","tres dimens","ocupa"],"hints":["Pense num quadrado e num cubo.","Qual deles dá para segurar?","Fale de altura ou de ocupar espaço."],"explanation":"Plana: 2 dimensões. Sólido: 3 dimensões.","id":"q12"}],"review":["Planas: triângulo, quadrado, retângulo, círculo","Polígonos têm lados retos; nº de lados = nº de vértices","Sólidos: poliedros (não rolam) e corpos redondos (rolam)","Cubo: 6 faces, 12 arestas, 8 vértices"],"relatedQuestions":["Quais são as figuras geométricas?","Quantas faces tem um cubo?","O que é aresta e vértice?"],"equivalentQuestions":["quais sao as formas geometricas","o que é figura plana","o que é solido geometrico","qual a diferença entre quadrado e retangulo","quantos lados tem um hexagono","o que é poligono","circulo é poligono","o que é vertice","o que é aresta","o que é face de um solido","quantas arestas tem o cubo","quantos vertices tem o cubo","quais objetos tem forma de cilindro","o que é um cone","o que é piramide na geometria","qual solido rola","nome das figuras com 5 lados","o que é corpo redondo","o que é poliedro","me explica figuras geometricas","como diferenciar prisma e piramide"],"commonDoubts":[{"q":"O quadrado é um retângulo?","a":"Sim! O retângulo tem 4 ângulos retos; o quadrado também tem, e ainda tem os 4 lados iguais. Todo quadrado é um retângulo especial."},{"q":"Qual a diferença entre círculo e esfera?","a":"O círculo é plano (desenho no papel). A esfera é um sólido (como uma bola)."}],"commonErrors":["Chamar o cubo de quadrado (quadrado é plano, cubo é sólido)","Achar que o círculo é polígono","Contar arestas só de uma face do cubo"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática — Anos Iniciais","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Portal da Matemática OBMEP — videoaulas e materiais do Ensino Fundamental e Médio","url":"https://portaldaobmep.impa.br/","author":"IMPA / OBMEP","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"mat-medidas","subject":"matematica","title":"Medidas de comprimento, massa e capacidade","levels":["fund1","fund2"],"grade":"3º ao 6º ano","topic":"Grandezas e medidas","subtopic":"Unidades de medida","aliases":["medidas","unidades de medida","metro centimetro quilometro","grama quilograma","litro mililitro","converter medidas","transformar unidades","comprimento massa capacidade"],"summary":"Conheça metro, grama e litro, seus múltiplos e submúltiplos, e aprenda a converter entre eles.","intro":"Quanto você mede? Quanto pesa um pacote de arroz? Quanto cabe numa garrafa? Vamos medir!","objective":"Usar unidades de comprimento, massa e capacidade e converter entre elas.","prerequisites":["mat-multiplicacao","mat-divisao"],"next":["mat-area-perimetro","mat-decimais"],"skills":{"comprimento":"Comprimento","massa":"Massa","capacidade":"Capacidade","conversao":"Conversão de unidades"},"blocks":[{"skill":"comprimento","title":"Comprimento: metro","text":"Comprimento é medido em metro (m). 1 m = 100 centímetros (cm) = 1.000 milímetros (mm). Para distâncias grandes, usamos o quilômetro: 1 km = 1.000 m.","example":"Uma porta tem cerca de 2 m de altura. De uma cidade a outra podem ser 50 km.","variants":{"simples":"Régua mede em centímetros. Estrada mede em quilômetros.","exemplo":"Uma criança de 1,30 m tem 130 cm de altura.","passos":"1. Escolha a unidade pelo tamanho: mm (muito pequeno), cm (objetos), m (salas, pessoas), km (estradas).\n2. Lembre: 1 km = 1.000 m.\n3. 1 m = 100 cm.\n4. 1 cm = 10 mm."},"id":"b1"},{"skill":"massa","title":"Massa: grama e quilograma","text":"Massa (o que chamamos de \"peso\" no dia a dia) é medida em grama (g) e quilograma (kg). 1 kg = 1.000 g. Para coisas muito leves, usamos o miligrama (mg): 1 g = 1.000 mg.","example":"Um pacote de arroz tem 5 kg; um pacote de biscoito, 200 g.","variants":{"simples":"Coisas leves em gramas, coisas pesadas em quilos.","exemplo":"Meio quilo de carne são 500 g.","passos":"1. Veja se o objeto é leve ou pesado.\n2. Leve: gramas. Pesado: quilogramas.\n3. Para passar kg para g, multiplique por 1.000.\n4. Para passar g para kg, divida por 1.000."},"id":"b2"},{"skill":"capacidade","title":"Capacidade: litro","text":"Capacidade é quanto cabe dentro de um recipiente. Usamos o litro (L) e o mililitro (mL): 1 L = 1.000 mL.","example":"Uma garrafa de refrigerante pode ter 2 L; uma lata, 350 mL.","variants":{"simples":"Litro é para quanto cabe de líquido.","exemplo":"Um copo de 250 mL: quatro copos enchem 1 litro (4 × 250 = 1.000).","passos":"1. Pergunte: quanto cabe?\n2. Muito líquido: litros.\n3. Pouco líquido: mililitros.\n4. 1 L = 1.000 mL."},"id":"b3"},{"skill":"conversao","title":"Convertendo unidades","text":"Para passar de uma unidade maior para uma menor, multiplicamos; da menor para a maior, dividimos. Os prefixos ajudam: quilo = 1.000, centi = 1/100, mili = 1/1.000.","example":"3 km = 3 × 1.000 = 3.000 m. 2.500 g = 2.500 ÷ 1.000 = 2,5 kg.","variants":{"simples":"De grande para pequeno: multiplica. De pequeno para grande: divide.","exemplo":"Uma corrida de 5 km tem 5.000 m.","passos":"1. Descubra a relação (ex.: 1 km = 1.000 m).\n2. Indo para uma unidade menor, multiplique.\n3. Indo para uma unidade maior, divida.\n4. Escreva o resultado com a nova unidade."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"comprimento","prompt":"Quantos centímetros há em 1 metro?","options":["10","100","1.000","12"],"answer":1,"hints":["\"Centi\" lembra cem.","Uma régua grande de 1 m tem…","100 cm."],"explanation":"1 m = 100 cm.","id":"q1"},{"type":"mc","difficulty":1,"skill":"massa","prompt":"Qual unidade é melhor para medir a massa de um pacote de arroz?","options":["Metro","Litro","Quilograma","Centímetro"],"answer":2,"hints":["Arroz não se mede pelo tamanho.","Queremos saber o \"peso\".","Massa: grama ou quilograma."],"explanation":"Massa é medida em kg (quilograma).","id":"q2"},{"type":"tf","difficulty":1,"skill":"capacidade","prompt":"O litro é usado para medir capacidade.","answer":true,"hints":["Capacidade é quanto cabe.","Refrigerante vem em…","Litros!"],"explanation":"Verdadeiro.","id":"q3"},{"type":"fill","difficulty":2,"skill":"conversao","prompt":"Quantos metros há em 3 km?","answers":["3000","3.000"],"hints":["1 km = 1.000 m.","De km para m, multiplique.","3 × 1.000."],"explanation":"3 km = 3.000 m.","id":"q4"},{"type":"mc","difficulty":2,"skill":"conversao","prompt":"2.500 g equivalem a:","options":["25 kg","2,5 kg","250 kg","0,25 kg"],"answer":1,"hints":["1 kg = 1.000 g.","De g para kg, divida por 1.000.","2.500 ÷ 1.000."],"explanation":"2.500 g = 2,5 kg.","id":"q5"},{"type":"match","difficulty":2,"skill":"comprimento","prompt":"Ligue cada medida à unidade mais adequada.","pairs":[["Distância entre cidades","Quilômetro"],["Comprimento de um lápis","Centímetro"],["Espessura de uma moeda","Milímetro"],["Altura de uma porta","Metro"]],"hints":["Distâncias grandes: km.","Objetos pequenos: cm.","Coisas muito finas: mm."],"explanation":"Cidades–km · lápis–cm · moeda–mm · porta–m.","id":"q6"},{"type":"fill","difficulty":2,"skill":"capacidade","prompt":"Quantos mililitros há em 1 litro?","answers":["1000","1.000"],"hints":["\"Mili\" = milésima parte.","São mil partes.","1 L = … mL."],"explanation":"1 L = 1.000 mL.","id":"q7"},{"type":"tf","difficulty":2,"skill":"massa","prompt":"1 kg de algodão tem a mesma massa que 1 kg de ferro.","answer":true,"hints":["Os dois têm 1 kg.","O volume é diferente, a massa não.","1 kg é 1 kg."],"explanation":"Verdadeiro: a massa é a mesma; o algodão só ocupa mais espaço.","id":"q8"},{"type":"mc","difficulty":3,"skill":"capacidade","prompt":"Quantos copos de 250 mL enchem uma jarra de 2 L?","options":["4","8","10","250"],"answer":1,"hints":["2 L = 2.000 mL.","Quantas vezes 250 cabe em 2.000?","2.000 ÷ 250."],"explanation":"2.000 ÷ 250 = 8 copos.","id":"q9"},{"type":"fill","difficulty":3,"skill":"conversao","prompt":"Uma criança mede 1,35 m. Quantos centímetros ela tem?","answers":["135","135 cm"],"hints":["1 m = 100 cm.","Multiplique por 100.","1,35 × 100."],"explanation":"1,35 × 100 = 135 cm.","id":"q10"},{"type":"order","difficulty":3,"skill":"comprimento","prompt":"Ordene do MENOR para o MAIOR.","items":["8 mm","5 cm","2 m","1 km"],"hints":["Converta tudo para a mesma unidade.","8 mm < 50 mm (5 cm).","1 km = 1.000 m."],"explanation":"8 mm < 5 cm (50 mm) < 2 m < 1 km.","id":"q11"},{"type":"open","difficulty":3,"skill":"conversao","prompt":"Explique como transformar quilômetros em metros, com um exemplo.","modelAnswer":"Como 1 km tem 1.000 m, multiplico o número de quilômetros por 1.000. Por exemplo, 4 km = 4 × 1.000 = 4.000 m.","keywords":["1000","multiplic","metros","quilometro"],"hints":["Quantos metros tem 1 km?","De maior para menor: multiplica ou divide?","Dê um exemplo com números."],"explanation":"km → m: multiplica por 1.000.","id":"q12"}],"review":["Comprimento: 1 km = 1.000 m · 1 m = 100 cm · 1 cm = 10 mm","Massa: 1 kg = 1.000 g","Capacidade: 1 L = 1.000 mL","Maior → menor: multiplica · menor → maior: divide"],"relatedQuestions":["Como transformar km em metros?","Quantos gramas tem 1 kg?","Quantos mL tem 1 litro?"],"equivalentQuestions":["quantos cm tem um metro","como converter metros em centimetros","quantos metros tem um quilometro","como transformar gramas em quilos","quantas gramas tem meio quilo","quantos ml tem 1 litro","como converter litros em mililitros","qual unidade usar para medir peso","diferença entre massa e peso","o que significa quilo centi e mili","como saber se multiplico ou divido na conversão","1,35 m em centimetros","quantos mm tem 1 cm","como medir capacidade","unidade de medida de comprimento","o que é capacidade na matematica","quantos copos de 250 ml tem 1 litro","me explica medidas","tabela de conversão de medidas","2500 gramas em kg","como passar de km para m"],"commonDoubts":[{"q":"Massa e peso são a mesma coisa?","a":"No dia a dia usamos como sinônimos, mas na Física massa (kg) é a quantidade de matéria e peso é a força da gravidade sobre ela (em newtons)."},{"q":"Como lembrar se multiplico ou divido?","a":"Indo para uma unidade menor, o número fica maior (multiplica). Indo para uma unidade maior, o número fica menor (divide)."}],"commonErrors":["Dividir quando deveria multiplicar (3 km = 3.000 m, não 0,003 m)","Achar que 1 m = 10 cm","Comparar medidas em unidades diferentes sem converter"],"formulas":[{"name":"Relações principais","expression":"1 km = 1.000 m · 1 m = 100 cm · 1 kg = 1.000 g · 1 L = 1.000 mL","variables":[{"symbol":"k (quilo)","meaning":"× 1.000"},{"symbol":"c (centi)","meaning":"÷ 100"},{"symbol":"m (mili)","meaning":"÷ 1.000"}]}],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática — Anos Iniciais","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Portal da Matemática OBMEP — videoaulas e materiais do Ensino Fundamental e Médio","url":"https://portaldaobmep.impa.br/","author":"IMPA / OBMEP","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"mat-sistema-monetario","subject":"matematica","title":"Sistema monetário: dinheiro e troco","levels":["fund1"],"grade":"2º ao 5º ano","topic":"Grandezas e medidas","subtopic":"Sistema monetário brasileiro","aliases":["sistema monetario","dinheiro","real","moedas e cedulas","troco","centavos","reais e centavos","contar dinheiro","compras"],"summary":"Conheça o real, as moedas e cédulas, e aprenda a calcular preços, totais e troco.","intro":"Ir à padaria, comprar um lanche, receber troco… Usamos matemática com dinheiro o tempo todo!","objective":"Reconhecer cédulas e moedas do real, fazer trocas equivalentes e calcular totais e troco.","prerequisites":["mat-adicao-subtracao"],"next":["mat-decimais"],"skills":{"real":"Real e centavos","trocas":"Trocas equivalentes","total":"Calcular o total","troco":"Calcular o troco"},"blocks":[{"skill":"real","title":"O real e os centavos","text":"A moeda do Brasil é o real (R$). 1 real = 100 centavos. Há moedas de 5, 10, 25 e 50 centavos e de 1 real, e cédulas de 2, 5, 10, 20, 50, 100 e 200 reais.","example":"R$ 3,50 lê-se \"três reais e cinquenta centavos\".","variants":{"simples":"Cem centavos fazem 1 real.","exemplo":"Duas moedas de 50 centavos valem R$ 1,00.","passos":"1. Os números antes da vírgula são reais.\n2. Os dois números depois da vírgula são centavos.\n3. 100 centavos = R$ 1,00.\n4. Leia: \"x reais e y centavos\"."},"id":"b1"},{"skill":"trocas","title":"Trocas que valem o mesmo","text":"Podemos formar o mesmo valor com cédulas e moedas diferentes. Trocar uma nota de R$ 10 por duas de R$ 5 não muda o valor.","example":"R$ 20 = 2 notas de R$ 10 = 4 notas de R$ 5 = 10 notas de R$ 2.","variants":{"simples":"O valor é o mesmo, só muda o jeito de juntar.","exemplo":"Para pagar R$ 1,00 você pode usar 4 moedas de 25 centavos.","passos":"1. Veja o valor que quer formar.\n2. Escolha as cédulas maiores que cabem.\n3. Complete com as menores e moedas.\n4. Some para conferir."},"id":"b2"},{"skill":"total","title":"Quanto vou pagar?","text":"Para saber o total de uma compra, somamos os preços. Com vírgula, alinhamos a vírgula: reais embaixo de reais e centavos embaixo de centavos.","example":"Suco R$ 4,50 + pão R$ 2,30 = R$ 6,80.","variants":{"simples":"Some os preços de tudo que você comprou.","exemplo":"Um caderno de R$ 12,00 e um lápis de R$ 1,50 custam juntos R$ 13,50.","passos":"1. Escreva os preços um embaixo do outro, vírgula embaixo de vírgula.\n2. Some os centavos.\n3. Se passar de 100 centavos, vira 1 real.\n4. Some os reais."},"id":"b3"},{"skill":"troco","title":"Quanto recebo de troco?","text":"Troco é o dinheiro que volta: valor pago menos o preço. Dá para calcular \"completando\": do preço, conte até o valor pago.","example":"Paguei R$ 10 por algo de R$ 6,80: 6,80 + 0,20 = 7,00; 7,00 + 3,00 = 10,00. Troco: R$ 3,20.","variants":{"simples":"Troco = o que eu dei − o que custou.","exemplo":"Com uma nota de R$ 20 para um lanche de R$ 15, o troco é R$ 5.","passos":"1. Anote quanto você pagou.\n2. Anote o preço.\n3. Subtraia (ou complete a partir do preço).\n4. Confira: preço + troco = valor pago."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"real","prompt":"Quantos centavos formam 1 real?","options":["10","50","100","1.000"],"answer":2,"hints":["Pense em moedas de 50 centavos.","Duas delas formam 1 real.","50 + 50."],"explanation":"1 real = 100 centavos.","id":"q1"},{"type":"mc","difficulty":1,"skill":"trocas","prompt":"Quantas moedas de 25 centavos formam R$ 1,00?","options":["2","4","5","25"],"answer":1,"hints":["R$ 1,00 = 100 centavos.","Quantas vezes 25 cabe em 100?","25 + 25 + 25 + 25."],"explanation":"4 × 25 = 100 centavos = R$ 1,00.","id":"q2"},{"type":"tf","difficulty":1,"skill":"trocas","prompt":"Uma nota de R$ 10 vale o mesmo que duas notas de R$ 5.","answer":true,"hints":["Some as duas de R$ 5.","5 + 5 = ?","10."],"explanation":"Verdadeiro.","id":"q3"},{"type":"fill","difficulty":2,"skill":"total","prompt":"Um suco custa R$ 4,50 e um pão R$ 2,30. Quanto custa tudo? (R$)","answers":["6,80","6.80","6,8"],"hints":["Some os centavos: 50 + 30.","Some os reais: 4 + 2.","Junte reais e centavos."],"explanation":"4,50 + 2,30 = R$ 6,80.","id":"q4"},{"type":"mc","difficulty":2,"skill":"troco","prompt":"Paguei com R$ 10 algo que custou R$ 6,80. Qual o troco?","options":["R$ 4,20","R$ 3,20","R$ 3,80","R$ 16,80"],"answer":1,"hints":["Troco = pago − preço.","De 6,80 até 7,00 faltam 0,20.","De 7,00 até 10,00 faltam 3,00."],"explanation":"10,00 − 6,80 = R$ 3,20.","id":"q5"},{"type":"match","difficulty":2,"skill":"trocas","prompt":"Ligue cada valor a uma forma de formá-lo.","pairs":[["R$ 20","4 notas de R$ 5"],["R$ 1","2 moedas de 50 centavos"],["R$ 50","5 notas de R$ 10"],["R$ 6","3 notas de R$ 2"]],"hints":["Multiplique a quantidade pelo valor da nota.","4 × 5 = 20.","5 × 10 = 50."],"explanation":"20 = 4×5 · 1 = 2×0,50 · 50 = 5×10 · 6 = 3×2.","id":"q6"},{"type":"fill","difficulty":2,"skill":"troco","prompt":"Com uma nota de R$ 20, comprei um lanche de R$ 15. Qual é o troco em reais?","answers":["5","5,00","R$ 5"],"hints":["Troco = pago − preço.","20 − 15.","Confira: 15 + ? = 20."],"explanation":"20 − 15 = R$ 5.","id":"q7"},{"type":"tf","difficulty":3,"skill":"real","prompt":"R$ 3,05 e R$ 3,50 são o mesmo valor.","answer":false,"hints":["Olhe os centavos.","05 centavos e 50 centavos são iguais?","Não."],"explanation":"Falso: R$ 3,05 tem 5 centavos; R$ 3,50 tem 50 centavos.","id":"q8"},{"type":"mc","difficulty":3,"skill":"total","prompt":"Comprei 3 cadernos de R$ 8,50. Quanto gastei?","options":["R$ 24,50","R$ 25,50","R$ 11,50","R$ 26,00"],"answer":1,"hints":["São 3 vezes o mesmo preço.","3 × 8 = 24 e 3 × 0,50 = 1,50.","Some as partes."],"explanation":"3 × 8,50 = 24 + 1,50 = R$ 25,50.","id":"q9"},{"type":"order","difficulty":2,"skill":"real","prompt":"Ordene do MENOR para o MAIOR valor.","items":["R$ 0,75","R$ 1,20","R$ 2,05","R$ 2,50"],"hints":["Compare primeiro os reais.","Com reais iguais, compare os centavos.","05 centavos < 50 centavos."],"explanation":"0,75 < 1,20 < 2,05 < 2,50.","id":"q10"},{"type":"mc","difficulty":3,"skill":"troco","prompt":"Tenho R$ 50. Gastei R$ 12,40 e R$ 23,60. Quanto sobrou?","options":["R$ 14,00","R$ 36,00","R$ 13,00","R$ 24,00"],"answer":0,"hints":["Some os gastos primeiro.","12,40 + 23,60 = 36,00.","50 − 36."],"explanation":"Gastos: R$ 36,00. Sobra: 50 − 36 = R$ 14,00.","id":"q11"},{"type":"open","difficulty":3,"skill":"troco","prompt":"Explique como você confere se recebeu o troco certo.","modelAnswer":"Somo o preço da compra com o troco recebido. Se der o valor que eu paguei, o troco está certo.","keywords":["preco","soma","somar","troco","paguei","igual"],"hints":["O troco é o que volta do valor pago.","Preço + troco deve dar…","O valor que você entregou."],"explanation":"Preço + troco = valor pago.","id":"q12"}],"review":["1 real = 100 centavos","Valores iguais podem ser formados de jeitos diferentes","Total: some alinhando a vírgula","Troco = valor pago − preço (confira somando)"],"relatedQuestions":["Como calcular o troco?","Quantos centavos tem um real?","Como somar preços com vírgula?"],"equivalentQuestions":["como calcular troco","quanto de troco eu recebo","quantos centavos tem 1 real","como somar dinheiro com virgula","como ler preços em reais","quais sao as moedas do real","quais notas de dinheiro existem","como formar 1 real com moedas","como conferir o troco","como calcular o total da compra","o que significa R$","quanto é meio real","como contar dinheiro","problema de dinheiro e troco","como pagar com notas diferentes","como subtrair dinheiro","me explica sistema monetario","como saber se vai sobrar dinheiro","quantas moedas de 25 centavos fazem 1 real","diferença entre 3,05 e 3,50"],"commonDoubts":[{"q":"Por que R$ 0,50 é metade de 1 real?","a":"Porque 1 real tem 100 centavos, e 50 é metade de 100."}],"commonErrors":["Confundir R$ 3,05 com R$ 3,50","Somar sem alinhar a vírgula","Esquecer que 100 centavos viram 1 real na soma"],"formulas":[{"name":"Troco","expression":"troco = valor pago − preço","variables":[{"symbol":"valor pago","meaning":"quanto você entregou"},{"symbol":"preço","meaning":"quanto custou"},{"symbol":"troco","meaning":"o que volta"}]}],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática — Anos Iniciais","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Cédulas e moedas do Real","url":"https://www.bcb.gov.br/cedulasemoedas","author":"Banco Central do Brasil","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Números racionais","subtopic":"Frações","relatedQuestions":["O que é numerador e denominador?","Como simplificar uma fração?","O que são frações equivalentes?","Como ler uma fração?"],"id":"mat-fracoes","subject":"matematica","title":"Frações","levels":["fund1","fund2"],"grade":"4º ao 6º ano","aliases":["fracao","fracoes","numerador","denominador","fracoes equivalentes","simplificar fracao","simplificacao de fracoes"],"summary":"Entenda o que é uma fração, como ler, encontrar frações equivalentes e simplificar.","intro":"Vamos entender juntos. Fração é um jeito de mostrar pedaços de alguma coisa — de uma pizza, de uma barra de chocolate ou de um grupo de pessoas.","skills":{"conceito":"Conceito de fração","leitura":"Leitura de frações","equivalentes":"Frações equivalentes","simplificacao":"Simplificação de frações"},"blocks":[{"id":"b1","skill":"conceito","title":"O que é uma fração","text":"A fração representa uma parte de um todo. O número de cima (numerador) indica quantas partes você está pegando. O número de baixo (denominador) indica em quantas partes iguais o todo foi dividido.","example":"Uma pizza cortada em 8 pedaços iguais. Se você come 3, comeu 3/8 da pizza: 3 é o numerador e 8 é o denominador.","variants":{"simples":"Pense numa pizza. O número de baixo diz em quantos pedaços ela foi cortada. O número de cima diz quantos pedaços você pegou. Só isso!","exemplo":"Uma barra de chocolate tem 4 quadradinhos iguais. Você deu 1 para seu amigo. Seu amigo ganhou 1/4 da barra: 1 pedaço de 4.","outra":"Fração é uma divisão escrita de um jeito especial. 3/8 quer dizer \"dividi em 8 partes iguais e fiquei com 3 delas\". O traço do meio é como um \"de\": 3 de 8.","detalhado":"Numa fração a/b, o denominador b (que nunca pode ser zero) diz em quantas partes IGUAIS o inteiro foi dividido — as partes precisam ter o mesmo tamanho. O numerador a conta quantas dessas partes estamos considerando. Se a = b, temos o inteiro (8/8 = 1). Se a > b, temos mais de um inteiro, como 9/8."}},{"id":"b2","skill":"leitura","title":"Como ler uma fração","text":"Lemos primeiro o numerador e depois o denominador com um nome especial: 2 = meio, 3 = terço, 4 = quarto, 5 = quinto… até 9 = nono, e 10 = décimo. Acima de 10, usamos a palavra \"avos\".","example":"1/2 = um meio · 2/3 = dois terços · 3/10 = três décimos · 5/12 = cinco doze avos.","variants":{"simples":"1/2 é \"um meio\" (metade). 1/3 é \"um terço\". 1/4 é \"um quarto\". Quando o número de baixo passa de 10, falamos \"avos\": 1/12 é \"um doze avos\".","exemplo":"Se um bolo foi cortado em 12 fatias e você comeu 5, você comeu \"cinco doze avos\" do bolo. Se foi cortado em 4 e você comeu 3, comeu \"três quartos\".","outra":"O denominador vira um nome parecido com os números de ordem: quinto, sexto, sétimo, oitavo, nono, décimo. Exceções: 2 é \"meio\" e 3 é \"terço\". Depois do 10, é o número + \"avos\".","detalhado":"Denominadores 100 e 1000 também têm nomes próprios: centésimo (1/100) e milésimo (1/1000). Por isso 25/100 se lê \"vinte e cinco centésimos\". Nos demais casos acima de 10 usamos \"avos\": 7/15 = sete quinze avos."}},{"id":"b3","skill":"equivalentes","title":"Frações equivalentes","text":"Frações equivalentes representam a mesma quantidade, mesmo com números diferentes. Para encontrar uma, multiplique (ou divida) o numerador e o denominador pelo mesmo número.","example":"1/2 = 2/4 = 4/8. Metade da pizza é sempre metade, esteja ela cortada em 2, 4 ou 8 pedaços.","variants":{"simples":"Metade de uma pizza é igual a 2 pedaços de 4, ou 4 pedaços de 8. Muda o número de pedaços, mas a quantidade de pizza é a mesma.","exemplo":"Você tem 1/3 de uma barra. Se cortar cada pedaço ao meio, agora são 6 pedaços no total e você tem 2: 2/6. Continua sendo a mesma quantidade de chocolate.","outra":"Multiplicar em cima e embaixo pelo mesmo número é como \"cortar os pedaços em pedaços menores\": aumenta a quantidade de pedaços, mas não a quantidade de pizza.","detalhado":"a/b e c/d são equivalentes quando a·d = b·c (produto cruzado). Exemplo: 2/3 e 4/6 → 2·6 = 12 e 3·4 = 12, então são equivalentes. Isso funciona porque multiplicar numerador e denominador pelo mesmo número é o mesmo que multiplicar a fração por 1 (n/n = 1)."}},{"id":"b4","skill":"simplificacao","title":"Simplificar frações","text":"Simplificar é escrever a fração com os menores números possíveis. Divida o numerador e o denominador pelo mesmo número até não ser mais possível. A fração final é chamada de irredutível.","example":"6/8 → dividindo os dois por 2 → 3/4. Como 3 e 4 não têm outro divisor comum, 3/4 é irredutível.","variants":{"simples":"Procure um número que divide o de cima e o de baixo ao mesmo tempo. Divida os dois. Repita até não dar mais.","exemplo":"12/18: os dois são pares, divide por 2 → 6/9. Os dois estão na tabuada do 3, divide por 3 → 2/3. Pronto: 2/3.","outra":"Simplificar é o caminho contrário das equivalentes: em vez de cortar os pedaços em partes menores, você junta pedaços até ficarem do maior tamanho possível.","detalhado":"O jeito mais rápido é dividir numerador e denominador pelo máximo divisor comum (MDC). MDC(12, 18) = 6, então 12/18 = (12÷6)/(18÷6) = 2/3 em um passo só. Uma fração é irredutível quando o MDC entre numerador e denominador é 1."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"conceito","prompt":"Se João comeu 3 de 8 pedaços de uma pizza, qual fração representa o que ele comeu?","options":["3/5","3/8","5/8","8/3"],"answer":1,"hints":["Quantos pedaços a pizza tinha no total?","O número de baixo é o total de pedaços; o de cima é quantos ele comeu.","Total = 8 (embaixo). Comeu = 3 (em cima)."],"explanation":"A pizza tinha 8 pedaços (denominador) e João comeu 3 (numerador): 3/8."},{"id":"q2","type":"mc","difficulty":1,"skill":"conceito","prompt":"Na fração 2/5, qual é o denominador?","options":["2","5","7","10"],"answer":1,"hints":["Denominador fica em uma posição específica da fração.","O denominador é o número de baixo: em quantas partes o todo foi dividido.","Olhe o número abaixo do traço."],"explanation":"O denominador é o número de baixo, 5: o todo foi dividido em 5 partes iguais."},{"id":"q3","type":"tf","difficulty":1,"skill":"leitura","prompt":"A fração 1/4 se lê \"um quarto\".","answer":true,"hints":["Pense no nome especial do denominador 4.","2 = meio, 3 = terço, 4 = …","4 é \"quarto\", como em \"um quarto de hora\"."],"explanation":"Verdadeiro. O denominador 4 se lê \"quarto\": 1/4 = um quarto."},{"id":"q4","type":"mc","difficulty":1,"skill":"leitura","prompt":"Como se lê a fração 3/10?","options":["Três dez avos","Três décimos","Três dezenas","Dez terços"],"answer":1,"hints":["O 10 tem um nome especial.","Até o 10, os denominadores têm nomes próprios.","10 no denominador = décimo."],"explanation":"Quando o denominador é 10, usamos \"décimo(s)\": três décimos."},{"id":"q5","type":"fill","difficulty":2,"skill":"leitura","prompt":"Complete: 5/12 se lê \"cinco doze ____\".","answers":["avos"],"hints":["12 é maior que 10.","Acima de 10, os denominadores não têm nome especial.","Usamos a palavra que começa com \"a\" e termina com \"s\"."],"explanation":"Acima de 10 usamos \"avos\": cinco doze avos."},{"id":"q6","type":"mc","difficulty":2,"skill":"equivalentes","prompt":"Qual destas frações é equivalente a 1/2?","options":["2/3","4/8","3/5","1/4"],"answer":1,"hints":["Procure a fração que também representa \"metade\".","Multiplique o 1 e o 2 pelo mesmo número.","1×4 = 4 e 2×4 = 8."],"explanation":"4/8 é metade de 8, igual a 1/2. Multiplicamos em cima e embaixo por 4."},{"id":"q7","type":"tf","difficulty":2,"skill":"equivalentes","prompt":"As frações 2/3 e 4/6 são equivalentes.","answer":true,"hints":["Compare como 2 virou 4 e como 3 virou 6.","Se os dois foram multiplicados pelo mesmo número, são equivalentes.","2×2 = 4 e 3×2 = 6."],"explanation":"Verdadeiro. Numerador e denominador de 2/3 foram multiplicados por 2, gerando 4/6."},{"id":"q8","type":"fill","difficulty":2,"skill":"simplificacao","prompt":"Simplifique a fração 6/8. (Escreva no formato a/b)","answers":["3/4"],"hints":["6 e 8 são números pares.","Divida numerador e denominador pelo mesmo número.","6÷2 = 3 e 8÷2 = 4."],"explanation":"Dividindo os dois por 2: 6/8 = 3/4, que já é irredutível."},{"id":"q9","type":"mc","difficulty":3,"skill":"simplificacao","prompt":"Qual é a forma irredutível de 12/18?","options":["6/9","4/6","2/3","3/2"],"answer":2,"hints":["Irredutível = não dá mais para simplificar.","6/9 e 4/6 ainda podem ser simplificadas.","Divida 12 e 18 por 6."],"explanation":"O maior divisor comum de 12 e 18 é 6. 12÷6 = 2 e 18÷6 = 3, então 12/18 = 2/3."},{"id":"q10","type":"match","difficulty":2,"skill":"leitura","prompt":"Ligue cada fração ao seu nome.","pairs":[["1/2","Um meio"],["1/3","Um terço"],["1/4","Um quarto"],["1/5","Um quinto"]],"hints":["Comece pela mais conhecida: metade.","2 = meio, 3 = terço.","4 = quarto e 5 = quinto."],"explanation":"1/2 = um meio, 1/3 = um terço, 1/4 = um quarto, 1/5 = um quinto."},{"id":"q11","type":"mc","difficulty":3,"skill":"equivalentes","prompt":"Qual número deve ocupar o lugar do x em 3/5 = x/20?","options":["8","12","15","4"],"answer":1,"hints":["O que aconteceu com o denominador 5 para virar 20?","5 foi multiplicado por 4.","Faça o mesmo com o numerador: 3 × 4."],"explanation":"5 × 4 = 20, então o numerador também é multiplicado por 4: 3 × 4 = 12."},{"id":"q12","type":"open","difficulty":3,"skill":"equivalentes","prompt":"Explique com suas palavras por que 2/4 e 1/2 representam a mesma quantidade.","modelAnswer":"Porque 2/4 é a metade de 4 partes, e 1/2 também é metade. Se dividirmos o numerador e o denominador de 2/4 por 2, obtemos 1/2 — são frações equivalentes.","keywords":["metade","mesma","equivalente","dividir","multiplicar","2"],"hints":["Desenhe uma pizza cortada em 4 e outra em 2.","Pinte 2 pedaços de 4 e 1 pedaço de 2. O que você percebe?","Fale sobre \"metade\" ou sobre dividir em cima e embaixo por 2."],"explanation":"As duas representam metade do todo. 2/4 simplificada (÷2) vira 1/2 — por isso são equivalentes."}],"review":["Numerador (em cima) = partes que pegamos","Denominador (embaixo) = em quantas partes iguais o todo foi dividido","Equivalentes: multiplique ou divida em cima e embaixo pelo mesmo número","Simplificar: divida até não dar mais (irredutível)"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Proporcionalidade","subtopic":"Porcentagem","relatedQuestions":["Como calcular porcentagem?","Como calcular desconto?","Quanto é 10% de um valor?","Como calcular aumento percentual?"],"id":"mat-porcentagem","subject":"matematica","title":"Porcentagem","levels":["fund2","medio"],"grade":"6º e 7º ano","aliases":["porcentagem","por cento","percentual","desconto","juros simples","aumento percentual"],"summary":"Aprenda o que significa \"por cento\", como calcular porcentagens, descontos e aumentos.","intro":"Porcentagem está em todo lugar: promoções, bateria do celular, notas. Vamos descobrir como ela funciona.","skills":{"conceito":"O que é porcentagem","atalhos":"Atalhos de cálculo","calculo":"Calcular porcentagem de um valor","desconto":"Descontos e aumentos"},"blocks":[{"id":"b1","skill":"conceito","title":"O que é \"por cento\"","text":"Porcentagem é uma fração com denominador 100. \"25%\" significa 25 de cada 100, ou seja, 25/100. O todo sempre vale 100%.","example":"Se a bateria do celular está em 40%, sobrou 40 de 100 partes da carga total.","variants":{"simples":"Imagine algo dividido em 100 pedacinhos. 30% são 30 desses pedacinhos. 100% é tudo.","exemplo":"Numa turma de 100 alunos, 60 gostam de futebol. Então 60% da turma gosta de futebol.","outra":"O símbolo % é um jeito curto de escrever \"dividido por 100\". Então 7% = 7 ÷ 100 = 0,07.","detalhado":"Porcentagem é uma razão centesimal. Toda porcentagem pode ser escrita como fração (15% = 15/100 = 3/20) ou como decimal (15% = 0,15). Valores acima de 100% indicam mais que o todo, como um aumento de 150%."}},{"id":"b2","skill":"atalhos","title":"Atalhos que ajudam muito","text":"50% é a metade. 25% é um quarto (metade da metade). 10% é dividir por 10. A partir daí você monta outras: 20% = 2 × 10%, 5% = metade de 10%.","example":"De R$ 80: 10% = R$ 8 · 5% = R$ 4 · 15% = R$ 8 + R$ 4 = R$ 12.","variants":{"simples":"Para achar 10%, tire o último zero ou divida por 10. Para 50%, pegue a metade.","exemplo":"De 200 figurinhas: 50% = 100, 25% = 50, 10% = 20.","outra":"Pense em \"blocos de 10%\". 30% são três blocos de 10%. Achou um bloco, é só somar.","detalhado":"Os atalhos funcionam porque 10% = 1/10, 50% = 1/2, 25% = 1/4 e 20% = 1/5. Combinar porcentagens é somar as frações: 35% = 25% + 10% = 1/4 + 1/10."}},{"id":"b3","skill":"calculo","title":"Calculando a porcentagem de um valor","text":"Para calcular x% de um valor, multiplique o valor por x e divida por 100. Para saber quantos por cento uma parte representa, divida a parte pelo todo e multiplique por 100.","example":"20% de 150 = 150 × 20 ÷ 100 = 30. E 30 de 120 é: 30 ÷ 120 = 0,25 → 25%.","variants":{"simples":"x% de um número: número × x ÷ 100. Exemplo: 20% de 50 = 50 × 20 ÷ 100 = 10.","exemplo":"Uma prova tem 40 questões e você acertou 30. 30 ÷ 40 = 0,75 → 75% de acerto.","outra":"Transforme a porcentagem em decimal e multiplique: 20% = 0,2. Então 20% de 150 = 0,2 × 150 = 30.","detalhado":"São duas perguntas diferentes: (1) \"quanto é p% de V?\" → p/100 × V; (2) \"a parte P é quantos % de V?\" → P/V × 100. Confundir qual é o todo (V) é o erro mais comum."}},{"id":"b4","skill":"desconto","title":"Descontos e aumentos","text":"No desconto, você calcula a porcentagem e subtrai do preço. No aumento, calcula e soma. Atalho: desconto de 10% = pagar 90% do preço.","example":"Camiseta de R$ 60 com 10% de desconto: 10% de 60 = 6 → 60 − 6 = R$ 54.","variants":{"simples":"Desconto: acha a porcentagem e tira. Aumento: acha a porcentagem e soma.","exemplo":"Um tênis de R$ 200 subiu 15%: 15% de 200 = 30. Novo preço: 200 + 30 = R$ 230.","outra":"Use o fator: desconto de 20% → multiplica por 0,8. Aumento de 20% → multiplica por 1,2.","detalhado":"Aumentos e descontos sucessivos não se cancelam: 100 com +20% vira 120; 120 com −20% vira 96. Isso acontece porque o segundo cálculo é feito sobre um valor diferente (1,2 × 0,8 = 0,96)."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"atalhos","prompt":"50% de alguma coisa é o mesmo que:","options":["Um terço","A metade","Um quarto","O dobro"],"answer":1,"hints":["50 é que parte de 100?","50 de 100 partes.","50/100 simplificado dá 1/2."],"explanation":"50% = 50/100 = 1/2, ou seja, a metade."},{"id":"q2","type":"fill","difficulty":1,"skill":"conceito","prompt":"Escreva 25% como fração simplificada (a/b).","answers":["1/4"],"hints":["Porcentagem é uma fração com denominador 100.","25% = 25/100.","Simplifique 25/100 dividindo por 25."],"explanation":"25% = 25/100 = 1/4."},{"id":"q3","type":"mc","difficulty":1,"skill":"atalhos","prompt":"Quanto é 10% de 80?","options":["8","10","18","0,8"],"answer":0,"hints":["10% é um atalho fácil.","10% = dividir por 10.","80 ÷ 10."],"explanation":"10% de 80 = 80 ÷ 10 = 8."},{"id":"q4","type":"tf","difficulty":1,"skill":"conceito","prompt":"100% representa o todo.","answer":true,"hints":["Porcentagem é \"de cada 100\".","100 de 100 partes é quanto?","É tudo."],"explanation":"Verdadeiro. 100% = 100/100 = 1 inteiro."},{"id":"q5","type":"fill","difficulty":2,"skill":"calculo","prompt":"Quanto é 20% de 150?","answers":["30"],"hints":["Comece achando 10%.","10% de 150 = 15.","20% = 2 × 10%."],"explanation":"10% de 150 = 15, então 20% = 30. Ou: 150 × 20 ÷ 100 = 30."},{"id":"q6","type":"mc","difficulty":2,"skill":"desconto","prompt":"Uma camiseta custa R$ 60 e tem 10% de desconto. Quanto você paga?","options":["R$ 50","R$ 54","R$ 56","R$ 66"],"answer":1,"hints":["Primeiro ache quanto é o desconto.","10% de 60 = 6.","Desconto se subtrai: 60 − 6."],"explanation":"O desconto é 10% de 60 = R$ 6. Você paga 60 − 6 = R$ 54."},{"id":"q7","type":"match","difficulty":2,"skill":"atalhos","prompt":"Ligue cada porcentagem à fração correspondente.","pairs":[["50%","A metade"],["25%","Um quarto"],["10%","Um décimo"],["100%","O todo"]],"hints":["Escreva cada uma sobre 100.","25/100 = 1/4 e 10/100 = 1/10.","100/100 = 1."],"explanation":"50% = 1/2, 25% = 1/4, 10% = 1/10, 100% = o todo."},{"id":"q8","type":"tf","difficulty":2,"skill":"atalhos","prompt":"Para calcular 10% de um número, basta dividi-lo por 10.","answer":true,"hints":["10% = 10/100.","10/100 simplificado.","= 1/10."],"explanation":"Verdadeiro. 10% = 1/10, então é só dividir por 10."},{"id":"q9","type":"mc","difficulty":3,"skill":"desconto","prompt":"Um produto de R$ 200 teve aumento de 15%. Qual é o novo preço?","options":["R$ 215","R$ 230","R$ 185","R$ 300"],"answer":1,"hints":["Calcule 15% de 200.","10% = 20 e 5% = 10.","Aumento se soma: 200 + 30."],"explanation":"15% de 200 = 30. Novo preço = 200 + 30 = R$ 230."},{"id":"q10","type":"fill","difficulty":3,"skill":"calculo","prompt":"30 é quantos por cento de 120? (só o número)","answers":["25","25%"],"hints":["Divida a parte pelo todo.","30 ÷ 120 = 0,25.","Multiplique por 100."],"explanation":"30 ÷ 120 = 0,25 = 25%."},{"id":"q11","type":"mc","difficulty":3,"skill":"desconto","prompt":"Um valor de 100 sofre desconto de 20% e depois aumento de 20%. Qual o resultado final?","options":["100","96","104","120"],"answer":1,"hints":["Faça em duas etapas.","Depois do desconto: 80.","Agora calcule 20% de 80 e some."],"explanation":"100 − 20% = 80. 80 + 20% de 80 (16) = 96. O segundo cálculo é sobre um valor menor."},{"id":"q12","type":"mc","difficulty":3,"skill":"calculo","prompt":"Quanto é 15% de 40?","options":["4","6","15","5,5"],"answer":1,"hints":["Quebre 15% em 10% + 5%.","10% de 40 = 4.","5% é a metade de 10%: 2. Some."],"explanation":"10% de 40 = 4 e 5% = 2. Total: 4 + 2 = 6."}],"review":["% = dividido por 100","10% = ÷10 · 50% = metade · 25% = um quarto","Desconto: subtrai · Aumento: soma","Parte ÷ todo × 100 = porcentagem"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Álgebra","subtopic":"Equação do 1º grau","relatedQuestions":["Como achar o valor de x?","Como resolver uma equação simples?","O que é incógnita?"],"id":"mat-equacao-1-grau","subject":"matematica","title":"Equação do 1º grau","levels":["fund2","medio"],"grade":"7º ano","aliases":["equacao do primeiro grau","equacao do 1 grau","equacao simples","incognita","achar o x","isolar o x"],"summary":"Aprenda a encontrar o valor desconhecido (x) mantendo a equação equilibrada.","intro":"Uma equação é como uma balança em equilíbrio. Vamos descobrir o peso escondido!","skills":{"conceito":"O que é uma equação","operacoes":"Operações inversas","resolucao":"Resolver passo a passo","problemas":"Montar equações a partir de problemas"},"blocks":[{"id":"b1","skill":"conceito","title":"Uma balança em equilíbrio","text":"Equação é uma igualdade com um valor desconhecido, a incógnita (geralmente x). Resolver é descobrir o valor de x que torna a igualdade verdadeira.","example":"Em x + 3 = 10, o valor de x é 7, porque 7 + 3 = 10."},{"id":"b2","skill":"operacoes","title":"Operações inversas","text":"Para isolar o x, desfazemos as operações usando a inversa: a soma se desfaz com subtração, e a multiplicação, com divisão. O que fazemos de um lado, fazemos do outro.","example":"x + 5 = 12 → subtraia 5 dos dois lados → x = 7. E 3x = 18 → divida os dois lados por 3 → x = 6."},{"id":"b3","skill":"resolucao","title":"Passo a passo","text":"Primeiro junte os números sem x de um lado e os termos com x do outro. Depois, divida pelo número que multiplica o x.","example":"2x + 4 = 14 → 2x = 14 − 4 → 2x = 10 → x = 5. Confira: 2·5 + 4 = 14 ✓."},{"id":"b4","skill":"problemas","title":"Transformando problemas em equações","text":"Chame o valor desconhecido de x e traduza a frase em matemática: \"o dobro\" é 2x, \"o triplo\" é 3x, \"somado a\" é +.","example":"\"O dobro de um número mais 3 é 11\" → 2x + 3 = 11 → x = 4."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"conceito","prompt":"Qual é o valor de x em x + 3 = 10?","options":["13","7","3","30"],"answer":1,"hints":["Que número somado a 3 dá 10?","Desfaça a soma.","10 − 3."],"explanation":"x = 10 − 3 = 7."},{"id":"q2","type":"fill","difficulty":1,"skill":"operacoes","prompt":"Resolva: x − 4 = 9. x = ?","answers":["13"],"hints":["A subtração se desfaz com…","Some 4 aos dois lados.","9 + 4."],"explanation":"x = 9 + 4 = 13."},{"id":"q3","type":"mc","difficulty":1,"skill":"operacoes","prompt":"Resolva: 3x = 18.","options":["x = 6","x = 15","x = 21","x = 54"],"answer":0,"hints":["3x quer dizer 3 vezes x.","A multiplicação se desfaz com divisão.","18 ÷ 3."],"explanation":"x = 18 ÷ 3 = 6."},{"id":"q4","type":"tf","difficulty":1,"skill":"conceito","prompt":"Numa equação, o que fazemos de um lado devemos fazer também do outro.","answer":true,"hints":["Lembre da balança.","Tirar peso só de um lado desequilibra.","Os dois lados mudam juntos."],"explanation":"Verdadeiro. Assim a igualdade continua valendo."},{"id":"q5","type":"fill","difficulty":2,"skill":"resolucao","prompt":"Resolva: 2x + 4 = 14. x = ?","answers":["5"],"hints":["Primeiro tire o 4.","2x = 10.","Divida por 2."],"explanation":"2x = 10 → x = 5."},{"id":"q6","type":"mc","difficulty":2,"skill":"resolucao","prompt":"Resolva: 5x − 10 = 15.","options":["x = 1","x = 5","x = 25","x = 3"],"answer":1,"hints":["Some 10 aos dois lados.","5x = 25.","25 ÷ 5."],"explanation":"5x = 25 → x = 5."},{"id":"q7","type":"match","difficulty":2,"skill":"problemas","prompt":"Ligue cada frase à expressão.","pairs":[["O dobro de um número","2x"],["O triplo de um número","3x"],["Um número mais 5","x + 5"],["A metade de um número","x ÷ 2"]],"hints":["Dobro = 2 vezes.","Triplo = 3 vezes.","Metade = dividir por 2."],"explanation":"Dobro: 2x · triplo: 3x · mais 5: x + 5 · metade: x ÷ 2."},{"id":"q8","type":"mc","difficulty":3,"skill":"problemas","prompt":"O dobro de um número mais 3 é igual a 11. Que número é esse?","options":["4","7","8","14"],"answer":0,"hints":["Monte: 2x + 3 = 11.","2x = 8.","x = 8 ÷ 2."],"explanation":"2x + 3 = 11 → 2x = 8 → x = 4."},{"id":"q9","type":"fill","difficulty":3,"skill":"resolucao","prompt":"Resolva: 4x + 2 = 2x + 10. x = ?","answers":["4"],"hints":["Junte os x de um lado: 4x − 2x.","2x = 10 − 2.","2x = 8."],"explanation":"2x = 8 → x = 4. Confira: 18 = 18 ✓."},{"id":"q10","type":"tf","difficulty":3,"skill":"operacoes","prompt":"Em x ÷ 3 = 5, o valor de x é 15.","answer":true,"hints":["A divisão se desfaz com…","Multiplique os dois lados por 3.","5 × 3."],"explanation":"Verdadeiro: x = 5 × 3 = 15."}],"review":["Equação = igualdade com incógnita","Use operações inversas dos dois lados","Junte x de um lado e números do outro","Sempre confira substituindo o valor"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Álgebra","subtopic":"Equação do 2º grau","relatedQuestions":["Como usar a fórmula de Bhaskara?","Como calcular o delta?","Como achar as raízes de uma equação do segundo grau?"],"id":"mat-equacao-2-grau","subject":"matematica","title":"Equação do 2º grau","levels":["fund2","medio"],"grade":"9º ano e 1ª série","aliases":["equacao do segundo grau","equacao do 2 grau","bhaskara","baskara","delta","discriminante","equacao quadratica","raizes"],"summary":"Reconheça a equação do 2º grau, calcule o delta e encontre as raízes com a fórmula de Bhaskara.","intro":"A equação do 2º grau aparece quando a incógnita está elevada ao quadrado. Vamos por partes, sem pressa.","skills":{"forma":"Forma geral e coeficientes","delta":"Discriminante (Δ)","bhaskara":"Fórmula de Bhaskara","incompletas":"Equações incompletas"},"blocks":[{"id":"b1","skill":"forma","title":"A forma geral","text":"Toda equação do 2º grau pode ser escrita como ax² + bx + c = 0, em que a, b e c são números chamados coeficientes e a nunca é zero.","example":"Em 2x² − 3x + 1 = 0: a = 2, b = −3 e c = 1. O sinal faz parte do coeficiente!","variants":{"simples":"Se o maior expoente do x é 2 (x²), é uma equação do 2º grau. O número na frente do x² é o a, na frente do x é o b, e o número sozinho é o c.","exemplo":"x² − 5x + 6 = 0 → a = 1 (tem um \"1\" invisível na frente do x²), b = −5, c = 6.","outra":"Pense como uma ficha com três espaços: [a]x² + [b]x + [c] = 0. Seu trabalho é preencher a ficha com os números da equação, sempre levando o sinal junto.","detalhado":"Se a = 0, o termo x² desaparece e a equação passa a ser do 1º grau — por isso a ≠ 0. Antes de identificar os coeficientes, organize a equação: tudo de um lado e zero do outro. Ex.: x² = 5x − 6 vira x² − 5x + 6 = 0."}},{"id":"b2","skill":"delta","title":"O discriminante (Δ)","text":"O delta é calculado por Δ = b² − 4ac. Ele revela quantas raízes reais a equação tem: Δ > 0 → duas raízes diferentes; Δ = 0 → duas raízes iguais (uma só); Δ < 0 → nenhuma raiz real.","example":"x² − 5x + 6 = 0 → Δ = (−5)² − 4·1·6 = 25 − 24 = 1. Como 1 > 0, há duas raízes diferentes.","variants":{"simples":"Delta é uma conta que vem antes da resposta: b vezes b, menos 4 vezes a vezes c. Se der positivo, tem duas respostas. Zero, uma. Negativo, nenhuma (nos números reais).","exemplo":"x² + 2x + 5 = 0 → Δ = 4 − 20 = −16. Negativo: essa equação não tem raiz real.","outra":"O delta é como um \"detector\": antes de fazer toda a conta, ele avisa se vale a pena continuar e quantas respostas vão sair.","detalhado":"Na fórmula de Bhaskara aparece √Δ. Não existe raiz quadrada real de número negativo, por isso Δ < 0 não tem solução real. Quando Δ = 0, +√Δ e −√Δ dão o mesmo valor e as raízes coincidem: x = −b/2a."}},{"id":"b3","skill":"bhaskara","title":"A fórmula de Bhaskara","text":"Com o delta calculado, as raízes são x = (−b ± √Δ) ÷ 2a. O \"±\" gera duas contas: uma somando e outra subtraindo a raiz de delta.","example":"x² − 5x + 6 = 0, Δ = 1 → x = (5 ± 1) ÷ 2 → x₁ = 6 ÷ 2 = 3 e x₂ = 4 ÷ 2 = 2.","variants":{"simples":"Receita: 1) ache a, b, c. 2) calcule delta. 3) faça (−b + √Δ) ÷ 2a e depois (−b − √Δ) ÷ 2a.","exemplo":"x² + 2x − 8 = 0 → Δ = 4 + 32 = 36, √36 = 6 → x = (−2 ± 6) ÷ 2 → x₁ = 2 e x₂ = −4.","outra":"Sempre confira: coloque a resposta no lugar do x. Se a conta der zero, acertou. Em x² − 5x + 6 com x = 3: 9 − 15 + 6 = 0 ✓.","detalhado":"Cuidado com o −b: se b = −5, então −b = 5. Também vale a relação de soma e produto: x₁ + x₂ = −b/a e x₁ · x₂ = c/a — útil para conferir ou até resolver de cabeça."}},{"id":"b4","skill":"incompletas","title":"Equações incompletas","text":"Quando b = 0 ou c = 0 existe um caminho mais curto. Se c = 0, coloque x em evidência: x(ax + b) = 0. Se b = 0, isole o x² e tire a raiz.","example":"x² − 4x = 0 → x(x − 4) = 0 → x = 0 ou x = 4. E x² − 9 = 0 → x² = 9 → x = 3 ou x = −3.","variants":{"simples":"Falta o número sozinho? Tire o x para fora. Falta o termo com x? Passe o número para o outro lado e tire a raiz.","exemplo":"2x² − 18 = 0 → 2x² = 18 → x² = 9 → x = ±3.","outra":"Um produto só dá zero se um dos fatores for zero. Por isso x(x − 4) = 0 leva a x = 0 ou x − 4 = 0.","detalhado":"Bhaskara também funciona nas incompletas, mas é mais lento. Quando c = 0, uma das raízes é sempre zero. Quando b = 0 e −c/a > 0, as raízes são simétricas (±√(−c/a))."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"forma","prompt":"Qual destas é uma equação do 2º grau?","options":["3x + 2 = 0","x² − 5x + 6 = 0","x³ = 8","2x = 10"],"answer":1,"hints":["Procure o maior expoente do x.","No 2º grau, o maior expoente é 2.","Qual tem x²?"],"explanation":"x² − 5x + 6 = 0 tem x² como maior potência: é do 2º grau."},{"id":"q2","type":"mc","difficulty":1,"skill":"forma","prompt":"Em 2x² − 3x + 1 = 0, quais são a, b e c?","options":["a=2, b=3, c=1","a=2, b=−3, c=1","a=−3, b=2, c=1","a=1, b=−3, c=2"],"answer":1,"hints":["a acompanha x², b acompanha x.","O sinal faz parte do coeficiente.","O termo com x é −3x."],"explanation":"a = 2 (x²), b = −3 (x, com o sinal) e c = 1."},{"id":"q3","type":"tf","difficulty":1,"skill":"forma","prompt":"Em uma equação do 2º grau, o coeficiente a pode ser zero.","answer":false,"hints":["O que acontece com ax² se a = 0?","0 · x² = 0.","O x² desaparece."],"explanation":"Falso. Se a = 0 o termo x² some e a equação vira do 1º grau."},{"id":"q4","type":"fill","difficulty":2,"skill":"delta","prompt":"Calcule o Δ da equação x² − 5x + 6 = 0.","answers":["1"],"hints":["Δ = b² − 4ac.","a = 1, b = −5, c = 6.","(−5)² = 25 e 4·1·6 = 24."],"explanation":"Δ = 25 − 24 = 1."},{"id":"q5","type":"mc","difficulty":2,"skill":"delta","prompt":"Se Δ < 0, a equação:","options":["Tem duas raízes reais diferentes","Tem uma raiz real","Não tem raízes reais","Tem infinitas raízes"],"answer":2,"hints":["Na fórmula aparece √Δ.","Existe raiz quadrada real de número negativo?","Não existe."],"explanation":"Não existe raiz quadrada real de número negativo, então não há raízes reais."},{"id":"q6","type":"match","difficulty":2,"skill":"delta","prompt":"Ligue o valor do delta ao número de raízes reais.","pairs":[["Δ > 0","Duas raízes diferentes"],["Δ = 0","Duas raízes iguais"],["Δ < 0","Nenhuma raiz real"]],"hints":["Pense no ± da fórmula.","Se √Δ = 0, somar e subtrair dá o mesmo.","Negativo não tem raiz real."],"explanation":"Δ > 0: duas diferentes · Δ = 0: iguais · Δ < 0: nenhuma real."},{"id":"q7","type":"mc","difficulty":2,"skill":"bhaskara","prompt":"Quais são as raízes de x² − 5x + 6 = 0?","options":["1 e 6","2 e 3","−2 e −3","5 e 6"],"answer":1,"hints":["O Δ dessa equação é 1.","x = (5 ± 1) ÷ 2.","6 ÷ 2 e 4 ÷ 2."],"explanation":"x = (5 ± 1) ÷ 2 → 3 e 2. Conferindo: 9 − 15 + 6 = 0 ✓."},{"id":"q8","type":"fill","difficulty":2,"skill":"incompletas","prompt":"Qual é a raiz positiva de x² − 9 = 0?","answers":["3","+3"],"hints":["Não precisa de Bhaskara.","Passe o 9 para o outro lado.","x² = 9. Que número vezes ele mesmo dá 9?"],"explanation":"x² = 9 → x = ±3. A positiva é 3."},{"id":"q9","type":"mc","difficulty":3,"skill":"incompletas","prompt":"Quais são as raízes de x² − 4x = 0?","options":["0 e 4","2 e −2","4 e −4","Só 4"],"answer":0,"hints":["Falta o c.","Coloque x em evidência.","x(x − 4) = 0."],"explanation":"x(x − 4) = 0 → x = 0 ou x = 4."},{"id":"q10","type":"mc","difficulty":3,"skill":"bhaskara","prompt":"Quais são as raízes de x² + 2x − 8 = 0?","options":["2 e −4","−2 e 4","4 e 8","1 e −8"],"answer":0,"hints":["Δ = 4 − 4·1·(−8).","Δ = 36, √Δ = 6.","x = (−2 ± 6) ÷ 2."],"explanation":"Δ = 36 → x = (−2 ± 6) ÷ 2 → 2 e −4."},{"id":"q11","type":"tf","difficulty":2,"skill":"delta","prompt":"Quando Δ = 0, a equação tem duas raízes reais iguais.","answer":true,"hints":["Quanto é √0?","−b + 0 e −b − 0.","Dá o mesmo resultado."],"explanation":"Verdadeiro. Com √Δ = 0, as duas contas dão o mesmo valor."},{"id":"q12","type":"mc","difficulty":3,"skill":"bhaskara","prompt":"Quais são as raízes de 2x² − 8x + 6 = 0?","options":["1 e 3","2 e 6","−1 e −3","4 e 2"],"answer":0,"hints":["a = 2, b = −8, c = 6.","Δ = 64 − 48 = 16.","x = (8 ± 4) ÷ 4."],"explanation":"Δ = 16 → x = (8 ± 4) ÷ 4 → 3 e 1."}],"review":["Forma geral: ax² + bx + c = 0, com a ≠ 0","Δ = b² − 4ac","x = (−b ± √Δ) ÷ 2a","Incompletas: evidência (c = 0) ou isolar x² (b = 0)"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Geometria","subtopic":"Triângulo retângulo","relatedQuestions":["Como calcular a hipotenusa?","O que diz o teorema de Pitágoras?","Como achar o cateto?"],"id":"mat-teorema-pitagoras","subject":"matematica","title":"Teorema de Pitágoras","levels":["fund2","medio"],"grade":"9º ano","aliases":["pitagoras","teorema de pitagoras","triangulo retangulo","hipotenusa","catetos"],"summary":"Descubra a relação entre os lados de um triângulo retângulo e use-a para calcular medidas.","intro":"Há mais de 2 mil anos já se sabia um segredo dos triângulos com um ângulo reto. Vamos a ele!","skills":{"elementos":"Hipotenusa e catetos","teorema":"A fórmula a² = b² + c²","calculo":"Calcular um lado","aplicacoes":"Aplicações"},"blocks":[{"id":"b1","skill":"elementos","title":"O triângulo retângulo","text":"Triângulo retângulo é o que tem um ângulo de 90° (ângulo reto). O lado oposto ao ângulo reto é a hipotenusa — sempre o maior lado. Os outros dois são os catetos.","example":"No canto de uma folha de papel há um ângulo reto. A diagonal da folha faria o papel de hipotenusa."},{"id":"b2","skill":"teorema","title":"A relação de Pitágoras","text":"Em todo triângulo retângulo, o quadrado da hipotenusa é igual à soma dos quadrados dos catetos: a² = b² + c², em que a é a hipotenusa.","example":"Catetos 3 e 4: 3² + 4² = 9 + 16 = 25 = 5². A hipotenusa mede 5."},{"id":"b3","skill":"calculo","title":"Calculando o lado que falta","text":"Para achar a hipotenusa, some os quadrados dos catetos e tire a raiz. Para achar um cateto, subtraia do quadrado da hipotenusa o quadrado do outro cateto e tire a raiz.","example":"Hipotenusa 13 e cateto 5: c² = 169 − 25 = 144 → c = 12."},{"id":"b4","skill":"aplicacoes","title":"Onde isso aparece","text":"O teorema calcula distâncias em diagonal: a altura que uma escada alcança numa parede, a diagonal de uma tela ou de um terreno.","example":"Escada de 5 m com o pé a 3 m da parede alcança √(25 − 9) = 4 m de altura."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"elementos","prompt":"Num triângulo retângulo, o lado oposto ao ângulo reto se chama:","options":["Cateto","Hipotenusa","Base","Mediana"],"answer":1,"hints":["É o maior lado.","Não é cateto.","Começa com H."],"explanation":"A hipotenusa fica oposta ao ângulo de 90°."},{"id":"q2","type":"tf","difficulty":1,"skill":"elementos","prompt":"A hipotenusa é sempre o maior lado do triângulo retângulo.","answer":true,"hints":["Ela fica oposta ao maior ângulo.","O maior ângulo é o de 90°.","Maior ângulo → maior lado."],"explanation":"Verdadeiro."},{"id":"q3","type":"mc","difficulty":1,"skill":"teorema","prompt":"Qual é a fórmula do Teorema de Pitágoras (a = hipotenusa)?","options":["a = b + c","a² = b² + c²","a² = b + c","a = b² − c²"],"answer":1,"hints":["Envolve quadrados.","A hipotenusa fica sozinha de um lado.","Soma dos quadrados dos catetos."],"explanation":"a² = b² + c²."},{"id":"q4","type":"fill","difficulty":2,"skill":"calculo","prompt":"Os catetos medem 3 e 4. Quanto mede a hipotenusa?","answers":["5"],"hints":["Calcule 3² + 4².","9 + 16 = 25.","Raiz de 25."],"explanation":"a² = 25 → a = 5."},{"id":"q5","type":"fill","difficulty":2,"skill":"calculo","prompt":"Os catetos medem 6 e 8. Quanto mede a hipotenusa?","answers":["10"],"hints":["6² + 8².","36 + 64 = 100.","√100."],"explanation":"a² = 100 → a = 10."},{"id":"q6","type":"mc","difficulty":2,"skill":"calculo","prompt":"A hipotenusa mede 13 e um cateto mede 5. Quanto mede o outro cateto?","options":["8","12","18","10"],"answer":1,"hints":["c² = 13² − 5².","169 − 25 = 144.","√144."],"explanation":"c² = 144 → c = 12."},{"id":"q7","type":"match","difficulty":2,"skill":"elementos","prompt":"Ligue cada termo à descrição.","pairs":[["Hipotenusa","Maior lado, oposto ao ângulo reto"],["Catetos","Lados que formam o ângulo reto"],["Ângulo reto","Mede 90°"],["a² = b² + c²","Teorema de Pitágoras"]],"hints":["O ângulo reto é o do \"canto\".","Os catetos o formam.","A fórmula tem nome de um matemático grego."],"explanation":"Hipotenusa: maior lado · catetos: formam o ângulo reto · ângulo reto: 90° · a² = b² + c²: Pitágoras."},{"id":"q8","type":"mc","difficulty":3,"skill":"aplicacoes","prompt":"Uma escada de 5 m está apoiada numa parede, com o pé a 3 m dela. Que altura ela alcança?","options":["2 m","4 m","8 m","√34 m"],"answer":1,"hints":["A escada é a hipotenusa.","h² = 5² − 3².","25 − 9 = 16."],"explanation":"h = √16 = 4 m."},{"id":"q9","type":"tf","difficulty":3,"skill":"teorema","prompt":"O Teorema de Pitágoras vale para qualquer triângulo.","answer":false,"hints":["Releia a condição do teorema.","Precisa ter um ângulo especial.","Só com ângulo de 90°."],"explanation":"Falso. Vale apenas para triângulos retângulos."},{"id":"q10","type":"open","difficulty":3,"skill":"aplicacoes","prompt":"Explique como você usaria o Teorema de Pitágoras para descobrir a diagonal de um terreno retangular de 30 m por 40 m.","modelAnswer":"A diagonal divide o retângulo em dois triângulos retângulos. Os lados 30 e 40 são os catetos e a diagonal é a hipotenusa: d² = 30² + 40² = 900 + 1600 = 2500, então d = 50 m.","keywords":["cateto","hipotenusa","triangulo","2500","50","quadrado","raiz"],"hints":["A diagonal forma que tipo de triângulo?","Quem são os catetos?","Some 30² e 40² e tire a raiz."],"explanation":"Catetos 30 e 40, hipotenusa = diagonal = 50 m."}],"review":["Triângulo retângulo: um ângulo de 90°","Hipotenusa = maior lado; catetos formam o ângulo reto","a² = b² + c²","Serve para distâncias em diagonal"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Funções","subtopic":"Função afim","relatedQuestions":["O que é função do primeiro grau?","Como achar a raiz da função?","O que é coeficiente angular?"],"id":"mat-funcao-1-grau","subject":"matematica","title":"Função do 1º grau","levels":["medio"],"grade":"1ª série","aliases":["funcao afim","funcao do primeiro grau","funcao do 1 grau","funcao linear","coeficiente angular","grafico de funcao"],"summary":"Entenda a função f(x) = ax + b, seus coeficientes, a raiz e o gráfico em linha reta.","intro":"Funções descrevem relações: quanto mais você anda de táxi, mais paga. Vamos ver a mais simples delas.","skills":{"forma":"Forma f(x) = ax + b","coeficientes":"Coeficientes a e b","raiz":"Raiz da função","grafico":"Gráfico e crescimento"},"blocks":[{"id":"b1","skill":"forma","title":"O que é a função afim","text":"A função do 1º grau tem a forma f(x) = ax + b, com a ≠ 0. Para cada valor de x, a função devolve um único valor f(x).","example":"Táxi com bandeirada de R$ 5 e R$ 2 por km: f(x) = 2x + 5. Em 10 km: f(10) = 25 reais."},{"id":"b2","skill":"coeficientes","title":"Os coeficientes a e b","text":"O coeficiente a (angular) indica quanto f(x) muda quando x aumenta 1. O coeficiente b (linear) é o valor de f(x) quando x = 0 — o ponto onde a reta corta o eixo y.","example":"Em f(x) = 2x + 5, cada km a mais custa 2 reais (a = 2), e o valor inicial é 5 (b = 5)."},{"id":"b3","skill":"raiz","title":"A raiz (zero da função)","text":"A raiz é o valor de x que faz f(x) = 0. Basta resolver ax + b = 0, que dá x = −b/a. No gráfico, é onde a reta corta o eixo x.","example":"f(x) = 2x − 6 → 2x − 6 = 0 → x = 3."},{"id":"b4","skill":"grafico","title":"Gráfico: uma reta","text":"O gráfico da função afim é sempre uma reta. Se a > 0, a função é crescente (a reta sobe); se a < 0, é decrescente (a reta desce).","example":"f(x) = −x + 4 é decrescente: quando x aumenta, f(x) diminui."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"forma","prompt":"Qual destas é uma função do 1º grau?","options":["f(x) = x² + 1","f(x) = 3x − 2","f(x) = 5","f(x) = 1/x"],"answer":1,"hints":["A forma é ax + b.","O x não pode estar ao quadrado.","Procure \"número vezes x mais número\"."],"explanation":"f(x) = 3x − 2 tem a forma ax + b com a = 3."},{"id":"q2","type":"fill","difficulty":1,"skill":"forma","prompt":"Se f(x) = 2x + 5, quanto vale f(10)?","answers":["25"],"hints":["Troque x por 10.","2 · 10 + 5.","20 + 5."],"explanation":"f(10) = 20 + 5 = 25."},{"id":"q3","type":"mc","difficulty":1,"skill":"coeficientes","prompt":"Em f(x) = 4x − 7, qual é o coeficiente angular?","options":["4","−7","x","−3"],"answer":0,"hints":["O angular acompanha o x.","É o \"a\" de ax + b.","O número na frente do x."],"explanation":"a = 4."},{"id":"q4","type":"tf","difficulty":1,"skill":"grafico","prompt":"O gráfico de uma função do 1º grau é uma reta.","answer":true,"hints":["Pense na forma do desenho.","Não é curva.","É uma linha reta."],"explanation":"Verdadeiro."},{"id":"q5","type":"fill","difficulty":2,"skill":"raiz","prompt":"Qual é a raiz de f(x) = 2x − 6?","answers":["3"],"hints":["Faça f(x) = 0.","2x − 6 = 0.","2x = 6."],"explanation":"x = 3."},{"id":"q6","type":"mc","difficulty":2,"skill":"grafico","prompt":"A função f(x) = −3x + 1 é:","options":["Crescente","Decrescente","Constante","Não é função"],"answer":1,"hints":["Olhe o sinal de a.","a = −3.","a negativo → reta desce."],"explanation":"a < 0: decrescente."},{"id":"q7","type":"match","difficulty":2,"skill":"coeficientes","prompt":"Ligue cada termo ao significado.","pairs":[["Coeficiente a","Taxa de variação"],["Coeficiente b","Onde a reta corta o eixo y"],["Raiz","Onde a reta corta o eixo x"],["a > 0","Função crescente"]],"hints":["b é o valor quando x = 0.","A raiz faz f(x) = 0.","a positivo sobe."],"explanation":"a: variação · b: corte no eixo y · raiz: corte no eixo x · a > 0: crescente."},{"id":"q8","type":"mc","difficulty":3,"skill":"forma","prompt":"Um plano de celular custa R$ 30 fixos mais R$ 0,50 por minuto. Qual função representa o valor f(x) para x minutos?","options":["f(x) = 30x + 0,5","f(x) = 0,5x + 30","f(x) = 30,5x","f(x) = 0,5x − 30"],"answer":1,"hints":["O que depende dos minutos?","R$ 0,50 multiplica x.","O fixo é o b."],"explanation":"f(x) = 0,5x + 30."},{"id":"q9","type":"fill","difficulty":3,"skill":"raiz","prompt":"Qual é a raiz de f(x) = −4x + 12?","answers":["3"],"hints":["−4x + 12 = 0.","−4x = −12.","x = −12 ÷ −4."],"explanation":"x = 3."},{"id":"q10","type":"tf","difficulty":3,"skill":"coeficientes","prompt":"Em f(x) = 5x + 2, o gráfico corta o eixo y no ponto (0, 2).","answer":true,"hints":["O eixo y é onde x = 0.","f(0) = 5·0 + 2.","f(0) = 2."],"explanation":"Verdadeiro: f(0) = b = 2."}],"review":["f(x) = ax + b, com a ≠ 0","a = taxa de variação · b = valor inicial","Raiz: x = −b/a","a > 0 cresce · a < 0 decresce · gráfico é reta"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Matemática","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Classes gramaticais","subtopic":"Substantivo e adjetivo","relatedQuestions":["O que é substantivo?","O que é adjetivo?","Qual a diferença entre substantivo próprio e comum?"],"id":"por-substantivo-adjetivo","subject":"portugues","title":"Substantivo e adjetivo","levels":["fund1","fund2"],"grade":"3º ao 6º ano","aliases":["gramatica","substantivo","adjetivo","classes gramaticais","classes de palavras","substantivo proprio","substantivo comum","concordancia nominal"],"summary":"Aprenda a reconhecer substantivos e adjetivos e a fazer a concordância entre eles.","intro":"As palavras têm \"profissões\" diferentes numa frase. Hoje vamos conhecer duas muito importantes: o substantivo e o adjetivo.","skills":{"substantivo":"Reconhecer substantivos","tipos":"Substantivo comum e próprio","adjetivo":"Reconhecer adjetivos","concordancia":"Concordância"},"blocks":[{"id":"b1","skill":"substantivo","title":"Substantivo: a palavra que dá nome","text":"Substantivo é a palavra que dá nome a pessoas, animais, lugares, objetos, sentimentos e ideias.","example":"Em \"O cachorro correu no parque\", as palavras cachorro e parque são substantivos.","variants":{"simples":"Tudo o que tem nome é substantivo: mesa, gato, mãe, escola, alegria.","exemplo":"Olhe ao seu redor: celular, cadeira, janela, caderno. Todos esses nomes são substantivos.","outra":"Um teste: se dá para colocar \"o\", \"a\", \"um\" ou \"uma\" antes da palavra, ela provavelmente é um substantivo. \"Um sonho\", \"a amizade\", \"o lápis\".","detalhado":"Os substantivos podem ser concretos (seres com existência própria, reais ou imaginários: casa, fada) ou abstratos (dependem de outro ser para existir: saudade, beleza, coragem). Também variam em gênero (menino/menina) e número (menino/meninos)."}},{"id":"b2","skill":"tipos","title":"Comum ou próprio","text":"O substantivo comum nomeia qualquer ser de uma espécie (cidade, rio, menina). O substantivo próprio nomeia um ser específico e é escrito com letra maiúscula (Itajaí, Amazonas, Maria).","example":"\"rio\" é comum; \"Rio Amazonas\" usa um substantivo próprio para dizer qual rio.","variants":{"simples":"Comum: nome de qualquer um (cachorro). Próprio: nome de um só, com letra maiúscula (Totó).","exemplo":"Você mora numa cidade (comum). O nome da sua cidade, como Florianópolis, é próprio.","outra":"Pergunte: \"é o nome de um tipo de coisa ou o nome de alguém/lugar em especial?\". Tipo = comum. Especial = próprio.","detalhado":"Nomes de pessoas, cidades, países, rios, planetas, instituições e datas comemorativas costumam ser próprios. Um mesmo termo pode mudar: \"sol\" (qualquer estrela) × \"Sol\" (a estrela do nosso sistema)."}},{"id":"b3","skill":"adjetivo","title":"Adjetivo: a palavra que caracteriza","text":"Adjetivo é a palavra que dá uma característica ao substantivo: qualidade, estado, cor, tamanho, origem.","example":"Em \"A casa amarela é bonita\", as palavras amarela e bonita são adjetivos que caracterizam \"casa\".","variants":{"simples":"Adjetivo diz \"como é\" a coisa: grande, azul, feliz, gostoso.","exemplo":"Um cachorro. Um cachorro pequeno. Um cachorro pequeno e brincalhão. Pequeno e brincalhão são adjetivos.","outra":"Pergunte \"como é?\" para o substantivo. A resposta é o adjetivo. \"Como é o menino?\" → \"inteligente\".","detalhado":"A classe de uma palavra depende da função na frase. Em \"O velho abriu a porta\", velho nomeia a pessoa (substantivo). Em \"O homem velho abriu a porta\", velho caracteriza o homem (adjetivo). Adjetivos também têm locuções: \"amor de mãe\" = amor materno."}},{"id":"b4","skill":"concordancia","title":"Concordância","text":"O adjetivo concorda com o substantivo em gênero (masculino/feminino) e número (singular/plural).","example":"Menino cansado → meninas cansadas. Blusa bonita → blusas bonitas.","variants":{"simples":"Se o nome está no plural, o adjetivo também vai. Se o nome é feminino, o adjetivo também fica feminino.","exemplo":"\"As meninas estão cansadas\" está certo. \"As meninas estão cansado\" está errado, porque \"cansado\" não acompanhou \"meninas\".","outra":"Substantivo e adjetivo andam \"de mãos dadas\": o que acontece com um (plural, feminino) acontece com o outro.","detalhado":"Quando um adjetivo se refere a substantivos de gêneros diferentes, costuma ir para o masculino plural: \"O menino e a menina estão atentos\". Alguns adjetivos têm forma única para os dois gêneros: feliz, inteligente, azul."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"substantivo","prompt":"Em \"O cachorro correu\", qual palavra é um substantivo?","options":["O","cachorro","correu","Nenhuma"],"answer":1,"hints":["Substantivo dá nome.","Qual palavra é o nome de um animal?","Dá para dizer \"um ______\"."],"explanation":"\"Cachorro\" dá nome a um animal: é substantivo."},{"id":"q2","type":"mc","difficulty":1,"skill":"adjetivo","prompt":"Em \"A casa amarela é bonita\", quais são os adjetivos?","options":["casa e bonita","amarela e bonita","A e casa","casa e é"],"answer":1,"hints":["Adjetivo responde \"como é?\".","Como é a casa?","Tem uma cor e uma qualidade."],"explanation":"\"Amarela\" (cor) e \"bonita\" (qualidade) caracterizam a casa."},{"id":"q3","type":"tf","difficulty":1,"skill":"tipos","prompt":"\"Brasil\" é um substantivo próprio.","answer":true,"hints":["É o nome de um lugar específico?","Existe só um Brasil.","E é escrito com maiúscula."],"explanation":"Verdadeiro. Nomeia um país específico e vai com maiúscula."},{"id":"q4","type":"fill","difficulty":2,"skill":"tipos","prompt":"O substantivo próprio é escrito com letra ________.","answers":["maiuscula","maiúscula"],"hints":["Olhe como se escreve \"Maria\".","A primeira letra é grande.","O contrário de minúscula."],"explanation":"Com letra maiúscula."},{"id":"q5","type":"mc","difficulty":2,"skill":"tipos","prompt":"Qual destas palavras é um substantivo comum?","options":["Itajaí","Maria","cidade","Amazonas"],"answer":2,"hints":["Comum nomeia qualquer ser de um tipo.","Três delas estão com maiúscula.","Qual nomeia um tipo de lugar?"],"explanation":"\"Cidade\" nomeia qualquer cidade: é comum."},{"id":"q6","type":"match","difficulty":2,"skill":"adjetivo","prompt":"Ligue cada palavra à sua classe.","pairs":[["gato","Substantivo comum"],["Paulo","Substantivo próprio"],["alegre","Adjetivo"],["correr","Verbo (ação)"]],"hints":["Qual é nome de pessoa?","Qual diz \"como é\"?","Qual indica uma ação?"],"explanation":"gato → comum; Paulo → próprio; alegre → adjetivo; correr → verbo."},{"id":"q7","type":"tf","difficulty":2,"skill":"adjetivo","prompt":"Em \"o menino inteligente\", a palavra \"inteligente\" é um substantivo.","answer":false,"hints":["Como é o menino?","A palavra responde \"como é?\".","Isso é função de adjetivo."],"explanation":"Falso. \"Inteligente\" caracteriza o menino: é adjetivo."},{"id":"q8","type":"mc","difficulty":2,"skill":"concordancia","prompt":"Qual frase está com a concordância correta?","options":["As meninas estão cansado.","As meninas estão cansadas.","A meninas estão cansadas.","As menina estão cansadas."],"answer":1,"hints":["\"Meninas\" é feminino e plural.","O adjetivo acompanha.","Procure \"-as\" no adjetivo."],"explanation":"\"As meninas estão cansadas\": tudo no feminino plural."},{"id":"q9","type":"fill","difficulty":3,"skill":"concordancia","prompt":"Complete com o adjetivo \"bonito\" na forma correta: \"Comprei duas blusas ________.\"","answers":["bonitas"],"hints":["\"Blusas\" é feminino.","E está no plural.","Bonit + as."],"explanation":"\"Bonitas\", concordando com \"blusas\" (feminino plural)."},{"id":"q10","type":"mc","difficulty":3,"skill":"substantivo","prompt":"Em \"O velho abriu a porta\", a palavra \"velho\" é:","options":["Adjetivo","Substantivo","Verbo","Artigo"],"answer":1,"hints":["Aqui não existe \"homem\" na frase.","A palavra está nomeando quem abriu a porta.","Tem \"o\" antes dela."],"explanation":"Aqui \"velho\" nomeia a pessoa, funcionando como substantivo."},{"id":"q11","type":"tf","difficulty":3,"skill":"concordancia","prompt":"O adjetivo concorda em gênero e número com o substantivo.","answer":true,"hints":["Lembre do \"de mãos dadas\".","Blusa bonita → blusas bonitas.","Muda junto."],"explanation":"Verdadeiro. É a regra da concordância nominal."},{"id":"q12","type":"open","difficulty":2,"skill":"adjetivo","prompt":"Explique com suas palavras a diferença entre substantivo e adjetivo.","modelAnswer":"O substantivo dá nome às coisas, pessoas, lugares e sentimentos. O adjetivo dá uma característica ou qualidade ao substantivo. Ex.: em \"gato preto\", gato é substantivo e preto é adjetivo.","keywords":["nome","nomeia","caracteristica","qualidade","caracteriza","como e"],"hints":["Um deles dá nome.","O outro diz como a coisa é.","Use um exemplo, como \"gato preto\"."],"explanation":"Substantivo nomeia; adjetivo caracteriza o substantivo."}],"review":["Substantivo = dá nome","Comum (qualquer um) × próprio (específico, maiúscula)","Adjetivo = dá característica (\"como é?\")","Concordância em gênero e número"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Portuguesa","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Classes gramaticais","subtopic":"Verbo","relatedQuestions":["O que é verbo?","Quais são os tempos verbais?","O que é modo subjuntivo?","Como conjugar um verbo?"],"id":"por-verbos","subject":"portugues","title":"Verbos e tempos verbais","levels":["fund1","fund2"],"grade":"4º ao 7º ano","aliases":["verbo","verbos","tempos verbais","presente passado futuro","preterito","conjugacao","modo indicativo","subjuntivo","imperativo"],"summary":"Reconheça verbos, os tempos presente, passado e futuro e os modos verbais.","intro":"Os verbos contam o que acontece e quando acontece. Vamos conhecê-los!","skills":{"conceito":"O que é verbo","tempos":"Presente, pretérito e futuro","modos":"Modos verbais","conjugacao":"Concordância do verbo com a pessoa"},"blocks":[{"id":"b1","skill":"conceito","title":"Verbo indica ação, estado ou fenômeno","text":"Verbo é a palavra que indica ação (correr, estudar), estado (ser, estar, ficar) ou fenômeno da natureza (chover, ventar). Ele muda conforme o tempo e a pessoa.","example":"Ana corre. · Ana está feliz. · Choveu ontem.","variants":{"simples":"Verbo é a palavra que mostra o que alguém faz ou como está: pular, comer, ser, estar."}},{"id":"b2","skill":"tempos","title":"Presente, passado e futuro","text":"O presente indica o que acontece agora (eu estudo). O pretérito (passado) indica o que já aconteceu (eu estudei, eu estudava). O futuro indica o que ainda vai acontecer (eu estudarei).","example":"Hoje eu jogo. Ontem eu joguei. Amanhã eu jogarei.","variants":{"simples":"Agora: eu brinco. Já passou: eu brinquei. Ainda vai acontecer: eu brincarei."}},{"id":"b3","skill":"modos","title":"Os três modos","text":"Indicativo expressa certeza (Ele viaja amanhã). Subjuntivo expressa dúvida ou desejo (Talvez ele viaje; Espero que ele viaje). Imperativo expressa ordem ou pedido (Viaje com cuidado!).","example":"Estude! (imperativo) · Se eu estudasse… (subjuntivo) · Eu estudo. (indicativo)"},{"id":"b4","skill":"conjugacao","title":"O verbo acompanha a pessoa","text":"O verbo muda de forma para concordar com quem faz a ação: eu canto, tu cantas, ele canta, nós cantamos, vós cantais, eles cantam.","example":"\"Nós canta\" está errado; o correto é \"nós cantamos\".","variants":{"simples":"Eu canto, ele canta, nós cantamos, eles cantam. O verbo muda junto com quem faz."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"conceito","prompt":"Na frase \"O menino pulou o muro\", qual palavra é o verbo?","options":["menino","pulou","muro","o"],"answer":1,"hints":["Qual palavra mostra uma ação?","O que o menino fez?","Ele…"],"explanation":"\"Pulou\" indica a ação."},{"id":"q2","type":"tf","difficulty":1,"skill":"conceito","prompt":"\"Chover\" é um verbo.","answer":true,"hints":["Verbo pode indicar fenômeno da natureza.","Chuva acontece.","Choveu, choverá…"],"explanation":"Verdadeiro: indica um fenômeno da natureza."},{"id":"q3","type":"mc","difficulty":1,"skill":"tempos","prompt":"\"Eu estudei para a prova.\" O verbo está no:","options":["Presente","Passado (pretérito)","Futuro","Imperativo"],"answer":1,"hints":["A ação já aconteceu ou vai acontecer?","Já aconteceu.","Passado também se chama pretérito."],"explanation":"\"Estudei\" está no pretérito (passado)."},{"id":"q4","type":"fill","difficulty":2,"skill":"tempos","prompt":"Complete no futuro: \"Amanhã eu ______ (viajar) para a praia.\"","answers":["viajarei","vou viajar"],"hints":["Vai acontecer depois.","Futuro com \"eu\" termina em -rei.","Viaja + rei."],"explanation":"\"Viajarei\" (ou \"vou viajar\")."},{"id":"q5","type":"match","difficulty":2,"skill":"tempos","prompt":"Ligue cada frase ao tempo do verbo.","pairs":[["Eu como maçã agora.","Presente"],["Eu comi maçã ontem.","Pretérito"],["Eu comerei maçã amanhã.","Futuro"]],"hints":["Olhe as palavras \"agora\", \"ontem\" e \"amanhã\".","Ontem = passado.","Amanhã = futuro."],"explanation":"Como → presente · comi → pretérito · comerei → futuro."},{"id":"q6","type":"mc","difficulty":2,"skill":"conjugacao","prompt":"Qual frase está correta?","options":["Nós canta no coral.","Nós cantamos no coral.","Nós cantam no coral.","Nós canto no coral."],"answer":1,"hints":["O verbo concorda com \"nós\".","Com \"nós\" o verbo termina em -mos.","Canta + mos."],"explanation":"\"Nós cantamos\"."},{"id":"q7","type":"mc","difficulty":2,"skill":"modos","prompt":"\"Feche a porta, por favor!\" O verbo está no modo:","options":["Indicativo","Subjuntivo","Imperativo","Infinitivo"],"answer":2,"hints":["A frase é um pedido.","Pedido ou ordem.","Modo das ordens."],"explanation":"Imperativo: ordem ou pedido."},{"id":"q8","type":"tf","difficulty":3,"skill":"modos","prompt":"Em \"Talvez ele chegue cedo\", o verbo está no modo subjuntivo.","answer":true,"hints":["\"Talvez\" indica certeza ou dúvida?","Dúvida.","Dúvida → subjuntivo."],"explanation":"Verdadeiro: expressa dúvida."},{"id":"q9","type":"fill","difficulty":3,"skill":"conjugacao","prompt":"Complete: \"Eles ______ (estudar) todos os dias.\"","answers":["estudam"],"hints":["Presente, com \"eles\".","Com \"eles\" termina em -am.","Estud + am."],"explanation":"\"Eles estudam\"."},{"id":"q10","type":"mc","difficulty":3,"skill":"tempos","prompt":"\"Quando eu era criança, eu brincava na rua.\" O verbo \"brincava\" indica:","options":["Ação terminada num momento exato","Ação que se repetia no passado","Ação no futuro","Uma ordem"],"answer":1,"hints":["É passado.","Acontecia uma vez ou várias?","Era um costume."],"explanation":"O pretérito imperfeito (\"brincava\") indica ação habitual no passado."}],"review":["Verbo = ação, estado ou fenômeno","Presente · pretérito · futuro","Indicativo (certeza) · subjuntivo (dúvida/desejo) · imperativo (ordem)","O verbo concorda com a pessoa"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Portuguesa","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Sintaxe","subtopic":"Termos essenciais da oração","relatedQuestions":["Como encontrar o sujeito da frase?","O que é predicado?","O que é sujeito oculto?","O que é oração sem sujeito?"],"id":"por-sujeito-predicado","subject":"portugues","title":"Sujeito e predicado","levels":["fund2","medio"],"grade":"7º e 8º ano","aliases":["sujeito","predicado","analise sintatica","termos essenciais da oracao","sujeito oculto","sujeito composto","oracao sem sujeito"],"summary":"Identifique o sujeito e o predicado e conheça os tipos de sujeito.","intro":"Toda frase conta algo sobre alguém. Vamos descobrir quem é esse \"alguém\" e o que se diz dele.","skills":{"conceito":"Sujeito e predicado","identificar":"Como encontrar o sujeito","tipos":"Tipos de sujeito","sem_sujeito":"Oração sem sujeito"},"blocks":[{"id":"b1","skill":"conceito","title":"De quem se fala e o que se diz","text":"Sujeito é o termo sobre o qual se declara algo. Predicado é tudo o que se declara sobre o sujeito — e nele sempre está o verbo.","example":"\"Os alunos | fizeram a tarefa.\" Sujeito: os alunos. Predicado: fizeram a tarefa."},{"id":"b2","skill":"identificar","title":"A pergunta mágica","text":"Encontre o verbo e pergunte \"quem?\" ou \"o quê?\" antes dele. A resposta é o sujeito. O verbo concorda com o sujeito em número e pessoa.","example":"\"Chegaram as encomendas.\" O que chegou? As encomendas → sujeito (mesmo vindo depois do verbo)."},{"id":"b3","skill":"tipos","title":"Tipos de sujeito","text":"Simples: um núcleo (O cão latiu). Composto: dois ou mais núcleos (O cão e o gato brigaram). Oculto (desinencial): não aparece, mas é identificado pela terminação do verbo (Estudamos muito → nós). Indeterminado: não se sabe ou não se quer dizer quem é (Roubaram minha bicicleta).","example":"\"Fomos ao cinema\" → sujeito oculto: nós."},{"id":"b4","skill":"sem_sujeito","title":"Orações sem sujeito","text":"Algumas orações não têm sujeito: com verbos de fenômenos da natureza (Choveu muito), com \"haver\" no sentido de existir (Há dois alunos) e com \"fazer\" indicando tempo (Faz três anos).","example":"\"Nevou na serra\" não tem sujeito — ninguém \"faz\" a neve."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"conceito","prompt":"Em \"A professora explicou a matéria\", qual é o sujeito?","options":["explicou","a matéria","A professora","explicou a matéria"],"answer":2,"hints":["Ache o verbo: explicou.","Quem explicou?","A resposta é o sujeito."],"explanation":"Quem explicou? A professora."},{"id":"q2","type":"tf","difficulty":1,"skill":"conceito","prompt":"O verbo faz parte do predicado.","answer":true,"hints":["O predicado é o que se diz do sujeito.","O verbo é o centro dessa informação.","Está sempre no predicado."],"explanation":"Verdadeiro."},{"id":"q3","type":"mc","difficulty":2,"skill":"identificar","prompt":"Em \"Chegaram as encomendas\", qual é o sujeito?","options":["Chegaram","as encomendas","Não há sujeito","Nós"],"answer":1,"hints":["O sujeito pode vir depois do verbo.","O que chegou?","O verbo está no plural por causa dele."],"explanation":"\"As encomendas\" chegaram."},{"id":"q4","type":"match","difficulty":2,"skill":"tipos","prompt":"Ligue cada frase ao tipo de sujeito.","pairs":[["O cão latiu.","Simples"],["Ana e Pedro saíram.","Composto"],["Estudamos muito.","Oculto"],["Roubaram minha bicicleta.","Indeterminado"]],"hints":["Conte os núcleos.","Em \"Estudamos\", quem é?","Em \"Roubaram\", sabemos quem foi?"],"explanation":"Simples · composto · oculto (nós) · indeterminado."},{"id":"q5","type":"fill","difficulty":2,"skill":"tipos","prompt":"Em \"Fomos ao cinema\", o sujeito oculto é: ______","answers":["nos","nós"],"hints":["Olhe a terminação do verbo.","\"-mos\" indica qual pessoa?","Primeira pessoa do plural."],"explanation":"Nós (sujeito oculto)."},{"id":"q6","type":"mc","difficulty":2,"skill":"sem_sujeito","prompt":"Qual destas orações NÃO tem sujeito?","options":["Maria cantou.","Choveu a noite toda.","Os meninos correram.","Eu li o livro."],"answer":1,"hints":["Procure um fenômeno da natureza.","Quem \"faz\" a chuva?","Ninguém."],"explanation":"\"Choveu a noite toda\" é oração sem sujeito."},{"id":"q7","type":"tf","difficulty":3,"skill":"sem_sujeito","prompt":"Em \"Há muitos alunos na sala\", o sujeito é \"muitos alunos\".","answer":false,"hints":["\"Haver\" aqui significa existir.","Com esse sentido, o verbo é impessoal.","Impessoal = sem sujeito."],"explanation":"Falso. \"Haver\" = existir é impessoal: oração sem sujeito (\"muitos alunos\" é objeto direto)."},{"id":"q8","type":"mc","difficulty":3,"skill":"identificar","prompt":"Qual frase tem a concordância correta?","options":["Faltou dois alunos.","Faltaram dois alunos.","Faltou os alunos.","Faltaram o aluno."],"answer":1,"hints":["Quem faltou?","\"Dois alunos\" é o sujeito, no plural.","O verbo vai para o plural."],"explanation":"\"Faltaram dois alunos\": o verbo concorda com o sujeito."},{"id":"q9","type":"mc","difficulty":3,"skill":"tipos","prompt":"\"Precisa-se de vendedores.\" O sujeito é:","options":["Simples","Oculto","Indeterminado","Composto"],"answer":2,"hints":["Quem precisa?","A frase não diz.","Verbo + \"se\" + preposição."],"explanation":"Sujeito indeterminado (índice de indeterminação do sujeito \"se\")."},{"id":"q10","type":"open","difficulty":3,"skill":"identificar","prompt":"Explique como você descobre o sujeito de uma oração.","modelAnswer":"Encontro o verbo e pergunto \"quem?\" ou \"o quê?\" fez a ação ou sobre quem se fala. A resposta é o sujeito. Depois confiro se o verbo concorda com ele.","keywords":["verbo","quem","que","concorda","pergunta"],"hints":["Qual palavra você procura primeiro?","Que pergunta você faz?","Fale do verbo e da pergunta \"quem?\"."],"explanation":"Ache o verbo e pergunte \"quem?/o quê?\"."}],"review":["Sujeito: de quem se fala · predicado: o que se diz","Ache o verbo e pergunte \"quem?\"","Simples, composto, oculto, indeterminado","Sem sujeito: fenômenos, haver = existir, fazer (tempo)"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Portuguesa","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Leitura e produção de texto","subtopic":"Tipos e gêneros textuais","relatedQuestions":["Qual a diferença entre tipo e gênero textual?","O que é texto narrativo?","O que é texto dissertativo?","Como interpretar um texto?"],"id":"por-tipos-generos-textuais","subject":"portugues","title":"Tipos e gêneros textuais","levels":["fund2","medio"],"grade":"6º ao 9º ano","aliases":["interpretacao de texto","generos textuais","tipos textuais","texto narrativo","texto dissertativo","texto argumentativo","redacao","narracao descricao"],"summary":"Diferencie tipos textuais (narrar, descrever, argumentar…) de gêneros (notícia, crônica, receita…).","intro":"Uma receita e uma notícia são textos bem diferentes. Por quê? Vamos entender.","skills":{"tipos":"Tipos textuais","generos":"Gêneros textuais","diferenca":"Tipo × gênero","interpretacao":"Ler com objetivo"},"blocks":[{"id":"b1","skill":"tipos","title":"Os tipos textuais","text":"Tipo textual é o modo de organizar o texto. Narrativo conta fatos com personagens, tempo e lugar. Descritivo mostra como algo é. Dissertativo-argumentativo defende uma opinião com argumentos. Expositivo explica um assunto. Injuntivo dá instruções.","example":"\"Era uma vez…\" é narrativo. \"Misture a farinha e o ovo\" é injuntivo."},{"id":"b2","skill":"generos","title":"Os gêneros textuais","text":"Gênero textual é o \"formato\" que o texto tem no dia a dia, com uma função social: notícia, crônica, conto, receita, bula, carta, e-mail, anúncio, artigo de opinião.","example":"A receita serve para ensinar a preparar um prato; a notícia, para informar um fato recente."},{"id":"b3","skill":"diferenca","title":"Tipo × gênero","text":"Os tipos são poucos e fixos; os gêneros são muitos e surgem novos com o tempo (como o post de rede social). Um mesmo gênero pode misturar tipos: um conto narra e também descreve.","example":"Receita (gênero) usa principalmente o tipo injuntivo."},{"id":"b4","skill":"interpretacao","title":"Ler com objetivo","text":"Para interpretar, identifique o gênero e a finalidade do texto, quem escreveu e para quem, a ideia principal de cada parágrafo e as palavras que mostram opinião.","example":"Num artigo de opinião, expressões como \"é inaceitável\" revelam a posição do autor."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"tipos","prompt":"Um texto que começa com \"Era uma vez uma menina que…\" é do tipo:","options":["Descritivo","Narrativo","Injuntivo","Argumentativo"],"answer":1,"hints":["Ele conta uma história?","Tem personagem e acontecimentos.","Contar = narrar."],"explanation":"Narrativo: conta uma história."},{"id":"q2","type":"mc","difficulty":1,"skill":"generos","prompt":"Qual destes é um gênero textual?","options":["Narração","Receita","Descrição","Injunção"],"answer":1,"hints":["Gênero é o formato do dia a dia.","Três opções são tipos.","Qual você encontra num livro de culinária?"],"explanation":"Receita é um gênero; as outras são tipos."},{"id":"q3","type":"tf","difficulty":1,"skill":"tipos","prompt":"O texto injuntivo dá instruções ou ordens.","answer":true,"hints":["Pense num manual.","\"Aperte o botão…\"","Instrução = injunção."],"explanation":"Verdadeiro."},{"id":"q4","type":"match","difficulty":2,"skill":"generos","prompt":"Ligue cada gênero à sua principal função.","pairs":[["Notícia","Informar um fato recente"],["Receita","Ensinar a preparar algo"],["Artigo de opinião","Defender um ponto de vista"],["Anúncio","Convencer a comprar ou aderir"]],"hints":["Qual quer vender?","Qual informa?","Qual defende uma ideia?"],"explanation":"Notícia informa, receita ensina, artigo opina, anúncio convence."},{"id":"q5","type":"mc","difficulty":2,"skill":"tipos","prompt":"\"A casa era pequena, com janelas azuis e um jardim florido.\" Esse trecho é predominantemente:","options":["Narrativo","Descritivo","Argumentativo","Injuntivo"],"answer":1,"hints":["Acontece alguma ação?","Ele mostra como a casa é.","Mostrar características = descrever."],"explanation":"Descritivo: apresenta características."},{"id":"q6","type":"tf","difficulty":2,"skill":"diferenca","prompt":"Existem muito mais gêneros textuais do que tipos textuais.","answer":true,"hints":["Os tipos são poucos.","Gêneros surgem com o tempo.","Ex.: post, meme, podcast…"],"explanation":"Verdadeiro."},{"id":"q7","type":"fill","difficulty":2,"skill":"tipos","prompt":"O tipo de texto que defende uma opinião com argumentos é o dissertativo-________.","answers":["argumentativo"],"hints":["Usa argumentos.","Argument…","É o tipo da redação do ENEM."],"explanation":"Dissertativo-argumentativo."},{"id":"q8","type":"mc","difficulty":3,"skill":"interpretacao","prompt":"Num artigo de opinião, qual expressão mostra mais claramente a posição do autor?","options":["\"Segundo o IBGE, a população cresceu.\"","\"É inaceitável que isso continue.\"","\"O evento ocorreu na segunda-feira.\"","\"A pesquisa ouviu 2 mil pessoas.\""],"answer":1,"hints":["Procure uma avaliação, não um dado.","Palavras que julgam.","\"Inaceitável\" é um julgamento."],"explanation":"\"É inaceitável\" expressa opinião; as outras apresentam fatos."},{"id":"q9","type":"mc","difficulty":3,"skill":"diferenca","prompt":"Um conto costuma ser:","options":["Um tipo textual injuntivo","Um gênero em que predomina a narração","Um gênero sem descrição","Um tipo textual expositivo"],"answer":1,"hints":["Conto é tipo ou gênero?","É gênero.","Ele conta uma história."],"explanation":"Conto é um gênero de tipo predominantemente narrativo."},{"id":"q10","type":"open","difficulty":3,"skill":"diferenca","prompt":"Explique a diferença entre tipo textual e gênero textual, dando um exemplo.","modelAnswer":"Tipo textual é o modo de organização do texto, como narrar, descrever, argumentar, expor ou instruir. Gênero textual é o formato usado no dia a dia com uma função social, como notícia, receita ou carta. Por exemplo, a receita é um gênero que usa o tipo injuntivo.","keywords":["tipo","genero","narrar","narrativo","funcao","formato","receita","noticia","injuntivo"],"hints":["Quais são os tipos?","Quais são alguns gêneros?","Dê o exemplo da receita."],"explanation":"Tipo = modo de organizar; gênero = formato social."}],"review":["Tipos: narrativo, descritivo, argumentativo, expositivo, injuntivo","Gêneros: notícia, receita, crônica, carta…","Gêneros misturam tipos","Interpretar: finalidade, autor, ideia principal"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Portuguesa","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Plantas","subtopic":"Fotossíntese","relatedQuestions":["Como as plantas produzem seu próprio alimento?","Como a planta se alimenta?","Por que as folhas são verdes?","Como as plantas fazem comida?","Para que serve a clorofila?"],"id":"cie-fotossintese","subject":"ciencias","title":"Fotossíntese","levels":["fund1","fund2","medio"],"grade":"6º e 7º ano","aliases":["fotossintese","clorofila","cloroplasto","como as plantas se alimentam","plantas produzem alimento"],"summary":"Descubra como as plantas fabricam o próprio alimento usando luz, água e gás carbônico.","intro":"As plantas não comem como nós. Elas fabricam o próprio alimento — e ainda liberam o oxigênio que respiramos.","skills":{"conceito":"O que é fotossíntese","ingredientes":"O que a planta usa","produtos":"O que a planta produz","importancia":"Importância para a vida"},"blocks":[{"id":"b1","skill":"conceito","title":"O que é fotossíntese","text":"Fotossíntese é o processo em que plantas, algas e algumas bactérias usam a energia da luz para produzir o próprio alimento. \"Foto\" quer dizer luz e \"síntese\" quer dizer produção.","example":"Uma planta num vaso perto da janela cresce usando a luz do sol. Sem luz, ela fica fraca e amarelada.","variants":{"simples":"A planta é como uma cozinha movida a luz do sol: ela pega luz e faz a própria comida.","exemplo":"Por isso colocamos as plantas perto da janela. Se deixarmos um vaso num armário escuro por semanas, a planta enfraquece porque não consegue fazer a fotossíntese.","outra":"Nós precisamos comer para ter energia. A planta não: ela transforma a energia da luz em energia guardada num açúcar, e usa esse açúcar para viver e crescer.","detalhado":"A fotossíntese acontece em duas etapas: na fase clara, a energia luminosa é captada pela clorofila e a água é quebrada, liberando oxigênio; na fase escura (que não precisa de luz diretamente), o gás carbônico é fixado e transformado em glicose."}},{"id":"b2","skill":"ingredientes","title":"Os ingredientes","text":"A planta precisa de água (absorvida pelas raízes), gás carbônico (que entra pelas folhas, por pequenas aberturas chamadas estômatos) e luz. Quem capta a luz é a clorofila, um pigmento verde que fica dentro dos cloroplastos.","example":"É por causa da clorofila que a maioria das folhas é verde.","variants":{"simples":"A receita da planta: água + gás carbônico do ar + luz do sol. A parte verde da folha (clorofila) é quem \"pega\" a luz.","exemplo":"Quando você rega uma planta, a água sobe da raiz até a folha. Ao mesmo tempo, a folha \"puxa\" gás carbônico do ar. Com a luz do sol, está tudo pronto.","outra":"Pense numa fábrica: a água chega por um cano (raiz), o gás carbônico entra pelas janelas (estômatos), e a clorofila é o painel solar que liga as máquinas.","detalhado":"Os cloroplastos são organelas presentes principalmente nas células das folhas. A clorofila absorve bem luz vermelha e azul e reflete o verde. A água é transportada pelo xilema, e a abertura dos estômatos controla a entrada de CO₂ e a perda de água."}},{"id":"b3","skill":"produtos","title":"O que a planta produz","text":"O resultado da fotossíntese é a glicose (um açúcar que é o alimento da planta) e o gás oxigênio, que é liberado no ar. Resumindo: gás carbônico + água + luz → glicose + oxigênio.","example":"Parte da glicose vira amido e fica guardada, como na batata e na mandioca.","variants":{"simples":"A planta faz duas coisas: açúcar para ela comer e oxigênio, que ela solta no ar para a gente respirar.","exemplo":"A batata que você come é a reserva de alimento que a planta guardou depois de fazer fotossíntese.","outra":"Entra: gás carbônico e água. Sai: açúcar (glicose) e oxigênio. A luz é a energia que faz essa troca acontecer.","detalhado":"A equação geral é 6 CO₂ + 6 H₂O → C₆H₁₂O₆ + 6 O₂, na presença de luz e clorofila. O oxigênio liberado vem da quebra das moléculas de água. Lembre que as plantas também respiram: usam oxigênio para quebrar a glicose e liberar energia, dia e noite."}},{"id":"b4","skill":"importancia","title":"Por que isso importa para todos","text":"A fotossíntese produz grande parte do oxigênio da atmosfera e é a base das cadeias alimentares: as plantas são produtoras e todos os outros seres dependem delas, direta ou indiretamente.","example":"O capim faz fotossíntese, o boi come o capim e nós comemos alimentos que vêm dessa cadeia.","variants":{"simples":"Sem as plantas, faltaria oxigênio para respirar e comida para os animais.","exemplo":"Uma lagarta come a folha, um passarinho come a lagarta. Tudo começou com a energia da luz que a folha guardou.","outra":"As plantas são o \"primeiro elo\" da corrente: elas transformam luz em alimento, e o resto da natureza vai passando essa energia adiante.","detalhado":"Por serem autótrofos, os seres fotossintetizantes são produtores. As algas marinhas (fitoplâncton) respondem por boa parte do oxigênio produzido no planeta. A fotossíntese também retira CO₂ da atmosfera, o que se relaciona com o controle do efeito estufa."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"conceito","prompt":"A fotossíntese é o processo em que as plantas:","options":["Absorvem comida do solo","Produzem o próprio alimento usando luz","Dormem durante a noite","Liberam gás carbônico para crescer"],"answer":1,"hints":["\"Foto\" significa luz.","\"Síntese\" significa produção.","Produção com luz."],"explanation":"Na fotossíntese, a planta produz o próprio alimento (glicose) usando a energia da luz."},{"id":"q2","type":"tf","difficulty":1,"skill":"produtos","prompt":"A fotossíntese libera gás oxigênio.","answer":true,"hints":["Pense no que respiramos.","A planta produz açúcar e mais uma coisa.","Essa outra coisa vai para o ar."],"explanation":"Verdadeiro. O oxigênio é um dos produtos da fotossíntese."},{"id":"q3","type":"fill","difficulty":1,"skill":"ingredientes","prompt":"O pigmento verde que capta a luz se chama ________.","answers":["clorofila"],"hints":["É ele que deixa a folha verde.","Começa com \"cloro\".","Cloro + fila."],"explanation":"A clorofila é o pigmento verde que absorve a luz."},{"id":"q4","type":"mc","difficulty":2,"skill":"ingredientes","prompt":"Qual destes NÃO é usado pela planta para fazer fotossíntese?","options":["Luz","Água","Gás carbônico","Gás oxigênio"],"answer":3,"hints":["Separe o que entra do que sai.","Entra: luz, água e gás carbônico.","Um dos itens é um produto, não um ingrediente."],"explanation":"O oxigênio é produzido (sai), não é usado para fazer fotossíntese."},{"id":"q5","type":"mc","difficulty":2,"skill":"ingredientes","prompt":"Em que parte da planta a fotossíntese acontece principalmente?","options":["Raiz","Folhas","Flores","Sementes"],"answer":1,"hints":["Onde fica a maior parte da clorofila?","É a parte que mais recebe luz.","É verde e larga."],"explanation":"Nas folhas, onde há muitos cloroplastos com clorofila."},{"id":"q6","type":"mc","difficulty":2,"skill":"produtos","prompt":"Qual açúcar a planta produz na fotossíntese?","options":["Sacarose","Glicose","Lactose","Frutose"],"answer":1,"hints":["É o mesmo açúcar que nosso corpo usa como energia.","Começa com \"gli\".","Gli + cose."],"explanation":"A glicose é o açúcar produzido; parte dela pode ser guardada como amido."},{"id":"q7","type":"match","difficulty":2,"skill":"ingredientes","prompt":"Ligue cada ingrediente ao seu papel.","pairs":[["Água","Absorvida pelas raízes"],["Gás carbônico","Entra pelas folhas"],["Luz","Fornece a energia"],["Clorofila","Capta a luz"]],"hints":["Pense por onde cada um chega.","A raiz fica no solo, que é úmido.","A clorofila é o \"painel solar\"."],"explanation":"Água pela raiz, gás carbônico pelas folhas (estômatos), a luz dá energia e a clorofila a capta."},{"id":"q8","type":"tf","difficulty":2,"skill":"conceito","prompt":"As plantas fazem fotossíntese no escuro total.","answer":false,"hints":["Qual é a fonte de energia da fotossíntese?","Sem ela, o processo para.","No escuro não há luz."],"explanation":"Falso. Sem luz, a planta não capta energia e a fotossíntese não acontece."},{"id":"q9","type":"fill","difficulty":3,"skill":"ingredientes","prompt":"A organela onde ocorre a fotossíntese é o ________.","answers":["cloroplasto","cloroplastos"],"hints":["É onde a clorofila fica guardada.","Começa igual a clorofila.","Cloro + plasto."],"explanation":"O cloroplasto é a organela que contém a clorofila."},{"id":"q10","type":"mc","difficulty":3,"skill":"importancia","prompt":"Por que a fotossíntese é importante para os animais?","options":["Porque aquece o planeta","Porque produz oxigênio e é a base das cadeias alimentares","Porque produz água","Porque elimina todos os gases"],"answer":1,"hints":["Pense no que os animais respiram.","E no que os animais comem.","As plantas são produtoras."],"explanation":"Ela libera oxigênio e é o início das cadeias alimentares."},{"id":"q11","type":"tf","difficulty":3,"skill":"produtos","prompt":"As plantas também respiram, consumindo oxigênio.","answer":true,"hints":["Toda célula viva precisa liberar energia.","Isso acontece dia e noite.","É a respiração celular."],"explanation":"Verdadeiro. As plantas respiram o tempo todo; de dia, a fotossíntese costuma produzir mais oxigênio do que elas consomem."},{"id":"q12","type":"open","difficulty":3,"skill":"importancia","prompt":"O que aconteceria com os animais se todas as plantas parassem de fazer fotossíntese?","modelAnswer":"Faltaria alimento, porque as plantas são a base das cadeias alimentares, e o oxigênio do ar diminuiria com o tempo. Os animais não conseguiriam sobreviver.","keywords":["oxigenio","alimento","comida","cadeia","morrer","sobreviver"],"hints":["Pense em duas coisas que vêm das plantas.","Uma delas respiramos.","A outra está no começo da cadeia alimentar."],"explanation":"Os animais perderiam a fonte de alimento e, aos poucos, o oxigênio."}],"review":["Fotossíntese = produzir alimento com luz","Usa: água, gás carbônico e luz (clorofila capta)","Produz: glicose e oxigênio","Base das cadeias alimentares"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências da Natureza","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Terra e Universo","subtopic":"Sistema Solar","relatedQuestions":["Quantos planetas existem?","Qual é o maior planeta?","Por que existe dia e noite?","O Sol é uma estrela?"],"id":"cie-sistema-solar","subject":"ciencias","title":"Sistema Solar","levels":["fund1","fund2"],"grade":"3º ao 6º ano","aliases":["sistema solar","planetas","sol","rotacao","translacao","movimentos da terra","astronomia"],"summary":"Conheça o Sol, os oito planetas e os movimentos da Terra.","intro":"Vamos fazer uma viagem pelo espaço, começando pela nossa estrela: o Sol.","skills":{"sol":"O Sol","planetas":"Os planetas","tipos":"Planetas rochosos e gasosos","movimentos":"Movimentos da Terra"},"blocks":[{"id":"b1","skill":"sol","title":"O Sol, nossa estrela","text":"O Sol é uma estrela: uma enorme bola de gases muito quentes que produz luz e calor. Ele fica no centro do Sistema Solar, e tudo gira ao redor dele.","example":"As estrelas que vemos à noite também são sóis, só que estão muito mais longe.","variants":{"simples":"O Sol é uma estrela. Ele dá luz e calor para a Terra.","exemplo":"Sem o Sol não haveria dia, as plantas não cresceriam e a Terra seria gelada.","outra":"Imagine uma fogueira gigante no meio de uma roda. Os planetas ficam dando voltas ao redor dela. Essa fogueira é o Sol.","detalhado":"O Sol concentra mais de 99% da massa do Sistema Solar. Sua gravidade mantém os planetas em órbita. Plutão, que já foi chamado de planeta, hoje é classificado como planeta anão."}},{"id":"b2","skill":"planetas","title":"Os oito planetas","text":"Em ordem, a partir do Sol: Mercúrio, Vênus, Terra, Marte, Júpiter, Saturno, Urano e Netuno. A Terra é o terceiro planeta, e Júpiter é o maior de todos.","example":"Uma frase para lembrar: \"Minha Vó Tem Muitas Joias, Só Usa No Natal\".","variants":{"simples":"São 8 planetas. O mais perto do Sol é Mercúrio. A Terra é o 3º. O maior é Júpiter.","exemplo":"Se o Sol fosse do tamanho de uma porta, a Terra seria do tamanho de uma moeda pequena, e Júpiter de uma bola de tênis.","outra":"Use as iniciais: M-V-T-M-J-S-U-N. Cada palavra da frase \"Minha Vó Tem Muitas Joias, Só Usa No Natal\" começa com a letra de um planeta.","detalhado":"Os planetas giram em órbitas quase circulares. Quanto mais longe do Sol, mais tempo leva para dar uma volta: Mercúrio leva cerca de 88 dias, a Terra cerca de 365, e Netuno cerca de 165 anos terrestres."}},{"id":"b3","skill":"tipos","title":"Rochosos e gasosos","text":"Os quatro primeiros (Mercúrio, Vênus, Terra e Marte) são rochosos: têm superfície sólida. Os quatro últimos (Júpiter, Saturno, Urano e Netuno) são gigantes gasosos, muito maiores e formados principalmente por gases.","example":"Um robô pode pousar em Marte. Em Júpiter, não haveria chão para pousar.","variants":{"simples":"Os 4 mais perto do Sol são de pedra. Os 4 mais longe são enormes e feitos de gás.","exemplo":"A Terra tem montanhas e chão. Saturno é uma bola gigante de gás com anéis ao redor.","outra":"Pense em dois times: o time pequeno e duro (rochosos) perto do Sol, e o time gigante e \"fofo\" (gasosos) lá longe.","detalhado":"Os gasosos são formados principalmente por hidrogênio e hélio; Urano e Netuno também são chamados de gigantes de gelo. Todos os gasosos possuem anéis, embora os de Saturno sejam os mais visíveis."}},{"id":"b4","skill":"movimentos","title":"Os movimentos da Terra","text":"A Terra gira em torno de si mesma (rotação), e isso leva cerca de 24 horas, formando o dia e a noite. Ela também dá uma volta ao redor do Sol (translação), que leva cerca de 365 dias: um ano.","example":"Quando é dia no Brasil, é noite no Japão, porque cada lado da Terra está virado para o Sol em momentos diferentes.","variants":{"simples":"Girando em volta de si mesma: dia e noite (24 horas). Girando em volta do Sol: um ano (365 dias).","exemplo":"Gire uma bola perto de uma lanterna: o lado iluminado é o dia, o lado escuro é a noite. Agora ande com a bola em volta da lanterna: isso é a translação.","outra":"Rotação = Roda em si mesma. Translação = Trajeto ao redor do Sol.","detalhado":"A translação leva cerca de 365 dias e 6 horas — por isso, a cada 4 anos, somamos um dia (ano bissexto). A inclinação do eixo da Terra, combinada com a translação, causa as estações do ano."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"sol","prompt":"O Sol é:","options":["Um planeta","Uma estrela","Um satélite","Um cometa"],"answer":1,"hints":["Ele produz luz própria.","Os planetas não produzem luz.","As que brilham à noite são do mesmo tipo."],"explanation":"O Sol é uma estrela: produz luz e calor."},{"id":"q2","type":"fill","difficulty":1,"skill":"planetas","prompt":"Quantos planetas existem no Sistema Solar? (número)","answers":["8","oito"],"hints":["Lembre da frase da vó.","Conte as palavras de \"Minha Vó Tem Muitas Joias, Só Usa No Natal\".","São menos que 10."],"explanation":"São 8 planetas."},{"id":"q3","type":"mc","difficulty":1,"skill":"planetas","prompt":"Qual planeta fica mais perto do Sol?","options":["Terra","Vênus","Mercúrio","Marte"],"answer":2,"hints":["É o primeiro da lista.","A frase começa com \"Minha\".","Começa com M e não é Marte."],"explanation":"Mercúrio é o primeiro planeta a partir do Sol."},{"id":"q4","type":"tf","difficulty":1,"skill":"movimentos","prompt":"O dia e a noite acontecem por causa da rotação da Terra.","answer":true,"hints":["Qual movimento leva 24 horas?","É a Terra girando em si mesma.","Rotação = roda em si mesma."],"explanation":"Verdadeiro. A rotação faz cada lado da Terra ficar virado para o Sol em momentos diferentes."},{"id":"q5","type":"mc","difficulty":2,"skill":"planetas","prompt":"Qual é o maior planeta do Sistema Solar?","options":["Saturno","Júpiter","Netuno","Terra"],"answer":1,"hints":["É um gigante gasoso.","É o quinto planeta.","Começa com J."],"explanation":"Júpiter é o maior planeta."},{"id":"q6","type":"match","difficulty":2,"skill":"movimentos","prompt":"Ligue cada item à sua descrição.","pairs":[["Rotação","Forma o dia e a noite"],["Translação","Volta ao redor do Sol"],["Lua","Satélite natural da Terra"],["Sol","Estrela no centro"]],"hints":["Rotação: roda em si mesma.","Translação: trajeto ao redor do Sol.","A Lua gira ao redor da Terra."],"explanation":"Rotação → dia e noite; Translação → ano; Lua → satélite; Sol → estrela."},{"id":"q7","type":"tf","difficulty":2,"skill":"tipos","prompt":"Júpiter é um planeta rochoso.","answer":false,"hints":["Onde Júpiter fica na lista?","Os 4 últimos são de um tipo.","Os últimos são gasosos."],"explanation":"Falso. Júpiter é um gigante gasoso."},{"id":"q8","type":"mc","difficulty":2,"skill":"tipos","prompt":"Quais são os planetas rochosos?","options":["Júpiter, Saturno, Urano e Netuno","Mercúrio, Vênus, Terra e Marte","Terra, Marte, Júpiter e Saturno","Só a Terra"],"answer":1,"hints":["São os mais próximos do Sol.","São os 4 primeiros.","A Terra está entre eles."],"explanation":"Os rochosos são os quatro primeiros: Mercúrio, Vênus, Terra e Marte."},{"id":"q9","type":"fill","difficulty":2,"skill":"movimentos","prompt":"A translação da Terra dura cerca de ____ dias.","answers":["365","365 dias"],"hints":["É o tempo de um ano.","Um ano tem mais de 300 dias.","3-6-5."],"explanation":"Cerca de 365 dias — um ano."},{"id":"q10","type":"mc","difficulty":3,"skill":"planetas","prompt":"Qual é a posição da Terra a partir do Sol?","options":["Primeira","Segunda","Terceira","Quarta"],"answer":2,"hints":["Mercúrio é o 1º.","Vênus é o 2º.","Quem vem depois de Vênus?"],"explanation":"A Terra é o terceiro planeta."},{"id":"q11","type":"tf","difficulty":3,"skill":"sol","prompt":"Plutão é considerado um planeta anão.","answer":true,"hints":["Plutão já foi chamado de planeta.","Em 2006 a classificação mudou.","Hoje é de uma categoria menor."],"explanation":"Verdadeiro. Desde 2006, Plutão é classificado como planeta anão."},{"id":"q12","type":"mc","difficulty":3,"skill":"movimentos","prompt":"Quanto tempo dura, aproximadamente, a rotação da Terra?","options":["12 horas","24 horas","7 dias","365 dias"],"answer":1,"hints":["A rotação forma o dia e a noite.","Um dia completo inclui a noite.","Quantas horas tem um dia?"],"explanation":"Cerca de 24 horas: um dia completo."}],"review":["O Sol é uma estrela","8 planetas: Mercúrio, Vênus, Terra, Marte, Júpiter, Saturno, Urano, Netuno","Rochosos (4 primeiros) × gasosos (4 últimos)","Rotação = dia/noite (24 h) · Translação = ano (365 dias)"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências da Natureza","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"games":{"words":[{"word":"Mercúrio","clue":"o planeta mais perto do Sol","difficulty":1},{"word":"Vênus","clue":"segundo planeta","difficulty":1},{"word":"Terra","clue":"o nosso planeta","difficulty":1},{"word":"Marte","clue":"o planeta vermelho","difficulty":1},{"word":"Júpiter","clue":"o maior planeta","difficulty":2},{"word":"Saturno","clue":"famoso pelos anéis","difficulty":2},{"word":"Urano","clue":"sétimo planeta","difficulty":3},{"word":"Netuno","clue":"o planeta mais distante do Sol","difficulty":3}],"sequences":[{"prompt":"Coloque os planetas em ordem de distância do Sol.","difficulty":2,"items":["Mercúrio","Vênus","Terra","Marte","Júpiter","Saturno","Urano","Netuno"],"explanation":"Mercúrio, Vênus, Terra, Marte, Júpiter, Saturno, Urano e Netuno."}]},"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Água","subtopic":"Ciclo hidrológico","relatedQuestions":["Como a chuva se forma?","Como as nuvens se formam?","Para onde vai a água da chuva?","O que é evaporação?"],"id":"cie-ciclo-da-agua","subject":"ciencias","title":"Ciclo da água","levels":["fund1","fund2"],"grade":"3º ao 6º ano","aliases":["ciclo da agua","ciclo hidrologico","evaporacao","condensacao","precipitacao","chuva","estados fisicos da agua","como a chuva se forma"],"summary":"Veja como a água viaja entre o mar, o céu e a terra: evaporação, condensação, precipitação e infiltração.","intro":"A água da chuva de hoje pode ter estado no oceano semana passada. Vamos acompanhar essa viagem!","skills":{"evaporacao":"Evaporação e transpiração","condensacao":"Condensação e nuvens","precipitacao":"Precipitação","retorno":"Infiltração e escoamento"},"blocks":[{"id":"b1","skill":"evaporacao","title":"A água sobe: evaporação","text":"O calor do Sol aquece a água de mares, rios e lagos, e ela passa do estado líquido para o gasoso (vapor), subindo para a atmosfera. As plantas também liberam vapor pelas folhas: é a transpiração.","example":"Uma roupa molhada seca no varal porque a água evapora.","variants":{"simples":"O Sol esquenta a água, e ela vira vapor, que sobe para o céu. Invisível!"}},{"id":"b2","skill":"condensacao","title":"As nuvens se formam: condensação","text":"Lá em cima o ar é mais frio. O vapor esfria e volta a virar gotinhas de água líquida, que se juntam e formam as nuvens.","example":"Um copo com água gelada fica \"suado\" por fora: o vapor do ar condensa no vidro frio.","variants":{"simples":"No alto é frio. O vapor vira gotinhas, e muitas gotinhas juntas formam as nuvens."}},{"id":"b3","skill":"precipitacao","title":"A água cai: precipitação","text":"Quando as gotinhas das nuvens ficam grandes e pesadas, caem como chuva. Em lugares muito frios, podem cair como neve ou granizo.","example":"Nuvens escuras e carregadas costumam anunciar chuva forte.","variants":{"simples":"Quando as gotas ficam pesadas, caem: é a chuva."}},{"id":"b4","skill":"retorno","title":"A água volta: infiltração e escoamento","text":"Parte da chuva infiltra no solo e forma a água subterrânea (lençol freático). Outra parte escorre pela superfície até rios, lagos e mares. E o ciclo recomeça.","example":"Em cidades com muito asfalto, a água não infiltra e escorre pelas ruas, causando enchentes.","variants":{"simples":"A chuva entra na terra ou escorre até os rios e o mar. Depois tudo começa de novo."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"evaporacao","prompt":"O que faz a água dos rios e mares evaporar?","options":["O frio","O calor do Sol","O vento sozinho","A Lua"],"answer":1,"hints":["A evaporação precisa de energia.","Essa energia vem do céu de dia.","Ela esquenta a água."],"explanation":"O calor do Sol transforma a água líquida em vapor."},{"id":"q2","type":"mc","difficulty":1,"skill":"condensacao","prompt":"Como as nuvens se formam?","options":["O vapor esfria e vira gotinhas","A fumaça das fábricas","A água do mar voa","O Sol cria nuvens"],"answer":0,"hints":["Lá em cima é mais frio.","O que acontece com o vapor no frio?","Ele vira líquido de novo."],"explanation":"O vapor condensa em gotinhas que formam as nuvens."},{"id":"q3","type":"tf","difficulty":1,"skill":"precipitacao","prompt":"A chuva é um tipo de precipitação.","answer":true,"hints":["Precipitação = água caindo do céu.","A chuva cai do céu?","Sim."],"explanation":"Verdadeiro. Neve e granizo também são precipitação."},{"id":"q4","type":"fill","difficulty":2,"skill":"condensacao","prompt":"A passagem do vapor para gotinhas de água se chama ________.","answers":["condensacao","condensação"],"hints":["Acontece quando o vapor esfria.","Forma as nuvens.","Conden…"],"explanation":"Condensação."},{"id":"q5","type":"match","difficulty":2,"skill":"retorno","prompt":"Ligue cada etapa ao que acontece.","pairs":[["Evaporação","Água vira vapor e sobe"],["Condensação","Vapor forma nuvens"],["Precipitação","Água cai como chuva"],["Infiltração","Água entra no solo"]],"hints":["Sobe, forma nuvem, cai, entra na terra.","Precipitação = cair.","Infiltrar = entrar."],"explanation":"Evaporação → condensação → precipitação → infiltração."},{"id":"q6","type":"tf","difficulty":2,"skill":"evaporacao","prompt":"As plantas também liberam vapor de água para a atmosfera.","answer":true,"hints":["Pense nas folhas.","Esse processo se chama transpiração.","Ele faz parte do ciclo."],"explanation":"Verdadeiro: é a transpiração das plantas."},{"id":"q7","type":"mc","difficulty":2,"skill":"condensacao","prompt":"Por que um copo com água gelada fica molhado por fora?","options":["A água atravessa o vidro","O vapor do ar condensa no vidro frio","O copo derrete","A água evapora de dentro"],"answer":1,"hints":["O vidro está frio.","O ar tem vapor invisível.","Vapor + frio = ?"],"explanation":"O vapor do ar esfria no vidro e condensa."},{"id":"q8","type":"mc","difficulty":3,"skill":"retorno","prompt":"Por que cidades com muito asfalto têm mais enchentes?","options":["Porque chove mais nas cidades","Porque a água não consegue infiltrar no solo","Porque o asfalto produz água","Porque não há evaporação"],"answer":1,"hints":["Asfalto deixa a água entrar na terra?","Não deixa.","Então ela escorre."],"explanation":"Sem infiltração, a água escorre toda pela superfície."},{"id":"q9","type":"fill","difficulty":3,"skill":"retorno","prompt":"A água que infiltra e fica guardada no subsolo forma o lençol ________.","answers":["freatico","freático"],"hints":["Fica embaixo da terra.","De onde vêm os poços.","Lençol frea…"],"explanation":"Lençol freático."},{"id":"q10","type":"open","difficulty":3,"skill":"precipitacao","prompt":"Explique com suas palavras como a água do mar pode virar chuva em outro lugar.","modelAnswer":"O Sol aquece o mar e a água evapora. O vapor sobe, esfria e condensa formando nuvens. O vento leva as nuvens, e quando as gotas ficam pesadas elas caem como chuva em outro lugar.","keywords":["evapora","vapor","nuvem","condensa","chuva","sol","vento"],"hints":["Comece pelo Sol.","Depois fale das nuvens.","Termine com a chuva caindo."],"explanation":"Evaporação → condensação → transporte pelo vento → precipitação."}],"review":["Evaporação: o Sol transforma água em vapor","Condensação: vapor esfria e forma nuvens","Precipitação: chuva, neve, granizo","Infiltração e escoamento devolvem a água"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências da Natureza","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Corpo humano","subtopic":"Sistema digestório","relatedQuestions":["Como funciona a digestão?","Para onde vai a comida que comemos?","O que faz o estômago?","Para que serve o intestino?"],"id":"cie-sistema-digestorio","subject":"ciencias","title":"Sistema digestório","levels":["fund2","medio"],"grade":"8º ano","aliases":["sistema digestorio","digestao","aparelho digestivo","estomago","intestino","corpo humano","como digerimos os alimentos"],"summary":"Acompanhe o caminho dos alimentos: da boca ao intestino, e o papel de cada órgão.","intro":"Um lanche leva horas viajando pelo seu corpo. Vamos seguir esse caminho!","skills":{"conceito":"O que é digestão","boca_estomago":"Boca, esôfago e estômago","intestinos":"Intestino delgado e grosso","anexos":"Fígado e pâncreas"},"blocks":[{"id":"b1","skill":"conceito","title":"Para que serve a digestão","text":"Digestão é a transformação dos alimentos em partes muito pequenas (nutrientes) que o corpo consegue absorver e usar para ter energia, crescer e se recuperar.","example":"O pão tem amido, que é quebrado até virar glicose, uma fonte de energia."},{"id":"b2","skill":"boca_estomago","title":"Da boca ao estômago","text":"Na boca, os dentes trituram o alimento e a saliva começa a digerir o amido. O alimento passa pela faringe e pelo esôfago até o estômago, onde o suco gástrico, muito ácido, digere as proteínas.","example":"Mastigar bem facilita todo o resto da digestão."},{"id":"b3","skill":"intestinos","title":"Os intestinos","text":"No intestino delgado a digestão termina e os nutrientes são absorvidos para o sangue. No intestino grosso, grande parte da água é absorvida e se formam as fezes, eliminadas pelo ânus.","example":"O intestino delgado de um adulto tem vários metros de comprimento, dobrado dentro da barriga."},{"id":"b4","skill":"anexos","title":"Os órgãos anexos","text":"O fígado produz a bile, que ajuda a digerir as gorduras (ela fica guardada na vesícula biliar). O pâncreas produz o suco pancreático, com enzimas que atuam no intestino delgado.","example":"Uma refeição muito gordurosa exige mais bile para ser digerida."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"boca_estomago","prompt":"Onde começa a digestão?","options":["No estômago","Na boca","No intestino","No fígado"],"answer":1,"hints":["É onde o alimento entra.","Lá há dentes e saliva.","É na…"],"explanation":"A digestão começa na boca, com a mastigação e a saliva."},{"id":"q2","type":"tf","difficulty":1,"skill":"conceito","prompt":"A digestão transforma os alimentos em nutrientes que o corpo pode absorver.","answer":true,"hints":["Para que serve a digestão?","O corpo precisa de partes pequenas.","Essas partes são os nutrientes."],"explanation":"Verdadeiro."},{"id":"q3","type":"mc","difficulty":1,"skill":"boca_estomago","prompt":"Qual órgão liga a boca (faringe) ao estômago?","options":["Intestino","Esôfago","Pâncreas","Traqueia"],"answer":1,"hints":["É um tubo.","Fica atrás da traqueia.","Começa com E."],"explanation":"O esôfago leva o alimento ao estômago."},{"id":"q4","type":"fill","difficulty":2,"skill":"intestinos","prompt":"A maior parte dos nutrientes é absorvida no intestino ________.","answers":["delgado"],"hints":["São dois intestinos.","Não é o grosso.","É o mais fino e comprido."],"explanation":"No intestino delgado."},{"id":"q5","type":"match","difficulty":2,"skill":"anexos","prompt":"Ligue cada órgão à sua função.","pairs":[["Estômago","Digere proteínas com suco ácido"],["Fígado","Produz a bile"],["Intestino grosso","Absorve água e forma as fezes"],["Pâncreas","Produz o suco pancreático"]],"hints":["A bile vem de um órgão grande do lado direito.","O intestino grosso cuida da água.","O suco ácido fica no estômago."],"explanation":"Estômago → proteínas · fígado → bile · intestino grosso → água · pâncreas → suco pancreático."},{"id":"q6","type":"mc","difficulty":2,"skill":"anexos","prompt":"A bile ajuda a digerir principalmente:","options":["Gorduras","Água","Vitaminas","Sais minerais"],"answer":0,"hints":["Pense em frituras.","A bile \"quebra\" gotas grandes.","Gotas de gordura."],"explanation":"A bile emulsiona as gorduras."},{"id":"q7","type":"tf","difficulty":2,"skill":"intestinos","prompt":"O intestino grosso absorve grande parte da água.","answer":true,"hints":["O que sobra depois do delgado?","Resto de alimento com muita água.","O grosso recupera essa água."],"explanation":"Verdadeiro."},{"id":"q8","type":"mc","difficulty":3,"skill":"boca_estomago","prompt":"Qual é a sequência correta do caminho do alimento?","options":["Boca → estômago → esôfago → intestinos","Boca → faringe → esôfago → estômago → intestino delgado → intestino grosso","Boca → intestino → estômago → esôfago","Esôfago → boca → estômago → intestinos"],"answer":1,"hints":["Começa na boca.","O esôfago vem antes do estômago.","O delgado vem antes do grosso."],"explanation":"Boca → faringe → esôfago → estômago → delgado → grosso."},{"id":"q9","type":"fill","difficulty":3,"skill":"anexos","prompt":"A bile fica armazenada na vesícula ________.","answers":["biliar"],"hints":["Vem da palavra bile.","Bil…","Termina em -ar."],"explanation":"Vesícula biliar."},{"id":"q10","type":"open","difficulty":3,"skill":"conceito","prompt":"Por que é importante mastigar bem os alimentos?","modelAnswer":"Porque a mastigação quebra o alimento em pedaços menores e mistura com a saliva, que já começa a digestão. Isso facilita o trabalho do estômago e dos intestinos.","keywords":["pedacos","menores","saliva","facilita","digestao","estomago","triturar"],"hints":["O que os dentes fazem?","O que a saliva faz?","Como isso ajuda os outros órgãos?"],"explanation":"Mastigar tritura o alimento e facilita a digestão."}],"review":["Digestão = transformar alimento em nutrientes","Boca → faringe → esôfago → estômago → intestinos","Delgado absorve nutrientes · grosso absorve água","Fígado (bile) e pâncreas (suco pancreático)"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências da Natureza","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Idade Contemporânea","subtopic":"Revolução Francesa","relatedQuestions":["O que foi a Revolução Francesa?","O que foi a Queda da Bastilha?","O que foi o período do Terror?"],"id":"his-revolucao-francesa","subject":"historia","title":"Revolução Francesa","levels":["fund2","medio"],"grade":"8º ano e 2ª série","aliases":["revolucao francesa","queda da bastilha","bastilha","robespierre","periodo do terror","jacobinos","girondinos","luis xvi","liberdade igualdade fraternidade","1789"],"summary":"Entenda por que a França entrou em revolução em 1789, suas fases e o que ela deixou para o mundo.","intro":"Em 1789, o povo francês derrubou um sistema que existia havia séculos. Vamos entender como isso aconteceu.","skills":{"contexto":"A França antes da revolução","inicio":"O início (1789)","ideias":"Ideias e direitos","fases":"Fases da revolução","legado":"Legado"},"blocks":[{"id":"b1","skill":"contexto","title":"A França antes de 1789","text":"A França era uma monarquia absolutista: o rei Luís XVI concentrava o poder. A sociedade era dividida em três estados: o clero (1º), a nobreza (2º) e o Terceiro Estado (burguesia, camponeses e trabalhadores urbanos). O Terceiro Estado era a imensa maioria e pagava quase todos os impostos.","example":"Um camponês pagava impostos ao rei, à Igreja e ao senhor da terra, enquanto muitos nobres e membros do clero tinham isenções.","variants":{"simples":"Na França havia três grupos: padres, nobres e o povo. O povo era quem mais trabalhava e quem pagava os impostos. O rei mandava em tudo.","exemplo":"Imagine uma escola em que só uma turma paga a cantina de todas as outras e ainda não pode opinar em nada. Era assim que o Terceiro Estado se sentia.","outra":"Três ingredientes explodiram juntos: um país endividado (guerras e gastos da corte), fome (colheitas ruins e pão caro) e ideias novas do Iluminismo, que diziam que o poder não vinha de Deus, e sim do povo.","detalhado":"Esse modelo é chamado de Antigo Regime. O Iluminismo, com pensadores como Rousseau, Montesquieu e Voltaire, criticava o absolutismo, os privilégios e defendia razão, liberdade e separação dos poderes. A burguesia, rica mas sem privilégios políticos, liderou a contestação."}},{"id":"b2","skill":"inicio","title":"O início: 1789","text":"Para resolver a crise, o rei convocou os Estados Gerais em 1789. O Terceiro Estado se declarou Assembleia Nacional e jurou criar uma Constituição. Em 14 de julho de 1789, o povo de Paris tomou a Bastilha, prisão que simbolizava o poder do rei.","example":"O 14 de julho é até hoje o feriado nacional da França.","variants":{"simples":"Em 1789 o povo se revoltou. No dia 14 de julho, invadiu uma prisão chamada Bastilha. Esse é o símbolo do começo da revolução.","exemplo":"Nos Estados Gerais cada estado tinha um voto. Clero e nobreza sempre se uniam e ganhavam por 2 a 1 do Terceiro Estado, mesmo ele representando quase toda a população.","outra":"Pense em três passos: o rei chama uma reunião (Estados Gerais) → o povo cria a própria assembleia → Paris toma a Bastilha. A partir daí, não tinha mais volta.","detalhado":"O impasse era o voto por estado × voto por cabeça. Com o Juramento da Sala do Jogo da Pela, os deputados do Terceiro Estado prometeram não se separar até dar uma Constituição à França. A tomada da Bastilha foi seguida por revoltas camponesas no campo (o \"Grande Medo\")."}},{"id":"b3","skill":"ideias","title":"Liberdade, Igualdade, Fraternidade","text":"Em agosto de 1789 foi aprovada a Declaração dos Direitos do Homem e do Cidadão, afirmando que todos nascem livres e iguais em direitos. O lema da revolução ficou famoso: Liberdade, Igualdade, Fraternidade.","example":"A ideia de que a lei vale igualmente para todos, sem privilégios de nascimento, vem desse período.","variants":{"simples":"Os revolucionários escreveram um documento dizendo que todas as pessoas têm direitos. O lema era: Liberdade, Igualdade, Fraternidade.","exemplo":"Antes, um nobre podia ser julgado de forma diferente de um camponês. A Declaração dizia que a lei deve ser a mesma para todos.","outra":"Liberdade = poder pensar e agir sem opressão. Igualdade = mesmas leis para todos. Fraternidade = união entre os cidadãos.","detalhado":"A Declaração garantia direitos como liberdade, propriedade, segurança e resistência à opressão, e afirmava a soberania da nação. Ela tinha limites: não incluía as mulheres na mesma condição — Olympe de Gouges escreveu em resposta a Declaração dos Direitos da Mulher e da Cidadã (1791)."}},{"id":"b4","skill":"fases","title":"As fases da revolução","text":"1) Monarquia constitucional (1789–1792): o rei continua, mas limitado por uma Constituição. 2) Convenção e República (1792–1795): o rei Luís XVI é executado em 1793; os jacobinos, liderados por Robespierre, promovem o período do Terror. 3) Diretório (1795–1799): governo da alta burguesia, que termina com o golpe de Napoleão Bonaparte, o 18 de Brumário, em 1799.","example":"No Terror, milhares de pessoas acusadas de serem inimigas da revolução foram executadas na guilhotina.","variants":{"simples":"Primeiro o rei perdeu poder. Depois foi morto e a França virou república, com uma fase violenta chamada Terror. No fim, Napoleão tomou o poder em 1799.","exemplo":"É como uma história em três capítulos: \"o rei com regras\", \"a república radical\" e \"a burguesia no comando\", terminando com Napoleão.","outra":"Grupos disputavam o rumo: os girondinos (alta burguesia, mais moderados) e os jacobinos (pequena burguesia, mais radicais, apoiados pelos sans-culottes). Cada fase mostra quem estava vencendo essa disputa.","detalhado":"Os jacobinos criaram o Comitê de Salvação Pública e tomaram medidas como a Lei do Máximo (teto de preços). Com a queda de Robespierre (1794), a reação termidoriana abriu caminho para o Diretório. A instabilidade e as guerras externas favoreceram o golpe do 18 de Brumário."}},{"id":"b5","skill":"legado","title":"O que ela deixou","text":"A Revolução Francesa pôs fim ao Antigo Regime na França, espalhou ideias de cidadania e direitos, e inspirou movimentos em vários países, inclusive na América. Por isso, ela é usada como marco do início da Idade Contemporânea.","example":"Conceitos que usamos hoje, como \"direitos do cidadão\" e \"direita e esquerda\" na política, ganharam força nessa época.","variants":{"simples":"Ela mudou o mundo porque espalhou a ideia de que as pessoas têm direitos e que o poder vem do povo.","exemplo":"Os termos \"direita\" e \"esquerda\" vêm da posição em que os grupos se sentavam na Assembleia francesa.","outra":"Antes: poder do rei e privilégios de nascimento. Depois: cidadãos com direitos e leis iguais. Essa virada é o legado.","detalhado":"A revolução consolidou a ascensão política da burguesia, influenciou constituições liberais e movimentos de independência, e fez circular o conceito moderno de nação. A historiografia usa 1789 como marco da Idade Contemporânea."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"inicio","prompt":"Em que ano começou a Revolução Francesa?","options":["1500","1789","1822","1917"],"answer":1,"hints":["É no século XVIII.","Mesmo ano da Queda da Bastilha.","Termina em 89."],"explanation":"A Revolução Francesa começou em 1789."},{"id":"q2","type":"mc","difficulty":1,"skill":"ideias","prompt":"Qual era o lema da Revolução Francesa?","options":["Ordem e Progresso","Liberdade, Igualdade, Fraternidade","Terra e Liberdade","Paz, Pão e Terra"],"answer":1,"hints":["São três palavras.","Uma delas é \"Liberdade\".","Outra é \"Igualdade\"."],"explanation":"Liberdade, Igualdade, Fraternidade."},{"id":"q3","type":"tf","difficulty":1,"skill":"inicio","prompt":"A Queda da Bastilha, em 14 de julho de 1789, é símbolo do início da revolução.","answer":true,"hints":["A Bastilha era uma prisão.","Ela representava o poder do rei.","Hoje o 14 de julho é feriado na França."],"explanation":"Verdadeiro. A tomada da Bastilha simboliza o início da revolução."},{"id":"q4","type":"match","difficulty":2,"skill":"contexto","prompt":"Ligue cada estado ao grupo que o formava.","pairs":[["Primeiro Estado","Clero"],["Segundo Estado","Nobreza"],["Terceiro Estado","Burguesia e povo"]],"hints":["A Igreja vinha primeiro.","Depois vinham os nobres.","O resto da população era o Terceiro."],"explanation":"1º: clero · 2º: nobreza · 3º: burguesia, camponeses e trabalhadores."},{"id":"q5","type":"fill","difficulty":2,"skill":"contexto","prompt":"O movimento de ideias que defendia a razão e criticava o absolutismo se chama ________.","answers":["iluminismo"],"hints":["Tem a ver com \"luz\".","A \"luz\" era a razão.","Ilumin…"],"explanation":"O Iluminismo."},{"id":"q6","type":"tf","difficulty":2,"skill":"contexto","prompt":"O clero e a nobreza pagavam a maior parte dos impostos.","answer":false,"hints":["Quem tinha privilégios?","Clero e nobreza tinham muitas isenções.","O peso caía sobre a maioria."],"explanation":"Falso. Quem pagava quase todos os impostos era o Terceiro Estado."},{"id":"q7","type":"mc","difficulty":2,"skill":"ideias","prompt":"Qual documento de 1789 afirmava que todos nascem livres e iguais em direitos?","options":["Constituição dos EUA","Declaração dos Direitos do Homem e do Cidadão","Carta Magna","Lei Áurea"],"answer":1,"hints":["Foi aprovado na França.","Fala em \"direitos\" e em \"cidadão\".","Foi em agosto de 1789."],"explanation":"A Declaração dos Direitos do Homem e do Cidadão."},{"id":"q8","type":"mc","difficulty":2,"skill":"contexto","prompt":"Quem fazia parte do Terceiro Estado?","options":["Apenas o rei e a rainha","Bispos e padres","Burguesia, camponeses e trabalhadores urbanos","Somente nobres"],"answer":2,"hints":["Era a maioria da população.","Não tinha privilégios.","Incluía ricos comerciantes e pobres."],"explanation":"Burguesia, camponeses e trabalhadores urbanos (sans-culottes)."},{"id":"q9","type":"mc","difficulty":3,"skill":"fases","prompt":"Como ficou conhecido o período de execuções liderado por Robespierre?","options":["Diretório","Terror","Consulado","Restauração"],"answer":1,"hints":["Foi uma fase muito violenta.","Usava muito a guilhotina.","O nome lembra medo."],"explanation":"O período do Terror (1793–1794), sob os jacobinos."},{"id":"q10","type":"fill","difficulty":3,"skill":"fases","prompt":"O rei francês guilhotinado em 1793 foi Luís ____. (algarismo romano)","answers":["xvi","16"],"hints":["Ele era o rei em 1789.","É um número entre 15 e 17.","Em romanos: X + V + I."],"explanation":"Luís XVI foi executado em 1793."},{"id":"q11","type":"mc","difficulty":3,"skill":"fases","prompt":"Como a Revolução Francesa terminou, em 1799?","options":["Com a volta do absolutismo","Com o golpe do 18 de Brumário, de Napoleão","Com a independência dos EUA","Com a Primeira Guerra Mundial"],"answer":1,"hints":["Um general tomou o poder.","Ele depois virou imperador.","O golpe tem nome de mês do calendário revolucionário."],"explanation":"Napoleão Bonaparte deu o golpe do 18 de Brumário e encerrou o Diretório."},{"id":"q12","type":"open","difficulty":3,"skill":"legado","prompt":"Por que a Revolução Francesa é considerada o marco do início da Idade Contemporânea?","modelAnswer":"Porque acabou com o Antigo Regime e o absolutismo na França, espalhou ideias de direitos, cidadania, liberdade e igualdade, e influenciou governos e movimentos no mundo todo.","keywords":["absolutismo","antigo regime","direitos","cidadao","cidadania","igualdade","liberdade","burguesia"],"hints":["O que ela derrubou?","Que ideias ela espalhou?","Fale de direitos ou do fim do poder absoluto do rei."],"explanation":"Ela encerrou o Antigo Regime e difundiu direitos e cidadania pelo mundo."}],"review":["Antigo Regime: rei absoluto + 3 estados","Terceiro Estado pagava os impostos","1789: Estados Gerais, Assembleia, Bastilha (14/07)","Declaração dos Direitos do Homem e do Cidadão","Fases: monarquia constitucional → República/Terror → Diretório → Napoleão (1799)"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — História","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"games":{"words":[{"word":"Bastilha","clue":"prisão tomada em 14/07/1789","difficulty":1},{"word":"clero","clue":"Primeiro Estado","difficulty":1},{"word":"nobreza","clue":"Segundo Estado","difficulty":1},{"word":"burguesia","clue":"liderou o Terceiro Estado","difficulty":2},{"word":"liberdade","clue":"primeira palavra do lema","difficulty":1},{"word":"igualdade","clue":"segunda palavra do lema","difficulty":1},{"word":"Napoleão","clue":"assumiu o poder em 1799","difficulty":2},{"word":"república","clue":"proclamada em 1792","difficulty":3}],"sequences":[{"prompt":"Coloque os acontecimentos da Revolução Francesa em ordem cronológica.","difficulty":2,"items":["Convocação dos Estados Gerais (maio de 1789)","Queda da Bastilha (14 de julho de 1789)","Declaração dos Direitos do Homem e do Cidadão (agosto de 1789)","Proclamação da República (1792)","Napoleão chega ao poder (1799)"],"explanation":"Estados Gerais → Bastilha → Declaração → República → Napoleão."}],"map":{"map":"europa","prompt":"A Revolução Francesa e países envolvidos nas guerras contra a França revolucionária (fronteiras atuais).","targets":[{"id":"France","label":"França","clue":"onde começou a revolução, em 1789","difficulty":1},{"id":"Austria","label":"Áustria","clue":"terra natal da rainha Maria Antonieta","difficulty":2},{"id":"United Kingdom","label":"Reino Unido","clue":"monarquia insular que integrou as coalizões contra a França","difficulty":2},{"id":"Spain","label":"Espanha","clue":"vizinha ao sul, integrou a Primeira Coalizão","difficulty":3}]}},"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"História do Brasil","subtopic":"Período colonial","relatedQuestions":["Como foi a chegada dos portugueses ao Brasil?","O que foram as capitanias hereditárias?","Quem foi Tomé de Sousa?","Como era a economia do açúcar?"],"id":"his-brasil-colonia","subject":"historia","title":"Brasil Colônia","levels":["fund2","medio"],"grade":"7º ano","aliases":["brasil colonia","periodo colonial","descobrimento do brasil","chegada dos portugueses","capitanias hereditarias","governo geral","pau brasil","ciclo do acucar","engenho"],"summary":"Da chegada dos portugueses em 1500 às capitanias, ao governo-geral e à economia do açúcar.","intro":"Em 1500, navios portugueses chegaram a uma terra que já era habitada por milhões de indígenas. Começava o período colonial.","skills":{"chegada":"A chegada dos portugueses","capitanias":"Capitanias hereditárias","governo":"Governo-geral","economia":"Economia colonial e escravidão"},"blocks":[{"id":"b1","skill":"chegada","title":"A chegada em 1500","text":"Em abril de 1500, a esquadra de Pedro Álvares Cabral chegou ao litoral da atual Bahia. A terra já era habitada por muitos povos indígenas. Nos primeiros anos, Portugal explorou principalmente o pau-brasil, árvore usada para tingir tecidos.","example":"O nome \"Brasil\" vem do pau-brasil, cuja madeira tem cor de brasa."},{"id":"b2","skill":"capitanias","title":"As capitanias hereditárias (1534)","text":"Para ocupar e defender a terra, o rei Dom João III dividiu o território em faixas chamadas capitanias hereditárias, entregues a donatários que deviam povoá-las e explorá-las por conta própria. Passavam de pai para filho.","example":"Pernambuco e São Vicente prosperaram; a maioria das outras fracassou por falta de recursos e conflitos."},{"id":"b3","skill":"governo","title":"O governo-geral (1549)","text":"Como as capitanias não deram certo em geral, Portugal criou o governo-geral para centralizar a administração. O primeiro governador, Tomé de Sousa, chegou em 1549 e fundou Salvador, primeira capital do Brasil.","example":"Com Tomé de Sousa vieram os primeiros jesuítas, liderados por Manuel da Nóbrega."},{"id":"b4","skill":"economia","title":"Açúcar e escravidão","text":"A principal atividade econômica foi a produção de açúcar nos engenhos do Nordeste, feita com o trabalho de africanos escravizados trazidos à força. Indígenas também foram escravizados. A escravidão marcou profundamente a sociedade brasileira.","example":"O engenho reunia a casa-grande, a senzala, a moenda e os canaviais."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"chegada","prompt":"Em que ano a esquadra de Cabral chegou ao Brasil?","options":["1492","1500","1822","1534"],"answer":1,"hints":["É o começo do século XVI.","Um número \"redondo\".","Mil e quinhentos."],"explanation":"Em 1500."},{"id":"q2","type":"tf","difficulty":1,"skill":"chegada","prompt":"Quando os portugueses chegaram, a terra já era habitada por povos indígenas.","answer":true,"hints":["Estava vazia?","Havia milhões de pessoas.","Os povos originários."],"explanation":"Verdadeiro."},{"id":"q3","type":"mc","difficulty":1,"skill":"chegada","prompt":"O primeiro produto explorado pelos portugueses foi:","options":["Ouro","Café","Pau-brasil","Borracha"],"answer":2,"hints":["Deu nome ao país.","É uma árvore.","Pau-…"],"explanation":"O pau-brasil."},{"id":"q4","type":"fill","difficulty":2,"skill":"capitanias","prompt":"As capitanias hereditárias foram criadas em ____.","answers":["1534"],"hints":["Foi na década de 1530.","Antes do governo-geral (1549).","15-3-4."],"explanation":"Em 1534."},{"id":"q5","type":"mc","difficulty":2,"skill":"governo","prompt":"Quem foi o primeiro governador-geral do Brasil?","options":["Pedro Álvares Cabral","Tomé de Sousa","Dom Pedro I","Martim Afonso"],"answer":1,"hints":["Chegou em 1549.","Fundou Salvador.","Tomé…"],"explanation":"Tomé de Sousa."},{"id":"q6","type":"match","difficulty":2,"skill":"governo","prompt":"Ligue cada fato ao ano.","pairs":[["Chegada de Cabral","1500"],["Capitanias hereditárias","1534"],["Chegada de Tomé de Sousa e fundação de Salvador","1549"]],"hints":["A chegada é a mais antiga.","As capitanias vieram antes do governo-geral.","Salvador foi fundada no fim da década de 1540."],"explanation":"1500 → 1534 → 1549."},{"id":"q7","type":"tf","difficulty":2,"skill":"capitanias","prompt":"A maioria das capitanias hereditárias prosperou.","answer":false,"hints":["Por que Portugal criou o governo-geral?","Porque o sistema não funcionou bem.","Poucas deram certo."],"explanation":"Falso. Só algumas, como Pernambuco e São Vicente, prosperaram."},{"id":"q8","type":"mc","difficulty":3,"skill":"economia","prompt":"Qual foi a principal base de trabalho nos engenhos de açúcar?","options":["Trabalhadores assalariados europeus","Africanos escravizados","Máquinas a vapor","Colonos voluntários"],"answer":1,"hints":["Pessoas trazidas à força.","Vinham de outro continente.","Da África."],"explanation":"O trabalho de africanos escravizados."},{"id":"q9","type":"fill","difficulty":3,"skill":"governo","prompt":"A primeira capital do Brasil foi a cidade de ________.","answers":["salvador"],"hints":["Fica na Bahia.","Foi fundada por Tomé de Sousa.","Salva…"],"explanation":"Salvador."},{"id":"q10","type":"open","difficulty":3,"skill":"capitanias","prompt":"Por que Portugal criou o governo-geral depois das capitanias?","modelAnswer":"Porque a maioria das capitanias fracassou por falta de recursos, isolamento e conflitos com indígenas. O governo-geral centralizou a administração para defender e organizar melhor a colônia.","keywords":["fracass","centraliz","organizar","defender","recursos","administracao"],"hints":["As capitanias funcionaram?","O que faltava a elas?","O governo-geral juntou o poder num só lugar."],"explanation":"Para centralizar a administração após o fracasso da maioria das capitanias."}],"review":["1500: chegada de Cabral; terra já habitada","Pau-brasil: primeira exploração","1534: capitanias hereditárias","1549: governo-geral, Tomé de Sousa, Salvador","Açúcar + trabalho escravizado"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — História","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Toda Matéria — Capitanias Hereditárias","url":"https://www.todamateria.com.br/capitanias-hereditarias/","kind":"site"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"História do Brasil","subtopic":"Independência","relatedQuestions":["Como foi a Independência do Brasil?","O que foi o Dia do Fico?","O que aconteceu em 7 de setembro?","Quem proclamou a independência?"],"id":"his-independencia-brasil","subject":"historia","title":"Independência do Brasil","levels":["fund1","fund2","medio"],"grade":"8º ano","aliases":["independencia do brasil","7 de setembro","grito do ipiranga","dom pedro i","dia do fico","1822","primeiro reinado"],"summary":"Os caminhos até 1822, o 7 de setembro e o reconhecimento da independência.","intro":"O 7 de setembro é feriado nacional. Mas a independência foi um processo — não aconteceu num dia só.","skills":{"contexto":"Antecedentes","dia_do_fico":"Dia do Fico","proclamacao":"7 de setembro de 1822","reconhecimento":"Guerras e reconhecimento"},"blocks":[{"id":"b1","skill":"contexto","title":"A família real no Brasil","text":"Em 1808, fugindo das tropas de Napoleão, a família real portuguesa veio para o Rio de Janeiro. O Brasil ganhou importância: portos abertos, novas instituições e, em 1815, virou Reino Unido a Portugal e Algarves.","example":"Nessa época surgiram o Banco do Brasil e o Jardim Botânico do Rio."},{"id":"b2","skill":"dia_do_fico","title":"O Dia do Fico (1822)","text":"Dom João VI voltou a Portugal em 1821 e deixou seu filho, Dom Pedro, como príncipe regente. As cortes portuguesas exigiram que ele também voltasse. Em 9 de janeiro de 1822, ele decidiu ficar: foi o Dia do Fico.","example":"A frase atribuída a ele: \"Diga ao povo que fico\"."},{"id":"b3","skill":"proclamacao","title":"O 7 de setembro","text":"Em 7 de setembro de 1822, às margens do riacho Ipiranga, em São Paulo, Dom Pedro proclamou a independência. Em dezembro, foi coroado Dom Pedro I, primeiro imperador do Brasil. O país virou uma monarquia.","example":"O episódio ficou conhecido como \"Grito do Ipiranga\"."},{"id":"b4","skill":"reconhecimento","title":"Guerras e reconhecimento","text":"Tropas portuguesas resistiram em províncias como Bahia, Maranhão e Pará, e houve guerras de independência. A Bahia só se libertou em 2 de julho de 1823. Portugal reconheceu a independência em 1825, pelo Tratado do Rio de Janeiro, mediante indenização paga pelo Brasil.","example":"O 2 de Julho é a grande data cívica da Bahia."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"proclamacao","prompt":"Em que data comemoramos a Independência do Brasil?","options":["15 de novembro","7 de setembro","21 de abril","1º de janeiro"],"answer":1,"hints":["É feriado nacional.","Tem desfile cívico.","Setembro."],"explanation":"7 de setembro (de 1822)."},{"id":"q2","type":"mc","difficulty":1,"skill":"proclamacao","prompt":"Quem proclamou a independência?","options":["Dom João VI","Dom Pedro","Tiradentes","Deodoro da Fonseca"],"answer":1,"hints":["Era o príncipe regente.","Virou o primeiro imperador.","Dom…"],"explanation":"Dom Pedro, depois Dom Pedro I."},{"id":"q3","type":"tf","difficulty":1,"skill":"proclamacao","prompt":"Depois da independência, o Brasil virou uma república.","answer":false,"hints":["Quem passou a governar?","Um imperador.","Imperador = monarquia."],"explanation":"Falso. Virou um império (monarquia); a república veio só em 1889."},{"id":"q4","type":"fill","difficulty":2,"skill":"contexto","prompt":"A família real portuguesa chegou ao Brasil em ____.","answers":["1808"],"hints":["Fugia de Napoleão.","Início do século XIX.","18-0-8."],"explanation":"Em 1808."},{"id":"q5","type":"mc","difficulty":2,"skill":"dia_do_fico","prompt":"O que foi o Dia do Fico?","options":["A volta de Dom João VI a Portugal","A decisão de Dom Pedro de permanecer no Brasil","A coroação de Dom Pedro I","O fim da escravidão"],"answer":1,"hints":["\"Diga ao povo que fico.\"","Ele ficaria onde?","No Brasil."],"explanation":"Em 9/1/1822, Dom Pedro decidiu ficar no Brasil."},{"id":"q6","type":"match","difficulty":2,"skill":"reconhecimento","prompt":"Ligue cada fato à data.","pairs":[["Chegada da família real","1808"],["Proclamação da independência","1822"],["Independência na Bahia","1823"],["Reconhecimento por Portugal","1825"]],"hints":["A chegada da família real é a mais antiga.","A Bahia lutou depois do 7 de setembro.","O reconhecimento é a mais recente."],"explanation":"1808 → 1822 → 1823 → 1825."},{"id":"q7","type":"tf","difficulty":2,"skill":"reconhecimento","prompt":"Portugal reconheceu a independência imediatamente, em 1822.","answer":false,"hints":["Houve guerras depois.","O reconhecimento veio por tratado.","Três anos depois."],"explanation":"Falso. Só em 1825, pelo Tratado do Rio de Janeiro."},{"id":"q8","type":"mc","difficulty":3,"skill":"reconhecimento","prompt":"Em qual província houve forte resistência portuguesa, encerrada em 2 de julho de 1823?","options":["São Paulo","Bahia","Rio Grande do Sul","Minas Gerais"],"answer":1,"hints":["É uma data cívica estadual.","Fica no Nordeste.","Capital: Salvador."],"explanation":"Na Bahia."},{"id":"q9","type":"fill","difficulty":3,"skill":"proclamacao","prompt":"A independência foi proclamada às margens do riacho ________.","answers":["ipiranga"],"hints":["Fica em São Paulo.","\"Grito do …\"","Ipi…"],"explanation":"Ipiranga."},{"id":"q10","type":"open","difficulty":3,"skill":"contexto","prompt":"Por que a vinda da família real em 1808 ajudou no caminho da independência?","modelAnswer":"Porque o Brasil passou a ser a sede do governo português, ganhou instituições, portos abertos e depois virou Reino Unido. Com isso, a elite local não aceitou voltar a ser uma simples colônia quando Portugal tentou recolonizá-lo.","keywords":["sede","governo","instituicoes","portos","reino unido","colonia","importancia","autonomia"],"hints":["O que o Brasil ganhou com a corte aqui?","Virou o quê em 1815?","Por que não aceitaria voltar a ser colônia?"],"explanation":"O Brasil ganhou autonomia e importância e não aceitou voltar a ser colônia."}],"review":["1808: família real no Rio","9/1/1822: Dia do Fico","7/9/1822: proclamação; Dom Pedro I imperador","1823: Bahia (2 de Julho) · 1825: reconhecimento por Portugal"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — História","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Arquivo Nacional — Reconhecimento da Independência do Brasil por Portugal","url":"https://historialuso.an.gov.br/index.php?option=com_content&view=article&id=3869%3Areconhecimento-da-independencia-do-brasil-por-port&catid=149&Itemid=215","kind":"instituicao"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Idade Contemporânea","subtopic":"Segunda Guerra Mundial","relatedQuestions":["Por que começou a Segunda Guerra Mundial?","O que foi o Holocausto?","O Brasil participou da Segunda Guerra?","Quem eram os Aliados e o Eixo?"],"id":"his-segunda-guerra","subject":"historia","title":"Segunda Guerra Mundial","levels":["fund2","medio"],"grade":"9º ano e 3ª série","aliases":["segunda guerra mundial","segunda guerra","2 guerra","nazismo","holocausto","hitler","feb","forca expedicionaria brasileira","aliados e eixo"],"summary":"Causas, lados, principais fatos, o Holocausto e a participação do Brasil (1939–1945).","intro":"Foi o maior conflito da história. Vamos entender por que começou e como terminou.","skills":{"causas":"Causas","lados":"Eixo e Aliados","fatos":"Principais acontecimentos","brasil":"O Brasil na guerra"},"blocks":[{"id":"b1","skill":"causas","title":"Por que começou","text":"Após a Primeira Guerra, a crise econômica e o descontentamento favoreceram regimes totalitários, como o nazismo na Alemanha (Hitler) e o fascismo na Itália (Mussolini). A guerra começou em 1º de setembro de 1939, com a invasão da Polônia pela Alemanha.","example":"O Tratado de Versalhes impôs duras punições à Alemanha, o que os nazistas usaram na propaganda."},{"id":"b2","skill":"lados","title":"Os dois lados","text":"O Eixo reunia principalmente Alemanha, Itália e Japão. Os Aliados reuniam Reino Unido, França, União Soviética (a partir de 1941) e Estados Unidos (a partir de 1941), entre outros.","example":"Os EUA entraram na guerra após o ataque japonês a Pearl Harbor, em dezembro de 1941."},{"id":"b3","skill":"fatos","title":"Fatos marcantes e o Holocausto","text":"O regime nazista perseguiu e assassinou cerca de 6 milhões de judeus, além de ciganos, pessoas com deficiência e outros grupos: o Holocausto. Em 1944 os Aliados desembarcaram na Normandia (Dia D). A guerra terminou na Europa em maio de 1945 e, após as bombas atômicas em Hiroshima e Nagasaki, o Japão se rendeu em setembro de 1945.","example":"Após a guerra foi criada a ONU (1945), para tentar evitar novos conflitos mundiais."},{"id":"b4","skill":"brasil","title":"O Brasil na guerra","text":"O Brasil declarou guerra ao Eixo em 1942, após navios brasileiros serem afundados. A Força Expedicionária Brasileira (FEB), com mais de 25 mil militares, lutou na Itália. A tomada de Monte Castelo, em 21 de fevereiro de 1945, é sua vitória mais lembrada.","example":"O símbolo da FEB era uma cobra fumando — resposta a quem dizia que era \"mais fácil uma cobra fumar\" do que o Brasil ir à guerra."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"causas","prompt":"Em que período aconteceu a Segunda Guerra Mundial?","options":["1914–1918","1939–1945","1789–1799","1964–1985"],"answer":1,"hints":["Começou no fim da década de 1930.","Terminou em meados dos anos 1940.","Termina em 1945."],"explanation":"De 1939 a 1945."},{"id":"q2","type":"mc","difficulty":1,"skill":"causas","prompt":"Qual fato marcou o início da guerra, em 1939?","options":["Ataque a Pearl Harbor","Invasão da Polônia pela Alemanha","Bomba de Hiroshima","Dia D"],"answer":1,"hints":["Foi na Europa.","Foi a Alemanha que atacou.","Um país vizinho da Alemanha a leste."],"explanation":"A invasão da Polônia, em 1º de setembro de 1939."},{"id":"q3","type":"match","difficulty":2,"skill":"lados","prompt":"Ligue cada país ao lado em que lutou.","pairs":[["Alemanha","Eixo"],["Estados Unidos","Aliados"],["Japão","Eixo (Ásia)"],["Reino Unido","Aliados (Europa)"]],"hints":["Hitler governava a Alemanha.","O Japão atacou os EUA.","Reino Unido lutou contra a Alemanha."],"explanation":"Alemanha e Japão: Eixo · EUA e Reino Unido: Aliados."},{"id":"q4","type":"tf","difficulty":1,"skill":"fatos","prompt":"O Holocausto foi a perseguição e o assassinato de milhões de judeus e outros grupos pelo regime nazista.","answer":true,"hints":["Aconteceu durante a guerra.","Foi promovido pelos nazistas.","Cerca de 6 milhões de judeus."],"explanation":"Verdadeiro."},{"id":"q5","type":"fill","difficulty":2,"skill":"brasil","prompt":"A sigla da força militar brasileira que lutou na Itália é ____.","answers":["feb"],"hints":["Força Expedicionária…","Brasileira.","Três letras."],"explanation":"FEB — Força Expedicionária Brasileira."},{"id":"q6","type":"mc","difficulty":2,"skill":"lados","prompt":"Por que os Estados Unidos entraram na guerra em 1941?","options":["Por causa do Dia D","Por causa do ataque japonês a Pearl Harbor","Por causa da invasão da Polônia","Por causa da criação da ONU"],"answer":1,"hints":["Foram atacados.","Pelo Japão.","Numa base no Havaí."],"explanation":"Após o ataque a Pearl Harbor, em dezembro de 1941."},{"id":"q7","type":"mc","difficulty":2,"skill":"brasil","prompt":"A vitória mais lembrada da FEB foi a tomada de:","options":["Normandia","Monte Castelo","Stalingrado","Berlim"],"answer":1,"hints":["Fica na Itália.","Foi em fevereiro de 1945.","Monte…"],"explanation":"Monte Castelo, 21/2/1945."},{"id":"q8","type":"tf","difficulty":3,"skill":"fatos","prompt":"A guerra terminou no mesmo dia na Europa e na Ásia.","answer":false,"hints":["A Alemanha se rendeu primeiro.","O Japão resistiu mais alguns meses.","Maio × setembro de 1945."],"explanation":"Falso. Europa: maio de 1945; Japão: setembro de 1945."},{"id":"q9","type":"mc","difficulty":3,"skill":"fatos","prompt":"Qual organização foi criada em 1945 para tentar evitar novas guerras mundiais?","options":["OTAN","ONU","União Europeia","Mercosul"],"answer":1,"hints":["Reúne quase todos os países.","Sede em Nova York.","Organização das Nações Unidas."],"explanation":"A ONU."},{"id":"q10","type":"open","difficulty":3,"skill":"causas","prompt":"Cite fatores que ajudaram os regimes totalitários a chegarem ao poder antes da guerra.","modelAnswer":"A crise econômica, o desemprego, o descontentamento com os resultados da Primeira Guerra e com o Tratado de Versalhes, e o medo de revoluções favoreceram líderes autoritários como Hitler e Mussolini, que usavam propaganda e nacionalismo.","keywords":["crise","economica","desemprego","versalhes","primeira guerra","nacionalismo","propaganda"],"hints":["Como estava a economia?","O que o Tratado de Versalhes impôs?","Fale de crise e descontentamento."],"explanation":"Crise econômica, Versalhes e nacionalismo fortaleceram o nazifascismo."}],"review":["1939–1945; começou com a invasão da Polônia","Eixo (Alemanha, Itália, Japão) × Aliados","Holocausto; Dia D (1944); fim em 1945","Brasil: FEB na Itália, Monte Castelo"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — História","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Blog do Exército Brasileiro — A tomada de Monte Castello pela FEB","url":"https://eblog.eb.mil.br/en/w/a-tomada-de-monte-castello-pela-for%C3%A7a-expedicion%C3%A1ria-brasileira-feb-em-21-de-fevereiro-de-1945","kind":"instituicao"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"games":{"sequences":[{"prompt":"Coloque os acontecimentos da Segunda Guerra Mundial em ordem.","difficulty":2,"items":["Alemanha invade a Polônia (setembro de 1939)","Ataque japonês a Pearl Harbor (dezembro de 1941)","Derrota alemã em Stalingrado (fevereiro de 1943)","Dia D, desembarque na Normandia (junho de 1944)","Rendição da Alemanha (maio de 1945)","Rendição do Japão (setembro de 1945)"],"explanation":"1939 Polônia → 1941 Pearl Harbor → 1943 Stalingrado → 1944 Dia D → maio/1945 Alemanha → set/1945 Japão."}],"map":{"map":"mundo","prompt":"Principais países do Eixo e dos Aliados (fronteiras atuais).","targets":[{"id":"Germany","label":"Alemanha","clue":"país do Eixo que invadiu a Polônia em 1939","difficulty":1},{"id":"Italy","label":"Itália","clue":"país do Eixo onde lutou a FEB brasileira","difficulty":1},{"id":"Japan","label":"Japão","clue":"país do Eixo que atacou Pearl Harbor","difficulty":1},{"id":"United Kingdom","label":"Reino Unido","clue":"Aliado europeu que resistiu aos bombardeios alemães","difficulty":2},{"id":"United States of America","label":"Estados Unidos","clue":"Aliado que entrou na guerra após Pearl Harbor","difficulty":2},{"id":"Russia","label":"Rússia (antiga União Soviética)","clue":"onde aconteceu a Batalha de Stalingrado","difficulty":2},{"id":"Brazil","label":"Brasil","clue":"enviou a FEB para lutar na Itália","difficulty":1},{"id":"Poland","label":"Polônia","clue":"invadida em 1939, início da guerra","difficulty":3}]}},"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Cartografia","subtopic":"Coordenadas geográficas","relatedQuestions":["O que é latitude e longitude?","O que é a Linha do Equador?","O que é o Meridiano de Greenwich?"],"id":"geo-coordenadas","subject":"geografia","title":"Coordenadas geográficas","levels":["fund2","medio"],"grade":"6º ano","aliases":["coordenadas geograficas","latitude","longitude","paralelos","meridianos","linha do equador","greenwich","hemisferios","localizacao"],"summary":"Aprenda latitude, longitude, paralelos e meridianos — o \"endereço\" de qualquer lugar do planeta.","intro":"Como o GPS sabe exatamente onde você está? Com um sistema de linhas imaginárias. Vamos conhecê-lo.","skills":{"latitude":"Paralelos e latitude","longitude":"Meridianos e longitude","coordenadas":"Coordenadas","hemisferios":"Hemisférios e o Brasil"},"blocks":[{"id":"b1","skill":"latitude","title":"Paralelos e latitude","text":"Paralelos são linhas imaginárias horizontais que dão a volta na Terra. O principal é a Linha do Equador (0°), que divide o planeta em Norte e Sul. Latitude é a distância, em graus, de um lugar até o Equador: vai de 0° a 90°, Norte (N) ou Sul (S).","example":"Os polos ficam a 90°: Polo Norte a 90° N e Polo Sul a 90° S.","variants":{"simples":"Imagine anéis deitados em volta da Terra. O do meio é o Equador. Latitude diz se você está mais para cima (Norte) ou para baixo (Sul) dele.","exemplo":"Os Trópicos de Câncer e de Capricórnio também são paralelos. O de Capricórnio passa bem perto da cidade de São Paulo.","outra":"Pense nos degraus de uma escada que sobe do Equador até o polo: cada degrau é um grau de latitude. O último degrau é o 90.","detalhado":"Os paralelos principais são: Equador (0°), Trópicos de Câncer e de Capricórnio (cerca de 23°27' N e S) e Círculos Polares Ártico e Antártico (cerca de 66°33' N e S). Todos os paralelos são paralelos entre si e diminuem de tamanho em direção aos polos."}},{"id":"b2","skill":"longitude","title":"Meridianos e longitude","text":"Meridianos são linhas imaginárias que vão de um polo ao outro. O principal é o Meridiano de Greenwich (0°), que divide a Terra em Leste (L ou E) e Oeste (O ou W). Longitude é a distância, em graus, até Greenwich: vai de 0° a 180°.","example":"Greenwich é um bairro de Londres, na Inglaterra, por onde passa o meridiano 0°.","variants":{"simples":"Meridianos são linhas que descem do Polo Norte ao Polo Sul, como os gomos de uma laranja. Longitude diz se você está para a direita (Leste) ou para a esquerda (Oeste) de Greenwich.","exemplo":"O Brasil fica a oeste de Greenwich; o Japão fica a leste.","outra":"Latitude responde \"quanto ao norte ou ao sul?\". Longitude responde \"quanto ao leste ou ao oeste?\".","detalhado":"O meridiano oposto a Greenwich (180°) serve de referência para a Linha Internacional de Data. Os meridianos também são usados para definir os fusos horários: a cada 15° de longitude, a hora muda em 1 hora (360° ÷ 24 h)."}},{"id":"b3","skill":"coordenadas","title":"Coordenadas: o endereço do planeta","text":"O cruzamento de uma latitude com uma longitude forma uma coordenada geográfica. Ela indica a localização exata de qualquer ponto da Terra. O GPS usa esse sistema.","example":"A cidade de São Paulo fica perto de 23° S e 46° O: ao sul do Equador e a oeste de Greenwich.","variants":{"simples":"Coordenada é como o número da rua e da casa, só que para o planeta inteiro: uma latitude + uma longitude.","exemplo":"No jogo de batalha naval você diz \"B5\": uma letra e um número. Coordenadas são isso: latitude e longitude.","outra":"Uma linha só não basta: a latitude diz uma \"faixa\" e a longitude diz outra. Onde elas se cruzam fica o ponto exato.","detalhado":"Coordenadas podem ser escritas em graus, minutos e segundos (23°32'51\" S) ou em graus decimais, usando sinal negativo para Sul e Oeste (−23,547; −46,636), que é o formato usado por mapas digitais."}},{"id":"b4","skill":"hemisferios","title":"Hemisférios e o Brasil","text":"O Equador separa os hemisférios Norte e Sul. Greenwich separa os hemisférios Oriental (Leste) e Ocidental (Oeste). O Brasil fica todo no Hemisfério Ocidental e em sua maior parte no Hemisfério Sul — mas a Linha do Equador passa pelo norte do país.","example":"Em Macapá (AP), o Equador passa pela cidade; lá existe o monumento Marco Zero.","variants":{"simples":"O Brasil está quase todo \"embaixo\" do Equador (Sul) e todo à esquerda de Greenwich (Oeste).","exemplo":"Roraima e parte do Amapá e do Amazonas ficam no Hemisfério Norte.","outra":"Pense na Terra cortada duas vezes: uma na horizontal (Equador) e outra na vertical (Greenwich). O Brasil está no pedaço de baixo à esquerda — com uma pontinha em cima.","detalhado":"O território brasileiro é cortado pelo Equador (no Norte) e pelo Trópico de Capricórnio (no Sudeste/Sul). Por isso, a maior parte do país está na zona intertropical, o que explica o predomínio de climas quentes."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"latitude","prompt":"Qual linha imaginária marca a latitude 0°?","options":["Meridiano de Greenwich","Linha do Equador","Trópico de Capricórnio","Círculo Polar Ártico"],"answer":1,"hints":["Latitude mede Norte e Sul.","É a linha que divide Norte e Sul.","Passa pelo \"meio\" da Terra."],"explanation":"A Linha do Equador é o paralelo 0°."},{"id":"q2","type":"mc","difficulty":1,"skill":"longitude","prompt":"Qual é o meridiano 0°?","options":["Equador","Greenwich","Trópico de Câncer","Meridiano de Brasília"],"answer":1,"hints":["Ele divide Leste e Oeste.","Passa por Londres.","Começa com G."],"explanation":"O Meridiano de Greenwich é o 0° de longitude."},{"id":"q3","type":"tf","difficulty":1,"skill":"latitude","prompt":"A latitude pode chegar a, no máximo, 90°.","answer":true,"hints":["Onde fica o ponto mais distante do Equador?","Nos polos.","Os polos ficam a 90°."],"explanation":"Verdadeiro. A latitude vai de 0° (Equador) a 90° (polos)."},{"id":"q4","type":"fill","difficulty":2,"skill":"longitude","prompt":"A longitude vai de 0° até ____°.","answers":["180"],"hints":["É o dobro da latitude máxima.","A latitude máxima é 90.","90 × 2."],"explanation":"A longitude vai de 0° a 180° para Leste ou Oeste."},{"id":"q5","type":"mc","difficulty":2,"skill":"coordenadas","prompt":"Uma coordenada geográfica é formada pelo cruzamento de:","options":["Dois paralelos","Latitude e longitude","Dois hemisférios","Equador e Trópico"],"answer":1,"hints":["Uma linha só não basta.","Precisamos de uma horizontal e uma vertical.","Uma de cada tipo."],"explanation":"Latitude + longitude = coordenada."},{"id":"q6","type":"match","difficulty":2,"skill":"coordenadas","prompt":"Ligue cada termo à sua descrição.","pairs":[["Equador","Divide Norte e Sul"],["Greenwich","Divide Leste e Oeste"],["Latitude","Distância até o Equador"],["Longitude","Distância até Greenwich"]],"hints":["O Equador é horizontal.","Greenwich vai de polo a polo.","Latitude usa o Equador como referência."],"explanation":"Equador → N/S; Greenwich → L/O; Latitude → até o Equador; Longitude → até Greenwich."},{"id":"q7","type":"tf","difficulty":2,"skill":"hemisferios","prompt":"O Brasil está inteiramente no Hemisfério Sul.","answer":false,"hints":["A Linha do Equador passa pelo Brasil?","Passa, sim.","Veja Macapá e Roraima."],"explanation":"Falso. A maior parte está no Sul, mas o Equador passa pelo norte do país."},{"id":"q8","type":"mc","difficulty":2,"skill":"hemisferios","prompt":"Em relação a Greenwich, o Brasil fica:","options":["Totalmente no Hemisfério Oriental","Totalmente no Hemisfério Ocidental","Metade em cada","Sobre o meridiano 0°"],"answer":1,"hints":["Greenwich passa pela Europa e pela África.","O Brasil está à esquerda no mapa.","Oeste = Ocidental."],"explanation":"O Brasil está todo a oeste de Greenwich: Hemisfério Ocidental."},{"id":"q9","type":"mc","difficulty":3,"skill":"coordenadas","prompt":"Um ponto em 23° S e 46° O fica:","options":["Acima do Equador e a leste de Greenwich","Abaixo do Equador e a oeste de Greenwich","Sobre o Equador","No Polo Sul"],"answer":1,"hints":["S = Sul. O = Oeste.","Sul fica abaixo do Equador.","Oeste fica à esquerda de Greenwich."],"explanation":"S → abaixo do Equador; O → a oeste de Greenwich. É perto de São Paulo."},{"id":"q10","type":"fill","difficulty":3,"skill":"latitude","prompt":"O trópico que passa pelo Brasil, perto de São Paulo, é o Trópico de ________.","answers":["capricornio","capricórnio"],"hints":["Existem dois trópicos: Câncer e…","O de Câncer fica no Hemisfério Norte.","O outro fica no Sul."],"explanation":"O Trópico de Capricórnio."},{"id":"q11","type":"tf","difficulty":3,"skill":"longitude","prompt":"Os paralelos são linhas que vão de um polo ao outro.","answer":false,"hints":["Pense na forma de cada linha.","Quem liga os polos são os \"gomos da laranja\".","Esses são os meridianos."],"explanation":"Falso. Quem vai de polo a polo são os meridianos; os paralelos são horizontais."},{"id":"q12","type":"open","difficulty":3,"skill":"coordenadas","prompt":"Por que as coordenadas geográficas são úteis no dia a dia?","modelAnswer":"Porque permitem localizar com exatidão qualquer ponto da Terra. O GPS do celular, os aplicativos de mapa, aviões e navios usam coordenadas para saber onde estão e traçar rotas.","keywords":["localizar","localizacao","exata","gps","mapa","ponto","rota"],"hints":["Pense no celular.","Que aplicativo usa sua localização?","Fale em localizar ou em GPS."],"explanation":"Elas localizam qualquer ponto com exatidão — é o que o GPS faz."}],"review":["Paralelos → latitude (0° a 90°, N/S), referência: Equador","Meridianos → longitude (0° a 180°, L/O), referência: Greenwich","Coordenada = latitude + longitude","Brasil: todo no Ocidental, maior parte no Sul"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Geografia","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Natureza e paisagem","subtopic":"Biomas do Brasil","relatedQuestions":["Quais são os biomas brasileiros?","Qual é o maior bioma do Brasil?","O que é a Caatinga?","O que é o Cerrado?"],"id":"geo-biomas-brasileiros","subject":"geografia","title":"Biomas brasileiros","levels":["fund1","fund2","medio"],"grade":"4º ao 7º ano","aliases":["biomas","biomas brasileiros","amazonia","cerrado","mata atlantica","caatinga","pampa","pantanal","vegetacao do brasil"],"summary":"Conheça os seis biomas do Brasil e o que torna cada um especial.","intro":"O Brasil tem florestas, savanas, sertão, campos e áreas alagadas. São seis biomas diferentes.","skills":{"conceito":"O que é bioma","florestas":"Amazônia e Mata Atlântica","outros":"Cerrado, Caatinga, Pampa e Pantanal","preservacao":"Ameaças e preservação"},"blocks":[{"id":"b1","skill":"conceito","title":"O que é um bioma","text":"Bioma é uma grande região com clima, vegetação e animais parecidos. Segundo o IBGE, o Brasil tem seis: Amazônia, Cerrado, Mata Atlântica, Caatinga, Pampa e Pantanal.","example":"A Amazônia é o maior, com cerca de 49,5% do território; o Pantanal é o menor, com cerca de 1,8%.","variants":{"simples":"Bioma é um grande \"tipo de paisagem\" com seu clima, plantas e bichos. O Brasil tem seis."}},{"id":"b2","skill":"florestas","title":"As florestas","text":"A Amazônia é uma floresta tropical quente e úmida, com enorme biodiversidade e a maior bacia hidrográfica do mundo. A Mata Atlântica acompanha o litoral; é um dos biomas mais devastados, pois ali se concentram grandes cidades.","example":"Onças-pintadas e botos vivem na Amazônia; o mico-leão-dourado é símbolo da Mata Atlântica.","variants":{"simples":"Amazônia: a maior floresta, muito quente e úmida. Mata Atlântica: floresta perto do mar, que perdeu muita área."}},{"id":"b3","skill":"outros","title":"Cerrado, Caatinga, Pampa e Pantanal","text":"Cerrado: savana do Brasil Central, com árvores de troncos retorcidos e muitas nascentes. Caatinga: bioma semiárido do Nordeste, o único exclusivamente brasileiro. Pampa: campos do sul do Rio Grande do Sul. Pantanal: maior área úmida continental do planeta, que alaga em parte do ano.","example":"O mandacaru é típico da Caatinga; o tuiuiú é símbolo do Pantanal.","variants":{"simples":"Cerrado tem árvores tortinhas. Caatinga é seca. Pampa é campo. Pantanal alaga."}},{"id":"b4","skill":"preservacao","title":"Ameaças e preservação","text":"Desmatamento, queimadas, expansão agropecuária sem controle e poluição ameaçam os biomas. Unidades de conservação, fiscalização e uso sustentável ajudam a protegê-los.","example":"Parques nacionais, como o da Chapada dos Veadeiros (Cerrado), protegem áreas naturais."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"conceito","prompt":"Quantos biomas o Brasil tem, segundo o IBGE?","options":["4","5","6","8"],"answer":2,"hints":["Amazônia, Cerrado, Mata Atlântica…","…Caatinga, Pampa e Pantanal.","Conte."],"explanation":"São 6 biomas."},{"id":"q2","type":"mc","difficulty":1,"skill":"florestas","prompt":"Qual é o maior bioma brasileiro?","options":["Cerrado","Amazônia","Pantanal","Caatinga"],"answer":1,"hints":["É uma floresta.","Fica no Norte.","Tem o rio mais volumoso do mundo."],"explanation":"A Amazônia, com cerca de 49,5% do território."},{"id":"q3","type":"tf","difficulty":1,"skill":"outros","prompt":"A Caatinga é o único bioma exclusivamente brasileiro.","answer":true,"hints":["Fica no Nordeste.","Não aparece em outros países.","É 100% brasileira."],"explanation":"Verdadeiro."},{"id":"q4","type":"match","difficulty":2,"skill":"outros","prompt":"Ligue cada bioma à sua característica.","pairs":[["Cerrado","Árvores de troncos retorcidos"],["Caatinga","Clima semiárido"],["Pantanal","Maior área úmida continental"],["Pampa","Campos do sul do Brasil"]],"hints":["Semiárido = pouca chuva.","Área úmida alaga.","Campos = Pampa."],"explanation":"Cerrado: troncos retorcidos · Caatinga: semiárido · Pantanal: alagado · Pampa: campos."},{"id":"q5","type":"fill","difficulty":2,"skill":"conceito","prompt":"O menor bioma do Brasil é o ________.","answers":["pantanal"],"hints":["Ocupa cerca de 1,8% do país.","É uma área alagada.","Fica em MT e MS."],"explanation":"O Pantanal."},{"id":"q6","type":"mc","difficulty":2,"skill":"florestas","prompt":"Por que a Mata Atlântica é um dos biomas mais devastados?","options":["Porque fica no deserto","Porque ali se concentram grandes cidades e ocupação humana antiga","Porque não tem árvores","Porque é o maior bioma"],"answer":1,"hints":["Onde ela fica?","No litoral.","Onde vive a maior parte da população."],"explanation":"A ocupação humana e as cidades se concentram no litoral."},{"id":"q7","type":"tf","difficulty":2,"skill":"outros","prompt":"O Pampa aparece no Brasil apenas no Rio Grande do Sul.","answer":true,"hints":["É um bioma do extremo sul.","Estende-se ao Uruguai e à Argentina.","No Brasil, só em um estado."],"explanation":"Verdadeiro."},{"id":"q8","type":"mc","difficulty":3,"skill":"outros","prompt":"Qual bioma é chamado de \"berço das águas\" por ter muitas nascentes de rios importantes?","options":["Pampa","Cerrado","Caatinga","Mata Atlântica"],"answer":1,"hints":["Fica no Brasil Central.","Tem árvores retorcidas.","Savana brasileira."],"explanation":"O Cerrado."},{"id":"q9","type":"mc","difficulty":3,"skill":"preservacao","prompt":"Qual destas ações ajuda a preservar os biomas?","options":["Queimadas para limpar o terreno","Criação de unidades de conservação","Desmatamento para pastagem","Descarte de lixo nos rios"],"answer":1,"hints":["Três opções causam danos.","Procure uma forma de proteger áreas.","Parques e reservas."],"explanation":"Unidades de conservação protegem áreas naturais."},{"id":"q10","type":"open","difficulty":3,"skill":"preservacao","prompt":"Escolha um bioma brasileiro e explique uma ameaça que ele sofre.","modelAnswer":"A Amazônia sofre com o desmatamento e as queimadas para abrir áreas de pasto e garimpo, o que destrói habitats, reduz a biodiversidade e afeta o clima.","keywords":["desmatamento","queimada","garimpo","pasto","poluicao","biodiversidade","agropecuaria"],"hints":["Escolha um bioma.","O que as pessoas fazem que o prejudica?","Fale de desmatamento ou queimadas."],"explanation":"Desmatamento e queimadas estão entre as principais ameaças."}],"review":["6 biomas: Amazônia, Cerrado, Mata Atlântica, Caatinga, Pampa, Pantanal","Amazônia é o maior (~49,5%); Pantanal, o menor (~1,8%)","Caatinga: exclusiva do Brasil","Ameaças: desmatamento e queimadas"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Geografia","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"IBGE Educa — Os biomas brasileiros","url":"https://educa.ibge.gov.br/jovens/materias-especiais/21592-os-biomas-brasileiros.html","kind":"instituicao"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"games":{"words":[{"word":"Amazônia","clue":"maior floresta tropical do mundo","difficulty":1},{"word":"Cerrado","clue":"savana brasileira","difficulty":1},{"word":"Caatinga","clue":"bioma exclusivo do Brasil, clima semiárido","difficulty":2},{"word":"Pantanal","clue":"maior planície alagável","difficulty":1},{"word":"Pampa","clue":"campos do Sul do Brasil","difficulty":2}]},"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Espaço brasileiro","subtopic":"Regiões do Brasil","relatedQuestions":["Quais são as regiões do Brasil?","Quantos estados tem o Brasil?","Quais estados ficam no Nordeste?","Em que região fica Santa Catarina?"],"id":"geo-regioes-brasil","subject":"geografia","title":"Regiões do Brasil","levels":["fund1","fund2"],"grade":"4º e 7º ano","aliases":["regioes do brasil","regioes brasileiras","estados e capitais","divisao regional","norte nordeste sudeste sul centro oeste","ibge regioes"],"summary":"As cinco regiões do IBGE, seus estados e características principais.","intro":"O Brasil é enorme: para estudar melhor, o IBGE o dividiu em cinco regiões.","skills":{"divisao":"A divisão do IBGE","estados":"Estados de cada região","caracteristicas":"Características das regiões"},"blocks":[{"id":"b1","skill":"divisao","title":"Cinco regiões","text":"O Brasil tem 26 estados e o Distrito Federal, onde fica Brasília, a capital do país. O IBGE agrupa os estados em cinco regiões: Norte, Nordeste, Centro-Oeste, Sudeste e Sul.","example":"A divisão atual está em vigor desde 1988, quando Tocantins foi criado.","variants":{"simples":"O Brasil tem 5 regiões: Norte, Nordeste, Centro-Oeste, Sudeste e Sul."}},{"id":"b2","skill":"estados","title":"Quem está em cada região","text":"Norte: AM, PA, AC, RO, RR, AP, TO. Nordeste: MA, PI, CE, RN, PB, PE, AL, SE, BA. Centro-Oeste: MT, MS, GO e DF. Sudeste: SP, RJ, MG, ES. Sul: PR, SC, RS.","example":"Santa Catarina fica na Região Sul; a Bahia, no Nordeste.","variants":{"simples":"O Nordeste tem mais estados (9). O Sul tem menos (3): Paraná, Santa Catarina e Rio Grande do Sul."}},{"id":"b3","skill":"caracteristicas","title":"Cada região tem seu jeito","text":"O Norte é a maior região e abriga grande parte da Amazônia. O Nordeste tem o maior número de estados e um litoral extenso. O Centro-Oeste se destaca na agropecuária. O Sudeste é a região mais populosa e industrializada. O Sul tem clima subtropical, com invernos mais frios.","example":"São Paulo, no Sudeste, é a cidade mais populosa do país.","variants":{"simples":"Norte: maior e com floresta. Sudeste: mais gente. Sul: mais frio."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"divisao","prompt":"Em quantas regiões o IBGE divide o Brasil?","options":["3","4","5","27"],"answer":2,"hints":["Norte, Nordeste…","…Centro-Oeste, Sudeste, Sul.","Conte."],"explanation":"Cinco regiões."},{"id":"q2","type":"mc","difficulty":1,"skill":"estados","prompt":"Santa Catarina fica em qual região?","options":["Sudeste","Sul","Nordeste","Centro-Oeste"],"answer":1,"hints":["É uma das regiões mais frias.","Tem só 3 estados.","Junto com Paraná e RS."],"explanation":"Região Sul."},{"id":"q3","type":"tf","difficulty":1,"skill":"divisao","prompt":"Brasília, a capital do país, fica no Distrito Federal.","answer":true,"hints":["O DF não é um estado comum.","É onde fica a capital.","Região Centro-Oeste."],"explanation":"Verdadeiro."},{"id":"q4","type":"fill","difficulty":2,"skill":"divisao","prompt":"O Brasil tem ____ estados, além do Distrito Federal.","answers":["26","vinte e seis"],"hints":["São 27 unidades da federação ao todo.","Tire o DF.","27 − 1."],"explanation":"26 estados + DF."},{"id":"q5","type":"match","difficulty":2,"skill":"caracteristicas","prompt":"Ligue cada região à característica.","pairs":[["Norte","Maior região, com grande parte da Amazônia"],["Sudeste","Mais populosa e industrializada"],["Nordeste","Maior número de estados"],["Sul","Clima subtropical, invernos frios"]],"hints":["A floresta fica no Norte.","São Paulo está no Sudeste.","O Nordeste tem 9 estados."],"explanation":"Norte: Amazônia · Sudeste: população · Nordeste: 9 estados · Sul: frio."},{"id":"q6","type":"mc","difficulty":2,"skill":"estados","prompt":"Qual região tem mais estados?","options":["Norte","Nordeste","Sudeste","Sul"],"answer":1,"hints":["São nove estados.","Inclui Bahia e Pernambuco.","Nord…"],"explanation":"O Nordeste, com 9 estados."},{"id":"q7","type":"tf","difficulty":2,"skill":"estados","prompt":"Minas Gerais fica na Região Centro-Oeste.","answer":false,"hints":["MG faz divisa com SP e RJ.","Está na região mais populosa.","Sudeste."],"explanation":"Falso. Minas Gerais fica no Sudeste."},{"id":"q8","type":"mc","difficulty":3,"skill":"estados","prompt":"Quais estados formam a Região Sudeste?","options":["SP, RJ, MG e ES","SP, PR, SC e RS","MG, GO, MT e MS","RJ, BA, ES e SP"],"answer":0,"hints":["São quatro estados.","Inclui o Espírito Santo.","Não inclui Paraná."],"explanation":"São Paulo, Rio de Janeiro, Minas Gerais e Espírito Santo."},{"id":"q9","type":"fill","difficulty":3,"skill":"estados","prompt":"O estado criado em 1988, que hoje faz parte da Região Norte, é o ________.","answers":["tocantins"],"hints":["Foi desmembrado de Goiás.","Capital: Palmas.","Toca…"],"explanation":"Tocantins."},{"id":"q10","type":"mc","difficulty":3,"skill":"caracteristicas","prompt":"A Região Centro-Oeste se destaca principalmente por:","options":["Pesca em alto-mar","Agropecuária (soja, milho e gado)","Clima frio com neve","Maior população do país"],"answer":1,"hints":["Tem grandes áreas planas no Cerrado.","Produz muitos grãos.","E cria gado."],"explanation":"Agropecuária: soja, milho e gado."}],"review":["26 estados + DF; 5 regiões do IBGE","Nordeste: 9 estados · Sul: 3","Norte: maior · Sudeste: mais populoso","Centro-Oeste: agropecuária · Sul: subtropical"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Geografia","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"IBGE Educa — Divisão Territorial","url":"https://educa.ibge.gov.br/jovens/conheca-o-brasil/territorio/19637-divisao-territorial.html","kind":"instituicao"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"games":{"words":[{"word":"Norte","clue":"a maior região","difficulty":1},{"word":"Nordeste","clue":"a região com mais estados (9)","difficulty":1},{"word":"Sudeste","clue":"a região mais populosa","difficulty":1},{"word":"Sul","clue":"a menor região, com 3 estados","difficulty":1},{"word":"Brasília","clue":"capital federal","difficulty":2},{"word":"Manaus","clue":"capital do Amazonas","difficulty":2},{"word":"Salvador","clue":"capital da Bahia","difficulty":2},{"word":"Curitiba","clue":"capital do Paraná","difficulty":3}],"map":{"map":"brasil","prompt":"Regiões, estados e capitais do Brasil (divisão do IBGE).","groups":{"Norte":["AC","AP","AM","PA","RO","RR","TO"],"Nordeste":["AL","BA","CE","MA","PB","PE","PI","RN","SE"],"Centro-Oeste":["DF","GO","MT","MS"],"Sudeste":["ES","MG","RJ","SP"],"Sul":["PR","RS","SC"]},"targets":[{"id":"Norte","label":"Região Norte","clue":"a maior região, com grande parte da Floresta Amazônica","difficulty":1},{"id":"Nordeste","label":"Região Nordeste","clue":"a região com mais estados: nove","difficulty":1},{"id":"Centro-Oeste","label":"Região Centro-Oeste","clue":"onde fica o Distrito Federal","difficulty":1},{"id":"Sudeste","label":"Região Sudeste","clue":"a região mais populosa","difficulty":1},{"id":"Sul","label":"Região Sul","clue":"a menor região, com três estados","difficulty":1},{"id":"BA","label":"Bahia","clue":"o estado cuja capital é Salvador","difficulty":2},{"id":"AM","label":"Amazonas","clue":"o estado cuja capital é Manaus","difficulty":2},{"id":"MG","label":"Minas Gerais","clue":"o estado cuja capital é Belo Horizonte","difficulty":2},{"id":"RS","label":"Rio Grande do Sul","clue":"o estado cuja capital é Porto Alegre","difficulty":2},{"id":"PE","label":"Pernambuco","clue":"o estado cuja capital é Recife","difficulty":3},{"id":"PA","label":"Pará","clue":"o estado cuja capital é Belém","difficulty":3},{"id":"SC","label":"Santa Catarina","clue":"o estado cuja capital é Florianópolis","difficulty":3},{"id":"GO","label":"Goiás","clue":"o estado cuja capital é Goiânia","difficulty":3}]}},"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Gramática","subtopic":"Verb to be","relatedQuestions":["Quando usar am, is e are?","Como fazer pergunta com verbo to be?","Como negar em inglês?"],"id":"ing-verb-to-be","subject":"ingles","title":"Verb to be","levels":["fund1","fund2","medio"],"grade":"6º ano","aliases":["verb to be","verbo to be","to be","am is are","ingles basico","verbo ser estar ingles"],"summary":"Aprenda o verbo mais usado do inglês: to be (ser/estar), nas formas afirmativa, negativa e interrogativa.","intro":"Let's start! O verbo \"to be\" significa \"ser\" ou \"estar\". Com ele você já consegue se apresentar e descrever coisas.","skills":{"afirmativa":"Forma afirmativa","contracao":"Contrações","negativa":"Forma negativa","interrogativa":"Perguntas e respostas curtas"},"blocks":[{"id":"b1","skill":"afirmativa","title":"Am, is, are","text":"O verbo to be tem três formas no presente: I am (eu sou/estou); he is, she is, it is (ele/ela é/está); you are, we are, they are (você é, nós somos, eles são).","example":"I am a student. = Eu sou estudante. · She is happy. = Ela está feliz. · They are my friends. = Eles são meus amigos.","variants":{"simples":"I → am. He, she, it → is. You, we, they → are. Decore essas três duplas e pronto!","exemplo":"I am 12 years old. (Eu tenho 12 anos — em inglês se usa \"ser\" para idade!) · My dog is small. · We are at school.","outra":"Pense em três caixas: a caixa do \"am\" só tem o I. A caixa do \"is\" tem uma pessoa ou coisa só (he, she, it). A caixa do \"are\" tem o resto.","detalhado":"Em inglês, \"you\" serve para \"você\" e \"vocês\", e sempre usa \"are\". \"It\" é usado para coisas e animais. Diferente do português, o inglês usa \"to be\" para idade (I am 12), fome (I am hungry) e frio (I am cold)."}},{"id":"b2","skill":"contracao","title":"Contrações","text":"Na fala e em textos informais, juntamos o pronome e o verbo com um apóstrofo: I'm, you're, he's, she's, it's, we're, they're.","example":"I'm tired = I am tired. · They're here = They are here.","variants":{"simples":"É um \"atalho\": tira uma letra e coloca um apóstrofo ('). I am → I'm.","exemplo":"Numa música ou série você vai ouvir \"I'm fine\", \"You're welcome\", \"It's OK\".","outra":"O apóstrofo marca o lugar da letra que sumiu: I am → I'm (sumiu o \"a\"); he is → he's (sumiu o \"i\").","detalhado":"Não confunda \"it's\" (it is) com \"its\" (possessivo: \"dele/dela\" para coisas e animais): \"It's a dog. Its name is Rex.\" O mesmo vale para \"they're\" (they are) × \"their\" (deles)."}},{"id":"b3","skill":"negativa","title":"Forma negativa","text":"Para negar, coloque \"not\" depois do verbo: I am not, he is not, they are not. Contrações: isn't (is not) e aren't (are not). Com \"I\", usamos I'm not.","example":"He isn't tired. = Ele não está cansado. · We aren't late. = Nós não estamos atrasados.","variants":{"simples":"É só colocar \"not\" depois de am, is ou are. Is not = isn't. Are not = aren't.","exemplo":"I'm not hungry. (Não estou com fome.) · It isn't cold today. (Não está frio hoje.)","outra":"No português o \"não\" vem antes do verbo (\"não está\"). No inglês, o \"not\" vem depois do to be (\"is not\").","detalhado":"Existem duas contrações possíveis para a negativa: \"he's not\" ou \"he isn't\"; \"they're not\" ou \"they aren't\". Para \"I am not\" não existe \"amn't\" no inglês padrão — usamos \"I'm not\"."}},{"id":"b4","skill":"interrogativa","title":"Perguntas e respostas curtas","text":"Para perguntar, troque a ordem: o verbo vem antes do pronome. You are ready → Are you ready? Nas respostas curtas, repetimos o verbo: Yes, I am. / No, I'm not.","example":"Is she a doctor? — Yes, she is. / No, she isn't.","variants":{"simples":"Pergunta: o verbo pula para a frente. \"She is\" → \"Is she…?\"","exemplo":"Are they from Brazil? — Yes, they are. · Is it your book? — No, it isn't.","outra":"É como trocar duas peças de lugar: [she] [is] vira [is] [she]. E coloque o ponto de interrogação no fim.","detalhado":"Na resposta curta afirmativa não se usa contração: diz-se \"Yes, she is\", nunca \"Yes, she's\". Na negativa, a contração é normal: \"No, she isn't\"."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"afirmativa","prompt":"Complete: I ___ a student.","options":["am","is","are","be"],"answer":0,"hints":["Qual forma combina com \"I\"?","O \"I\" tem uma forma só dele.","A caixa que só tem o \"I\"."],"explanation":"Com \"I\" usamos \"am\": I am a student."},{"id":"q2","type":"mc","difficulty":1,"skill":"afirmativa","prompt":"Complete: She ___ happy.","options":["am","is","are","be"],"answer":1,"hints":["\"She\" é uma pessoa só.","He, she, it usam a mesma forma.","Tem duas letras."],"explanation":"Com \"she\" usamos \"is\"."},{"id":"q3","type":"fill","difficulty":1,"skill":"afirmativa","prompt":"Complete: They ___ my friends.","answers":["are"],"hints":["\"They\" é mais de uma pessoa.","You, we e they usam a mesma forma.","Tem três letras."],"explanation":"Com \"they\" usamos \"are\"."},{"id":"q4","type":"tf","difficulty":1,"skill":"afirmativa","prompt":"A frase \"We is at school\" está correta.","answer":false,"hints":["\"We\" é de qual caixa?","We = nós (mais de uma pessoa).","We usa \"are\"."],"explanation":"Falso. O correto é \"We are at school\"."},{"id":"q5","type":"match","difficulty":2,"skill":"contracao","prompt":"Ligue cada forma à sua contração.","pairs":[["I am","I'm"],["You are","You're"],["He is","He's"],["They are","They're"]],"hints":["Some uma letra do verbo.","Am → 'm.","Are → 're e is → 's."],"explanation":"I'm, You're, He's, They're."},{"id":"q6","type":"mc","difficulty":2,"skill":"negativa","prompt":"Qual é a negativa de \"He is tired\"?","options":["He aren't tired.","He isn't tired.","He not is tired.","He amn't tired."],"answer":1,"hints":["\"Not\" vem depois do verbo.","He usa \"is\".","Is + not = ?"],"explanation":"He is not tired = He isn't tired."},{"id":"q7","type":"mc","difficulty":2,"skill":"interrogativa","prompt":"Qual é a forma interrogativa de \"You are ready\"?","options":["You are ready?","Are you ready?","Ready you are?","Is you ready?"],"answer":1,"hints":["Na pergunta, duas palavras trocam de lugar.","O verbo vai para a frente.","Are + you."],"explanation":"\"Are you ready?\" — o verbo vem antes do pronome."},{"id":"q8","type":"fill","difficulty":2,"skill":"negativa","prompt":"Complete: I ___ not sad.","answers":["am"],"hints":["Com \"I\" o verbo é sempre o mesmo.","O \"not\" vem depois dele.","I ___ = eu sou/estou."],"explanation":"I am not sad (I'm not sad)."},{"id":"q9","type":"tf","difficulty":1,"skill":"contracao","prompt":"\"I'm\" é a contração de \"I am\".","answer":true,"hints":["O apóstrofo marca uma letra que sumiu.","Qual letra sumiu de \"am\"?","O \"a\"."],"explanation":"Verdadeiro."},{"id":"q10","type":"mc","difficulty":3,"skill":"interrogativa","prompt":"Qual é a resposta curta afirmativa correta para \"Is she a doctor?\"","options":["Yes, she's.","Yes, she is.","Yes, she are.","Yes, is she."],"answer":1,"hints":["Repita o verbo da pergunta.","Na resposta curta afirmativa, sem contração.","She + is."],"explanation":"\"Yes, she is.\" Não se usa contração na resposta curta afirmativa."},{"id":"q11","type":"mc","difficulty":3,"skill":"afirmativa","prompt":"Qual é a tradução de \"The books are on the table\"?","options":["O livro é da mesa.","Os livros estão na mesa.","Os livros são mesas.","A mesa está nos livros."],"answer":1,"hints":["\"Books\" está no plural.","\"On the table\" = em cima da mesa.","\"Are\" aqui é \"estão\"."],"explanation":"\"Os livros estão na mesa.\""},{"id":"q12","type":"fill","difficulty":3,"skill":"interrogativa","prompt":"Complete a pergunta: ___ they from Brazil?","answers":["are"],"hints":["Na pergunta o verbo vem primeiro.","\"They\" usa qual forma?","A mesma de \"you\" e \"we\"."],"explanation":"\"Are they from Brazil?\""}],"review":["I am · he/she/it is · you/we/they are","Contrações: I'm, you're, he's, they're","Negativa: not depois do verbo (isn't, aren't, I'm not)","Pergunta: verbo antes do pronome (Are you…?)"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"english":{"cefr":"A1","unit":"a1-u1","order":4,"area":"grammar","focus":["grammar","speaking","listening"],"vocabulary":[{"word":"am","translation":"sou / estou","pos":"verb","definition":"form of “be” used with I","example":"I am a student.","difficulty":1},{"word":"is","translation":"é / está","pos":"verb","definition":"form of “be” used with he, she and it","example":"She is my friend.","difficulty":1},{"word":"are","translation":"são / estão / é (você)","pos":"verb","definition":"form of “be” used with you, we and they","example":"We are happy.","difficulty":1},{"word":"student","translation":"estudante","pos":"noun","definition":"a person who studies","example":"I'm a student.","difficulty":1},{"word":"happy","translation":"feliz","pos":"adjective","definition":"feeling good","example":"They are happy today.","difficulty":1,"antonyms":["sad"]},{"word":"tired","translation":"cansado(a)","pos":"adjective","definition":"needing rest or sleep","example":"I'm tired after school.","difficulty":2},{"word":"hungry","translation":"com fome","pos":"adjective","definition":"wanting to eat","example":"Are you hungry?","difficulty":2},{"word":"teacher","translation":"professor(a)","pos":"noun","definition":"a person who teaches","example":"She is a teacher.","difficulty":1}],"grammar":{"name":"Verb to be (present)","when":"Para dizer quem alguém é, como está, onde está, idade e origem.","structure":"I am · you/we/they are · he/she/it is","affirmative":["I'm twelve.","She's from Brazil.","We're friends."],"negative":["I'm not tired.","He isn't here.","They aren't late."],"interrogative":["Are you OK?","Is she your sister?","Where are they?"],"compare":"Em português temos “ser” e “estar”; em inglês os dois são “be”: I am a student (sou) · I am tired (estou).","context":"Preenchendo seu perfil num jogo: “I'm Leo. I'm 13. I'm from Belém.”"},"listening":{"title":"Quem é quem?","kind":"texto","rate":0.9,"script":["Hi! I'm Nina and I'm eleven.","This is my friend Omar. He's from Egypt.","We're in the same class.","Our teacher is Mr. Park. He isn't strict. He's very funny!"],"questions":[{"difficulty":1,"prompt":"Quantos anos Nina tem?","options":["10","11","12","7"],"answer":1,"explanation":"“I'm eleven.”"},{"difficulty":1,"prompt":"De onde é Omar?","options":["Egypt","Korea","Brazil","Spain"],"answer":0,"explanation":"“He's from Egypt.”"},{"difficulty":2,"prompt":"Como é o professor?","options":["Rígido","Engraçado","Cansado","Novo"],"answer":1,"explanation":"“He isn't strict. He's very funny!”"}]},"speaking":{"situation":"Você está se apresentando num vídeo para uma turma de outro país.","vocabulary":["I'm","from","years old","student"],"phrases":["I'm …","I'm … years old.","I'm from …","I'm a student."],"example":"Hi! I'm Sara. I'm twelve years old. I'm from Brazil and I'm a student.","challenge":"Fale 4 frases sobre você usando am/is/are.","expected":["i'm","from","years","student"]},"challenge":"Descreva três pessoas da sua turma com is/are: nome, idade e como elas estão hoje."},"games":{"words":[{"word":"happy","clue":"feliz","difficulty":1},{"word":"student","clue":"estudante","difficulty":1},{"word":"teacher","clue":"professor(a)","difficulty":1},{"word":"tired","clue":"cansado","difficulty":2},{"word":"hungry","clue":"com fome","difficulty":2}],"blanks":[{"difficulty":1,"sentence":"I ___ a student.","options":["am","is","are","be"],"answer":0,"explanation":"I am."},{"difficulty":1,"sentence":"She ___ my sister.","options":["is","am","are","be"],"answer":0,"explanation":"She is."},{"difficulty":2,"sentence":"We ___ from Brazil.","options":["are","is","am","be"],"answer":0,"explanation":"We are."},{"difficulty":2,"sentence":"He ___ tired. He is fine. (negativa)","options":["isn't","aren't","amn't","not"],"answer":0,"explanation":"He isn't."},{"difficulty":3,"sentence":"___ they your cousins?","options":["Are","Is","Am","Do"],"answer":0,"explanation":"Pergunta: Are they…?"}],"dialogues":[{"difficulty":1,"title":"No intervalo","gap":1,"options":["Yes, I am. I'm Kai.","Yes, I is.","No, I amn't.","Yes, you are."],"answer":0,"explanation":"Resposta curta: Yes, I am.","lines":[{"who":"Ana","text":"Are you new here?"},{"who":"Kai","text":"Yes, I am. I'm Kai."},{"who":"Ana","text":"Nice to meet you, Kai!"}]},{"difficulty":2,"title":"Perguntando por alguém","gap":3,"options":["Yes, she is. She's just busy.","Yes, she are.","No, she am.","Yes, I am."],"answer":0,"explanation":"Com she: Yes, she is.","lines":[{"who":"Tom","text":"Where is Sofia?"},{"who":"Lia","text":"She's in the library."},{"who":"Tom","text":"Is she OK?"},{"who":"Lia","text":"Yes, she is. She's just busy."}]}],"sequences":[{"difficulty":1,"prompt":"Organize a frase · Put the words in order","items":["I","am","twelve","years","old"],"words":true,"explanation":"Idade: I am + número + years old."},{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["Is","he","your","brother"],"words":true,"explanation":"Pergunta: Is + he + …?"}]},"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Gramática","subtopic":"Simple present","relatedQuestions":["Quando usar do e does?","Quando colocar s no verbo em inglês?","Como falar da rotina em inglês?"],"id":"ing-simple-present","subject":"ingles","title":"Simple present","levels":["fund2","medio"],"grade":"6º e 7º ano","aliases":["simple present","presente simples","do does","rotina em ingles","terceira pessoa ingles"],"summary":"Fale sobre rotinas e verdades em inglês usando o simple present, com do/does.","intro":"I study, she studies… Vamos aprender o tempo verbal da rotina!","skills":{"uso":"Quando usar","terceira":"Terceira pessoa (he/she/it)","negativa":"Negativa com don't/doesn't","interrogativa":"Perguntas com do/does"},"blocks":[{"id":"b1","skill":"uso","title":"Rotinas e verdades","text":"Usamos o simple present para hábitos, rotinas e fatos que são sempre verdadeiros. Palavras como always, usually, every day e never costumam aparecer.","example":"I go to school every day. · Water boils at 100 °C."},{"id":"b2","skill":"terceira","title":"He, she, it ganham -s","text":"Com he, she e it, o verbo recebe -s (works). Verbos terminados em -o, -s, -sh, -ch, -x recebem -es (goes, watches). Consoante + y vira -ies (study → studies). Have vira has.","example":"She plays guitar. · He watches TV. · It has four legs."},{"id":"b3","skill":"negativa","title":"Negativa","text":"Use don't (do not) com I, you, we, they e doesn't (does not) com he, she, it. Depois de doesn't, o verbo volta à forma base, sem -s.","example":"I don't like coffee. · She doesn't like coffee (e não \"doesn't likes\")."},{"id":"b4","skill":"interrogativa","title":"Perguntas","text":"Coloque Do ou Does no início. Does é para he, she, it — e o verbo também fica sem -s. Respostas curtas: Yes, I do. / No, she doesn't.","example":"Do you speak English? — Yes, I do. · Does he work here? — No, he doesn't."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"terceira","prompt":"Complete: She ___ guitar.","options":["play","plays","playes","playing"],"answer":1,"hints":["\"She\" é terceira pessoa.","Terceira pessoa ganha uma letra.","Play + s."],"explanation":"She plays."},{"id":"q2","type":"mc","difficulty":1,"skill":"uso","prompt":"O simple present é usado principalmente para:","options":["Ações acontecendo neste exato momento","Rotinas e hábitos","Ações que já terminaram","Planos futuros certos"],"answer":1,"hints":["Pense em \"every day\".","Coisas que se repetem.","Hábitos."],"explanation":"Rotinas, hábitos e verdades gerais."},{"id":"q3","type":"fill","difficulty":1,"skill":"terceira","prompt":"Complete: He ___ (go) to school by bus.","answers":["goes"],"hints":["Terceira pessoa.","Go termina em -o.","-o recebe -es."],"explanation":"He goes."},{"id":"q4","type":"tf","difficulty":1,"skill":"negativa","prompt":"A frase \"She doesn't likes pizza\" está correta.","answer":false,"hints":["Depois de doesn't, o verbo muda?","Ele volta à forma base.","Sem -s."],"explanation":"Falso. O correto é \"She doesn't like pizza\"."},{"id":"q5","type":"match","difficulty":2,"skill":"terceira","prompt":"Ligue cada verbo à forma com he/she/it.","pairs":[["study","studies"],["watch","watches"],["have","has"],["read","reads"]],"hints":["Consoante + y vira -ies.","-ch recebe -es.","Have é irregular."],"explanation":"studies · watches · has · reads."},{"id":"q6","type":"mc","difficulty":2,"skill":"negativa","prompt":"Qual é a negativa de \"They play soccer\"?","options":["They doesn't play soccer.","They don't play soccer.","They don't plays soccer.","They not play soccer."],"answer":1,"hints":["\"They\" usa do ou does?","They → do.","Do + not = don't."],"explanation":"They don't play soccer."},{"id":"q7","type":"mc","difficulty":2,"skill":"interrogativa","prompt":"Complete a pergunta: ___ she speak Spanish?","options":["Do","Does","Is","Are"],"answer":1,"hints":["A pergunta usa um auxiliar.","\"She\" é terceira pessoa.","Do → does."],"explanation":"Does she speak Spanish?"},{"id":"q8","type":"fill","difficulty":2,"skill":"interrogativa","prompt":"Responda curto (afirmativo): \"Do you like music?\" — Yes, I ___.","answers":["do"],"hints":["Repita o auxiliar da pergunta.","A pergunta usa \"Do\".","Yes, I…"],"explanation":"Yes, I do."},{"id":"q9","type":"mc","difficulty":3,"skill":"interrogativa","prompt":"Qual pergunta está correta?","options":["Does he works here?","Do he work here?","Does he work here?","He does work here?"],"answer":2,"hints":["He → does.","Depois de does, o verbo perde o -s.","Does + he + work."],"explanation":"Does he work here?"},{"id":"q10","type":"mc","difficulty":3,"skill":"uso","prompt":"Qual frase expressa uma verdade geral?","options":["I am reading now.","The sun rises in the east.","I watched a movie.","I will travel tomorrow."],"answer":1,"hints":["Procure algo que é sempre verdade.","Não depende do momento.","Um fato da natureza."],"explanation":"\"The sun rises in the east\" — verdade geral no simple present."}],"review":["Rotinas, hábitos e verdades","He/she/it: -s, -es, -ies; have → has","Negativa: don't / doesn't + verbo base","Pergunta: Do/Does + sujeito + verbo base"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"english":{"cefr":"A1","unit":"a1-u3","order":2,"area":"grammar","focus":["grammar","reading","writing"],"vocabulary":[{"word":"wake up","translation":"acordar","pos":"phrasal verb","definition":"to stop sleeping","example":"I wake up at 6:30.","difficulty":1},{"word":"usually","translation":"geralmente","pos":"adverb","definition":"in most cases","example":"I usually walk to school.","difficulty":2,"related":["always","never","sometimes"]},{"word":"always","translation":"sempre","pos":"adverb","definition":"every time","example":"She always drinks water.","difficulty":1,"antonyms":["never"]},{"word":"never","translation":"nunca","pos":"adverb","definition":"at no time","example":"He never eats fish.","difficulty":1,"antonyms":["always"]},{"word":"breakfast","translation":"café da manhã","pos":"noun","definition":"the first meal of the day","example":"I have breakfast at seven.","difficulty":1},{"word":"homework","translation":"lição de casa","pos":"noun","definition":"school work you do at home","example":"I do my homework after lunch.","difficulty":1},{"word":"work","translation":"trabalhar","pos":"verb","definition":"to do a job","example":"My dad works in a hospital.","difficulty":1},{"word":"watch","translation":"assistir","pos":"verb","definition":"to look at something for some time","example":"She watches TV at night.","difficulty":1}],"reading":{"title":"A day in the life of Theo","genre":"texto pessoal","text":"Theo is fourteen. He lives in Florianópolis. He wakes up at six thirty and has breakfast with his mom. He goes to school by bike. After school, he does his homework and plays volleyball on the beach. Theo doesn't watch TV at night — he reads comics.","questions":[{"difficulty":1,"prompt":"Como Theo vai para a escola?","options":["De ônibus","De bicicleta","A pé","De carro"],"answer":1,"explanation":"“He goes to school by bike.”"},{"difficulty":2,"prompt":"O que ele faz depois da escola?","options":["Assiste TV","Faz a lição e joga vôlei","Dorme","Trabalha"],"answer":1,"explanation":"“he does his homework and plays volleyball”."},{"difficulty":3,"prompt":"O que Theo faz à noite?","options":["Assiste TV","Lê quadrinhos","Joga vôlei","Toma café"],"answer":1,"explanation":"“He doesn't watch TV at night — he reads comics.”"}]},"writing":{"prompt":"Escreva sobre a rotina de alguém da sua família usando he/she (lembre do -s).","criteria":["Pelo menos 4 ações","Verbos com -s/-es","Um advérbio de frequência"],"model":"My mom wakes up at 6. She always drinks coffee. She works in a bank. She goes home at 5 and usually watches the news.","keywords":["wakes","works","goes","always","usually"],"minWords":20},"challenge":"Conte a sua rotina de ontem? Não — de TODO dia! Diga 5 frases no simple present."},"games":{"blanks":[{"difficulty":1,"sentence":"She ___ to school by bus.","options":["goes","go","going","gos"],"answer":0,"explanation":"She goes (-o recebe -es)."},{"difficulty":1,"sentence":"I ___ like coffee.","options":["don't","doesn't","not","isn't"],"answer":0,"explanation":"I don't."},{"difficulty":2,"sentence":"___ he play soccer?","options":["Does","Do","Is","Are"],"answer":0,"explanation":"He → Does."},{"difficulty":2,"sentence":"My brother ___ his homework after lunch.","options":["does","do","dos","doing"],"answer":0,"explanation":"Do → does."},{"difficulty":3,"sentence":"She doesn't ___ TV at night.","options":["watch","watches","watching","watched"],"answer":0,"explanation":"Depois de doesn't: verbo base."}],"sequences":[{"difficulty":1,"prompt":"Organize a frase · Put the words in order","items":["I","wake","up","at","seven"],"words":true,"explanation":"Sujeito + verbo + complemento."},{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["She","doesn't","eat","meat"],"words":true,"explanation":"Negativa: doesn't + verbo base."},{"difficulty":3,"prompt":"Organize a frase · Put the words in order","items":["Does","your","father","work","on","Saturday"],"words":true,"explanation":"Pergunta: Does + sujeito + verbo base."}]},"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-a1-greetings","subject":"ingles","title":"Greetings and introductions","levels":["fund1","fund2","medio"],"grade":"A partir do 3º ano","topic":"Inglês A1 — Primeiros passos","subtopic":"Cumprimentos e apresentações","aliases":["greetings","cumprimentos em ingles","saudacoes em ingles","hello","good morning","como se apresentar em ingles","nice to meet you","how are you"],"summary":"Cumprimente, se apresente, pergunte como a pessoa está e despeça-se em inglês.","intro":"Hello! Toda conversa começa com um cumprimento. Vamos aprender os mais usados — e quando usar cada um.","objective":"Cumprimentar conforme o período do dia, dizer o próprio nome, perguntar como a pessoa está e se despedir com educação.","next":["ing-a1-alphabet-numbers"],"skills":{"v_greet":"Cumprimentos pelo período do dia","g_intro":"Apresentar-se (I'm… / My name is…)","s_ask":"Perguntas iniciais (How are you? What's your name?)","v_bye":"Despedidas e palavras de cortesia"},"blocks":[{"skill":"v_greet","title":"Hello, hi, good morning…","text":"Para cumprimentar usamos Hello (neutro) e Hi (mais informal, entre amigos). Para marcar o período do dia: Good morning (de manhã), Good afternoon (à tarde) e Good evening (à noite, ao chegar). Atenção: Good night não é cumprimento — é usado para se despedir à noite ou antes de dormir.","example":"Hi, Ana! · Good morning, teacher! · Good evening, everyone.","variants":{"simples":"Hello e Hi = oi/olá. Good morning = bom dia. Good afternoon = boa tarde. Good evening = boa noite (quando você chega).","exemplo":"Entrando na sala às 8h: “Good morning, teacher!”. Encontrando um amigo no intervalo: “Hi, Leo!”.","passos":"1. Veja o horário. 2. Manhã → Good morning; tarde → Good afternoon; noite, chegando → Good evening. 3. Com amigos, pode usar só Hi.","compara":"Em português, “boa noite” serve para chegar e para sair. Em inglês são duas expressões: Good evening (chegando) e Good night (saindo ou indo dormir)."},"id":"b1"},{"skill":"g_intro","title":"I'm… / My name is…","text":"Para se apresentar: I'm + nome (forma curta de I am) ou My name is + nome. Quando alguém se apresenta, respondemos Nice to meet you (Prazer em conhecer você). A resposta costuma ser Nice to meet you, too.","example":"— Hi, I'm Carla. — Hello, Carla. My name is Pedro. Nice to meet you. — Nice to meet you, too!","variants":{"simples":"I'm Carla = Eu sou a Carla. My name is Pedro = Meu nome é Pedro. Nice to meet you = Prazer!","exemplo":"No primeiro dia de aula: “Hi, I'm Júlia. I'm new here.”","passos":"1. Cumprimente: Hi! 2. Diga seu nome: I'm… 3. Quando a pessoa se apresentar, responda: Nice to meet you.","compara":"“I'm Pedro” e “My name is Pedro” dizem a mesma coisa. I'm é o mais comum na conversa; My name is soa um pouco mais formal."},"id":"b2"},{"skill":"s_ask","title":"How are you? What's your name?","text":"Perguntas básicas: What's your name? (Qual é o seu nome?), How are you? (Como você está?) e Where are you from? (De onde você é?). Respostas comuns para How are you?: I'm fine, thanks. / I'm good. / Not bad. E, para devolver a pergunta: And you?","example":"— How are you? — I'm fine, thanks. And you? — I'm good!","variants":{"simples":"What's your name? = Qual é seu nome? How are you? = Tudo bem? I'm fine, thanks = Estou bem, obrigado(a).","exemplo":"Encontrando a vizinha: “Hi, Mrs. Silva! How are you?” — “I'm good, thanks. And you?”","passos":"1. Pergunte: How are you? 2. Ouça a resposta. 3. Quando perguntarem a você: I'm fine, thanks. And you?","compara":"What's your name? pergunta o nome; Where are you from? pergunta a origem; How are you? pergunta como a pessoa está — cada pergunta pede um tipo de resposta."},"id":"b3"},{"skill":"v_bye","title":"Goodbye e palavras de cortesia","text":"Para se despedir: Bye (informal), Goodbye, See you later / See you tomorrow (até mais / até amanhã) e Have a nice day (tenha um bom dia). Palavras de cortesia: please (por favor), thank you / thanks (obrigado/a), you're welcome (de nada), sorry (desculpe) e excuse me (com licença).","example":"— Thank you! — You're welcome. · Excuse me, where is the library? · See you tomorrow!","variants":{"simples":"Bye = tchau. Thank you = obrigado. You're welcome = de nada. Sorry = desculpa. Excuse me = com licença.","exemplo":"Saindo da escola: “Bye, see you tomorrow!”. Pedindo passagem no ônibus: “Excuse me.”","passos":"1. Vai embora? Bye / See you. 2. Recebeu ajuda? Thank you. 3. Agradeceram a você? You're welcome.","compara":"Sorry é para pedir desculpas (esbarrou em alguém). Excuse me é para pedir licença ou chamar a atenção antes de perguntar algo."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"v_greet","prompt":"São 9 horas da manhã e você chega à escola. Qual cumprimento combina?","options":["Good night","Good morning","Good evening","Goodbye"],"answer":1,"hints":["Pense no período do dia.","Nove horas é de manhã.","Morning = manhã."],"explanation":"Good morning é o cumprimento da manhã.","id":"q1"},{"type":"tf","difficulty":1,"skill":"v_bye","prompt":"“Good night” é usado para cumprimentar alguém que acabou de chegar à noite.","answer":false,"hints":["Good night é para chegar ou para sair?","Pense em “boa noite, vou dormir”.","Para chegar à noite há outra expressão."],"explanation":"Falso. Ao chegar à noite: Good evening. Good night é despedida.","id":"q2"},{"type":"fill","difficulty":1,"skill":"g_intro","prompt":"Complete: “Hi! ___ name is Lucas.”","answers":["My"],"hints":["Falta a palavra “meu”.","É um possessivo.","Começa com M."],"explanation":"My name is Lucas = Meu nome é Lucas.","id":"q3"},{"type":"mc","difficulty":1,"skill":"s_ask","prompt":"— How are you? — ________","options":["I'm fine, thanks.","I'm Lucas.","I'm from Brazil.","Nice to meet you."],"answer":0,"hints":["A pergunta é sobre como você está.","Não é sobre nome nem origem.","Fine = bem."],"explanation":"“I'm fine, thanks” responde como você está.","id":"q4"},{"type":"match","difficulty":2,"skill":"v_bye","prompt":"Ligue cada expressão ao seu significado.","pairs":[["Thank you","Obrigado(a)"],["You're welcome","De nada"],["Excuse me","Com licença"],["See you later","Até mais"]],"hints":["Welcome aparece na resposta a um agradecimento.","Excuse me é usado antes de pedir algo.","Later = mais tarde."],"explanation":"Thank you = obrigado · You're welcome = de nada · Excuse me = com licença · See you later = até mais.","id":"q5"},{"type":"mc","difficulty":2,"skill":"g_intro","prompt":"Alguém diz: “Hi, I'm Sofia. Nice to meet you.” Qual é a resposta mais natural?","options":["Nice to meet you, too.","Good night.","You're welcome.","I'm fine."],"answer":0,"hints":["A pessoa disse “prazer em conhecer você”.","Devolvemos a mesma frase.","Com “too” no final."],"explanation":"Respondemos “Nice to meet you, too”.","id":"q6"},{"type":"order","difficulty":2,"skill":"s_ask","prompt":"Coloque o diálogo na ordem.","items":["Hi! What's your name?","I'm Rafa. And you?","I'm Bia. Nice to meet you.","Nice to meet you, too!"],"hints":["Primeiro alguém pergunta o nome.","Depois vem a resposta e a pergunta de volta.","O “too” sempre vem na resposta."],"explanation":"Pergunta → resposta → apresentação → Nice to meet you, too.","id":"q7"},{"type":"mc","difficulty":2,"skill":"v_bye","prompt":"Você esbarrou sem querer em alguém no corredor. O que diz?","options":["Sorry!","You're welcome.","Good morning.","See you later."],"answer":0,"hints":["Você precisa se desculpar.","Não é agradecimento nem despedida.","Desculpa = …"],"explanation":"Sorry pede desculpas por algo que já aconteceu.","id":"q8"},{"type":"mc","difficulty":3,"skill":"v_greet","prompt":"Às 20h você chega a uma festa e, às 23h, vai embora. O que diz em cada momento?","options":["Good evening… Good night.","Good night… Good evening.","Good afternoon… Goodbye.","Good morning… See you."],"answer":0,"hints":["São dois momentos: chegar e sair.","Chegar à noite tem uma expressão; sair tem outra.","Evening = chegada; night = saída."],"explanation":"Chegando: Good evening. Saindo: Good night.","id":"q9"},{"type":"tf","difficulty":3,"skill":"g_intro","prompt":"Em “I'm Carla”, “I'm” é a forma curta de “I am”.","answer":true,"hints":["O apóstrofo indica uma letra que sumiu.","I + am juntos.","Qual letra saiu?"],"explanation":"Verdadeiro: I'm = I am (a letra “a” saiu).","id":"q10"}],"review":["Good morning / afternoon / evening para chegar; Good night para sair","I'm… / My name is… · Nice to meet you (too)","How are you? — I'm fine, thanks. And you?","Please, thank you, you're welcome, sorry, excuse me"],"relatedQuestions":["como cumprimentar em inglês","como se apresentar em inglês","como dizer bom dia em inglês"],"equivalentQuestions":["como dizer oi em inglês","como falar meu nome é em inglês","qual a diferença entre good evening e good night","o que significa nice to meet you","como responder how are you","como dizer obrigado em inglês","como dizer de nada em inglês","diferença entre sorry e excuse me","o que é cumprimentos em inglês","como usar cumprimentos em inglês","me explica cumprimentos em inglês","quando usar cumprimentos em inglês","exemplos de cumprimentos em inglês","cumprimentos em inglês em inglês","como funciona cumprimentos em inglês","regras de cumprimentos em inglês","exercícios de cumprimentos em inglês","aula de cumprimentos em inglês","não entendi cumprimentos em inglês","cumprimentos em inglês para iniciantes","resumo de cumprimentos em inglês","dúvida sobre cumprimentos em inglês","o que é greetings","como usar greetings","me explica greetings","quando usar greetings","exemplos de greetings","greetings em inglês","como funciona greetings","regras de greetings","exercícios de greetings","aula de greetings","não entendi greetings","greetings para iniciantes","resumo de greetings","dúvida sobre greetings"],"commonDoubts":[{"q":"Posso dizer Good night quando chego?","a":"Não. Ao chegar à noite diga Good evening. Good night é para se despedir ou antes de dormir."},{"q":"Hi é falta de educação?","a":"Não. Hi é informal, ótimo com amigos e colegas. Em situações formais, prefira Hello ou Good morning."}],"commonErrors":["Usar Good night para cumprimentar ao chegar.","Responder “Nice to meet you” sem o “too” quando a outra pessoa já disse a frase.","Confundir sorry (desculpa) com excuse me (com licença)."],"english":{"cefr":"A1","unit":"a1-u1","order":1,"area":"vocabulary","focus":["vocabulary","speaking","listening"],"vocabulary":[{"word":"hello","translation":"olá","pos":"interjection","definition":"a word you say when you meet someone","example":"Hello, my name is Ana.","difficulty":1,"pronunciation":"rê-LÔU","synonyms":["hi"]},{"word":"hi","translation":"oi","pos":"interjection","definition":"an informal way to say hello","example":"Hi, Leo! How are you?","difficulty":1,"synonyms":["hello"]},{"word":"morning","translation":"manhã","pos":"noun","definition":"the part of the day from sunrise to noon","example":"Good morning, teacher!","difficulty":1,"collocations":["good morning","this morning"]},{"word":"afternoon","translation":"tarde","pos":"noun","definition":"the part of the day after noon and before evening","example":"Good afternoon, everyone.","difficulty":1},{"word":"evening","translation":"noite (início)","pos":"noun","definition":"the part of the day from the end of the afternoon until night","example":"Good evening, welcome to the party.","difficulty":2},{"word":"goodbye","translation":"adeus / tchau","pos":"interjection","definition":"what you say when you leave","example":"Goodbye! See you tomorrow.","difficulty":1,"synonyms":["bye"],"antonyms":["hello"]},{"word":"please","translation":"por favor","pos":"adverb","definition":"a polite word you use when you ask for something","example":"Can I have water, please?","difficulty":1},{"word":"thanks","translation":"obrigado(a)","pos":"interjection","definition":"an informal way to say thank you","example":"Thanks for the help!","difficulty":1,"synonyms":["thank you"]},{"word":"sorry","translation":"desculpe","pos":"adjective","definition":"a word to say you feel bad about something you did","example":"Sorry, I'm late.","difficulty":1},{"word":"welcome","translation":"de nada / bem-vindo","pos":"adjective","definition":"used in “you're welcome” as an answer to thank you","example":"— Thank you! — You're welcome.","difficulty":2},{"word":"name","translation":"nome","pos":"noun","definition":"the word people use to call you","example":"What's your name?","difficulty":1},{"word":"fine","translation":"bem","pos":"adjective","definition":"healthy and happy; OK","example":"I'm fine, thanks.","difficulty":1,"synonyms":["good","well"]}],"grammar":{"name":"Apresentações: I'm / My name is / What's your name?","when":"Para dizer quem você é e perguntar o nome de alguém.","structure":"I'm + nome · My name is + nome · What's your name?","affirmative":["I'm Carla.","My name is Pedro."],"negative":["I'm not Carla. I'm Carol.","My name isn't Pedro."],"interrogative":["What's your name?","Are you Pedro?","How are you?"],"compare":"What's your name? (qual é o seu nome?) × How are you? (como você está?) — perguntas diferentes, respostas diferentes.","context":"Primeiro dia num curso: “Hi, I'm Leo. What's your name?”"},"listening":{"title":"Primeiro dia de aula","kind":"dialogo","rate":0.9,"script":["Teacher: Good morning, everyone!","Tom: Good morning! Excuse me, is this room five?","Teacher: Yes, it is. What's your name?","Tom: My name is Tom. I'm new here.","Teacher: Nice to meet you, Tom. I'm Mrs. Lee.","Tom: Nice to meet you, too."],"questions":[{"difficulty":1,"prompt":"Em que período do dia acontece a conversa?","options":["De manhã","À tarde","À noite","De madrugada"],"answer":0,"explanation":"Eles dizem “Good morning”."},{"difficulty":1,"prompt":"Qual é o nome do aluno?","options":["Tim","Tom","Lee","Ted"],"answer":1,"explanation":"Ele diz “My name is Tom”."},{"difficulty":2,"prompt":"Por que Tom diz “Excuse me”?","options":["Para pedir desculpas","Para pedir licença antes de perguntar","Para se despedir","Para agradecer"],"answer":1,"explanation":"Excuse me chama a atenção antes de uma pergunta."},{"difficulty":2,"prompt":"Quem é Mrs. Lee?","options":["A professora","A mãe de Tom","Uma aluna nova","A diretora"],"answer":0,"explanation":"Ela fala como “Teacher” no diálogo."}]},"speaking":{"situation":"Você chegou numa turma nova de inglês e quer se apresentar.","vocabulary":["hello","my name is","nice to meet you","how are you"],"phrases":["Hi! My name is…","Nice to meet you.","How are you?","I'm fine, thanks. And you?"],"example":"Hi! My name is Ana. Nice to meet you. How are you?","challenge":"Diga: um cumprimento + seu nome + “nice to meet you” + uma pergunta.","expected":["hi","name","nice","meet","how"]},"writing":{"prompt":"Escreva uma mensagem curta se apresentando para um novo colega de turma.","criteria":["Tem cumprimento","Diz o seu nome","Faz uma pergunta","Termina com despedida"],"model":"Hi! My name is Ana. Nice to meet you. How are you? See you tomorrow!","keywords":["hi","name","nice","how","see"],"minWords":10},"challenge":"Cumprimente três pessoas hoje em inglês, cada vez com uma expressão diferente (Good morning, Hi, How are you?).","tips":["Good night é despedida, não cumprimento.","Nice to meet you só se diz na primeira vez que você conhece alguém."]},"games":{"blanks":[{"difficulty":1,"sentence":"___ morning, teacher!","options":["Good","Hello","Nice","Fine"],"answer":0,"explanation":"Good morning = bom dia."},{"difficulty":1,"sentence":"Nice to ___ you.","options":["meet","see","know","look"],"answer":0,"explanation":"Nice to meet you = prazer em conhecer você."},{"difficulty":2,"sentence":"— Thank you! — You're ___.","options":["welcome","sorry","fine","please"],"answer":0,"explanation":"You're welcome = de nada."},{"difficulty":2,"sentence":"— How are you? — I'm ___, thanks.","options":["fine","name","Tom","from"],"answer":0,"explanation":"I'm fine = estou bem."},{"difficulty":3,"sentence":"___ me, where is the bathroom?","options":["Excuse","Sorry","Please","Thank"],"answer":0,"explanation":"Excuse me pede licença antes de uma pergunta."}],"dialogues":[{"difficulty":1,"title":"Conhecendo alguém","gap":3,"options":["Nice to meet you, too.","Good night.","You're welcome.","I'm from Brazil."],"answer":0,"explanation":"A resposta a “Nice to meet you” é “Nice to meet you, too”.","lines":[{"who":"Ana","text":"Hi! I'm Ana."},{"who":"Leo","text":"Hello, Ana. I'm Leo."},{"who":"Ana","text":"Nice to meet you, Leo."},{"who":"Leo","text":"Nice to meet you, too."}]},{"difficulty":2,"title":"Na escola","gap":1,"options":["I'm good, thanks. And you?","My name is Rafa.","Good night!","Excuse me."],"answer":0,"explanation":"Depois de “How are you?”, dizemos como estamos e devolvemos a pergunta.","lines":[{"who":"Teacher","text":"Good morning, Rafa. How are you?"},{"who":"Rafa","text":"I'm good, thanks. And you?"},{"who":"Teacher","text":"I'm fine. Is this your pen?"},{"who":"Rafa","text":"Yes! Thank you!"},{"who":"Teacher","text":"You're welcome."}]},{"difficulty":3,"title":"Hora de ir embora","gap":2,"options":["Thanks! See you tomorrow.","Nice to meet you.","Good morning!","I'm fine."],"answer":0,"explanation":"Agradecemos o “have a nice evening” e nos despedimos.","lines":[{"who":"Bia","text":"It's late. I have to go."},{"who":"Caio","text":"OK! Have a nice evening."},{"who":"Bia","text":"Thanks! See you tomorrow."},{"who":"Caio","text":"Bye! Good night!"}]}],"sequences":[{"difficulty":1,"prompt":"Organize a frase · Put the words in order","items":["My","name","is","Ana"],"words":true,"explanation":"Em inglês: My name is + nome."},{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["Nice","to","meet","you","too"],"words":true,"explanation":"É a resposta quando alguém diz “Nice to meet you”."},{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["How","are","you","today"],"words":true,"explanation":"Pergunta: How + are + you."}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-a1-alphabet-numbers","subject":"ingles","title":"Alphabet, spelling and numbers","levels":["fund1","fund2","medio"],"grade":"A partir do 3º ano","topic":"Inglês A1 — Primeiros passos","subtopic":"Alfabeto, soletrar e números","aliases":["alfabeto em ingles","alphabet","soletrar em ingles","spelling","numeros em ingles","numbers","how do you spell","contar em ingles"],"summary":"Aprenda o alfabeto, soletre seu nome, diga números de 0 a 100 e informe idade e telefone.","intro":"A, B, C… Em inglês as letras têm outros nomes. Vamos soletrar e contar!","objective":"Soletrar nomes e palavras, entender letras soletradas, dizer números de 0 a 100, a idade e um número de telefone.","prerequisites":["ing-a1-greetings"],"next":["ing-a1-countries"],"skills":{"p_letters":"Nome das letras","s_spell":"Soletrar (How do you spell…?)","v_num":"Números de 0 a 20","v_tens":"Dezenas e números até 100"},"blocks":[{"skill":"p_letters","title":"The alphabet","text":"O alfabeto inglês tem as mesmas 26 letras, mas o nome delas é diferente. As que mais confundem os brasileiros: A (êi), E (í), I (ái), G (dji), J (djêi), H (êitch), R (ár), W (dâbou-iú) e Y (uái). Dizer bem essas letras evita erros ao soletrar nomes e e-mails.","example":"A (êi) · E (í) · I (ái) · G (dji) · J (djêi)","variants":{"simples":"As letras são as mesmas, só o nome muda. A se diz “êi”, E se diz “í” e I se diz “ái”.","exemplo":"Seu e-mail tem “g”? Ao ditar, diga “dji” — se disser “gê”, a pessoa pode escrever “j”.","passos":"1. Ouça o nome da letra. 2. Repita. 3. Treine primeiro as vogais: A, E, I, O, U = êi, í, ái, ou, iú.","compara":"Em português, E se diz “é” e I se diz “i”. Em inglês é como se fossem trocados: E = “í” e I = “ái”."},"id":"b1"},{"skill":"s_spell","title":"How do you spell it?","text":"Para pedir que alguém soletre: How do you spell your name? ou Can you spell that, please? Soletramos letra por letra. Letras repetidas podem ser ditas como “double”: “double L” = LL.","example":"— How do you spell your name? — B-E-L-L-A. (B, E, double L, A)","variants":{"simples":"Soletrar = dizer as letras uma por uma. Double L = duas letras L seguidas.","exemplo":"Ao se inscrever num curso online, a atendente pergunta: “How do you spell your last name?”","passos":"1. Ouça a pergunta: How do you spell…? 2. Diga as letras uma por uma. 3. Letras repetidas: “double”.","compara":"Em português, dizemos “dois L” ou “L, L”. Em inglês é comum “double L”."},"id":"b2"},{"skill":"v_num","title":"Numbers 0–20","text":"0 zero · 1 one · 2 two · 3 three · 4 four · 5 five · 6 six · 7 seven · 8 eight · 9 nine · 10 ten · 11 eleven · 12 twelve · 13 thirteen · 14 fourteen · 15 fifteen · 16 sixteen · 17 seventeen · 18 eighteen · 19 nineteen · 20 twenty. De 13 a 19 os números terminam em -teen. Para a idade: I'm 12 (years old).","example":"I'm eleven. · My brother is fifteen.","variants":{"simples":"Um, dois, três = one, two, three. De 13 a 19 todos terminam em “teen”.","exemplo":"Perguntaram sua idade: “How old are you?” — “I'm thirteen.”","passos":"1. Decore de 1 a 12 (são diferentes). 2. De 13 a 19: número + teen. 3. Para a idade: I'm + número.","compara":"Cuidado: thirteen (13) × thirty (30); fifteen (15) × fifty (50). No -teen, a força da voz fica no final: thir-TEEN; no -ty, no começo: THIR-ty."},"id":"b3"},{"skill":"v_tens","title":"Tens and numbers to 100","text":"Dezenas: 20 twenty · 30 thirty · 40 forty · 50 fifty · 60 sixty · 70 seventy · 80 eighty · 90 ninety · 100 one hundred. Os outros números juntam dezena + unidade com hífen: 21 twenty-one, 45 forty-five, 99 ninety-nine. Telefones são ditos número por número; o 0 pode ser “oh”.","example":"34 thirty-four · 58 fifty-eight · phone: 9-8-7-oh-5…","variants":{"simples":"Dezenas terminam em -ty. 21 = twenty-one (vinte + um).","exemplo":"Preço de um livro: “It's forty-five reais.”","passos":"1. Diga a dezena (forty). 2. Um hífen. 3. Diga a unidade (five): forty-five.","compara":"Forty se escreve SEM u (não é “fourty”), mesmo vindo de four."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"p_letters","prompt":"Como se diz a letra E em inglês?","options":["é","í","ái","êi"],"answer":1,"hints":["É diferente do português.","Parece o nosso I.","Soa como “í”."],"explanation":"E se diz “í”.","id":"q1"},{"type":"mc","difficulty":1,"skill":"v_num","prompt":"Qual é o número “twelve”?","options":["2","11","12","20"],"answer":2,"hints":["Não termina em -teen.","Vem logo depois de eleven.","Eleven = 11."],"explanation":"Twelve = 12.","id":"q2"},{"type":"fill","difficulty":1,"skill":"v_num","prompt":"Escreva em inglês o número 3.","answers":["three"],"hints":["Começa com th.","Rima com free.","th-r-e-e."],"explanation":"3 = three.","id":"q3"},{"type":"tf","difficulty":1,"skill":"s_spell","prompt":"Para pedir que alguém soletre o nome, perguntamos “How do you spell your name?”","answer":true,"hints":["Spell = soletrar.","A pergunta começa com How.","É exatamente essa a pergunta."],"explanation":"Verdadeiro.","id":"q4"},{"type":"match","difficulty":2,"skill":"v_tens","prompt":"Ligue cada número à escrita correta.","pairs":[["30","thirty"],["13","thirteen"],["40","forty"],["15","fifteen"]],"hints":["-teen = de 13 a 19.","-ty = dezenas.","Forty não tem u."],"explanation":"30 thirty · 13 thirteen · 40 forty · 15 fifteen.","id":"q5"},{"type":"mc","difficulty":2,"skill":"v_tens","prompt":"Como se escreve 45?","options":["fourty-five","forty-five","fourteen-five","forty five teen"],"answer":1,"hints":["Primeiro a dezena, depois a unidade.","Forty se escreve sem u.","Com hífen."],"explanation":"45 = forty-five.","id":"q6"},{"type":"mc","difficulty":2,"skill":"s_spell","prompt":"A pessoa soletra: “M, A, double R, Y”. Qual é o nome?","options":["Mary","Marry","Marey","Mari"],"answer":1,"hints":["Double R = duas letras R.","Conte as letras: M, A, R, R, Y.","São 5 letras."],"explanation":"M-A-R-R-Y = Marry.","id":"q7"},{"type":"mc","difficulty":2,"skill":"p_letters","prompt":"Ao soletrar um e-mail, você diz “dji”. Que letra é?","options":["J","G","D","Z"],"answer":1,"hints":["É uma letra que o brasileiro costuma trocar.","Não é J (djêi).","É a letra de “good”."],"explanation":"“dji” é o nome da letra G.","id":"q8"},{"type":"order","difficulty":3,"skill":"v_tens","prompt":"Coloque os números em ordem crescente.","items":["thirteen","nineteen","thirty","fifty-two","ninety"],"hints":["-teen são menores que as dezenas.","Thirteen (13) vem antes de nineteen (19).","Depois vêm 30, 52 e 90."],"explanation":"13, 19, 30, 52, 90.","id":"q9"},{"type":"mc","difficulty":3,"skill":"v_num","prompt":"Alguém diz “I'm fif-TEEN”, com força no final. Qual é a idade?","options":["50","15","5","16"],"answer":1,"hints":["Força no final = -teen.","-teen = de 13 a 19.","Fif + teen."],"explanation":"Força no final indica -teen: 15.","id":"q10"}],"review":["Vogais: A êi · E í · I ái · O ou · U iú","How do you spell…? · double L","13–19 terminam em -teen; dezenas em -ty","Forty (sem u) · 21 = twenty-one"],"relatedQuestions":["alfabeto em inglês","como soletrar em inglês","números em inglês de 1 a 100"],"equivalentQuestions":["como falar as letras em inglês","como soletrar meu nome em inglês","como se escreve 40 em inglês","diferença entre thirteen e thirty","como dizer minha idade em inglês","como falar telefone em inglês","o que significa double l","como se diz a letra g em inglês","o que é alfabeto em inglês","como usar alfabeto em inglês","me explica alfabeto em inglês","quando usar alfabeto em inglês","exemplos de alfabeto em inglês","alfabeto em inglês em inglês","como funciona alfabeto em inglês","regras de alfabeto em inglês","exercícios de alfabeto em inglês","aula de alfabeto em inglês","não entendi alfabeto em inglês","alfabeto em inglês para iniciantes","resumo de alfabeto em inglês","dúvida sobre alfabeto em inglês","o que é números em inglês","como usar números em inglês","me explica números em inglês","quando usar números em inglês","exemplos de números em inglês","números em inglês em inglês","como funciona números em inglês","regras de números em inglês","exercícios de números em inglês","aula de números em inglês","não entendi números em inglês","números em inglês para iniciantes","resumo de números em inglês","dúvida sobre números em inglês"],"commonErrors":["Escrever “fourty” em vez de forty.","Confundir thirteen (13) com thirty (30).","Dizer as vogais com o som do português ao soletrar."],"english":{"cefr":"A1","unit":"a1-u1","order":2,"area":"pronunciation","focus":["vocabulary","listening","speaking"],"vocabulary":[{"word":"spell","translation":"soletrar","pos":"verb","definition":"to say the letters of a word one by one","example":"How do you spell your name?","difficulty":1},{"word":"letter","translation":"letra","pos":"noun","definition":"one of the signs of the alphabet","example":"A is the first letter.","difficulty":1},{"word":"number","translation":"número","pos":"noun","definition":"a word or sign like 1, 2 or 3","example":"What's your phone number?","difficulty":1},{"word":"three","translation":"três","pos":"number","definition":"the number 3","example":"I have three cats.","difficulty":1},{"word":"twelve","translation":"doze","pos":"number","definition":"the number 12","example":"My sister is twelve.","difficulty":1},{"word":"thirteen","translation":"treze","pos":"number","definition":"the number 13","example":"I'm thirteen years old.","difficulty":2,"related":["thirty"]},{"word":"thirty","translation":"trinta","pos":"number","definition":"the number 30","example":"There are thirty students.","difficulty":2,"related":["thirteen"]},{"word":"forty","translation":"quarenta","pos":"number","definition":"the number 40","example":"The book costs forty reais.","difficulty":2},{"word":"fifty","translation":"cinquenta","pos":"number","definition":"the number 50","example":"Fifty people came.","difficulty":2},{"word":"hundred","translation":"cem / centena","pos":"number","definition":"the number 100","example":"One hundred days.","difficulty":2},{"word":"old","translation":"velho / de idade","pos":"adjective","definition":"used to talk about age","example":"How old are you?","difficulty":1},{"word":"phone","translation":"telefone","pos":"noun","definition":"a device to call people","example":"My phone number is 9-8-7-6.","difficulty":1}],"listening":{"title":"Ficha de inscrição","kind":"dialogo","rate":0.85,"script":["Woman: Hello! What's your name, please?","Boy: Daniel Brooks.","Woman: How do you spell Brooks?","Boy: B, R, double O, K, S.","Woman: Thank you. How old are you, Daniel?","Boy: I'm fourteen.","Woman: And your phone number?","Boy: It's nine, eight, oh, three, five, two."],"questions":[{"difficulty":1,"prompt":"Qual é o sobrenome do menino?","options":["Brokes","Brooks","Broks","Bruks"],"answer":1,"explanation":"B-R-double O-K-S = Brooks."},{"difficulty":2,"prompt":"Quantos anos ele tem?","options":["4","14","40","15"],"answer":1,"explanation":"Ele diz “fourteen”."},{"difficulty":2,"prompt":"O que significa “oh” no telefone?","options":["A letra O","O número zero","Uma exclamação","O número 1"],"answer":1,"explanation":"Ao dizer números de telefone, o 0 pode ser “oh”."}]},"speaking":{"situation":"Você está se inscrevendo numa competição online e precisa soletrar seu nome e dizer sua idade.","vocabulary":["spell","double","years old"],"phrases":["My name is…","It's spelled…","I'm … years old."],"example":"My name is Bella. B, E, double L, A. I'm twelve years old.","challenge":"Soletre seu nome completo e diga sua idade em inglês.","expected":["name","old"]},"writing":{"prompt":"Escreva, por extenso em inglês, a sua idade, a idade de duas pessoas da família e o número da sua casa.","criteria":["Números por extenso","Dezenas com hífen","Frases com I'm / is"],"model":"I'm thirteen. My mother is forty-two. My brother is nine. My house number is fifty-five.","keywords":["is","my","years"],"minWords":10},"challenge":"Leia em inglês, em voz alta, os números de uma página de revista ou os preços de um folheto.","tips":["Força no final (-TEEN) = 13 a 19; força no começo (TH-ir-ty) = dezenas.","Treine as vogais em inglês: êi, í, ái, ou, iú."]},"games":{"words":[{"word":"spell","clue":"soletrar","difficulty":1},{"word":"letter","clue":"letra","difficulty":1},{"word":"twelve","clue":"12","difficulty":1},{"word":"thirteen","clue":"13","difficulty":2},{"word":"forty","clue":"40","difficulty":2},{"word":"hundred","clue":"100","difficulty":3},{"word":"seven","clue":"7","difficulty":1}],"blanks":[{"difficulty":1,"sentence":"How do you ___ your name?","options":["spell","say","write","call"],"answer":0,"explanation":"Spell = soletrar."},{"difficulty":1,"sentence":"— How ___ are you? — I'm ten.","options":["old","many","much","age"],"answer":0,"explanation":"How old are you? pergunta a idade."},{"difficulty":2,"sentence":"45 = ___-five","options":["forty","fourty","fourteen","fifty"],"answer":0,"explanation":"Forty sem u."},{"difficulty":2,"sentence":"13 = ___","options":["thirteen","thirty","three-ten","threeteen"],"answer":0,"explanation":"13 = thirteen."},{"difficulty":3,"sentence":"M, A, ___ R, Y — Marry","options":["double","two","twice","pair"],"answer":0,"explanation":"Letras repetidas: double."}],"pairs":[{"a":"50","b":"fifty","difficulty":1},{"a":"15","b":"fifteen","difficulty":2},{"a":"90","b":"ninety","difficulty":2},{"a":"19","b":"nineteen","difficulty":2}],"sequences":[{"prompt":"Coloque em ordem crescente · From smallest to biggest","items":["eight","eleven","eighteen","eighty","one hundred"],"difficulty":2,"explanation":"8, 11, 18, 80, 100."}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-a1-countries","subject":"ingles","title":"Countries and nationalities","levels":["fund1","fund2","medio"],"grade":"A partir do 4º ano","topic":"Inglês A1 — Primeiros passos","subtopic":"Países, nacionalidades e idiomas","aliases":["paises em ingles","nacionalidades em ingles","countries","nationalities","where are you from","idiomas em ingles","brazilian"],"summary":"Diga de onde você é, fale países, nacionalidades e idiomas e descubra onde o inglês é falado.","intro":"Where are you from? Vamos viajar pelo mapa aprendendo países e nacionalidades.","objective":"Perguntar e dizer de onde alguém é, diferenciar país, nacionalidade e idioma e escrevê-los com letra maiúscula.","prerequisites":["ing-a1-greetings"],"next":["ing-verb-to-be"],"skills":{"s_from":"Where are you from? / I'm from…","v_nation":"Nacionalidades","v_lang":"Idiomas e letra maiúscula","r_world":"Onde o inglês é falado"},"blocks":[{"skill":"s_from","title":"Where are you from?","text":"Para perguntar a origem: Where are you from? A resposta: I'm from + país (I'm from Brazil). Para outra pessoa: Where is she from? — She's from Canada.","example":"— Where are you from? — I'm from Brazil. And you? — I'm from Portugal.","variants":{"simples":"Where are you from? = De onde você é? I'm from Brazil = Eu sou do Brasil.","exemplo":"Num jogo online, alguém escreve: “Where are you from?”. Você responde: “I'm from Brazil!”","passos":"1. Pergunta: Where + are + you + from? 2. Resposta: I'm from + país.","compara":"Em português, “de onde você é?” começa com “de”. Em inglês o “from” vai para o FINAL da pergunta: Where are you from?"},"id":"b1"},{"skill":"v_nation","title":"Nationalities","text":"A nacionalidade descreve a pessoa: I'm Brazilian. Muitas terminam em -an/-ian (Brazilian, American, Canadian, Mexican), outras em -ish (British, Spanish, English, Irish) ou -ese (Japanese, Chinese, Portuguese); algumas são irregulares (French, Greek).","example":"Brazil → Brazilian · Spain → Spanish · Japan → Japanese · France → French","variants":{"simples":"País = lugar (Brazil). Nacionalidade = quem é de lá (Brazilian).","exemplo":"“I'm from Brazil. I'm Brazilian.” As duas frases estão certas e dizem quase a mesma coisa.","passos":"1. Saiba o país. 2. Veja a terminação: -ian, -ish, -ese ou irregular. 3. Use: I'm + nacionalidade.","compara":"Diga “I'm from Brazil” (from + país) ou “I'm Brazilian” (sem from + nacionalidade). “I'm from Brazilian” está errado."},"id":"b2"},{"skill":"v_lang","title":"Languages and capital letters","text":"Muitos idiomas têm o mesmo nome da nacionalidade: English, Spanish, French, Japanese. No Brasil falamos Portuguese. Em inglês, países, nacionalidades e idiomas SEMPRE começam com letra maiúscula.","example":"People in Brazil speak Portuguese. · She speaks English and French.","variants":{"simples":"Idioma: English (inglês), Portuguese (português). Sempre com letra maiúscula.","exemplo":"Numa rede social: “I speak Portuguese and a little English.”","passos":"1. Idioma quase sempre = nacionalidade. 2. Letra maiúscula. 3. Use com speak: I speak…","compara":"Em português escrevemos “brasileiro” e “inglês” com minúscula. Em inglês é obrigatório: Brazilian, English."},"id":"b3"},{"skill":"r_world","title":"English around the world","text":"O inglês é idioma oficial ou principal em muitos países, como Estados Unidos (the United States), Reino Unido (the United Kingdom), Canadá, Austrália, Irlanda, Nova Zelândia e África do Sul, e é idioma oficial na Índia e na Nigéria, entre outros. Por isso ele é tão usado para viagens, estudos e internet.","example":"English is spoken in Canada, Australia and Ireland.","variants":{"simples":"O inglês é falado em vários países do mundo, em quase todos os continentes.","exemplo":"Um canal de ciência da Austrália e uma série dos Estados Unidos: os dois em inglês, com sotaques diferentes.","passos":"1. Pense em países de vários continentes. 2. Muitos têm o inglês como idioma oficial. 3. Os sotaques mudam, o idioma é o mesmo.","compara":"Assim como o português é falado no Brasil, em Portugal, em Angola e em Moçambique, o inglês é falado em muitos países — com sotaques diferentes."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"s_from","prompt":"— Where are you from? — ________","options":["I'm from Brazil.","I'm Brazil.","I'm twelve.","I'm fine."],"answer":0,"hints":["A pergunta é sobre origem.","Use from + país.","I'm from…"],"explanation":"I'm from Brazil.","id":"q1"},{"type":"mc","difficulty":1,"skill":"v_nation","prompt":"Qual é a nacionalidade de quem nasceu no Japão (Japan)?","options":["Japanish","Japanese","Japanian","Japaner"],"answer":1,"hints":["A terminação é -ese.","Igual a Chinese.","Japan + ese."],"explanation":"Japan → Japanese.","id":"q2"},{"type":"tf","difficulty":1,"skill":"v_lang","prompt":"Em inglês, “english” se escreve com letra minúscula, como em português.","answer":false,"hints":["Idiomas em inglês…","…sempre com maiúscula.","English."],"explanation":"Falso. English, Portuguese, Brazilian: sempre maiúscula.","id":"q3"},{"type":"fill","difficulty":1,"skill":"v_nation","prompt":"Complete: I'm from Brazil. I'm ________.","answers":["Brazilian"],"hints":["É a nacionalidade.","Termina em -ian.","Brazil + ian."],"explanation":"Brazil → Brazilian.","id":"q4"},{"type":"match","difficulty":2,"skill":"v_nation","prompt":"Ligue o país à nacionalidade.","pairs":[["Spain","Spanish"],["Canada","Canadian"],["France","French"],["Portugal","Portuguese"]],"hints":["Spain termina em -ish.","Canada em -ian.","France é irregular."],"explanation":"Spanish · Canadian · French · Portuguese.","id":"q5"},{"type":"mc","difficulty":2,"skill":"s_from","prompt":"Qual pergunta está correta?","options":["From where you are?","Where are you from?","Where you are from?","Where from are you?"],"answer":1,"hints":["A palavra de pergunta vem primeiro.","Depois o verbo to be.","From fica no final."],"explanation":"Where are you from?","id":"q6"},{"type":"mc","difficulty":2,"skill":"v_lang","prompt":"Em qual país o idioma principal NÃO é o inglês?","options":["Australia","Ireland","Mexico","New Zealand"],"answer":2,"hints":["Três desses países falam inglês.","Pense na América Latina.","Lá se fala espanhol."],"explanation":"No México a língua principal é o espanhol.","id":"q7"},{"type":"mc","difficulty":2,"skill":"r_world","prompt":"Qual é o nome em inglês do Reino Unido?","options":["the United States","the United Kingdom","the England Union","the British States"],"answer":1,"hints":["Kingdom = reino.","States = estados.","The United Kingdom."],"explanation":"Reino Unido = the United Kingdom (UK).","id":"q8"},{"type":"mc","difficulty":3,"skill":"v_nation","prompt":"Qual frase está correta?","options":["She's from Brazilian.","She's Brazil.","She's from Brazil.","She's from brazil."],"answer":2,"hints":["From vem com o país.","Sem from vem a nacionalidade.","E sempre maiúscula."],"explanation":"She's from Brazil. (ou She's Brazilian.)","id":"q9"},{"type":"tf","difficulty":3,"skill":"r_world","prompt":"O inglês é idioma oficial em países de mais de um continente.","answer":true,"hints":["Pense na Austrália.","E no Canadá.","Oceania, América, Europa, África…"],"explanation":"Verdadeiro: EUA, Canadá, Reino Unido, Irlanda, Austrália, Nova Zelândia, África do Sul, Índia…","id":"q10"}],"review":["Where are you from? — I'm from Brazil.","Nacionalidade: -ian, -ish, -ese ou irregular","Países, nacionalidades e idiomas com letra maiúscula","O inglês é falado em vários continentes"],"relatedQuestions":["como dizer de onde eu sou em inglês","nacionalidades em inglês","países que falam inglês"],"equivalentQuestions":["como se diz brasileiro em inglês","como responder where are you from","como escrever japonês em inglês","quais países falam inglês","como dizer eu falo português em inglês","diferença entre brazil e brazilian","idiomas em inglês têm letra maiúscula","o que é nacionalidades em inglês","como usar nacionalidades em inglês","me explica nacionalidades em inglês","quando usar nacionalidades em inglês","exemplos de nacionalidades em inglês","nacionalidades em inglês em inglês","como funciona nacionalidades em inglês","regras de nacionalidades em inglês","exercícios de nacionalidades em inglês","aula de nacionalidades em inglês","não entendi nacionalidades em inglês","nacionalidades em inglês para iniciantes","resumo de nacionalidades em inglês","dúvida sobre nacionalidades em inglês","o que é países em inglês","como usar países em inglês","me explica países em inglês","quando usar países em inglês","exemplos de países em inglês","países em inglês em inglês","como funciona países em inglês","regras de países em inglês","exercícios de países em inglês","aula de países em inglês","não entendi países em inglês","países em inglês para iniciantes","resumo de países em inglês","dúvida sobre países em inglês"],"commonErrors":["Dizer “I'm from Brazilian”.","Escrever nacionalidades e idiomas com letra minúscula.","Começar a pergunta com “From where”."],"english":{"cefr":"A1","unit":"a1-u1","order":3,"area":"vocabulary","focus":["vocabulary","reading","writing"],"vocabulary":[{"word":"country","translation":"país","pos":"noun","definition":"a nation with its own land and government","example":"Brazil is a big country.","difficulty":1},{"word":"Brazilian","translation":"brasileiro(a)","pos":"adjective","definition":"from Brazil","example":"I'm Brazilian.","difficulty":1},{"word":"English","translation":"inglês (idioma)","pos":"noun","definition":"the language of the UK, the US and other countries","example":"I speak English.","difficulty":1},{"word":"Spanish","translation":"espanhol","pos":"adjective","definition":"from Spain; the language of Spain and many countries","example":"She speaks Spanish.","difficulty":1},{"word":"French","translation":"francês","pos":"adjective","definition":"from France; the language of France","example":"He's French.","difficulty":2},{"word":"Japanese","translation":"japonês","pos":"adjective","definition":"from Japan; the language of Japan","example":"My friend is Japanese.","difficulty":2},{"word":"Canadian","translation":"canadense","pos":"adjective","definition":"from Canada","example":"They are Canadian.","difficulty":2},{"word":"Portuguese","translation":"português","pos":"noun","definition":"the language of Brazil and Portugal","example":"People in Brazil speak Portuguese.","difficulty":1},{"word":"speak","translation":"falar (idioma)","pos":"verb","definition":"to use a language","example":"Do you speak English?","difficulty":1},{"word":"from","translation":"de (origem)","pos":"preposition","definition":"used to say where someone was born or lives","example":"I'm from Recife.","difficulty":1}],"reading":{"title":"New pen pals","genre":"mensagens de apresentação","text":"Hi! I'm Aiko. I'm from Japan and I'm twelve. I speak Japanese and a little English.\n\nHello! My name is Lucas. I'm Brazilian. I live in Salvador. I speak Portuguese and English.\n\nHi, everyone! I'm Emma. I'm from Canada. I speak English and French.","questions":[{"difficulty":1,"prompt":"De onde é Aiko?","options":["China","Japan","Canada","Brazil"],"answer":1,"explanation":"Ela diz “I'm from Japan”."},{"difficulty":1,"prompt":"Que idiomas Lucas fala?","options":["Portuguese and English","Only Portuguese","Spanish and English","French"],"answer":0,"explanation":"“I speak Portuguese and English.”"},{"difficulty":2,"prompt":"Quem fala francês?","options":["Aiko","Lucas","Emma","Ninguém"],"answer":2,"explanation":"Emma: “I speak English and French.”"},{"difficulty":3,"prompt":"Qual informação NÃO aparece no texto?","options":["A idade de Aiko","A cidade de Lucas","A idade de Emma","O país de Emma"],"answer":2,"explanation":"Só Aiko diz a idade."}]},"speaking":{"situation":"Um intercambista pergunta de onde você é e que idiomas fala.","vocabulary":["from","Brazilian","speak","Portuguese"],"phrases":["I'm from Brazil.","I'm Brazilian.","I speak Portuguese and a little English."],"example":"I'm from Brazil. I'm Brazilian and I speak Portuguese.","challenge":"Diga de onde você é, sua nacionalidade e os idiomas que você fala.","expected":["from","brazil","speak","portuguese"]},"writing":{"prompt":"Escreva um perfil curto para um site de amigos por correspondência: nome, país, nacionalidade e idiomas.","criteria":["Nome","País com from","Nacionalidade","Idiomas com letra maiúscula"],"model":"Hi! My name is Carla. I'm from Brazil. I'm Brazilian. I speak Portuguese and English.","keywords":["name","from","speak","brazil"],"minWords":12},"challenge":"Escolha três países no mapa e diga, em inglês, a nacionalidade de quem nasce em cada um."},"games":{"blanks":[{"difficulty":1,"sentence":"Where are you ___?","options":["from","of","in","to"],"answer":0,"explanation":"Where are you from?"},{"difficulty":1,"sentence":"I'm from Spain. I'm ___.","options":["Spanish","Spain","Spanian","Spaniese"],"answer":0,"explanation":"Spain → Spanish."},{"difficulty":2,"sentence":"People in Brazil speak ___.","options":["Portuguese","Brazilian","Spanish","Brazil"],"answer":0,"explanation":"No Brasil falamos português."},{"difficulty":2,"sentence":"She's from Canada. She's ___.","options":["Canadian","Canadese","Canadish","Canada"],"answer":0,"explanation":"Canada → Canadian."},{"difficulty":3,"sentence":"Do you ___ English?","options":["speak","talk","say","tell"],"answer":0,"explanation":"Com idiomas usamos speak."}],"map":{"map":"mundo","prompt":"Países onde o inglês é idioma oficial ou principal · Where is English spoken?","targets":[{"id":"United States of America","label":"the United States","clue":"na América do Norte, ao sul do Canadá","difficulty":1},{"id":"United Kingdom","label":"the United Kingdom","clue":"uma ilha a noroeste da Europa","difficulty":1},{"id":"Canada","label":"Canada","clue":"o país mais ao norte da América","difficulty":1},{"id":"Australia","label":"Australia","clue":"um país-continente na Oceania","difficulty":1},{"id":"Ireland","label":"Ireland","clue":"a ilha a oeste do Reino Unido","difficulty":3},{"id":"New Zealand","label":"New Zealand","clue":"ilhas a sudeste da Austrália","difficulty":3},{"id":"South Africa","label":"South Africa","clue":"no extremo sul da África","difficulty":2},{"id":"India","label":"India","clue":"no sul da Ásia (o inglês é um dos idiomas oficiais)","difficulty":2}]},"sequences":[{"difficulty":1,"prompt":"Organize a frase · Put the words in order","items":["I","am","from","Brazil"],"words":true,"explanation":"I + am + from + país."},{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["Where","are","you","from"],"words":true,"explanation":"From fica no final da pergunta."}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-a1-family","subject":"ingles","title":"Family and possessive adjectives","levels":["fund1","fund2","medio"],"grade":"A partir do 4º ano","topic":"Inglês A1 — Primeiros passos","subtopic":"Família e adjetivos possessivos","aliases":["familia em ingles","family","membros da familia em ingles","possessive adjectives","my your his her","pronomes possessivos","genitivo","apostrofo s"],"summary":"Fale da sua família com my, your, his, her, our e their e mostre de quem é algo com ’s.","intro":"This is my family! Vamos apresentar as pessoas que moram com a gente.","objective":"Nomear membros da família, usar os adjetivos possessivos corretamente e indicar posse com ’s.","prerequisites":["ing-verb-to-be"],"next":["ing-a1-this-that"],"skills":{"v_family":"Membros da família","g_poss":"My, your, his, her, its","g_poss2":"Our e their","g_s":"Posse com ’s"},"blocks":[{"skill":"v_family","title":"My family","text":"Família: mother/mom (mãe), father/dad (pai), parents (pais), sister (irmã), brother (irmão), grandmother/grandma (avó), grandfather/grandpa (avô), aunt (tia), uncle (tio), cousin (primo/prima), son (filho), daughter (filha).","example":"This is my mother. Her name is Rosa. · I have two brothers.","variants":{"simples":"Mother = mãe, father = pai, sister = irmã, brother = irmão.","exemplo":"Mostrando uma foto: “This is my grandma and this is my cousin, Theo.”","passos":"1. Mulheres: mother, sister, aunt, grandmother, daughter. 2. Homens: father, brother, uncle, grandfather, son. 3. Cousin serve para os dois.","compara":"Cuidado com “parents”: parece “parentes”, mas significa PAI E MÃE. Parentes em geral = relatives."},"id":"b1"},{"skill":"g_poss","title":"My, your, his, her, its","text":"Os adjetivos possessivos vêm antes do substantivo e mostram de quem é: I → my (meu/minha), you → your (seu/sua), he → his (dele), she → her (dela), it → its (dele/dela, para coisas e animais). Eles não mudam para plural: my brothers, her cousins.","example":"This is Ana. Her brother is ten. · This is Leo. His sister is nine.","variants":{"simples":"My = meu/minha. Your = seu/sua. His = dele. Her = dela.","exemplo":"Apresentando amigos: “This is Paulo. His dog is Max. This is Luna. Her cat is Mia.”","passos":"1. Veja quem é o DONO. 2. Dono homem → his; dono mulher → her. 3. O possessivo vem antes da coisa.","compara":"Em português, “seu irmão” pode ser dele ou dela. Em inglês você escolhe pelo dono: his brother (dele) ou her brother (dela)."},"id":"b2"},{"skill":"g_poss2","title":"Our and their","text":"Para mais de uma pessoa: we → our (nosso/nossa) e they → their (deles/delas). Como os outros possessivos, não vão para o plural: our parents, their house.","example":"We love our grandparents. · They are my cousins. Their names are Bia and Rui.","variants":{"simples":"Our = nosso. Their = deles/delas.","exemplo":"Na aula: “This is our classroom. Those are the students and their teacher.”","passos":"1. Dono = nós → our. 2. Dono = eles/elas → their. 3. Nunca coloque -s no possessivo.","compara":"Their (deles), there (lá) e they're (eles são) têm o mesmo som, mas escritas e sentidos diferentes."},"id":"b3"},{"skill":"g_s","title":"Possession with ’s","text":"Para dizer de quem é algo usando o nome da pessoa, colocamos ’s depois do dono: Maria's bag (a bolsa da Maria), my father's car (o carro do meu pai). Se o dono já termina em s por ser plural, só o apóstrofo: my parents' house.","example":"This is Carlos's phone. · My sister's name is Clara.","variants":{"simples":"Maria's bag = a bolsa da Maria. O ’s mostra o dono.","exemplo":"Achados e perdidos: “Is this Pedro's jacket?” — “Yes, it's Pedro's.”","passos":"1. Escreva o dono. 2. Coloque ’s. 3. Depois a coisa: dono + ’s + coisa.","compara":"Em português a ordem é “coisa + de + dono” (o carro do pai). Em inglês inverte: dono + ’s + coisa (Dad's car)."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"v_family","prompt":"Como se diz “irmã” em inglês?","options":["brother","sister","cousin","aunt"],"answer":1,"hints":["Brother é irmão.","É uma palavra feminina.","Começa com s."],"explanation":"Irmã = sister.","id":"q1"},{"type":"tf","difficulty":1,"skill":"v_family","prompt":"“Parents” significa “parentes”.","answer":false,"hints":["É um falso amigo.","Parents são duas pessoas específicas.","Pai e mãe."],"explanation":"Falso. Parents = pai e mãe. Parentes = relatives.","id":"q2"},{"type":"mc","difficulty":1,"skill":"g_poss","prompt":"This is Ana. ___ dog is white.","options":["His","Her","My","Its"],"answer":1,"hints":["O dono é a Ana.","Ana é mulher.","Possessivo feminino."],"explanation":"O dono é mulher: her.","id":"q3"},{"type":"fill","difficulty":1,"skill":"g_poss","prompt":"Complete: I'm Leo and this is ___ sister, Nina. (meu/minha)","answers":["my"],"hints":["Possessivo de I.","Duas letras.","M…"],"explanation":"I → my.","id":"q4"},{"type":"match","difficulty":2,"skill":"g_poss2","prompt":"Ligue o pronome ao possessivo.","pairs":[["I","my"],["he","his"],["we","our"],["they","their"]],"hints":["He termina com h, his também começa.","We → nosso.","They → deles."],"explanation":"I-my · he-his · we-our · they-their.","id":"q5"},{"type":"mc","difficulty":2,"skill":"g_poss","prompt":"This is Mr. Silva. ___ son is a doctor.","options":["Her","His","Their","Your"],"answer":1,"hints":["O dono é o Mr. Silva.","Mr. = senhor.","Dono homem."],"explanation":"His son = o filho dele.","id":"q6"},{"type":"mc","difficulty":2,"skill":"g_s","prompt":"Como se diz “o carro do meu pai”?","options":["the car of my father","my father's car","my fathers car","my car father's"],"answer":1,"hints":["Use o ’s.","Dono primeiro.","Dono + ’s + coisa."],"explanation":"My father's car.","id":"q7"},{"type":"mc","difficulty":2,"skill":"g_poss2","prompt":"Tom and Kate are my cousins. ___ house is big.","options":["Their","There","They're","Our"],"answer":0,"hints":["O dono são Tom e Kate.","É o possessivo, não “lá”.","Deles = …"],"explanation":"Their house = a casa deles.","id":"q8"},{"type":"order","difficulty":3,"skill":"g_s","prompt":"Organize: “O nome da irmã da Maria é Luísa.”","items":["Maria's","sister's","name","is","Luísa"],"hints":["Comece pelo primeiro dono.","Maria's sister = a irmã da Maria.","Depois: sister's name."],"explanation":"Maria's sister's name is Luísa.","id":"q9"},{"type":"mc","difficulty":3,"skill":"g_poss","prompt":"Qual frase está correta?","options":["They love theirs parents.","They love their parents.","They love there parents.","They love they parents."],"answer":1,"hints":["Possessivo de they.","Não tem -s.","Não é “there”."],"explanation":"They love their parents.","id":"q10"}],"review":["Família: mother, father, sister, brother, grandma, cousin…","my, your, his (dele), her (dela), its, our, their","Possessivos não vão para o plural","Dono + ’s + coisa: Maria's bag"],"relatedQuestions":["família em inglês","diferença entre his e her","como usar apóstrofo s"],"equivalentQuestions":["como se diz irmão em inglês","como se diz avó em inglês","parents significa parentes","quando usar his e her","diferença entre their e there","como dizer o carro do meu pai em inglês","o que é genitivo em inglês","o que é família em inglês","como usar família em inglês","me explica família em inglês","quando usar família em inglês","exemplos de família em inglês","família em inglês em inglês","como funciona família em inglês","regras de família em inglês","exercícios de família em inglês","aula de família em inglês","não entendi família em inglês","família em inglês para iniciantes","resumo de família em inglês","dúvida sobre família em inglês","o que é possessivos em inglês","como usar possessivos em inglês","me explica possessivos em inglês","quando usar possessivos em inglês","exemplos de possessivos em inglês","possessivos em inglês em inglês","como funciona possessivos em inglês","regras de possessivos em inglês","exercícios de possessivos em inglês","aula de possessivos em inglês","não entendi possessivos em inglês","possessivos em inglês para iniciantes","resumo de possessivos em inglês","dúvida sobre possessivos em inglês"],"commonErrors":["Usar his/her pelo gênero da coisa, e não do dono.","Achar que parents = parentes.","Colocar -s no possessivo (theirs parents)."],"english":{"cefr":"A1","unit":"a1-u2","order":1,"area":"grammar","focus":["vocabulary","grammar","writing"],"vocabulary":[{"word":"mother","translation":"mãe","pos":"noun","definition":"your female parent","example":"My mother is a nurse.","difficulty":1,"synonyms":["mom"]},{"word":"father","translation":"pai","pos":"noun","definition":"your male parent","example":"My father cooks on Sundays.","difficulty":1,"synonyms":["dad"]},{"word":"parents","translation":"pais (pai e mãe)","pos":"noun","definition":"your mother and father","example":"My parents are at work.","difficulty":2,"related":["relatives"]},{"word":"sister","translation":"irmã","pos":"noun","definition":"a girl or woman with the same parents as you","example":"My sister is older than me.","difficulty":1},{"word":"brother","translation":"irmão","pos":"noun","definition":"a boy or man with the same parents as you","example":"I have one brother.","difficulty":1},{"word":"cousin","translation":"primo(a)","pos":"noun","definition":"the child of your aunt or uncle","example":"My cousin lives in Manaus.","difficulty":2},{"word":"aunt","translation":"tia","pos":"noun","definition":"the sister of your mother or father","example":"My aunt is a teacher.","difficulty":2,"related":["uncle"]},{"word":"uncle","translation":"tio","pos":"noun","definition":"the brother of your mother or father","example":"My uncle plays the guitar.","difficulty":2,"related":["aunt"]},{"word":"grandmother","translation":"avó","pos":"noun","definition":"the mother of your mother or father","example":"My grandmother makes great cakes.","difficulty":1,"synonyms":["grandma"]},{"word":"daughter","translation":"filha","pos":"noun","definition":"a female child","example":"They have one daughter.","difficulty":2,"related":["son"]}],"grammar":{"name":"Possessive adjectives","when":"Para dizer de quem é algo; vêm antes do substantivo.","structure":"my · your · his · her · its · our · their + substantivo","affirmative":["This is my brother.","Her name is Lia."],"negative":["That isn't my bag.","His house isn't big."],"interrogative":["Is this your pen?","What's her name?"],"compare":"his (dono homem) × her (dono mulher) — em português “seu/sua” não mostra o dono; em inglês mostra.","context":"Apresentando fotos da família para um colega estrangeiro."},"reading":{"title":"My family photo","genre":"post em rede social","text":"This is a photo of my family. That's my dad, Marcos. His job is cool: he's a pilot! Next to him is my mom, Júlia. Her hobby is painting. The two kids are my brother and me. Our dog, Bolt, is in the photo too. Its ears are enormous!","questions":[{"difficulty":1,"prompt":"Qual é a profissão do pai?","options":["Pintor","Piloto","Professor","Médico"],"answer":1,"explanation":"“he's a pilot”."},{"difficulty":2,"prompt":"A que se refere “Her hobby”?","options":["Ao hobby do pai","Ao hobby da mãe","Ao hobby do irmão","Ao hobby do cachorro"],"answer":1,"explanation":"Her refere-se à mãe, Júlia."},{"difficulty":2,"prompt":"A quem se refere “Its ears”?","options":["Ao pai","À foto","Ao cachorro Bolt","Ao irmão"],"answer":2,"explanation":"Its é usado para animais e coisas: as orelhas do Bolt."},{"difficulty":3,"prompt":"Quem escreveu o post?","options":["A mãe","Um dos filhos","O pai","Um primo"],"answer":1,"explanation":"Ele diz “my brother and me”: é um dos filhos."}]},"writing":{"prompt":"Descreva uma foto da sua família (ou de uma família imaginária) usando pelo menos três possessivos diferentes.","criteria":["Nomeia pelo menos 3 pessoas","Usa my, his/her e our/their","Frases curtas com is/are"],"model":"This is my family. My mother is Ana. Her job is teacher. My father is Rui. His hobby is soccer. Our cat is Tom.","keywords":["my","his","her","our"],"minWords":18},"challenge":"Faça uma árvore genealógica simples e escreva o nome de cada pessoa em inglês (mother, uncle, cousin…)."},"games":{"blanks":[{"difficulty":1,"sentence":"This is Leo. ___ sister is Ana.","options":["His","Her","Their","Its"],"answer":0,"explanation":"Dono homem: his."},{"difficulty":1,"sentence":"My mother's sister is my ___.","options":["aunt","uncle","cousin","niece"],"answer":0,"explanation":"A irmã da mãe é a tia."},{"difficulty":2,"sentence":"We love ___ grandparents.","options":["our","we","us","ours"],"answer":0,"explanation":"We → our."},{"difficulty":2,"sentence":"This is ___ bag. (a bolsa da Maria)","options":["Maria's","Marias","of Maria","Maria"],"answer":0,"explanation":"Dono + ’s."},{"difficulty":3,"sentence":"The dog is happy. ___ tail is moving.","options":["Its","It's","His","Their"],"answer":0,"explanation":"Possessivo de it: its (sem apóstrofo)."}],"sequences":[{"difficulty":1,"prompt":"Organize a frase · Put the words in order","items":["This","is","my","brother"],"words":true,"explanation":"This is + possessivo + pessoa."},{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["Her","name","is","Clara"],"words":true,"explanation":"Her vem antes do substantivo."},{"difficulty":3,"prompt":"Organize a frase · Put the words in order","items":["My","father's","car","is","blue"],"words":true,"explanation":"Dono + ’s + coisa."}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-a1-this-that","subject":"ingles","title":"This, that, plurals and a/an","levels":["fund1","fund2","medio"],"grade":"A partir do 4º ano","topic":"Inglês A1 — Primeiros passos","subtopic":"Demonstrativos, plural e artigos","aliases":["this that these those","demonstrativos em ingles","plural em ingles","a an","artigo indefinido","objetos da sala em ingles","classroom objects"],"summary":"Aponte e nomeie objetos com this, that, these e those, faça o plural e use a ou an.","intro":"What's this? It's a pen! Vamos nomear o que tem ao nosso redor.","objective":"Usar this/that/these/those pela distância e quantidade, formar plurais regulares e irregulares e escolher entre a e an pelo som.","prerequisites":["ing-verb-to-be"],"next":["ing-a1-colors-adjectives"],"skills":{"g_demo":"This, that, these, those","g_plural":"Plural dos substantivos","g_article":"A ou an","v_class":"Objetos da sala de aula"},"blocks":[{"skill":"g_demo","title":"This, that, these, those","text":"Perto de você: this (isto/este, singular) e these (estes, plural). Longe: that (aquilo/aquele, singular) e those (aqueles, plural). Perguntas: What's this? / What are those?","example":"This is my pen. · Those are my friends over there.","variants":{"simples":"This = isto (perto). That = aquilo (longe). These e those são os plurais.","exemplo":"Na mesa: “This is my notebook.” Apontando para a janela: “That is a bird!”","passos":"1. Está perto ou longe? 2. É um ou vários? 3. Perto+um: this; perto+vários: these; longe+um: that; longe+vários: those.","compara":"Pense em português: este/estes (perto) × aquele/aqueles (longe). A lógica é a mesma."},"id":"b1"},{"skill":"g_plural","title":"Plurals","text":"A maioria ganha -s (book → books). Terminadas em -s, -sh, -ch, -x ganham -es (box → boxes). Consoante + y vira -ies (city → cities). Alguns são irregulares: man → men, woman → women, child → children, person → people, foot → feet, tooth → teeth, mouse → mice.","example":"one book, two books · one box, three boxes · one child, four children","variants":{"simples":"Plural é mais de um: quase sempre é só colocar -s.","exemplo":"Lista de material: two pencils, three notebooks, one eraser.","passos":"1. Veja o final da palavra. 2. -s/-sh/-ch/-x → -es. 3. Consoante + y → -ies. 4. Decore os irregulares.","compara":"Em português também temos plurais especiais (pão → pães). Em inglês, os irregulares mais usados são poucos: men, women, children, people."},"id":"b2"},{"skill":"g_article","title":"A or an?","text":"Usamos a ou an antes de UM substantivo contável no singular. A escolha depende do SOM que vem depois: a antes de som de consoante (a pen, a university) e an antes de som de vogal (an apple, an hour).","example":"a book · an eraser · an umbrella · a uniform","variants":{"simples":"A e an significam “um/uma”. An vem antes de palavras que começam com som de vogal.","exemplo":"Na cantina: “I want an orange and a sandwich.”","passos":"1. Fale a palavra em voz alta. 2. Começa com som de vogal? → an. 3. Senão → a.","compara":"O que vale é o SOM, não a letra: an hour (o h é mudo) e a university (soa “iu”)."},"id":"b3"},{"skill":"v_class","title":"Classroom objects","text":"Objetos da sala: pen (caneta), pencil (lápis), eraser (borracha), ruler (régua), notebook (caderno), book (livro), backpack (mochila), desk (carteira), board (quadro), scissors (tesoura — sempre plural), glue (cola).","example":"What's this? It's a ruler. · Those are my scissors.","variants":{"simples":"Pen = caneta, pencil = lápis, eraser = borracha, notebook = caderno.","exemplo":"Pedindo emprestado: “Can I borrow your eraser, please?”","passos":"1. Olhe ao redor da sala. 2. Diga o nome de cada objeto. 3. Use It's a/an…","compara":"Scissors é sempre plural em inglês (como “óculos” em português): These are my scissors."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"g_demo","prompt":"O livro está na sua mão. Você diz: “___ is my book.”","options":["This","That","These","Those"],"answer":0,"hints":["Está perto ou longe?","É um só livro.","Perto + singular."],"explanation":"Perto e singular: this.","id":"q1"},{"type":"mc","difficulty":1,"skill":"g_article","prompt":"Qual está correto?","options":["a apple","an apple","an pen","a eraser"],"answer":1,"hints":["Apple começa com som de vogal.","Antes de vogal usamos an.","An apple."],"explanation":"An apple (som de vogal).","id":"q2"},{"type":"fill","difficulty":1,"skill":"g_plural","prompt":"Escreva o plural de “book”.","answers":["books"],"hints":["É um plural regular.","Só acrescente uma letra.","Book + s."],"explanation":"Books.","id":"q3"},{"type":"tf","difficulty":1,"skill":"v_class","prompt":"“Eraser” significa borracha.","answer":true,"hints":["Erase = apagar.","O que apaga o lápis?","Borracha."],"explanation":"Verdadeiro.","id":"q4"},{"type":"match","difficulty":2,"skill":"g_plural","prompt":"Ligue o singular ao plural.","pairs":[["child","children"],["box","boxes"],["city","cities"],["man","men"]],"hints":["Child é irregular.","Box termina em x.","City: consoante + y."],"explanation":"children · boxes · cities · men.","id":"q5"},{"type":"mc","difficulty":2,"skill":"g_demo","prompt":"Os pássaros estão lá no telhado. “___ are birds.”","options":["This","These","That","Those"],"answer":3,"hints":["Longe.","Vários.","Longe + plural."],"explanation":"Longe e plural: those.","id":"q6"},{"type":"mc","difficulty":2,"skill":"g_article","prompt":"Complete: “It's ___ hour.”","options":["a","an","two","—"],"answer":1,"hints":["O h de hour é pronunciado?","Não, é mudo.","Começa com som de vogal."],"explanation":"An hour: o h é mudo.","id":"q7"},{"type":"mc","difficulty":2,"skill":"g_plural","prompt":"Qual é o plural de “person”?","options":["persons","people","peoples","personas"],"answer":1,"hints":["É irregular.","Muito usado.","Começa com p-e-o."],"explanation":"Person → people.","id":"q8"},{"type":"order","difficulty":3,"skill":"g_demo","prompt":"Organize: “Estas são as minhas canetas.”","items":["These","are","my","pens"],"hints":["Plural e perto: these.","Verbo no plural: are.","Possessivo antes do objeto."],"explanation":"These are my pens.","id":"q9"},{"type":"mc","difficulty":3,"skill":"g_article","prompt":"Qual frase está correta?","options":["She is an university student.","She is a university student.","She is university student.","She is an student."],"answer":1,"hints":["University começa com vogal, mas…","…o som é “iu”.","Som de consoante → a."],"explanation":"A university: o som é “iu”, de consoante.","id":"q10"}],"review":["This/these (perto) · that/those (longe)","Plural: -s, -es, -ies e irregulares (children, people)","A antes de som de consoante, an antes de som de vogal","Objetos: pen, pencil, eraser, ruler, notebook…"],"relatedQuestions":["diferença entre this e that","quando usar a e an","plural em inglês"],"equivalentQuestions":["diferença entre these e those","plural de child","plural de person","por que é an hour","objetos da sala de aula em inglês","como se diz borracha em inglês","o que é artigo indefinido em inglês","o que é this e that","como usar this e that","me explica this e that","quando usar this e that","exemplos de this e that","this e that em inglês","como funciona this e that","regras de this e that","exercícios de this e that","aula de this e that","não entendi this e that","this e that para iniciantes","resumo de this e that","dúvida sobre this e that","o que é plural em inglês","como usar plural em inglês","me explica plural em inglês","quando usar plural em inglês","exemplos de plural em inglês","plural em inglês em inglês","como funciona plural em inglês","regras de plural em inglês","exercícios de plural em inglês","aula de plural em inglês","não entendi plural em inglês","plural em inglês para iniciantes","resumo de plural em inglês","dúvida sobre plural em inglês","o que é a e an","como usar a e an","me explica a e an","quando usar a e an","exemplos de a e an","a e an em inglês","como funciona a e an","regras de a e an","exercícios de a e an","aula de a e an","não entendi a e an","a e an para iniciantes","resumo de a e an","dúvida sobre a e an"],"commonErrors":["Usar a antes de som de vogal (a apple).","Esquecer os plurais irregulares (childs, persons).","Usar this para coisas longe."],"english":{"cefr":"A1","unit":"a1-u2","order":2,"area":"grammar","focus":["grammar","vocabulary"],"vocabulary":[{"word":"pen","translation":"caneta","pos":"noun","definition":"a thing you use to write with ink","example":"Can I use your pen?","difficulty":1},{"word":"pencil","translation":"lápis","pos":"noun","definition":"a wooden thing you use to write or draw","example":"This is my pencil.","difficulty":1},{"word":"eraser","translation":"borracha","pos":"noun","definition":"a small thing that removes pencil marks","example":"I need an eraser.","difficulty":1},{"word":"ruler","translation":"régua","pos":"noun","definition":"a flat object used to measure and draw lines","example":"The ruler is thirty centimeters long.","difficulty":2},{"word":"notebook","translation":"caderno","pos":"noun","definition":"a book with blank pages to write in","example":"Open your notebook, please.","difficulty":1},{"word":"backpack","translation":"mochila","pos":"noun","definition":"a bag you carry on your back","example":"My backpack is heavy.","difficulty":2},{"word":"desk","translation":"carteira / mesa","pos":"noun","definition":"a table where you study or work","example":"Put your books on the desk.","difficulty":1},{"word":"scissors","translation":"tesoura","pos":"noun","definition":"a tool with two blades for cutting paper","example":"These scissors are sharp.","difficulty":3},{"word":"children","translation":"crianças","pos":"noun","definition":"plural of child","example":"The children are in the park.","difficulty":2},{"word":"people","translation":"pessoas","pos":"noun","definition":"plural of person","example":"Many people speak English.","difficulty":2}],"grammar":{"name":"Demonstratives + a/an","when":"Para apontar e nomear coisas perto ou longe.","structure":"This/That is a/an + substantivo · These/Those are + plural","affirmative":["This is a pen.","Those are my shoes."],"negative":["That isn't my bag.","These aren't pencils."],"interrogative":["What's this?","Are those your books?"],"compare":"this/these = perto · that/those = longe.","context":"Arrumando a mochila no começo do ano."},"listening":{"title":"Na papelaria","kind":"dialogo","rate":0.9,"script":["Clerk: Hi! Can I help you?","Girl: Yes, please. How much is this ruler?","Clerk: It's three dollars.","Girl: And those notebooks over there?","Clerk: They're two dollars each.","Girl: OK. Two notebooks and an eraser, please."],"questions":[{"difficulty":1,"prompt":"Quanto custa a régua?","options":["2 dólares","3 dólares","4 dólares","1 dólar"],"answer":1,"explanation":"“It's three dollars.”"},{"difficulty":2,"prompt":"Por que ela diz “those notebooks”?","options":["Porque estão perto","Porque estão longe e são vários","Porque é um só","Porque são dela"],"answer":1,"explanation":"Those = longe + plural (“over there”)."},{"difficulty":2,"prompt":"O que ela compra no final?","options":["Uma régua","Dois cadernos e uma borracha","Três canetas","Um caderno"],"answer":1,"explanation":"“Two notebooks and an eraser.”"}]},"challenge":"Aponte para 5 objetos ao seu redor e diga: This is a… / That is an… / These are…"},"games":{"blanks":[{"difficulty":1,"sentence":"I have ___ orange.","options":["an","a","two","these"],"answer":0,"explanation":"Orange começa com som de vogal: an."},{"difficulty":1,"sentence":"___ are my shoes. (perto)","options":["These","This","That","Those"],"answer":0,"explanation":"Perto e plural: these."},{"difficulty":2,"sentence":"Look at ___ plane in the sky!","options":["that","this","these","those"],"answer":0,"explanation":"Longe e singular: that."},{"difficulty":2,"sentence":"There are three ___ in the park.","options":["children","childs","childrens","child"],"answer":0,"explanation":"Child → children."},{"difficulty":3,"sentence":"He is ___ honest man.","options":["an","a","the","—"],"answer":0,"explanation":"O h de honest é mudo: an honest."}],"sequences":[{"difficulty":1,"prompt":"Organize a frase · Put the words in order","items":["This","is","a","pencil"],"words":true,"explanation":"This is + a + objeto."},{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["Those","are","my","books"],"words":true,"explanation":"Those + are + plural."}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-a1-time-days","subject":"ingles","title":"Time, days and months","levels":["fund1","fund2","medio"],"grade":"A partir do 4º ano","topic":"Inglês A1 — Meu dia a dia","subtopic":"Horas, dias da semana, meses e datas","aliases":["horas em ingles","what time is it","dias da semana em ingles","meses em ingles","datas em ingles","days of the week","months","in on at tempo"],"summary":"Diga as horas, os dias da semana, os meses e as datas, com in, on e at.","intro":"What time is it? Vamos organizar o tempo em inglês.","objective":"Perguntar e dizer as horas, nomear dias e meses com letra maiúscula e usar at (horas), on (dias e datas) e in (meses e anos).","prerequisites":["ing-a1-alphabet-numbers"],"next":["ing-simple-present"],"skills":{"v_time":"Dizer as horas","v_days":"Dias da semana","v_months":"Meses e datas","g_prep":"At, on, in para tempo"},"blocks":[{"skill":"v_time","title":"What time is it?","text":"Pergunta: What time is it? Resposta: It's + hora. Horas cheias: It's three o'clock. Com minutos: It's three fifteen (3:15), It's four thirty (4:30). Também: quarter past (e quinze), half past (e meia), quarter to (quinze para). Am = manhã; pm = tarde e noite.","example":"7:00 seven o'clock · 7:30 seven thirty / half past seven · 6:45 six forty-five / quarter to seven","variants":{"simples":"What time is it? = Que horas são? It's five o'clock = São cinco horas.","exemplo":"Combinando um jogo: “The game is at four thirty pm.”","passos":"1. It's… 2. Diga a hora. 3. Diga os minutos (ou o’clock se for hora cheia).","compara":"Em inglês é comum o relógio de 12 horas, com am e pm. 15h = 3 pm."},"id":"b1"},{"skill":"v_days","title":"Days of the week","text":"Monday (segunda), Tuesday (terça), Wednesday (quarta), Thursday (quinta), Friday (sexta), Saturday (sábado) e Sunday (domingo). Sempre com letra maiúscula. Saturday e Sunday formam o weekend (fim de semana).","example":"I have English on Monday and Wednesday.","variants":{"simples":"Monday = segunda-feira… Sunday = domingo. Todos terminam em -day.","exemplo":"Sua agenda: “Soccer on Tuesday, music class on Thursday.”","passos":"1. Decore em ordem, começando pela segunda. 2. Letra maiúscula. 3. Use on antes do dia.","compara":"Tuesday (terça) e Thursday (quinta) confundem: Tues = “tiuz”, Thurs = “thârz”. Pense: T-U terça, T-H quinta."},"id":"b2"},{"skill":"v_months","title":"Months and dates","text":"January, February, March, April, May, June, July, August, September, October, November, December — com letra maiúscula. Nas datas, usamos números ordinais: first (1st), second (2nd), third (3rd), fourth (4th)… twentieth (20th), twenty-first (21st). My birthday is on March 3rd.","example":"Today is May 10th. · Christmas is on December 25th.","variants":{"simples":"Os meses parecem com o português: April = abril, May = maio. Datas usam first, second, third…","exemplo":"“When is your birthday?” — “It's on July 21st.”","passos":"1. Mês com maiúscula. 2. Dia como ordinal: 1st, 2nd, 3rd, 4th… 3. Use on antes da data.","compara":"Nos Estados Unidos a data curta costuma vir mês/dia (03/10 = 10 de março); no Reino Unido, dia/mês, como no Brasil."},"id":"b3"},{"skill":"g_prep","title":"At, on, in (time)","text":"At para horas e momentos exatos (at 7 o'clock, at night, at noon). On para dias e datas (on Monday, on May 5th, on my birthday). In para meses, anos, estações e partes do dia (in July, in 2025, in the summer, in the morning).","example":"I wake up at 6:30. · We have tests on Friday. · My birthday is in June.","variants":{"simples":"At = hora. On = dia. In = mês e ano.","exemplo":"Convite: “The party is on Saturday, at 8 pm, in December.”","passos":"1. É hora? at. 2. É dia/data? on. 3. É mês, ano ou período maior? in.","compara":"Imagine uma pirâmide: in (o maior: ano, mês) → on (dia) → at (o menor: hora)."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"v_days","prompt":"Qual é o dia depois de Monday?","options":["Wednesday","Tuesday","Thursday","Sunday"],"answer":1,"hints":["Monday é segunda.","O próximo é terça.","Tues…"],"explanation":"Monday → Tuesday.","id":"q1"},{"type":"mc","difficulty":1,"skill":"v_time","prompt":"“It's eight o'clock” quer dizer:","options":["São oito horas","São oito e meia","Faltam oito minutos","São oito e quinze"],"answer":0,"hints":["O'clock = hora cheia.","Sem minutos.","Oito em ponto."],"explanation":"Hora cheia: 8:00.","id":"q2"},{"type":"fill","difficulty":1,"skill":"v_months","prompt":"Qual mês vem depois de “January”?","answers":["February"],"hints":["Segundo mês do ano.","Fevereiro.","Feb…"],"explanation":"January → February.","id":"q3"},{"type":"tf","difficulty":1,"skill":"v_days","prompt":"Em inglês, os dias da semana são escritos com letra maiúscula.","answer":true,"hints":["Igual aos idiomas e nacionalidades.","Monday, Friday…","Sim, sempre."],"explanation":"Verdadeiro.","id":"q4"},{"type":"match","difficulty":2,"skill":"g_prep","prompt":"Ligue cada expressão à preposição correta.","pairs":[["7 o'clock","at"],["Monday","on"],["July","in"]],"hints":["Hora exata: at.","Dia: on.","Mês: in."],"explanation":"at 7 o'clock · on Monday · in July.","id":"q5"},{"type":"mc","difficulty":2,"skill":"v_time","prompt":"4:30 pode ser dito como:","options":["half past four","half to four","four half","quarter past four"],"answer":0,"hints":["Trinta minutos = meia.","Passou da hora: past.","Half past."],"explanation":"4:30 = half past four (ou four thirty).","id":"q6"},{"type":"mc","difficulty":2,"skill":"g_prep","prompt":"My birthday is ___ March 3rd.","options":["in","at","on","of"],"answer":2,"hints":["É uma data com dia.","Dia/data usa…","On."],"explanation":"Datas com dia: on.","id":"q7"},{"type":"mc","difficulty":2,"skill":"v_months","prompt":"Como se escreve o ordinal de 3 (terceiro)?","options":["3th","3rd","3nd","3st"],"answer":1,"hints":["Third.","As duas últimas letras.","Th-i-r-D."],"explanation":"Third = 3rd.","id":"q8"},{"type":"order","difficulty":3,"skill":"v_days","prompt":"Coloque os dias em ordem, começando na segunda.","items":["Monday","Tuesday","Wednesday","Thursday","Friday"],"hints":["Segunda é Monday.","Quarta é Wednesday.","Quinta é Thursday."],"explanation":"Monday, Tuesday, Wednesday, Thursday, Friday.","id":"q9"},{"type":"mc","difficulty":3,"skill":"g_prep","prompt":"Qual frase está totalmente correta?","options":["I play soccer in Saturday at the morning.","I play soccer on Saturday in the morning.","I play soccer at Saturday on the morning.","I play soccer on Saturday at morning."],"answer":1,"hints":["Dia da semana usa on.","Parte do dia usa in the…","On Saturday in the morning."],"explanation":"On Saturday (dia) in the morning (parte do dia).","id":"q10"}],"review":["What time is it? — It's … o'clock / half past / quarter to","Dias e meses com letra maiúscula","Datas com ordinais: 1st, 2nd, 3rd, 4th…","At (hora) · on (dia/data) · in (mês/ano/período)"],"relatedQuestions":["como falar as horas em inglês","dias da semana em inglês","quando usar in on at"],"equivalentQuestions":["como se diz quinta-feira em inglês","diferença entre tuesday e thursday","como escrever datas em inglês","o que significa half past","quando usar on e in com datas","como dizer meu aniversário é em inglês","o que é am e pm","o que é horas em inglês","como usar horas em inglês","me explica horas em inglês","quando usar horas em inglês","exemplos de horas em inglês","horas em inglês em inglês","como funciona horas em inglês","regras de horas em inglês","exercícios de horas em inglês","aula de horas em inglês","não entendi horas em inglês","horas em inglês para iniciantes","resumo de horas em inglês","dúvida sobre horas em inglês","o que é dias da semana em inglês","como usar dias da semana em inglês","me explica dias da semana em inglês","quando usar dias da semana em inglês","exemplos de dias da semana em inglês","dias da semana em inglês em inglês","como funciona dias da semana em inglês","regras de dias da semana em inglês","exercícios de dias da semana em inglês","aula de dias da semana em inglês","não entendi dias da semana em inglês","dias da semana em inglês para iniciantes","resumo de dias da semana em inglês","dúvida sobre dias da semana em inglês","o que é meses em inglês","como usar meses em inglês","me explica meses em inglês","quando usar meses em inglês","exemplos de meses em inglês","meses em inglês em inglês","como funciona meses em inglês","regras de meses em inglês","exercícios de meses em inglês","aula de meses em inglês","não entendi meses em inglês","meses em inglês para iniciantes","resumo de meses em inglês","dúvida sobre meses em inglês"],"commonErrors":["Usar in com dias (in Monday).","Escrever dias e meses com minúscula.","Trocar Tuesday e Thursday."],"english":{"cefr":"A1","unit":"a1-u3","order":1,"area":"vocabulary","focus":["vocabulary","listening","grammar"],"vocabulary":[{"word":"Monday","translation":"segunda-feira","pos":"noun","definition":"the day after Sunday","example":"I have English on Monday.","difficulty":1},{"word":"Tuesday","translation":"terça-feira","pos":"noun","definition":"the day after Monday","example":"The test is on Tuesday.","difficulty":2,"related":["Thursday"]},{"word":"Wednesday","translation":"quarta-feira","pos":"noun","definition":"the day in the middle of the week","example":"We swim on Wednesday.","difficulty":2},{"word":"Thursday","translation":"quinta-feira","pos":"noun","definition":"the day after Wednesday","example":"My music class is on Thursday.","difficulty":2,"related":["Tuesday"]},{"word":"Friday","translation":"sexta-feira","pos":"noun","definition":"the day before Saturday","example":"I love Friday!","difficulty":1},{"word":"weekend","translation":"fim de semana","pos":"noun","definition":"Saturday and Sunday","example":"What do you do on the weekend?","difficulty":1},{"word":"month","translation":"mês","pos":"noun","definition":"one of the twelve parts of a year","example":"December is my favorite month.","difficulty":1},{"word":"birthday","translation":"aniversário","pos":"noun","definition":"the day you were born, every year","example":"My birthday is in May.","difficulty":1},{"word":"clock","translation":"relógio (de parede)","pos":"noun","definition":"a thing that shows the time","example":"The clock is on the wall.","difficulty":1},{"word":"today","translation":"hoje","pos":"adverb","definition":"this day","example":"Today is Friday.","difficulty":1,"related":["tomorrow","yesterday"]}],"listening":{"title":"Agenda da semana","kind":"texto","rate":0.9,"script":["Hi, this is Mia. On Monday I have swimming at four o'clock.","On Wednesday I have piano at half past five.","On Saturday, in the morning, I visit my grandma.","And my birthday is on June tenth!"],"questions":[{"difficulty":1,"prompt":"Em que dia Mia nada?","options":["Monday","Wednesday","Saturday","Sunday"],"answer":0,"explanation":"“On Monday I have swimming.”"},{"difficulty":2,"prompt":"Que horas é a aula de piano?","options":["5:00","5:30","4:00","4:30"],"answer":1,"explanation":"Half past five = 5:30."},{"difficulty":2,"prompt":"Quando ela visita a avó?","options":["Sábado de manhã","Sábado à noite","Domingo de manhã","Quarta à tarde"],"answer":0,"explanation":"“On Saturday, in the morning.”"},{"difficulty":3,"prompt":"Quando é o aniversário dela?","options":["10 de julho","10 de junho","1º de junho","20 de junho"],"answer":1,"explanation":"June tenth = 10 de junho."}]},"writing":{"prompt":"Escreva sua agenda da semana em inglês: três atividades, com o dia e a hora.","criteria":["Dias com maiúscula","On + dia","At + hora"],"model":"On Monday I have English at 2 pm. On Wednesday I play soccer at 5 pm. On Saturday I visit my aunt in the morning.","keywords":["on","at","monday"],"minWords":18},"challenge":"Diga em voz alta, em inglês, que horas são agora e que dia é hoje."},"games":{"words":[{"word":"Monday","clue":"segunda-feira","difficulty":1},{"word":"Friday","clue":"sexta-feira","difficulty":1},{"word":"weekend","clue":"fim de semana","difficulty":1},{"word":"April","clue":"abril","difficulty":1},{"word":"clock","clue":"relógio","difficulty":1},{"word":"Thursday","clue":"quinta-feira","difficulty":2},{"word":"December","clue":"dezembro","difficulty":2},{"word":"birthday","clue":"aniversário","difficulty":2}],"blanks":[{"difficulty":1,"sentence":"The class starts ___ 8 o'clock.","options":["at","on","in","of"],"answer":0,"explanation":"Hora: at."},{"difficulty":1,"sentence":"I go to the beach ___ Sunday.","options":["on","in","at","to"],"answer":0,"explanation":"Dia: on."},{"difficulty":2,"sentence":"We travel ___ July.","options":["in","on","at","by"],"answer":0,"explanation":"Mês: in."},{"difficulty":2,"sentence":"What ___ is it? — It's ten o'clock.","options":["time","hour","day","clock"],"answer":0,"explanation":"What time is it?"},{"difficulty":3,"sentence":"I study ___ the afternoon and sleep ___ night.","options":["in / at","at / in","on / on","in / in"],"answer":0,"explanation":"In the afternoon · at night."}],"sequences":[{"prompt":"Coloque os meses em ordem · Put the months in order","items":["January","March","May","August","October"],"difficulty":1,"explanation":"Jan, Mar, May, Aug, Oct."},{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["My","birthday","is","on","May","tenth"],"words":true,"explanation":"On + data."}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-a1-there-is","subject":"ingles","title":"There is / there are at home","levels":["fund1","fund2","medio"],"grade":"A partir do 5º ano","topic":"Inglês A1 — Meu dia a dia","subtopic":"There is/are, casa e preposições de lugar","aliases":["there is there are","ha em ingles","existe em ingles","casa em ingles","comodos da casa","house","preposicoes de lugar","in on under next to"],"summary":"Descreva a casa: o que existe em cada cômodo com there is/there are e onde as coisas estão.","intro":"There is a sofa in the living room… Vamos fazer um tour pela casa em inglês!","objective":"Descrever o que existe num lugar com there is/there are (afirmativa, negativa e pergunta) e localizar objetos com preposições de lugar.","prerequisites":["ing-a1-this-that"],"next":["ing-a1-can-directions"],"skills":{"g_there":"There is / there are","g_thereq":"Negativa e pergunta com there","v_house":"Cômodos e móveis","g_place":"Preposições de lugar"},"blocks":[{"skill":"g_there","title":"There is / there are","text":"There is (there's) = há/existe, para UMA coisa: There is a sofa in the room. There are = há/existem, para VÁRIAS: There are two beds. Com coisas incontáveis também usamos there is: There is some water in the glass.","example":"There's a big window in my bedroom. · There are three chairs in the kitchen.","variants":{"simples":"There is = tem (uma coisa). There are = tem (várias coisas).","exemplo":"Descrevendo seu quarto para um amigo: “There's a bed, a desk and there are two posters.”","passos":"1. Conte: é uma ou várias? 2. Uma → there is. 3. Várias → there are.","compara":"Em português dizemos “tem um sofá na sala”. Em inglês não se usa “have” aqui: There is a sofa in the living room."},"id":"b1"},{"skill":"g_thereq","title":"Is there…? Are there…?","text":"Negativa: There isn't a garage. / There aren't any plants. Pergunta: Is there a bathroom upstairs? — Yes, there is. / No, there isn't. Are there any shops near here? — Yes, there are.","example":"— Is there a park near your house? — Yes, there is.","variants":{"simples":"Para perguntar, inverta: Is there…? Are there…?","exemplo":"Procurando hotel: “Is there Wi-Fi in the room?”","passos":"1. Negativa: isn't / aren't. 2. Pergunta: Is/Are no começo. 3. Resposta curta: Yes, there is / No, there aren't.","compara":"Use any em perguntas e negativas no plural (Are there any…? / There aren't any…) e a/an no singular (Is there a…?)."},"id":"b2"},{"skill":"v_house","title":"Rooms and furniture","text":"Cômodos: living room (sala), kitchen (cozinha), bedroom (quarto), bathroom (banheiro), dining room (sala de jantar), garage (garagem), garden/yard (jardim/quintal). Móveis: sofa, bed, table, chair, wardrobe (guarda-roupa), fridge (geladeira), stove (fogão), shower (chuveiro).","example":"The fridge is in the kitchen. · There's a shower in the bathroom.","variants":{"simples":"Kitchen = cozinha, bedroom = quarto, bathroom = banheiro, living room = sala.","exemplo":"Anúncio de aluguel: “Two bedrooms, one bathroom, a small kitchen.”","passos":"1. Pense em cada cômodo. 2. Liste o que tem nele. 3. Junte: There's a … in the …","compara":"Bedroom = cômodo para dormir (bed + room). Bathroom = cômodo com banheira (bath + room). Muitas palavras em inglês são “juntadas” assim."},"id":"b3"},{"skill":"g_place","title":"In, on, under, next to…","text":"In (dentro), on (em cima, sobre), under (embaixo), next to (ao lado de), between (entre), behind (atrás de), in front of (na frente de), near (perto de).","example":"The cat is under the table. · The lamp is next to the bed. · The keys are on the desk.","variants":{"simples":"In = dentro. On = em cima. Under = embaixo. Next to = ao lado.","exemplo":"Procurando o controle: “It's under the sofa!”","passos":"1. Veja a posição do objeto. 2. Escolha a preposição. 3. Diga: It's + preposição + the + lugar.","compara":"Em português, “na mesa” pode ser em cima (on the table) ou dentro da gaveta (in the drawer). Em inglês a preposição mostra exatamente onde."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"g_there","prompt":"___ two bedrooms in my house.","options":["There is","There are","It is","They is"],"answer":1,"hints":["Quantos quartos?","Dois = plural.","Plural: there are."],"explanation":"Plural: there are.","id":"q1"},{"type":"mc","difficulty":1,"skill":"v_house","prompt":"Onde fica a geladeira (fridge) normalmente?","options":["bedroom","kitchen","bathroom","garage"],"answer":1,"hints":["Onde guardamos comida?","Onde cozinhamos?","Cozinha."],"explanation":"Na kitchen (cozinha).","id":"q2"},{"type":"fill","difficulty":1,"skill":"g_place","prompt":"O gato está embaixo da mesa: The cat is ______ the table.","answers":["under"],"hints":["Embaixo = …","Começa com u.","Un…"],"explanation":"Under = embaixo de.","id":"q3"},{"type":"tf","difficulty":1,"skill":"g_there","prompt":"“There is a lot of books” está correto.","answer":false,"hints":["Books é singular ou plural?","Plural pede are.","There are…"],"explanation":"Falso: There are a lot of books.","id":"q4"},{"type":"match","difficulty":2,"skill":"v_house","prompt":"Ligue cada cômodo ao seu significado.","pairs":[["bedroom","quarto"],["bathroom","banheiro"],["living room","sala de estar"],["kitchen","cozinha"]],"hints":["Bed = cama.","Bath = banho.","Living = viver."],"explanation":"bedroom quarto · bathroom banheiro · living room sala · kitchen cozinha.","id":"q5"},{"type":"mc","difficulty":2,"skill":"g_thereq","prompt":"— ___ there a bathroom upstairs? — Yes, there is.","options":["Is","Are","Does","Has"],"answer":0,"hints":["A resposta é “there is”.","Singular.","Is there…?"],"explanation":"Is there a bathroom…?","id":"q6"},{"type":"mc","difficulty":2,"skill":"g_thereq","prompt":"Complete a negativa: There ___ any chairs in the room.","options":["isn't","aren't","don't","not"],"answer":1,"hints":["Chairs é plural.","Negativa de are.","Are + not."],"explanation":"There aren't any chairs.","id":"q7"},{"type":"mc","difficulty":2,"skill":"g_place","prompt":"O abajur está ao lado da cama: The lamp is ___ the bed.","options":["between","next to","behind","in"],"answer":1,"hints":["Ao lado…","Next = próximo.","Next to."],"explanation":"Next to = ao lado de.","id":"q8"},{"type":"order","difficulty":3,"skill":"g_thereq","prompt":"Organize a pergunta: “Há alguma loja perto daqui?”","items":["Are","there","any","shops","near","here?"],"hints":["Pergunta no plural: Are there…","Any em perguntas no plural.","Near here no final."],"explanation":"Are there any shops near here?","id":"q9"},{"type":"mc","difficulty":3,"skill":"g_there","prompt":"Qual frase descreve a casa corretamente em inglês?","options":["Has a garden in my house.","There have a garden in my house.","There is a garden in my house.","It have a garden in my house."],"answer":2,"hints":["Não usamos have para “existir”.","Singular.","There is…"],"explanation":"There is a garden in my house.","id":"q10"}],"review":["There is (1) · there are (vários)","Is there…? / Are there any…? · isn't / aren't","Cômodos: kitchen, bedroom, bathroom, living room","Lugar: in, on, under, next to, between, behind"],"relatedQuestions":["quando usar there is e there are","cômodos da casa em inglês","preposições de lugar em inglês"],"equivalentQuestions":["como dizer tem em inglês","diferença entre there is e there are","como perguntar se tem algo em inglês","como se diz cozinha em inglês","o que significa under","como dizer ao lado de em inglês","there is ou have","o que é there is e there are","como usar there is e there are","me explica there is e there are","quando usar there is e there are","exemplos de there is e there are","there is e there are em inglês","como funciona there is e there are","regras de there is e there are","exercícios de there is e there are","aula de there is e there are","não entendi there is e there are","there is e there are para iniciantes","resumo de there is e there are","dúvida sobre there is e there are","o que é casa em inglês","como usar casa em inglês","me explica casa em inglês","quando usar casa em inglês","exemplos de casa em inglês","casa em inglês em inglês","como funciona casa em inglês","regras de casa em inglês","exercícios de casa em inglês","aula de casa em inglês","não entendi casa em inglês","casa em inglês para iniciantes","resumo de casa em inglês","dúvida sobre casa em inglês","o que é preposições de lugar","como usar preposições de lugar","me explica preposições de lugar","quando usar preposições de lugar","exemplos de preposições de lugar","preposições de lugar em inglês","como funciona preposições de lugar","regras de preposições de lugar","exercícios de preposições de lugar","aula de preposições de lugar","não entendi preposições de lugar","preposições de lugar para iniciantes","resumo de preposições de lugar","dúvida sobre preposições de lugar"],"commonErrors":["Usar have para “existir” (Have a park near here).","There is + plural.","Confundir in (dentro) e on (em cima)."],"english":{"cefr":"A1","unit":"a1-u4","order":1,"area":"grammar","focus":["grammar","vocabulary","reading"],"vocabulary":[{"word":"kitchen","translation":"cozinha","pos":"noun","definition":"the room where you cook","example":"Mom is in the kitchen.","difficulty":1},{"word":"bedroom","translation":"quarto","pos":"noun","definition":"the room where you sleep","example":"My bedroom is small.","difficulty":1},{"word":"bathroom","translation":"banheiro","pos":"noun","definition":"the room with a shower and a toilet","example":"Where is the bathroom?","difficulty":1},{"word":"sofa","translation":"sofá","pos":"noun","definition":"a long soft seat for two or more people","example":"The cat is on the sofa.","difficulty":1},{"word":"fridge","translation":"geladeira","pos":"noun","definition":"a machine that keeps food cold","example":"The milk is in the fridge.","difficulty":2},{"word":"wardrobe","translation":"guarda-roupa","pos":"noun","definition":"a tall piece of furniture for clothes","example":"My clothes are in the wardrobe.","difficulty":3},{"word":"under","translation":"embaixo de","pos":"preposition","definition":"below something","example":"The shoes are under the bed.","difficulty":1},{"word":"next to","translation":"ao lado de","pos":"preposition","definition":"very near, at the side of","example":"The lamp is next to the bed.","difficulty":2},{"word":"between","translation":"entre","pos":"preposition","definition":"in the space that separates two things","example":"The table is between the chairs.","difficulty":2},{"word":"behind","translation":"atrás de","pos":"preposition","definition":"at the back of","example":"The ball is behind the door.","difficulty":2}],"reading":{"title":"Apartment for rent","genre":"anúncio","text":"APARTMENT FOR RENT — Downtown\nThere are two bedrooms and one bathroom. There's a big living room with a balcony. The kitchen is small, but there is a new fridge. There isn't a garage, but there are bus stops next to the building. Pets are welcome!","questions":[{"difficulty":1,"prompt":"Quantos quartos há?","options":["1","2","3","Nenhum"],"answer":1,"explanation":"“There are two bedrooms.”"},{"difficulty":2,"prompt":"O que o apartamento NÃO tem?","options":["Varanda","Geladeira nova","Garagem","Banheiro"],"answer":2,"explanation":"“There isn't a garage.”"},{"difficulty":2,"prompt":"O que há ao lado do prédio?","options":["Um parque","Pontos de ônibus","Uma garagem","Uma loja"],"answer":1,"explanation":"“bus stops next to the building”."},{"difficulty":3,"prompt":"Uma família com um cachorro pode alugar?","options":["Sim, animais são bem-vindos","Não, não aceitam animais","O texto não diz","Só com garagem"],"answer":0,"explanation":"“Pets are welcome!”"}]},"writing":{"prompt":"Descreva o seu quarto (ou o quarto dos sonhos) com there is/there are e duas preposições de lugar.","criteria":["There is e there are","Pelo menos 4 objetos","2 preposições de lugar"],"model":"In my bedroom there is a bed and a desk. There are two shelves. My backpack is under the desk and the lamp is next to the bed.","keywords":["there","is","are","under","next"],"minWords":20},"challenge":"Esconda um objeto em casa e dê a pista em inglês para alguém achar: “It's under/behind/next to…”."},"games":{"blanks":[{"difficulty":1,"sentence":"There ___ a sofa in the living room.","options":["is","are","am","be"],"answer":0,"explanation":"Singular: there is."},{"difficulty":1,"sentence":"The milk is ___ the fridge.","options":["in","on","under","at"],"answer":0,"explanation":"Dentro: in."},{"difficulty":2,"sentence":"___ there any eggs? — No, there aren't.","options":["Are","Is","Do","Have"],"answer":0,"explanation":"Plural: Are there any…?"},{"difficulty":2,"sentence":"The ball is ___ the chair and the table.","options":["between","next","behind to","under of"],"answer":0,"explanation":"Entre duas coisas: between."},{"difficulty":3,"sentence":"There ___ a lot of noise in the street today.","options":["is","are","have","has"],"answer":0,"explanation":"Noise é incontável: there is."}],"sequences":[{"difficulty":1,"prompt":"Organize a frase · Put the words in order","items":["There","is","a","bed","in","my","room"],"words":true,"explanation":"There is + a + objeto + lugar."},{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["Is","there","a","park","near","here"],"words":true,"explanation":"Is there…? + lugar."}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-a1-can-directions","subject":"ingles","title":"Can, imperatives and directions","levels":["fund1","fund2","medio"],"grade":"A partir do 5º ano","topic":"Inglês A1 — Meu dia a dia","subtopic":"Can, imperativo e direções na cidade","aliases":["can em ingles","verbo can","habilidade em ingles","imperativo em ingles","direcoes em ingles","how do i get to","turn left","lugares da cidade em ingles"],"summary":"Diga o que você sabe fazer com can, dê instruções no imperativo e peça e dê direções na cidade.","intro":"Can you help me? Vamos nos virar na cidade em inglês.","objective":"Usar can para habilidade, permissão e pedido; dar instruções com o imperativo; pedir e dar direções simples com lugares da cidade.","prerequisites":["ing-a1-there-is"],"next":["ing-a2-present-continuous"],"skills":{"g_can":"Can / can't","g_imp":"Imperativo","v_city":"Lugares da cidade","s_dir":"Pedir e dar direções"},"blocks":[{"skill":"g_can","title":"Can and can't","text":"Can + verbo (sem to) expressa habilidade (I can swim), permissão (Can I go to the bathroom?) e pedido (Can you help me?). Negativa: can't (cannot). Can não muda com he/she/it: She can dance.","example":"I can speak two languages. · He can't cook. · Can you open the window?","variants":{"simples":"Can = consigo/sei/posso. Can't = não consigo/não posso.","exemplo":"Na aula: “Can I borrow your pencil?” — “Sure!”","passos":"1. Sujeito. 2. Can ou can't. 3. Verbo sem to e sem -s.","compara":"Diferente do simple present, com can o verbo NÃO ganha -s: She can play (nunca “she cans plays”)."},"id":"b1"},{"skill":"g_imp","title":"Imperatives","text":"O imperativo dá ordens, instruções e conselhos: é o verbo na forma base, sem sujeito: Open your books. Turn left. Negativo: Don't + verbo: Don't run! Para ser educado, acrescente please.","example":"Sit down, please. · Don't touch that! · Take the first street on the right.","variants":{"simples":"Imperativo = mandar ou orientar: Open! Close! Don't run!","exemplo":"Receita: “Mix the eggs. Don't add salt.”","passos":"1. Comece pelo verbo. 2. Negativo: Don't + verbo. 3. Educado: please.","compara":"O imperativo é igual para uma ou várias pessoas: “Sit down” serve para você e para a turma inteira."},"id":"b2"},{"skill":"v_city","title":"Places in town","text":"Lugares: bank (banco), bakery (padaria), pharmacy/drugstore (farmácia), supermarket, hospital, library (biblioteca), museum, park, bus stop (ponto de ônibus), train station (estação), post office (correios), restaurant, school, church.","example":"The library is next to the park. · There's a bakery near the school.","variants":{"simples":"Library = biblioteca (não é livraria!). Bakery = padaria.","exemplo":"Turista pergunta: “Is there a pharmacy near here?”","passos":"1. Liste os lugares do seu bairro. 2. Diga em inglês. 3. Use there is/next to para localizá-los.","compara":"Library parece “livraria”, mas é BIBLIOTECA. Livraria = bookstore."},"id":"b3"},{"skill":"s_dir","title":"Asking for and giving directions","text":"Para perguntar: Excuse me, where is the bank? / How do I get to the station? Para responder: Go straight (ahead) (siga em frente), Turn left/right (vire à esquerda/direita), Take the second street on the left, It's on the corner (na esquina), It's across from the park (em frente ao parque).","example":"— How do I get to the museum? — Go straight and turn right. It's next to the bank.","variants":{"simples":"Go straight = siga reto. Turn left = vire à esquerda. Turn right = vire à direita.","exemplo":"Você explica para um turista: “Go straight, turn left at the bakery. The station is on the right.”","passos":"1. Excuse me + pergunta. 2. Ouça: straight, left, right. 3. Agradeça: Thank you!","compara":"Right tem dois sentidos: direita e certo. Em direções, “on the right” = à direita."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"g_can","prompt":"Qual frase está correta?","options":["She can swims.","She cans swim.","She can swim.","She can to swim."],"answer":2,"hints":["Can não muda.","Verbo sem -s.","Sem to."],"explanation":"She can swim.","id":"q1"},{"type":"mc","difficulty":1,"skill":"s_dir","prompt":"“Turn left” significa:","options":["Vire à direita","Vire à esquerda","Siga em frente","Volte"],"answer":1,"hints":["Left = …","Oposto de right.","Esquerda."],"explanation":"Turn left = vire à esquerda.","id":"q2"},{"type":"tf","difficulty":1,"skill":"v_city","prompt":"“Library” significa livraria.","answer":false,"hints":["É um falso amigo.","Lugar onde se pegam livros emprestados.","Biblioteca."],"explanation":"Falso: library = biblioteca; livraria = bookstore.","id":"q3"},{"type":"fill","difficulty":1,"skill":"g_imp","prompt":"Complete a ordem negativa: ___ run in the corridor!","answers":["Don't","Do not"],"hints":["Imperativo negativo.","Do + not.","D-o-n-'-t."],"explanation":"Don't run!","id":"q4"},{"type":"match","difficulty":2,"skill":"v_city","prompt":"Ligue o lugar ao que você faz lá.","pairs":[["bakery","comprar pão"],["pharmacy","comprar remédio"],["library","pegar livros emprestados"],["bank","sacar dinheiro"]],"hints":["Bake = assar.","Pharmacy parece farmácia.","Library = biblioteca."],"explanation":"bakery pão · pharmacy remédio · library livros · bank dinheiro.","id":"q5"},{"type":"mc","difficulty":2,"skill":"g_can","prompt":"Você quer pedir permissão para ir ao banheiro. Diga:","options":["Can I go to the bathroom?","I can go to the bathroom.","Can you go to the bathroom?","Go to the bathroom."],"answer":0,"hints":["É um pedido de permissão.","Pergunta começa com can.","Can I…?"],"explanation":"Can I go to the bathroom?","id":"q6"},{"type":"mc","difficulty":2,"skill":"s_dir","prompt":"Como perguntar o caminho para a estação?","options":["How do I get to the station?","How I get to the station?","Where I go station?","How do get I to the station?"],"answer":0,"hints":["Pergunta com How do I…","Get to = chegar a.","How do I get to…?"],"explanation":"How do I get to the station?","id":"q7"},{"type":"mc","difficulty":2,"skill":"g_imp","prompt":"Qual é uma instrução no imperativo?","options":["You opens the book.","Open your book, please.","Opening the book.","To open the book."],"answer":1,"hints":["Imperativo começa pelo verbo.","Sem sujeito.","Open…"],"explanation":"Open your book, please.","id":"q8"},{"type":"order","difficulty":3,"skill":"s_dir","prompt":"Coloque as instruções na ordem para chegar ao museu: saia, siga reto, vire à direita no banco, o museu fica à esquerda.","items":["Leave the school.","Go straight.","Turn right at the bank.","The museum is on the left."],"hints":["Primeiro você sai.","Depois segue reto.","Por último a posição do museu."],"explanation":"Leave → go straight → turn right → on the left.","id":"q9"},{"type":"mc","difficulty":3,"skill":"g_can","prompt":"“Can you speak French?” — “No, I ___.”","options":["don't","can't","not","cannot speak it can"],"answer":1,"hints":["Resposta curta repete o auxiliar.","A pergunta usa can.","Negativo: can't."],"explanation":"No, I can't.","id":"q10"}],"review":["Can + verbo base (sem to, sem -s) · can't","Imperativo: Open… / Don't run!","Lugares: bakery, pharmacy, library (biblioteca), bank…","Direções: go straight, turn left/right, on the corner"],"relatedQuestions":["como usar can em inglês","como pedir direções em inglês","imperativo em inglês"],"equivalentQuestions":["como dizer eu sei nadar em inglês","como pedir licença para ir ao banheiro em inglês","como perguntar onde fica algo em inglês","o que significa turn right","library é livraria","como se diz padaria em inglês","como dar ordem em inglês","o que é can em inglês","como usar can em inglês","me explica can em inglês","quando usar can em inglês","exemplos de can em inglês","can em inglês em inglês","como funciona can em inglês","regras de can em inglês","exercícios de can em inglês","aula de can em inglês","não entendi can em inglês","can em inglês para iniciantes","resumo de can em inglês","dúvida sobre can em inglês","o que é direções em inglês","como usar direções em inglês","me explica direções em inglês","quando usar direções em inglês","exemplos de direções em inglês","direções em inglês em inglês","como funciona direções em inglês","regras de direções em inglês","exercícios de direções em inglês","aula de direções em inglês","não entendi direções em inglês","direções em inglês para iniciantes","resumo de direções em inglês","dúvida sobre direções em inglês","o que é imperativo em inglês","como usar imperativo em inglês","me explica imperativo em inglês","quando usar imperativo em inglês","exemplos de imperativo em inglês","imperativo em inglês em inglês","como funciona imperativo em inglês","regras de imperativo em inglês","exercícios de imperativo em inglês","aula de imperativo em inglês","não entendi imperativo em inglês","imperativo em inglês para iniciantes","resumo de imperativo em inglês","dúvida sobre imperativo em inglês"],"commonErrors":["Colocar -s ou to depois de can (she can swims, can to go).","Achar que library = livraria.","Usar sujeito no imperativo (You open the door!)."],"english":{"cefr":"A1","unit":"a1-u4","order":2,"area":"speaking","focus":["speaking","listening","grammar"],"vocabulary":[{"word":"bakery","translation":"padaria","pos":"noun","definition":"a shop that sells bread and cakes","example":"I buy bread at the bakery.","difficulty":1},{"word":"library","translation":"biblioteca","pos":"noun","definition":"a place where you can borrow books","example":"The library is quiet.","difficulty":2,"related":["bookstore"]},{"word":"pharmacy","translation":"farmácia","pos":"noun","definition":"a shop that sells medicine","example":"Is there a pharmacy near here?","difficulty":1,"synonyms":["drugstore"]},{"word":"station","translation":"estação","pos":"noun","definition":"a place where trains or buses stop","example":"The train station is big.","difficulty":2},{"word":"left","translation":"esquerda","pos":"noun","definition":"the side opposite to right","example":"Turn left at the bank.","difficulty":1,"antonyms":["right"]},{"word":"right","translation":"direita","pos":"noun","definition":"the side opposite to left","example":"The school is on the right.","difficulty":1,"antonyms":["left"]},{"word":"straight","translation":"reto / em frente","pos":"adverb","definition":"without turning","example":"Go straight for two blocks.","difficulty":2},{"word":"corner","translation":"esquina","pos":"noun","definition":"the place where two streets meet","example":"The bank is on the corner.","difficulty":2},{"word":"turn","translation":"virar","pos":"verb","definition":"to change direction","example":"Turn right at the park.","difficulty":1},{"word":"can","translation":"poder / conseguir","pos":"verb","definition":"to be able to","example":"I can ride a bike.","difficulty":1}],"listening":{"title":"Where is the museum?","kind":"dialogo","rate":0.88,"script":["Tourist: Excuse me, how do I get to the museum?","Girl: Go straight for two blocks.","Girl: Then turn left at the bakery.","Girl: The museum is on the right, across from the park.","Tourist: Thank you so much!","Girl: You're welcome."],"questions":[{"difficulty":1,"prompt":"Para onde o turista quer ir?","options":["Ao parque","Ao museu","À padaria","Ao banco"],"answer":1,"explanation":"“How do I get to the museum?”"},{"difficulty":2,"prompt":"Onde ele deve virar à esquerda?","options":["No parque","No banco","Na padaria","Na escola"],"answer":2,"explanation":"“turn left at the bakery”."},{"difficulty":3,"prompt":"Onde fica o museu?","options":["À esquerda, ao lado da padaria","À direita, em frente ao parque","Na esquina do banco","Atrás do parque"],"answer":1,"explanation":"“on the right, across from the park”."}]},"speaking":{"situation":"Um turista para você na rua e pergunta como chegar à biblioteca.","vocabulary":["go straight","turn left","turn right","next to"],"phrases":["Go straight.","Turn left at…","It's next to…","It's on the right."],"example":"Go straight and turn right at the bank. The library is next to the park.","challenge":"Explique em inglês o caminho da sua casa até a padaria ou a escola.","expected":["go","straight","turn","left","right"]},"challenge":"Faça uma lista de 3 coisas que você can e 3 que você can't fazer."},"games":{"words":[{"word":"bakery","clue":"padaria","difficulty":1},{"word":"library","clue":"biblioteca","difficulty":2},{"word":"bank","clue":"banco","difficulty":1},{"word":"museum","clue":"museu","difficulty":1},{"word":"left","clue":"esquerda","difficulty":1},{"word":"right","clue":"direita","difficulty":1},{"word":"corner","clue":"esquina","difficulty":2},{"word":"straight","clue":"em frente","difficulty":3}],"blanks":[{"difficulty":1,"sentence":"I ___ play the guitar.","options":["can","cans","can to","am can"],"answer":0,"explanation":"Can + verbo base."},{"difficulty":1,"sentence":"___ left at the bank.","options":["Turn","Turns","Turning","To turn"],"answer":0,"explanation":"Imperativo: verbo na forma base."},{"difficulty":2,"sentence":"Excuse me, how do I ___ to the station?","options":["get","go to","arrive","come"],"answer":0,"explanation":"How do I get to…?"},{"difficulty":2,"sentence":"The bank is ___ the corner.","options":["on","in","at to","under"],"answer":0,"explanation":"On the corner = na esquina."},{"difficulty":3,"sentence":"___ touch the stove! It's hot.","options":["Don't","Not","No","Can"],"answer":0,"explanation":"Imperativo negativo: Don't."}],"dialogues":[{"difficulty":1,"title":"Pedindo permissão","gap":1,"options":["Yes, you can.","Yes, I can.","Turn left.","You're welcome."],"answer":0,"explanation":"Para dar permissão: Yes, you can.","lines":[{"who":"Student","text":"Can I open the window, please?"},{"who":"Teacher","text":"Yes, you can."},{"who":"Student","text":"Thank you!"}]},{"difficulty":2,"title":"Na rua","gap":1,"options":["Go straight and turn right. It's on the corner.","I can't swim.","It's eight o'clock.","Nice to meet you."],"answer":0,"explanation":"A pergunta pede uma direção.","lines":[{"who":"Man","text":"Excuse me, where is the pharmacy?"},{"who":"Girl","text":"Go straight and turn right. It's on the corner."},{"who":"Man","text":"Thanks a lot!"}]}],"sequences":[{"difficulty":1,"prompt":"Organize a frase · Put the words in order","items":["Can","you","help","me","please"],"words":true,"explanation":"Pedido: Can you + verbo…?"},{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["Turn","left","at","the","bakery"],"words":true,"explanation":"Imperativo + direção + lugar."}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-a2-present-continuous","subject":"ingles","title":"Present continuous","levels":["fund2","medio"],"grade":"6º e 7º ano","topic":"Inglês A2 — Agora e antes","subtopic":"Present continuous × simple present","aliases":["present continuous","presente continuo","ing em ingles","gerundio em ingles","am is are ing","acontecendo agora em ingles","present progressive"],"summary":"Fale do que está acontecendo agora com am/is/are + -ing e saiba quando usar o simple present.","intro":"Look! It's raining! Vamos falar do que está acontecendo neste momento.","objective":"Formar o present continuous (afirmativa, negativa e pergunta), aplicar as regras do -ing e escolher entre ele e o simple present.","prerequisites":["ing-simple-present","ing-verb-to-be"],"next":["ing-a2-simple-past"],"skills":{"g_form":"Formação: am/is/are + -ing","g_ing":"Regras de ortografia do -ing","g_negq":"Negativa e pergunta","g_vs":"Present continuous × simple present"},"blocks":[{"skill":"g_form","title":"am / is / are + verb-ing","text":"O present continuous mostra uma ação em andamento agora ou nestes dias: sujeito + am/is/are + verbo com -ing. Palavras que costumam aparecer: now, right now, at the moment, today, Look!, Listen!","example":"I'm studying now. · She's playing the piano. · They're watching a movie.","variants":{"simples":"É o nosso “estou fazendo”: I'm eating = estou comendo.","exemplo":"Mensagem para um amigo: “I'm waiting for the bus. I'm late!”","passos":"1. Sujeito. 2. Am, is ou are (verb to be). 3. Verbo + ing.","compara":"Em português: “estou + -ndo” (estou comendo). Em inglês: am + -ing (I am eating). O “estar” vira o verb to be."},"id":"b1"},{"skill":"g_ing","title":"Spelling: -ing","text":"Regra geral: verbo + ing (play → playing). Verbos que terminam em -e perdem o e (write → writing, dance → dancing). Verbos curtos que terminam em consoante + vogal + consoante dobram a última letra (run → running, swim → swimming, sit → sitting). Terminados em -ie viram -ying (lie → lying).","example":"make → making · stop → stopping · die → dying","variants":{"simples":"Quase sempre é só colocar -ing. Tire o -e do final e dobre a letra em palavras curtas como run.","exemplo":"Legenda de foto: “Swimming in the sea!” (swim + m + ing).","passos":"1. Termina em -e? Tire o e. 2. É curto com consoante-vogal-consoante? Dobre a última. 3. Senão, só -ing.","compara":"Compare: hope → hoping (tira o e) × hop → hopping (dobra o p). Uma letra muda o sentido: esperar × pular."},"id":"b2"},{"skill":"g_negq","title":"Negative and questions","text":"Negativa: am not / isn't / aren't + -ing: He isn't sleeping. Pergunta: Am/Is/Are + sujeito + -ing? Is she working? — Yes, she is. / No, she isn't. Com palavra de pergunta: What are you doing? Where are they going?","example":"— What are you doing? — I'm reading a comic.","variants":{"simples":"Negativa: isn't / aren't. Pergunta: coloque am/is/are no começo.","exemplo":"Mãe no telefone: “Are you doing your homework?” — “Yes, I am!”","passos":"1. Negativa: coloque not depois de am/is/are. 2. Pergunta: troque a ordem. 3. Resposta curta: Yes, I am / No, he isn't.","compara":"No present continuous NÃO usamos do/does: é “Are you working?”, e não “Do you working?”."},"id":"b3"},{"skill":"g_vs","title":"Now or every day?","text":"Simple present = rotina, hábito, verdade (I play soccer on Sundays). Present continuous = agora, temporário (I'm playing soccer now). Verbos de estado (like, love, want, know, need, understand) quase nunca vão para o -ing: I want pizza (e não “I'm wanting”).","example":"She usually walks to school, but today she's taking the bus.","variants":{"simples":"Todo dia → simple present. Agora → present continuous.","exemplo":"Status: “I usually study in the morning, but this week I'm studying at night.”","passos":"1. Procure palavras de tempo: every day, usually (rotina) × now, at the moment (agora). 2. Escolha o tempo. 3. Cuidado com verbos de estado.","compara":"“I work in a bank” = é o meu emprego. “I'm working in a bank this month” = é temporário, só agora."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"g_form","prompt":"Look! The children ___ in the park.","options":["play","are playing","is playing","plays"],"answer":1,"hints":["“Look!” indica agora.","Children é plural.","Are + -ing."],"explanation":"Agora + plural: are playing.","id":"q1"},{"type":"fill","difficulty":1,"skill":"g_ing","prompt":"Escreva o -ing de “write”.","answers":["writing"],"hints":["Termina em -e.","Tire o e.","writ + ing."],"explanation":"Write → writing.","id":"q2"},{"type":"tf","difficulty":1,"skill":"g_negq","prompt":"“Do you studying now?” está correto.","answer":false,"hints":["No present continuous usamos do?","Usamos o verb to be.","Are you studying…?"],"explanation":"Falso: Are you studying now?","id":"q3"},{"type":"mc","difficulty":1,"skill":"g_form","prompt":"Qual frase significa “Estou comendo”?","options":["I eat.","I'm eating.","I eating.","I'm eat."],"answer":1,"hints":["Estou = I am.","Comendo = eating.","I'm eating."],"explanation":"I'm eating.","id":"q4"},{"type":"match","difficulty":2,"skill":"g_ing","prompt":"Ligue o verbo à forma com -ing.","pairs":[["run","running"],["dance","dancing"],["play","playing"],["lie","lying"]],"hints":["Run é curto: dobra.","Dance perde o e.","Lie → -ying."],"explanation":"running · dancing · playing · lying.","id":"q5"},{"type":"mc","difficulty":2,"skill":"g_negq","prompt":"— Is your sister sleeping? — No, she ___. She's reading.","options":["isn't","doesn't","aren't","not"],"answer":0,"hints":["Resposta curta repete o auxiliar.","A pergunta usa is.","Is + not."],"explanation":"No, she isn't.","id":"q6"},{"type":"mc","difficulty":2,"skill":"g_vs","prompt":"I usually ___ to school, but today I ___ the bus.","options":["walk / am taking","am walking / take","walks / taking","walk / take"],"answer":0,"hints":["Usually = rotina.","Today = temporário/agora.","Simple present + present continuous."],"explanation":"Rotina: walk; hoje: am taking.","id":"q7"},{"type":"mc","difficulty":2,"skill":"g_vs","prompt":"Qual frase está correta?","options":["I'm wanting a sandwich.","I want a sandwich.","I wanting a sandwich.","I'm want a sandwich."],"answer":1,"hints":["Want é verbo de estado.","Não costuma ir para -ing.","Simple present."],"explanation":"I want a sandwich (want é verbo de estado).","id":"q8"},{"type":"order","difficulty":3,"skill":"g_negq","prompt":"Organize a pergunta: “O que você está fazendo?”","items":["What","are","you","doing?"],"hints":["Comece pela palavra de pergunta.","Depois o verb to be.","Sujeito + -ing."],"explanation":"What are you doing?","id":"q9"},{"type":"mc","difficulty":3,"skill":"g_ing","prompt":"Qual está escrita corretamente?","options":["swiming","swimming","swimeing","swimmming"],"answer":1,"hints":["Swim: consoante-vogal-consoante.","Dobra o m.","Uma vez só."],"explanation":"Swim → swimming.","id":"q10"}],"review":["am/is/are + verbo-ing = acontecendo agora","-ing: tira o -e (writing), dobra (running), -ie → -ying","Negativa isn't/aren't · pergunta Are you…?","Rotina = simple present · agora = present continuous"],"relatedQuestions":["como usar o present continuous","diferença entre simple present e present continuous","regras do ing em inglês"],"equivalentQuestions":["como dizer estou fazendo em inglês","quando usar ing em inglês","por que running tem dois n","diferença entre I work e I am working","como perguntar o que você está fazendo em inglês","verbos que não vão para ing","o que é gerúndio em inglês","o que é present continuous","como usar present continuous","me explica present continuous","quando usar present continuous","exemplos de present continuous","present continuous em inglês","como funciona present continuous","regras de present continuous","exercícios de present continuous","aula de present continuous","não entendi present continuous","present continuous para iniciantes","resumo de present continuous","dúvida sobre present continuous","o que é presente contínuo","como usar presente contínuo","me explica presente contínuo","quando usar presente contínuo","exemplos de presente contínuo","presente contínuo em inglês","como funciona presente contínuo","regras de presente contínuo","exercícios de presente contínuo","aula de presente contínuo","não entendi presente contínuo","presente contínuo para iniciantes","resumo de presente contínuo","dúvida sobre presente contínuo"],"commonErrors":["Esquecer o am/is/are (I playing).","Usar do/does em perguntas (Do you working?).","Colocar verbos de estado no -ing (I'm knowing)."],"english":{"cefr":"A2","unit":"a2-u1","order":1,"area":"grammar","focus":["grammar","listening","speaking"],"vocabulary":[{"word":"now","translation":"agora","pos":"adverb","definition":"at this moment","example":"I'm busy now.","difficulty":1},{"word":"at the moment","translation":"no momento","pos":"phrase","definition":"now, at this time","example":"She's working at the moment.","difficulty":2},{"word":"wait","translation":"esperar","pos":"verb","definition":"to stay until something happens","example":"I'm waiting for the bus.","difficulty":1},{"word":"rain","translation":"chover","pos":"verb","definition":"when water falls from the sky","example":"Look! It's raining.","difficulty":1},{"word":"cook","translation":"cozinhar","pos":"verb","definition":"to prepare food","example":"Dad is cooking dinner.","difficulty":1},{"word":"listen","translation":"ouvir / escutar","pos":"verb","definition":"to pay attention to a sound","example":"Listen! The baby is crying.","difficulty":1},{"word":"cry","translation":"chorar","pos":"verb","definition":"to have tears falling from your eyes","example":"Why are you crying?","difficulty":2},{"word":"busy","translation":"ocupado(a)","pos":"adjective","definition":"having a lot to do","example":"I can't talk, I'm busy.","difficulty":2}],"grammar":{"name":"Present continuous","when":"Ações acontecendo agora ou temporárias (nestes dias).","structure":"sujeito + am/is/are + verbo-ing","affirmative":["I'm reading.","She's cooking.","They're playing."],"negative":["I'm not sleeping.","He isn't working.","We aren't watching TV."],"interrogative":["Are you listening?","Is it raining?","What are they doing?"],"compare":"I play (rotina) × I'm playing (agora).","context":"Descrevendo pelo telefone o que está acontecendo numa festa."},"listening":{"title":"Ligação de domingo","kind":"dialogo","rate":0.9,"script":["Grandma: Hi, sweetie! What are you doing?","Girl: Hi, Grandma! I'm making a cake with Dad.","Grandma: Lovely! And your brother?","Girl: He's playing video games in his room.","Grandma: Is your mom there?","Girl: No, she isn't. She's running in the park."],"questions":[{"difficulty":1,"prompt":"O que a menina está fazendo?","options":["Jogando videogame","Fazendo um bolo","Correndo","Dormindo"],"answer":1,"explanation":"“I'm making a cake with Dad.”"},{"difficulty":2,"prompt":"Onde está o irmão?","options":["No parque","No quarto","Na cozinha","Na casa da avó"],"answer":1,"explanation":"“in his room”."},{"difficulty":2,"prompt":"O que a mãe está fazendo?","options":["Cozinhando","Correndo no parque","Trabalhando","Falando ao telefone"],"answer":1,"explanation":"“She's running in the park.”"}]},"speaking":{"situation":"Um amigo liga e pergunta o que você e sua família estão fazendo agora.","vocabulary":["right now","I'm","he's","they're"],"phrases":["Right now I'm…","My mom is…","My friends are…"],"example":"Right now I'm studying English. My mom is cooking and my dad is watching TV.","challenge":"Diga 3 frases sobre o que está acontecendo ao seu redor neste momento.","expected":["i'm","is","ing"]},"writing":{"prompt":"Olhe pela janela (ou imagine uma praça) e escreva 4 frases sobre o que as pessoas estão fazendo.","criteria":["am/is/are + -ing","Pelo menos 4 ações","Ortografia do -ing"],"model":"A man is walking his dog. Two kids are riding bikes. A woman is sitting on a bench. It isn't raining today.","keywords":["is","are","ing"],"minWords":18},"challenge":"Tire uma foto (ou escolha uma) e descreva em inglês o que está acontecendo nela."},"games":{"blanks":[{"difficulty":1,"sentence":"Listen! Somebody ___ at the door.","options":["is knocking","knocks","knock","are knocking"],"answer":0,"explanation":"“Listen!” = agora: is knocking."},{"difficulty":1,"sentence":"We ___ a movie right now.","options":["are watching","watch","is watching","watches"],"answer":0,"explanation":"We + are + -ing."},{"difficulty":2,"sentence":"She ___ to the radio at the moment.","options":["isn't listening","doesn't listen","not listening","aren't listening"],"answer":0,"explanation":"Negativa: isn't + -ing."},{"difficulty":2,"sentence":"He goes to work by car, but this week he ___ the train.","options":["is taking","takes","take","taking"],"answer":0,"explanation":"Temporário: is taking."},{"difficulty":3,"sentence":"I ___ what you mean.","options":["understand","am understanding","understanding","am understand"],"answer":0,"explanation":"Understand é verbo de estado."}],"sequences":[{"difficulty":1,"prompt":"Organize a frase · Put the words in order","items":["She","is","reading","a","book"],"words":true,"explanation":"Sujeito + is + -ing + complemento."},{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["Are","they","playing","soccer"],"words":true,"explanation":"Pergunta: Are + sujeito + -ing?"},{"difficulty":3,"prompt":"Organize a frase · Put the words in order","items":["I","am","not","sleeping","right","now"],"words":true,"explanation":"Negativa: am not + -ing."}],"dialogues":[{"difficulty":2,"title":"No telefone","gap":1,"options":["Yes, I'm doing my homework.","Yes, I do my homework.","Yes, I am do homework.","Yes, I doing homework."],"answer":0,"explanation":"Agora: I'm doing.","lines":[{"who":"Leo","text":"Hi! Are you busy?"},{"who":"Ana","text":"Yes, I'm doing my homework."},{"who":"Leo","text":"OK, call me later!"}]},{"difficulty":3,"title":"Na praia","gap":1,"options":["I'm looking for my sunglasses.","I look for my sunglasses every day.","I looking my sunglasses.","I'm look for my sunglasses."],"answer":0,"explanation":"Present continuous: I'm looking for.","lines":[{"who":"Bia","text":"What are you doing?"},{"who":"Rui","text":"I'm looking for my sunglasses."},{"who":"Bia","text":"They're on your head!"}]}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-a2-simple-past","subject":"ingles","title":"Simple past","levels":["fund2","medio"],"grade":"7º e 8º ano","topic":"Inglês A2 — Agora e antes","subtopic":"Simple past: regulares, irregulares, did","aliases":["simple past","passado simples","past simple","verbos irregulares","ed em ingles","did didnt","passado em ingles","was were"],"summary":"Conte o que aconteceu: verbos com -ed, os irregulares mais comuns, was/were e did.","intro":"Yesterday I watched a great movie! Vamos contar histórias do passado.","objective":"Formar o simple past de verbos regulares e irregulares, usar was/were e fazer negativas e perguntas com did.","prerequisites":["ing-simple-present"],"next":["ing-a2-past-continuous"],"skills":{"g_reg":"Verbos regulares (-ed)","g_irr":"Verbos irregulares","g_did":"Negativa e pergunta com did","g_was":"Was / were"},"blocks":[{"skill":"g_reg","title":"Regular verbs: -ed","text":"O simple past fala de ações terminadas num momento do passado (yesterday, last week, in 2020, two days ago). Nos verbos regulares, acrescentamos -ed: play → played. Terminados em -e: só -d (dance → danced). Consoante + y: -ied (study → studied). Curtos com consoante-vogal-consoante dobram: stop → stopped.","example":"I watched TV yesterday. · She studied for the test last night.","variants":{"simples":"Passado regular = verbo + ed: I played = eu joguei.","exemplo":"Contando o fim de semana: “On Saturday I visited my grandma and we cooked lunch.”","passos":"1. Veja se o verbo é regular. 2. Acrescente -ed (ou -d, -ied, dobra). 3. A forma é a mesma para todas as pessoas.","compara":"Diferente do presente, no passado NÃO existe -s para he/she: He played (e não “he playeds”)."},"id":"b1"},{"skill":"g_irr","title":"Irregular verbs","text":"Muitos verbos comuns são irregulares e precisam ser memorizados: go → went, have → had, do → did, see → saw, eat → ate, make → made, get → got, come → came, take → took, buy → bought, write → wrote, say → said.","example":"We went to the beach. · I saw a shark! · She bought a new phone.","variants":{"simples":"Alguns verbos mudam de jeito no passado: go vira went, eat vira ate.","exemplo":"Diário de viagem: “We took a boat, ate fish and saw dolphins.”","passos":"1. Faça uma lista com os 20 irregulares mais usados. 2. Treine em frases. 3. Revise um pouco por dia.","compara":"Em português também temos irregulares: “ir → fui”, “ter → tive”. Em inglês: go → went, have → had."},"id":"b2"},{"skill":"g_did","title":"Negative and questions with did","text":"Negativa: didn't + verbo na forma base: I didn't go (e não “didn't went”). Pergunta: Did + sujeito + verbo base? Did you like it? — Yes, I did. / No, I didn't. Com palavra de pergunta: Where did you go? What did she say?","example":"— Did you finish your homework? — No, I didn't.","variants":{"simples":"Did carrega o passado; por isso o verbo volta ao normal: Did you go?","exemplo":"Professor pergunta: “What did you do on the weekend?”","passos":"1. Negativa: didn't + verbo base. 2. Pergunta: Did + sujeito + verbo base. 3. Resposta: Yes, I did / No, I didn't.","compara":"É o mesmo esquema do do/does do presente, só que tudo vira did — para todas as pessoas."},"id":"b3"},{"skill":"g_was","title":"Was and were","text":"O passado do verb to be: was (I, he, she, it) e were (you, we, they). Negativa: wasn't / weren't. Pergunta: Was she at school? Were they happy? Não usamos did com was/were.","example":"I was tired. · They were at the party. · Was it good? — Yes, it was.","variants":{"simples":"Was = era/estava (um). Were = eram/estavam (vários, e “você”).","exemplo":"Depois do jogo: “The game was amazing! We were so happy.”","passos":"1. Sujeito I/he/she/it → was. 2. You/we/they → were. 3. Pergunta: Was/Were no começo.","compara":"Com o verb to be não entra did: “Were you there?” (e não “Did you were there?”)."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"g_reg","prompt":"Yesterday I ___ soccer with my friends.","options":["play","played","plays","playing"],"answer":1,"hints":["Yesterday = passado.","Play é regular.","Play + ed."],"explanation":"Played.","id":"q1"},{"type":"mc","difficulty":1,"skill":"g_irr","prompt":"Qual é o passado de “go”?","options":["goed","went","gone","goes"],"answer":1,"hints":["É irregular.","Não tem -ed.","W…"],"explanation":"Go → went.","id":"q2"},{"type":"fill","difficulty":1,"skill":"g_reg","prompt":"Escreva o passado de “study”.","answers":["studied"],"hints":["Consoante + y.","O y vira i.","studi + ed."],"explanation":"Study → studied.","id":"q3"},{"type":"tf","difficulty":1,"skill":"g_did","prompt":"“I didn't went to school” está correto.","answer":false,"hints":["Depois de didn't…","…o verbo volta à forma base.","Didn't go."],"explanation":"Falso: I didn't go to school.","id":"q4"},{"type":"match","difficulty":2,"skill":"g_irr","prompt":"Ligue o verbo ao seu passado.","pairs":[["eat","ate"],["see","saw"],["buy","bought"],["have","had"]],"hints":["Eat → a…","See → s…w","Buy e bring têm “ought”."],"explanation":"ate · saw · bought · had.","id":"q5"},{"type":"mc","difficulty":2,"skill":"g_was","prompt":"They ___ at the cinema last night.","options":["was","were","did","are"],"answer":1,"hints":["They → were ou was?","Plural.","Were."],"explanation":"They were.","id":"q6"},{"type":"mc","difficulty":2,"skill":"g_did","prompt":"___ you like the movie?","options":["Did","Do","Were","Was"],"answer":0,"hints":["Like é verbo comum (não é to be).","Passado.","Did."],"explanation":"Did you like the movie?","id":"q7"},{"type":"mc","difficulty":2,"skill":"g_did","prompt":"Qual pergunta está correta?","options":["Where did you went?","Where you went?","Where did you go?","Where did you goes?"],"answer":2,"hints":["Did já mostra o passado.","Verbo na forma base.","Did + you + go."],"explanation":"Where did you go?","id":"q8"},{"type":"order","difficulty":3,"skill":"g_irr","prompt":"Coloque a história na ordem.","items":["Last Saturday we woke up early.","We took the bus to the beach.","We swam and ate sandwiches.","In the evening we came home tired."],"hints":["A manhã vem primeiro.","Depois o transporte.","A volta é no final."],"explanation":"Acordar → ônibus → praia → voltar.","id":"q9"},{"type":"mc","difficulty":3,"skill":"g_was","prompt":"— Was the test difficult? — No, it ___.","options":["didn't","wasn't","weren't","isn't"],"answer":1,"hints":["A pergunta usa was.","Resposta curta repete.","Was + not."],"explanation":"No, it wasn't.","id":"q10"}],"review":["Regulares: -ed / -d / -ied / dobra (stopped)","Irregulares: went, had, did, saw, ate, bought…","didn't + verbo base · Did you…?","was (I/he/she/it) · were (you/we/they)"],"relatedQuestions":["como usar o simple past","lista de verbos irregulares","quando usar did em inglês"],"equivalentQuestions":["como falar do passado em inglês","passado de go","passado de eat","por que didn't go e não didn't went","diferença entre was e were","como perguntar o que você fez no fim de semana em inglês","verbos irregulares mais usados","o que é simple past","como usar simple past","me explica simple past","quando usar simple past","exemplos de simple past","simple past em inglês","como funciona simple past","regras de simple past","exercícios de simple past","aula de simple past","não entendi simple past","simple past para iniciantes","resumo de simple past","dúvida sobre simple past","o que é passado simples em inglês","como usar passado simples em inglês","me explica passado simples em inglês","quando usar passado simples em inglês","exemplos de passado simples em inglês","passado simples em inglês em inglês","como funciona passado simples em inglês","regras de passado simples em inglês","exercícios de passado simples em inglês","aula de passado simples em inglês","não entendi passado simples em inglês","passado simples em inglês para iniciantes","resumo de passado simples em inglês","dúvida sobre passado simples em inglês"],"commonErrors":["Usar did + verbo no passado (didn't went).","Colocar -ed em irregulares (goed, eated).","Usar did com was/were."],"english":{"cefr":"A2","unit":"a2-u2","order":1,"area":"grammar","focus":["grammar","reading","writing"],"vocabulary":[{"word":"yesterday","translation":"ontem","pos":"adverb","definition":"the day before today","example":"I saw her yesterday.","difficulty":1},{"word":"last","translation":"passado(a) / último","pos":"determiner","definition":"the one before this one","example":"Last week I was sick.","difficulty":1,"collocations":["last night","last year"]},{"word":"ago","translation":"atrás","pos":"adverb","definition":"before now (two days ago)","example":"I moved here three years ago.","difficulty":2},{"word":"went","translation":"foi / fui (go)","pos":"verb","definition":"past of go","example":"We went to the zoo.","difficulty":1},{"word":"saw","translation":"viu / vi (see)","pos":"verb","definition":"past of see","example":"I saw a rainbow.","difficulty":1},{"word":"bought","translation":"comprou (buy)","pos":"verb","definition":"past of buy","example":"She bought a new bike.","difficulty":2},{"word":"took","translation":"pegou / levou (take)","pos":"verb","definition":"past of take","example":"We took a lot of photos.","difficulty":2},{"word":"trip","translation":"viagem","pos":"noun","definition":"a journey to a place and back","example":"Our trip was great.","difficulty":1}],"grammar":{"name":"Simple past","when":"Ações terminadas num momento do passado.","structure":"verbo-ed / irregular · didn't + base · Did + sujeito + base?","affirmative":["I watched a movie.","She went home."],"negative":["I didn't watch it.","She didn't go."],"interrogative":["Did you watch it?","Where did she go?"],"compare":"Simple present (I play every day) × simple past (I played yesterday).","context":"Contar uma viagem ou o fim de semana."},"reading":{"title":"My trip to Bonito","genre":"relato de viagem","text":"Last July, my family went to Bonito, in Mato Grosso do Sul. We stayed in a small hotel near a river. On the first day, we snorkeled in crystal-clear water and saw hundreds of fish. My little brother didn't want to go in the water at first, but then he loved it. On the last day it rained, so we visited a museum. It was the best trip of my life!","questions":[{"difficulty":1,"prompt":"Quando foi a viagem?","options":["Julho passado","Junho passado","Ano que vem","Ontem"],"answer":0,"explanation":"“Last July”."},{"difficulty":2,"prompt":"O que eles viram na água?","options":["Tubarões","Centenas de peixes","Golfinhos","Tartarugas"],"answer":1,"explanation":"“saw hundreds of fish”."},{"difficulty":2,"prompt":"Como o irmão se sentiu no final?","options":["Continuou com medo","Adorou","Ficou doente","Não entrou na água"],"answer":1,"explanation":"“but then he loved it”."},{"difficulty":3,"prompt":"Por que visitaram um museu no último dia?","options":["Porque estava chovendo","Porque o hotel fechou","Porque o irmão pediu","Porque era de graça"],"answer":0,"explanation":"“it rained, so we visited a museum”."}]},"writing":{"prompt":"Conte o seu último fim de semana em pelo menos 5 frases no simple past (use 2 verbos irregulares).","criteria":["Marcadores de tempo (on Saturday, last…)","2 irregulares","1 negativa com didn't"],"model":"Last Saturday I woke up late. I went to the park with my cousin and we played basketball. We didn't go to the mall. In the evening I watched a movie.","keywords":["went","didn't","last","ed"],"minWords":25},"challenge":"Faça 3 perguntas com Did… para alguém da sua casa sobre o dia de ontem e anote as respostas em inglês."},"games":{"blanks":[{"difficulty":1,"sentence":"We ___ a pizza last night.","options":["ate","eat","eated","eats"],"answer":0,"explanation":"Eat → ate."},{"difficulty":1,"sentence":"She ___ happy yesterday.","options":["was","were","did","is"],"answer":0,"explanation":"She → was."},{"difficulty":2,"sentence":"I ___ finish my homework.","options":["didn't","don't","wasn't","not"],"answer":0,"explanation":"Passado negativo: didn't."},{"difficulty":2,"sentence":"What ___ you do on Sunday?","options":["did","do","were","was"],"answer":0,"explanation":"Pergunta no passado: did."},{"difficulty":3,"sentence":"They moved to Brazil five years ___.","options":["ago","last","before of","yesterday"],"answer":0,"explanation":"Tempo + ago = há… (atrás)."}],"pairs":[{"a":"go","b":"went","difficulty":1},{"a":"take","b":"took","difficulty":2},{"a":"write","b":"wrote","difficulty":2},{"a":"come","b":"came","difficulty":1},{"a":"make","b":"made","difficulty":1},{"a":"say","b":"said","difficulty":2},{"a":"think","b":"thought","difficulty":3},{"a":"teach","b":"taught","difficulty":3}],"sequences":[{"difficulty":1,"prompt":"Organize a frase · Put the words in order","items":["I","visited","my","grandma","yesterday"],"words":true,"explanation":"Sujeito + verbo-ed + complemento + tempo."},{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["Did","you","see","the","game"],"words":true,"explanation":"Did + sujeito + verbo base."},{"difficulty":3,"prompt":"Organize a frase · Put the words in order","items":["She","didn't","buy","the","tickets"],"words":true,"explanation":"didn't + verbo base."}],"dialogues":[{"difficulty":2,"title":"Segunda-feira de manhã","gap":1,"options":["It was great! I went camping.","It is great! I go camping.","It were great! I goed camping.","It was great! I go camping."],"answer":0,"explanation":"Passado: was + went.","lines":[{"who":"Kim","text":"How was your weekend?"},{"who":"Rui","text":"It was great! I went camping."},{"who":"Kim","text":"Cool! Did you see any animals?"},{"who":"Rui","text":"Yes, I saw a fox!"}]}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-a2-past-continuous","subject":"ingles","title":"Past continuous","levels":["fund2","medio"],"grade":"8º e 9º ano","topic":"Inglês A2 — Agora e antes","subtopic":"Past continuous, when e while","aliases":["past continuous","passado continuo","was were ing","when while","estava fazendo em ingles","past progressive"],"summary":"Descreva o que estava acontecendo no passado e interrompa a cena com when e while.","intro":"I was sleeping when the phone rang… Vamos montar cenas do passado.","objective":"Formar o past continuous, usá-lo para cenas e ações em andamento no passado e combiná-lo com o simple past usando when e while.","prerequisites":["ing-a2-simple-past","ing-a2-present-continuous"],"next":["ing-a2-future"],"skills":{"g_form":"Was/were + -ing","g_when":"Ação longa interrompida (when)","g_while":"Ações simultâneas (while)","g_negq":"Negativa e pergunta"},"blocks":[{"skill":"g_form","title":"was / were + verb-ing","text":"O past continuous mostra algo que estava em andamento num momento do passado: was/were + verbo-ing. At 8 pm yesterday I was having dinner. Serve para descrever o cenário de uma história.","example":"At 10 o'clock we were playing chess. · It was raining all morning.","variants":{"simples":"É o nosso “estava fazendo”: I was reading = eu estava lendo.","exemplo":"Começo de conto: “The sun was shining and the birds were singing.”","passos":"1. Sujeito. 2. Was (I/he/she/it) ou were (you/we/they). 3. Verbo + ing.","compara":"Present continuous (I am reading agora) → past continuous (I was reading ontem às 9h). Só o verb to be vai para o passado."},"id":"b1"},{"skill":"g_when","title":"Interrupted actions: when","text":"Uma ação longa (past continuous) pode ser interrompida por uma curta (simple past), geralmente com when: I was taking a shower when the lights went out. A ação curta é o “acontecimento”.","example":"She was walking home when she found a wallet.","variants":{"simples":"Estava fazendo algo (longa) QUANDO aconteceu outra coisa (curta).","exemplo":"Relato: “We were watching TV when the dog started barking.”","passos":"1. Qual ação durou mais? → past continuous. 2. Qual interrompeu? → simple past. 3. Ligue com when.","compara":"Imagine um filme: a cena de fundo (was raining) e o acontecimento que corta a cena (the phone rang)."},"id":"b2"},{"skill":"g_while","title":"Simultaneous actions: while","text":"Com while mostramos duas ações longas ao mesmo tempo, as duas no past continuous: While I was cooking, my sister was setting the table. While também aparece antes da ação longa: While I was studying, the phone rang.","example":"While Dad was driving, we were singing.","variants":{"simples":"While = enquanto. Duas coisas acontecendo juntas.","exemplo":"Na festa: “While some people were dancing, others were eating.”","passos":"1. While + ação longa. 2. Vírgula se a frase começar com while. 3. A outra ação: longa (were) ou curta (simple past).","compara":"When costuma vir com a ação curta; while, com a ação longa: I was sleeping when you called / While I was sleeping, you called."},"id":"b3"},{"skill":"g_negq","title":"Negative and questions","text":"Negativa: wasn't / weren't + -ing: I wasn't listening. Pergunta: Was/Were + sujeito + -ing? What were you doing at 9 pm? — I was studying.","example":"— Were you sleeping? — No, I wasn't. I was reading.","variants":{"simples":"Negativa: wasn't/weren't. Pergunta: Was/Were no começo.","exemplo":"Detetive: “What were you doing at eight o'clock last night?”","passos":"1. Negativa: was/were + not. 2. Pergunta: inverta. 3. Resposta: Yes, I was / No, they weren't.","compara":"Assim como no present continuous, não usamos did: “Were you working?” e não “Did you working?”."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"g_form","prompt":"At 9 pm yesterday, I ___ TV.","options":["watched","was watching","am watching","were watching"],"answer":1,"hints":["Ação em andamento num horário do passado.","I → was.","Was + -ing."],"explanation":"I was watching TV.","id":"q1"},{"type":"mc","difficulty":1,"skill":"g_form","prompt":"They ___ soccer when it started to rain.","options":["was playing","were playing","played","are playing"],"answer":1,"hints":["They → were.","Ação longa interrompida.","Were + -ing."],"explanation":"They were playing.","id":"q2"},{"type":"fill","difficulty":1,"skill":"g_negq","prompt":"Negativa: She ___ listening. (was not)","answers":["wasn't","was not"],"hints":["Contração de was not.","wasn…","wasn't."],"explanation":"She wasn't listening.","id":"q3"},{"type":"tf","difficulty":1,"skill":"g_when","prompt":"Em “I was cooking when the doorbell rang”, a ação curta é “the doorbell rang”.","answer":true,"hints":["Qual durou mais?","Cozinhar dura mais.","A campainha interrompe."],"explanation":"Verdadeiro.","id":"q4"},{"type":"match","difficulty":2,"skill":"g_form","prompt":"Ligue o sujeito à forma correta.","pairs":[["I","was reading"],["you","were reading"],["she","was sleeping"],["they","were sleeping"]],"hints":["I e she usam was.","You e they usam were.","Depois o -ing."],"explanation":"I was · you were · she was · they were.","id":"q5"},{"type":"mc","difficulty":2,"skill":"g_when","prompt":"I ___ a shower when the lights ___ out.","options":["was taking / went","took / were going","was taking / was going","take / went"],"answer":0,"hints":["Banho = ação longa.","A luz apagou = ação curta.","Past continuous + simple past."],"explanation":"was taking / went.","id":"q6"},{"type":"mc","difficulty":2,"skill":"g_while","prompt":"___ I was studying, my brother was playing video games.","options":["When","While","During","Because"],"answer":1,"hints":["Duas ações longas juntas.","Enquanto = …","While."],"explanation":"While = enquanto.","id":"q7"},{"type":"mc","difficulty":2,"skill":"g_negq","prompt":"— What ___ you doing at 7? — I was having dinner.","options":["were","did","was","are"],"answer":0,"hints":["Pergunta no past continuous.","You → were.","Were."],"explanation":"What were you doing?","id":"q8"},{"type":"order","difficulty":3,"skill":"g_when","prompt":"Organize: “Ela estava andando quando viu um gato.”","items":["She","was","walking","when","she","saw","a","cat"],"hints":["Comece pela ação longa.","Depois when.","Ação curta no simple past."],"explanation":"She was walking when she saw a cat.","id":"q9"},{"type":"mc","difficulty":3,"skill":"g_while","prompt":"Qual frase está correta?","options":["While I slept, the phone was ringing all night.","When I was sleeping, the phone rang.","While I was sleeping, the phone rang.","While I sleeping, the phone rang."],"answer":2,"hints":["While vem com a ação longa.","Ação longa no past continuous.","Ação curta no simple past."],"explanation":"While I was sleeping, the phone rang.","id":"q10"}],"review":["was/were + -ing = estava fazendo","Longa (past continuous) + when + curta (simple past)","While + duas ações longas","wasn't/weren't · Were you…?"],"relatedQuestions":["como usar o past continuous","diferença entre when e while","diferença entre simple past e past continuous"],"equivalentQuestions":["como dizer eu estava fazendo em inglês","quando usar was e were com ing","when ou while","diferença entre past continuous e simple past","como contar uma história no passado em inglês","what were you doing","o que é past continuous","como usar past continuous","me explica past continuous","quando usar past continuous","exemplos de past continuous","past continuous em inglês","como funciona past continuous","regras de past continuous","exercícios de past continuous","aula de past continuous","não entendi past continuous","past continuous para iniciantes","resumo de past continuous","dúvida sobre past continuous","o que é passado contínuo","como usar passado contínuo","me explica passado contínuo","quando usar passado contínuo","exemplos de passado contínuo","passado contínuo em inglês","como funciona passado contínuo","regras de passado contínuo","exercícios de passado contínuo","aula de passado contínuo","não entendi passado contínuo","passado contínuo para iniciantes","resumo de passado contínuo","dúvida sobre passado contínuo"],"commonErrors":["Usar was com you/we/they.","Colocar as duas ações no past continuous quando uma interrompe a outra.","Usar did nas perguntas (Did you sleeping?)."],"english":{"cefr":"A2","unit":"a2-u2","order":2,"area":"grammar","focus":["grammar","reading","writing"],"vocabulary":[{"word":"while","translation":"enquanto","pos":"conjunction","definition":"during the time that","example":"While I was cooking, he called.","difficulty":2},{"word":"when","translation":"quando","pos":"conjunction","definition":"at the time that","example":"I was reading when you arrived.","difficulty":1},{"word":"suddenly","translation":"de repente","pos":"adverb","definition":"quickly and unexpectedly","example":"Suddenly, the lights went out.","difficulty":2},{"word":"shine","translation":"brilhar","pos":"verb","definition":"to give light (the sun)","example":"The sun was shining.","difficulty":2},{"word":"ring","translation":"tocar (telefone, campainha)","pos":"verb","definition":"to make a bell sound","example":"The phone rang twice.","difficulty":2},{"word":"noise","translation":"barulho","pos":"noun","definition":"a loud or strange sound","example":"I heard a noise.","difficulty":1},{"word":"storm","translation":"tempestade","pos":"noun","definition":"very bad weather with wind and rain","example":"There was a big storm.","difficulty":2}],"reading":{"title":"The night of the storm","genre":"conto curto","text":"It was a dark night. Rain was falling and the wind was blowing hard. Mila was reading in bed while her parents were watching a movie downstairs. Suddenly, she heard a strange noise at the window. She was feeling scared when a small wet cat jumped onto her bed. The family adopted it the next day and called it Storm.","questions":[{"difficulty":1,"prompt":"O que Mila estava fazendo?","options":["Assistindo a um filme","Lendo na cama","Dormindo","Cozinhando"],"answer":1,"explanation":"“Mila was reading in bed”."},{"difficulty":2,"prompt":"O que os pais estavam fazendo ao mesmo tempo?","options":["Lendo","Assistindo a um filme","Conversando","Dormindo"],"answer":1,"explanation":"“while her parents were watching a movie”."},{"difficulty":2,"prompt":"O que interrompeu a leitura?","options":["Uma ligação","Um barulho na janela","A luz apagou","A mãe chamou"],"answer":1,"explanation":"“she heard a strange noise at the window”."},{"difficulty":3,"prompt":"Por que o gato recebeu o nome Storm?","options":["Porque era bravo","Porque apareceu numa noite de tempestade","Porque era cinza","Porque era da vizinha"],"answer":1,"explanation":"Ele apareceu durante a tempestade (storm)."}]},"writing":{"prompt":"Escreva o início de uma história: descreva a cena (past continuous) e um acontecimento que interrompe (when + simple past).","criteria":["Cenário com was/were + -ing","Uma interrupção com when","Uma frase com while"],"model":"It was a sunny afternoon. The kids were playing in the park while their parents were talking. Suddenly, a big dog appeared when a boy was eating an ice cream.","keywords":["was","were","when","while"],"minWords":25},"challenge":"Diga o que você estava fazendo ontem às 8h, às 15h e às 21h."},"games":{"blanks":[{"difficulty":1,"sentence":"We ___ dinner at 8 pm.","options":["were having","was having","had having","are having"],"answer":0,"explanation":"We → were + -ing."},{"difficulty":2,"sentence":"She was reading ___ the phone rang.","options":["when","while","during","so"],"answer":0,"explanation":"Interrupção curta: when."},{"difficulty":2,"sentence":"___ I was walking, I listened to music.","options":["While","When","Then","After"],"answer":0,"explanation":"While + ação longa."},{"difficulty":3,"sentence":"I ___ attention, so I didn't hear the question.","options":["wasn't paying","didn't paying","weren't paying","not paid"],"answer":0,"explanation":"Negativa: wasn't + -ing."}],"sequences":[{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["It","was","raining","when","I","left","home"],"words":true,"explanation":"Ação longa + when + ação curta."},{"difficulty":3,"prompt":"Organize a frase · Put the words in order","items":["What","were","you","doing","last","night"],"words":true,"explanation":"Pergunta: What + were + you + -ing."}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-a2-future","subject":"ingles","title":"Future: will and going to","levels":["fund2","medio"],"grade":"8º e 9º ano","topic":"Inglês A2 — Planos e comparações","subtopic":"Will, going to e present continuous para o futuro","aliases":["future","futuro em ingles","will","going to","will ou going to","planos em ingles","previsoes em ingles","future forms"],"summary":"Fale de planos, decisões, previsões e compromissos escolhendo entre will, going to e o present continuous.","intro":"What are you going to do tomorrow? Vamos falar do futuro.","objective":"Escolher entre will (decisão na hora, promessa, previsão por opinião), going to (plano, previsão com evidência) e present continuous (compromisso marcado).","prerequisites":["ing-a2-present-continuous"],"next":["ing-a2-comparatives"],"skills":{"g_will":"Will: decisões, promessas e previsões","g_going":"Going to: planos e evidências","g_arr":"Present continuous para compromissos","g_choose":"Escolher a forma certa"},"blocks":[{"skill":"g_will","title":"Will","text":"Will + verbo base (I'll, she'll): decisões na hora (I'll have the chicken), promessas e ofertas (I'll help you), previsões baseadas em opinião (I think it will be fun). Negativa: won't (will not). Pergunta: Will you come?","example":"The phone is ringing. — I'll get it! · I won't tell anyone, I promise.","variants":{"simples":"Will = vou (decidido agora) / vai (acho que vai).","exemplo":"Garçom pergunta, você decide na hora: “I'll have orange juice, please.”","passos":"1. Decidiu agora ou prometeu? will. 2. É uma opinião sobre o futuro (I think…)? will. 3. Verbo sem to depois de will.","compara":"Won't parece “want”, mas é a negativa de will: I won't go = eu não vou."},"id":"b1"},{"skill":"g_going","title":"Going to","text":"Am/is/are + going to + verbo: planos e intenções já decididos antes (I'm going to study medicine) e previsões com evidência no presente (Look at those clouds! It's going to rain).","example":"We're going to visit Salvador in July. · Careful! You're going to fall!","variants":{"simples":"Going to = vou (já planejei) / vai (dá para ver que vai acontecer).","exemplo":"Metas do ano: “I'm going to read ten books this year.”","passos":"1. Já tinha decidido? going to. 2. Há uma prova agora (nuvens, alguém tropeçando)? going to. 3. Estrutura: am/is/are + going to + verbo.","compara":"Will = opinião (I think it will rain). Going to = evidência (Look at the sky! It's going to rain)."},"id":"b2"},{"skill":"g_arr","title":"Present continuous for arrangements","text":"Para compromissos marcados, com hora e lugar, usamos o present continuous com sentido de futuro: I'm meeting Ana at 5. We're flying to Lisbon on Friday.","example":"What are you doing tonight? — I'm going to the cinema with Leo.","variants":{"simples":"Compromisso marcado na agenda → I'm + -ing.","exemplo":"Consulta marcada: “I'm seeing the dentist tomorrow at 10.”","passos":"1. Está marcado com alguém, com dia/hora? 2. Use am/is/are + -ing. 3. Inclua a expressão de tempo (tomorrow, on Friday).","compara":"Em português também fazemos isso: “Amanhã eu viajo” (presente com sentido de futuro)."},"id":"b3"},{"skill":"g_choose","title":"Which future?","text":"Resumo: decisão agora, promessa, oferta → will. Plano/intenção → going to. Evidência → going to. Compromisso marcado → present continuous. Horários fixos (trem, filme) → simple present: The train leaves at 7.","example":"The movie starts at 8. We're meeting at 7:30. I think we'll love it!","variants":{"simples":"Pergunte: decidi agora? planejei antes? tenho prova? está marcado?","exemplo":"Planejando o sábado: “I'm going to relax. Maybe I'll watch a series.”","passos":"1. Identifique a situação. 2. Escolha a forma. 3. Confira a estrutura.","compara":"Em muitas conversas, will e going to aparecem juntos: o plano (going to) e a decisão na hora (will)."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"g_will","prompt":"The phone is ringing. — I ___ answer it!","options":["'ll","'m going to","'m answering","answer"],"answer":0,"hints":["Decisão tomada agora.","Ninguém planejou isso antes.","Will."],"explanation":"Decisão na hora: I'll answer it.","id":"q1"},{"type":"mc","difficulty":1,"skill":"g_going","prompt":"Look at those black clouds! It ___ rain.","options":["will","is going to","rains","is raining"],"answer":1,"hints":["Há uma evidência?","As nuvens são a prova.","Evidência → going to."],"explanation":"Evidência: It's going to rain.","id":"q2"},{"type":"fill","difficulty":1,"skill":"g_will","prompt":"Negativa de will: I ___ tell anyone.","answers":["won't","will not"],"hints":["Contração de will not.","Parece “want”, mas não é.","w-o-n-'-t."],"explanation":"I won't tell anyone.","id":"q3"},{"type":"tf","difficulty":1,"skill":"g_going","prompt":"“We are going to visit Rio next month” fala de um plano.","answer":true,"hints":["Going to = plano.","Next month = futuro.","Eles já decidiram."],"explanation":"Verdadeiro.","id":"q4"},{"type":"match","difficulty":2,"skill":"g_choose","prompt":"Ligue a situação à forma de futuro.","pairs":[["Decisão na hora","will"],["Plano já decidido","going to"],["Compromisso marcado","present continuous"],["Horário fixo (trem)","simple present"]],"hints":["Resumo do bloco final.","Agenda com hora → -ing.","Tabela de horário → presente simples."],"explanation":"decisão will · plano going to · compromisso present continuous · horário simple present.","id":"q5"},{"type":"mc","difficulty":2,"skill":"g_arr","prompt":"Já está marcado: “I ___ the dentist tomorrow at 10.”","options":["will see","see","am seeing","saw"],"answer":2,"hints":["Compromisso com hora.","Está na agenda.","Present continuous."],"explanation":"I'm seeing the dentist tomorrow.","id":"q6"},{"type":"mc","difficulty":2,"skill":"g_will","prompt":"Qual é uma previsão baseada em opinião?","options":["I think Brazil will win.","Look! He's going to fall.","I'm meeting Ana at 5.","The train leaves at 7."],"answer":0,"hints":["Procure “I think”.","Opinião, sem evidência.","Will."],"explanation":"I think Brazil will win.","id":"q7"},{"type":"mc","difficulty":2,"skill":"g_going","prompt":"Qual frase está correta?","options":["She is going to studies medicine.","She going to study medicine.","She is going to study medicine.","She will going to study medicine."],"answer":2,"hints":["Precisa do verb to be.","Going to + verbo base.","Sem will junto."],"explanation":"She is going to study medicine.","id":"q8"},{"type":"order","difficulty":3,"skill":"g_arr","prompt":"Organize: “O que você vai fazer hoje à noite?”","items":["What","are","you","doing","tonight?"],"hints":["Pergunta sobre compromissos.","Present continuous.","Tonight no final."],"explanation":"What are you doing tonight?","id":"q9"},{"type":"mc","difficulty":3,"skill":"g_choose","prompt":"A: “We don't have any milk.” B: “Oh, really? I ___ buy some.”","options":["'ll","'m going to","buy","'m buying"],"answer":0,"hints":["B acabou de saber.","Decisão na hora.","Will."],"explanation":"Soube agora e decidiu: I'll buy some.","id":"q10"}],"review":["Will: decisão agora, promessa, oferta, opinião (I think…)","Going to: plano ou evidência (Look! It's going to…)","Present continuous: compromisso marcado","Horário fixo: simple present"],"relatedQuestions":["diferença entre will e going to","como falar do futuro em inglês","quando usar present continuous para o futuro"],"equivalentQuestions":["quando usar will","quando usar going to","will ou going to para previsão","o que significa won't","como falar de planos em inglês","como dizer eu vou viajar em inglês","present continuous com sentido de futuro","o que é futuro em inglês","como usar futuro em inglês","me explica futuro em inglês","quando usar futuro em inglês","exemplos de futuro em inglês","futuro em inglês em inglês","como funciona futuro em inglês","regras de futuro em inglês","exercícios de futuro em inglês","aula de futuro em inglês","não entendi futuro em inglês","futuro em inglês para iniciantes","resumo de futuro em inglês","dúvida sobre futuro em inglês","o que é will e going to","como usar will e going to","me explica will e going to","quando usar will e going to","exemplos de will e going to","will e going to em inglês","como funciona will e going to","regras de will e going to","exercícios de will e going to","aula de will e going to","não entendi will e going to","will e going to para iniciantes","resumo de will e going to","dúvida sobre will e going to"],"commonErrors":["Juntar will e going to (will going to).","Esquecer o verb to be em going to (She going to…).","Usar will para planos já decididos."],"english":{"cefr":"A2","unit":"a2-u3","order":1,"area":"grammar","focus":["grammar","listening","speaking"],"vocabulary":[{"word":"plan","translation":"plano / planejar","pos":"noun","definition":"something you decided to do","example":"What are your plans for the weekend?","difficulty":1},{"word":"tomorrow","translation":"amanhã","pos":"adverb","definition":"the day after today","example":"See you tomorrow!","difficulty":1},{"word":"next","translation":"próximo(a)","pos":"determiner","definition":"the one after this one","example":"Next year I'm going to learn Spanish.","difficulty":1},{"word":"promise","translation":"prometer","pos":"verb","definition":"to say you will certainly do something","example":"I promise I'll call you.","difficulty":2},{"word":"probably","translation":"provavelmente","pos":"adverb","definition":"very likely","example":"It will probably be hot.","difficulty":2},{"word":"maybe","translation":"talvez","pos":"adverb","definition":"perhaps","example":"Maybe I'll go to the party.","difficulty":1},{"word":"tonight","translation":"hoje à noite","pos":"adverb","definition":"this evening or night","example":"What are you doing tonight?","difficulty":1}],"grammar":{"name":"Future forms","when":"Decisões, planos, previsões e compromissos.","structure":"will + base · am/is/are going to + base · am/is/are + -ing","affirmative":["I'll help you.","We're going to travel.","I'm meeting Ana at 5."],"negative":["I won't forget.","She isn't going to come."],"interrogative":["Will you help me?","Are you going to study?","What are you doing tomorrow?"],"compare":"I think it will rain (opinião) × Look! It's going to rain (evidência).","context":"Combinar o fim de semana com os amigos."},"listening":{"title":"Planos para as férias","kind":"dialogo","rate":0.9,"script":["Sam: What are you going to do in the holidays?","Lia: I'm going to visit my cousins in Recife.","Sam: Nice! When are you leaving?","Lia: I'm flying on Saturday morning.","Sam: I think you'll love the beaches there.","Lia: I'm sure I will! I'll send you photos."],"questions":[{"difficulty":1,"prompt":"Quem Lia vai visitar?","options":["Os avós","Os primos","Os tios","Uma amiga"],"answer":1,"explanation":"“visit my cousins”."},{"difficulty":2,"prompt":"Quando ela viaja?","options":["Sábado de manhã","Domingo à noite","Sexta à tarde","Não diz"],"answer":0,"explanation":"“I'm flying on Saturday morning.”"},{"difficulty":3,"prompt":"O que ela promete?","options":["Trazer um presente","Mandar fotos","Ligar todo dia","Voltar cedo"],"answer":1,"explanation":"“I'll send you photos.” (promessa com will)"}]},"speaking":{"situation":"Um colega pergunta sobre os seus planos para o próximo fim de semana.","vocabulary":["going to","I'll","maybe","tonight"],"phrases":["I'm going to…","Maybe I'll…","On Saturday I'm meeting…"],"example":"On Saturday I'm going to play soccer. Maybe I'll watch a movie at night.","challenge":"Fale um plano (going to), uma possibilidade (maybe I'll) e um compromisso marcado (I'm + -ing).","expected":["going","maybe","will"]},"challenge":"Escreva 3 metas para o próximo mês com going to e 1 promessa com will."},"games":{"blanks":[{"difficulty":1,"sentence":"I'm tired. I think I ___ go to bed.","options":["will","am going","going","goes"],"answer":0,"explanation":"Decisão agora: will."},{"difficulty":1,"sentence":"We ___ going to travel in July.","options":["are","will","is","do"],"answer":0,"explanation":"We are going to…"},{"difficulty":2,"sentence":"Careful! That glass ___ fall!","options":["is going to","will to","falls","going"],"answer":0,"explanation":"Evidência: is going to."},{"difficulty":2,"sentence":"I ___ tell your secret. I promise!","options":["won't","don't","am not","not will"],"answer":0,"explanation":"Promessa negativa: won't."},{"difficulty":3,"sentence":"The bus ___ at 6:15 every morning.","options":["leaves","will leave","is going to leave","leaving"],"answer":0,"explanation":"Horário fixo: simple present."}],"sequences":[{"difficulty":1,"prompt":"Organize a frase · Put the words in order","items":["I","will","help","you"],"words":true,"explanation":"Oferta: will + verbo."},{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["She","is","going","to","buy","a","bike"],"words":true,"explanation":"Plano: is going to + verbo."}],"dialogues":[{"difficulty":2,"title":"No restaurante","gap":1,"options":["Yes. I'll have the fish, please.","Yes. I'm going to have fish every day.","Yes. I had the fish.","Yes. I have fish tomorrow."],"answer":0,"explanation":"Decisão na hora: I'll have…","lines":[{"who":"Waiter","text":"Are you ready to order?"},{"who":"Leo","text":"Yes. I'll have the fish, please."},{"who":"Waiter","text":"Great choice!"}]},{"difficulty":3,"title":"Combinando","gap":1,"options":["I'm meeting my cousin at the mall.","I meet my cousin yesterday.","I'll met my cousin.","I going to meet cousin."],"answer":0,"explanation":"Compromisso marcado: present continuous.","lines":[{"who":"Bia","text":"What are you doing on Friday?"},{"who":"Rafa","text":"I'm meeting my cousin at the mall."},{"who":"Bia","text":"Oh! Maybe I'll go too."}]}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-a2-comparatives","subject":"ingles","title":"Comparatives and superlatives","levels":["fund2","medio"],"grade":"7º ao 9º ano","topic":"Inglês A2 — Planos e comparações","subtopic":"Comparativos e superlativos","aliases":["comparativo em ingles","superlativo em ingles","comparatives","superlatives","er than","the most","better best","as as"],"summary":"Compare pessoas, lugares e coisas com -er/more, the -est/the most, os irregulares e as…as.","intro":"Which is bigger: Brazil or Argentina? Vamos comparar!","objective":"Formar comparativos e superlativos de adjetivos curtos, longos e irregulares e fazer comparações de igualdade com as…as.","prerequisites":["ing-a1-this-that"],"next":["ing-a2-quantifiers"],"skills":{"g_comp":"Comparativo (-er than / more … than)","g_sup":"Superlativo (the -est / the most)","g_irr":"Irregulares (good, bad, far)","g_as":"Igualdade (as … as)"},"blocks":[{"skill":"g_comp","title":"Comparatives","text":"Adjetivos curtos (1 sílaba) ganham -er + than: tall → taller than. Terminados em -y: -ier (happy → happier). Consoante-vogal-consoante dobra: big → bigger. Adjetivos longos (2+ sílabas, na maioria): more + adjetivo + than: more expensive than.","example":"My brother is taller than me. · This phone is more expensive than that one.","variants":{"simples":"Mais alto que = taller than. Mais caro que = more expensive than.","exemplo":"Comparando cidades: “São Paulo is bigger than Curitiba.”","passos":"1. Conte as sílabas. 2. Curto: -er; longo: more. 3. Termine com than.","compara":"Em português sempre usamos “mais”: mais alto, mais caro. Em inglês, adjetivo curto ganha -er e não usa more: “more tall” está errado."},"id":"b1"},{"skill":"g_sup","title":"Superlatives","text":"O superlativo mostra o “mais” de um grupo: the + adjetivo curto + -est (the tallest), -iest (the happiest), the most + adjetivo longo (the most beautiful). Geralmente vem com in/of: the tallest in the class.","example":"Mount Everest is the highest mountain in the world. · It's the most interesting book I've read.","variants":{"simples":"O mais alto = the tallest. O mais bonito = the most beautiful.","exemplo":"Ranking: “The Amazon is the largest rainforest in the world.”","passos":"1. Use the. 2. Curto: -est; longo: most. 3. Complete com in/of + grupo.","compara":"Comparativo compara DOIS (taller than); superlativo destaca UM de um grupo (the tallest in the class)."},"id":"b2"},{"skill":"g_irr","title":"Irregular forms","text":"Alguns são irregulares: good → better → the best; bad → worse → the worst; far → farther/further → the farthest/furthest; many/much → more → the most; little → less → the least.","example":"Today is better than yesterday. · This is the worst movie ever!","variants":{"simples":"Bom → melhor → o melhor = good → better → the best.","exemplo":"Avaliação de restaurante: “The food was good, but the dessert was the best!”","passos":"1. Decore os 4 principais: good, bad, far, many. 2. Treine em frases. 3. Nunca diga “gooder”.","compara":"Igual ao português: “bom” não vira “mais bom”, vira “melhor”. Em inglês, good vira better."},"id":"b3"},{"skill":"g_as","title":"As … as","text":"Para igualdade: as + adjetivo + as (tão … quanto): She is as tall as her mother. Negativa: not as … as (não tão … quanto): This test isn't as difficult as the last one.","example":"My dog is as friendly as yours. · Winter here isn't as cold as in Canada.","variants":{"simples":"As tall as = tão alto quanto.","exemplo":"Comparando notas: “My grade isn't as good as I wanted.”","passos":"1. As. 2. Adjetivo na forma normal. 3. As + o que é comparado.","compara":"“Not as big as” e “smaller than” dizem quase a mesma coisa — a primeira forma soa mais delicada."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"g_comp","prompt":"An elephant is ___ than a dog.","options":["big","bigger","more big","biggest"],"answer":1,"hints":["Comparando dois.","Big é curto.","Dobra o g + er."],"explanation":"Bigger than.","id":"q1"},{"type":"mc","difficulty":1,"skill":"g_irr","prompt":"Qual é o comparativo de “good”?","options":["gooder","more good","better","best"],"answer":2,"hints":["É irregular.","Não é best (superlativo).","Better."],"explanation":"Good → better.","id":"q2"},{"type":"fill","difficulty":1,"skill":"g_comp","prompt":"Complete: My sister is ______ (happy) than me.","answers":["happier"],"hints":["Termina em -y.","Y vira i.","happi + er."],"explanation":"Happy → happier.","id":"q3"},{"type":"tf","difficulty":1,"skill":"g_sup","prompt":"“The most tall student” está correto.","answer":false,"hints":["Tall é curto ou longo?","Curto usa -est.","The tallest."],"explanation":"Falso: the tallest student.","id":"q4"},{"type":"match","difficulty":2,"skill":"g_irr","prompt":"Ligue o adjetivo ao seu superlativo.","pairs":[["good","the best"],["bad","the worst"],["far","the farthest"],["beautiful","the most beautiful"]],"hints":["Good → best.","Bad → worst.","Beautiful é longo."],"explanation":"the best · the worst · the farthest · the most beautiful.","id":"q5"},{"type":"mc","difficulty":2,"skill":"g_comp","prompt":"This book is ___ than the movie.","options":["interestinger","more interesting","most interesting","as interesting"],"answer":1,"hints":["Interesting é longo.","More + adjetivo.","Than no final."],"explanation":"More interesting than.","id":"q6"},{"type":"mc","difficulty":2,"skill":"g_sup","prompt":"Brazil is ___ country in South America.","options":["the biggest","bigger","the most big","biggest than"],"answer":0,"hints":["Um de um grupo.","Superlativo.","The + big + g + est."],"explanation":"The biggest country.","id":"q7"},{"type":"mc","difficulty":2,"skill":"g_as","prompt":"Tom tem 1,70 m e Leo também. Tom is ___ Leo.","options":["taller than","as tall as","the tallest","not as tall as"],"answer":1,"hints":["Têm a mesma altura.","Igualdade.","As … as."],"explanation":"As tall as.","id":"q8"},{"type":"order","difficulty":3,"skill":"g_sup","prompt":"Organize: “É o pior dia da minha vida!”","items":["It's","the","worst","day","of","my","life!"],"hints":["Superlativo de bad.","The worst.","Of my life no final."],"explanation":"It's the worst day of my life!","id":"q9"},{"type":"mc","difficulty":3,"skill":"g_as","prompt":"Qual frase tem o mesmo sentido de “My city is smaller than yours”?","options":["My city is as big as yours.","My city isn't as big as yours.","My city is the biggest.","My city is bigger than yours."],"answer":1,"hints":["Se é menor, não é tão grande.","Negativa de as…as.","Not as big as."],"explanation":"Isn't as big as = é menor.","id":"q10"}],"review":["Curto: -er than / the -est · longo: more … than / the most","happy → happier; big → bigger","good-better-best · bad-worse-worst · far-farther-farthest","as … as (igual) · not as … as"],"relatedQuestions":["como fazer comparativo em inglês","diferença entre comparativo e superlativo","better ou best"],"equivalentQuestions":["quando usar more e quando usar er","comparativo de good","superlativo de bad","como dizer mais alto que em inglês","como dizer o maior do mundo em inglês","o que significa as tall as","por que bigger tem dois g","o que é comparativo em inglês","como usar comparativo em inglês","me explica comparativo em inglês","quando usar comparativo em inglês","exemplos de comparativo em inglês","comparativo em inglês em inglês","como funciona comparativo em inglês","regras de comparativo em inglês","exercícios de comparativo em inglês","aula de comparativo em inglês","não entendi comparativo em inglês","comparativo em inglês para iniciantes","resumo de comparativo em inglês","dúvida sobre comparativo em inglês","o que é superlativo em inglês","como usar superlativo em inglês","me explica superlativo em inglês","quando usar superlativo em inglês","exemplos de superlativo em inglês","superlativo em inglês em inglês","como funciona superlativo em inglês","regras de superlativo em inglês","exercícios de superlativo em inglês","aula de superlativo em inglês","não entendi superlativo em inglês","superlativo em inglês para iniciantes","resumo de superlativo em inglês","dúvida sobre superlativo em inglês"],"commonErrors":["Usar more com adjetivo curto (more tall).","Esquecer o the no superlativo.","Dizer gooder/baddest."],"english":{"cefr":"A2","unit":"a2-u4","order":1,"area":"grammar","focus":["grammar","reading","vocabulary"],"vocabulary":[{"word":"tall","translation":"alto(a) (pessoa)","pos":"adjective","definition":"having a big height","example":"My dad is tall.","difficulty":1,"antonyms":["short"]},{"word":"expensive","translation":"caro(a)","pos":"adjective","definition":"costing a lot of money","example":"This bag is expensive.","difficulty":1,"antonyms":["cheap"]},{"word":"cheap","translation":"barato(a)","pos":"adjective","definition":"not costing much money","example":"The bus is cheaper than the taxi.","difficulty":1,"antonyms":["expensive"]},{"word":"fast","translation":"rápido(a)","pos":"adjective","definition":"moving quickly","example":"Cheetahs are the fastest animals.","difficulty":1,"antonyms":["slow"]},{"word":"dangerous","translation":"perigoso(a)","pos":"adjective","definition":"able to hurt you","example":"Sharks can be dangerous.","difficulty":2},{"word":"large","translation":"grande","pos":"adjective","definition":"big","example":"The Amazon is the largest rainforest.","difficulty":2,"synonyms":["big"]},{"word":"worse","translation":"pior","pos":"adjective","definition":"comparative of bad","example":"The traffic is worse today.","difficulty":2},{"word":"best","translation":"o(a) melhor","pos":"adjective","definition":"superlative of good","example":"She's my best friend.","difficulty":1}],"reading":{"title":"Record breakers","genre":"texto informativo","text":"The cheetah is the fastest land animal: it can run at about 100 km per hour. The blue whale is the largest animal that has ever lived — it is bigger than any dinosaur we know. The Amazon River carries more water than any other river in the world, and the Sahara is the largest hot desert on Earth.","questions":[{"difficulty":1,"prompt":"Qual é o animal terrestre mais rápido?","options":["Leão","Guepardo (cheetah)","Cavalo","Baleia"],"answer":1,"explanation":"“The cheetah is the fastest land animal”."},{"difficulty":2,"prompt":"O que o texto diz sobre a baleia-azul?","options":["É menor que alguns dinossauros","É o maior animal que já existiu","É o mais rápido do mar","Vive no Rio Amazonas"],"answer":1,"explanation":"“the largest animal that has ever lived”."},{"difficulty":3,"prompt":"Qual recorde do Rio Amazonas aparece no texto?","options":["É o mais longo","Leva mais água que qualquer outro rio","É o mais frio","É o mais antigo"],"answer":1,"explanation":"“carries more water than any other river”."}]},"writing":{"prompt":"Compare duas cidades, dois animais ou dois times usando comparativo, superlativo e as…as.","criteria":["1 comparativo com than","1 superlativo com the","1 frase com as…as"],"model":"Salvador is hotter than Porto Alegre. Porto Alegre is bigger than Florianópolis, but it isn't as beautiful. For me, Salvador has the best food in Brazil.","keywords":["than","the","as"],"minWords":20},"challenge":"Faça um ranking dos 3 melhores filmes ou jogos que você conhece usando the best, better than e the most."},"games":{"blanks":[{"difficulty":1,"sentence":"A car is ___ than a bike.","options":["faster","fast","more fast","fastest"],"answer":0,"explanation":"Fast (curto) → faster."},{"difficulty":1,"sentence":"She's ___ student in the class.","options":["the best","better","the good","best than"],"answer":0,"explanation":"Superlativo de good: the best."},{"difficulty":2,"sentence":"Gold is ___ than silver.","options":["more expensive","expensiver","most expensive","as expensive"],"answer":0,"explanation":"Expensive (longo) → more expensive."},{"difficulty":2,"sentence":"My room isn't ___ big ___ yours.","options":["as / as","more / than","so / that","the / of"],"answer":0,"explanation":"Not as … as."},{"difficulty":3,"sentence":"Today's traffic is ___ than yesterday's.","options":["worse","badder","worst","more bad"],"answer":0,"explanation":"Bad → worse."}],"pairs":[{"a":"big","b":"bigger","difficulty":1},{"a":"happy","b":"happier","difficulty":2},{"a":"good","b":"better","difficulty":1},{"a":"bad","b":"worse","difficulty":2},{"a":"far","b":"farther","difficulty":3}],"sequences":[{"difficulty":1,"prompt":"Organize a frase · Put the words in order","items":["My","brother","is","taller","than","me"],"words":true,"explanation":"Adjetivo curto + er + than."},{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["It","is","the","most","beautiful","beach"],"words":true,"explanation":"The most + adjetivo longo."}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-b1-present-perfect","subject":"ingles","title":"Present perfect","levels":["fund2","medio"],"grade":"9º ano e Ensino Médio","topic":"Inglês B1 — Experiências e hipóteses","subtopic":"Present perfect: experiências, for/since, já/ainda","aliases":["present perfect","presente perfeito","have has particípio","for since","ever never","already yet just","present perfect ou simple past","have you ever"],"summary":"Fale de experiências de vida, de situações que continuam até hoje e de coisas que acabaram de acontecer.","intro":"Have you ever eaten sushi? O present perfect liga o passado ao presente.","objective":"Formar o present perfect com have/has + particípio, usar ever/never, for/since e already/yet/just, e escolher entre ele e o simple past.","prerequisites":["ing-a2-simple-past"],"next":["ing-b1-present-perfect-continuous"],"skills":{"g_form":"Have/has + particípio","g_exp":"Experiências: ever / never","g_forsince":"For e since (até hoje)","g_vs":"Present perfect × simple past"},"blocks":[{"skill":"g_form","title":"have / has + past participle","text":"Estrutura: have (I, you, we, they) ou has (he, she, it) + particípio passado. Regulares: igual ao passado (worked, played). Irregulares: é a 3ª forma (go-went-gone, see-saw-seen, eat-ate-eaten, do-did-done, be-was-been, write-wrote-written). Negativa: haven't/hasn't. Pergunta: Have you…? Has she…?","example":"I've finished my homework. · She hasn't called yet. · Have they arrived?","variants":{"simples":"Have/has + particípio: I have seen = eu já vi / tenho visto.","exemplo":"Mensagem: “I've sent you the file. Have you received it?”","passos":"1. Sujeito. 2. Have ou has. 3. Particípio (3ª coluna da tabela de irregulares).","compara":"Não confunda o have auxiliar (I have eaten) com o have de “ter” (I have a dog). No present perfect, ele só ajuda a formar o tempo."},"id":"b1"},{"skill":"g_exp","title":"Experiences: ever and never","text":"O present perfect fala de experiências na vida, sem dizer quando: I've been to Argentina. Ever (alguma vez) aparece em perguntas: Have you ever eaten sushi? Never (nunca) na afirmativa: I've never seen snow. Been to = já esteve em (e voltou).","example":"— Have you ever been to Bahia? — Yes, I have. / No, I've never been there.","variants":{"simples":"Have you ever…? = Você já…? I've never… = Eu nunca…","exemplo":"Jogo de perguntas com amigos: “Have you ever broken a bone?”","passos":"1. Pergunta: Have you ever + particípio? 2. Resposta: Yes, I have / No, I haven't. 3. Detalhe no simple past: “Yes! I went there in 2022.”","compara":"Se você disser QUANDO (in 2022, last year), mude para o simple past: I went there in 2022. Sem data: I've been there."},"id":"b2"},{"skill":"g_forsince","title":"For and since","text":"Para algo que começou no passado e continua até agora: For + período (for three years, for a long time). Since + ponto de início (since 2020, since Monday, since I was a child). Pergunta: How long have you lived here?","example":"I've lived here for five years. · She's been my friend since 2019.","variants":{"simples":"For = há (quanto tempo). Since = desde (quando começou).","exemplo":"“How long have you studied English?” — “For two years / Since 2023.”","passos":"1. Pense na duração ou no começo. 2. Duração → for. 3. Começo → since.","compara":"Em português dizemos “Moro aqui há 5 anos” (presente). Em inglês é present perfect: I've lived here for 5 years — “I live here for 5 years” está errado."},"id":"b3"},{"skill":"g_vs","title":"Present perfect or simple past?","text":"Simple past: tempo terminado e definido (yesterday, in 2020, last week, when I was 10). Present perfect: tempo não dito ou que ainda não acabou (ever, never, today, this week, so far, already, yet, just). Already (já) e just (acabou de) na afirmativa; yet (ainda/já) em negativas e perguntas.","example":"I saw that movie last week. · I've already seen that movie. · Have you finished yet?","variants":{"simples":"Tem data no passado? simple past. Não tem data ou continua? present perfect.","exemplo":"Conversa: “Have you had lunch?” (hoje, não acabou) — “Yes, I had lunch at noon.” (hora definida)","passos":"1. Procure a palavra de tempo. 2. Yesterday, last…, in 2020 → simple past. 3. Ever, never, yet, already, since, for → present perfect.","compara":"Em português usamos “já comi” e “comi ontem” no mesmo tempo verbal. Em inglês são dois: I've already eaten × I ate yesterday."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"g_form","prompt":"She ___ her keys. She can't open the door.","options":["has lost","have lost","lost yesterday","is losing"],"answer":0,"hints":["Resultado no presente.","She → has.","Has + particípio."],"explanation":"She has lost her keys.","id":"q1"},{"type":"mc","difficulty":1,"skill":"g_exp","prompt":"— Have you ever ___ to Paris? — No, never.","options":["went","been","go","going"],"answer":1,"hints":["Ever + particípio.","Já esteve em = been to.","Been."],"explanation":"Have you ever been to Paris?","id":"q2"},{"type":"fill","difficulty":1,"skill":"g_forsince","prompt":"Complete: I've lived here ___ 2018.","answers":["since"],"hints":["2018 é o ponto de início.","Início → since.","Desde = …"],"explanation":"Since 2018.","id":"q3"},{"type":"tf","difficulty":1,"skill":"g_form","prompt":"O particípio de “eat” é “eaten”.","answer":true,"hints":["eat - ate - …","Terceira forma.","Termina em -en."],"explanation":"Verdadeiro: eat-ate-eaten.","id":"q4"},{"type":"match","difficulty":2,"skill":"g_form","prompt":"Ligue o verbo ao particípio.","pairs":[["go","gone"],["write","written"],["do","done"],["see","seen"]],"hints":["Go → g…","Write → written (dois t).","See → seen."],"explanation":"gone · written · done · seen.","id":"q5"},{"type":"mc","difficulty":2,"skill":"g_forsince","prompt":"We've been friends ___ ten years.","options":["since","for","ago","during"],"answer":1,"hints":["Ten years é duração.","Duração → for.","For."],"explanation":"For ten years.","id":"q6"},{"type":"mc","difficulty":2,"skill":"g_vs","prompt":"I ___ that movie last Saturday.","options":["have seen","saw","have saw","seen"],"answer":1,"hints":["Last Saturday é data definida.","Tempo terminado.","Simple past."],"explanation":"I saw it last Saturday.","id":"q7"},{"type":"mc","difficulty":2,"skill":"g_vs","prompt":"— Have you finished your project ___? — Not yet.","options":["already","yet","just","since"],"answer":1,"hints":["Pergunta.","Ainda/já em pergunta.","Yet."],"explanation":"Have you finished yet?","id":"q8"},{"type":"order","difficulty":3,"skill":"g_forsince","prompt":"Organize: “Há quanto tempo você estuda inglês?”","items":["How","long","have","you","studied","English?"],"hints":["How long = quanto tempo.","Depois have + you.","Particípio."],"explanation":"How long have you studied English?","id":"q9"},{"type":"mc","difficulty":3,"skill":"g_vs","prompt":"Qual frase está correta?","options":["I have visited Rome in 2019.","I visited Rome in 2019.","I have visit Rome in 2019.","I visit Rome since 2019."],"answer":1,"hints":["Tem data definida (2019).","Data definida → simple past.","Visited."],"explanation":"Com “in 2019”: I visited Rome in 2019.","id":"q10"}],"review":["have/has + particípio (gone, seen, eaten, done)","Have you ever…? · I've never…","for + duração · since + início","Data definida → simple past; sem data/até hoje → present perfect"],"relatedQuestions":["como usar o present perfect","diferença entre for e since","present perfect ou simple past"],"equivalentQuestions":["quando usar have e has com particípio","diferença entre present perfect e simple past","como dizer eu moro aqui há 5 anos em inglês","o que significa have you ever","quando usar already e yet","particípio de go","been ou gone","o que é present perfect","como usar present perfect","me explica present perfect","quando usar present perfect","exemplos de present perfect","present perfect em inglês","como funciona present perfect","regras de present perfect","exercícios de present perfect","aula de present perfect","não entendi present perfect","present perfect para iniciantes","resumo de present perfect","dúvida sobre present perfect","o que é presente perfeito","como usar presente perfeito","me explica presente perfeito","quando usar presente perfeito","exemplos de presente perfeito","presente perfeito em inglês","como funciona presente perfeito","regras de presente perfeito","exercícios de presente perfeito","aula de presente perfeito","não entendi presente perfeito","presente perfeito para iniciantes","resumo de presente perfeito","dúvida sobre presente perfeito"],"commonErrors":["Usar present perfect com data definida (I have gone yesterday).","Dizer “I live here for 5 years”.","Usar o passado no lugar do particípio (have went)."],"english":{"cefr":"B1","unit":"b1-u1","order":1,"area":"grammar","focus":["grammar","speaking","reading"],"vocabulary":[{"word":"ever","translation":"alguma vez / já","pos":"adverb","definition":"at any time","example":"Have you ever flown in a plane?","difficulty":1},{"word":"never","translation":"nunca","pos":"adverb","definition":"not at any time","example":"I've never seen snow.","difficulty":1},{"word":"already","translation":"já","pos":"adverb","definition":"before now, sooner than expected","example":"I've already eaten.","difficulty":2},{"word":"yet","translation":"ainda / já (perguntas)","pos":"adverb","definition":"until now (in questions and negatives)","example":"She hasn't replied yet.","difficulty":2},{"word":"just","translation":"acabou de","pos":"adverb","definition":"a very short time ago","example":"I've just arrived.","difficulty":2},{"word":"since","translation":"desde","pos":"preposition","definition":"from a point in the past until now","example":"I've known him since 2020.","difficulty":2},{"word":"experience","translation":"experiência","pos":"noun","definition":"something that happened to you","example":"It was an amazing experience.","difficulty":2},{"word":"abroad","translation":"no exterior","pos":"adverb","definition":"in or to another country","example":"Have you ever studied abroad?","difficulty":3}],"grammar":{"name":"Present perfect","when":"Experiências sem data, situações que continuam até hoje e resultados no presente.","structure":"have/has + past participle","affirmative":["I've been to Chile.","She has lived here since 2015."],"negative":["I haven't seen it yet.","He hasn't called."],"interrogative":["Have you ever tried it?","How long has she worked there?"],"compare":"I lost my phone yesterday (quando) × I've lost my phone (e ainda não achei: resultado agora).","context":"Entrevista para intercâmbio: “Have you ever lived abroad?”"},"reading":{"title":"Adventure blog","genre":"post de blog","text":"I've always loved traveling. So far, I've visited twelve countries and I've tried food from all of them. I've never been to Asia, but I've saved money for two years to go to Japan. My flight is next month! I went to Peru in 2023 and climbed to Machu Picchu — it was the hardest walk of my life.","questions":[{"difficulty":1,"prompt":"Quantos países a autora já visitou?","options":["2","10","12","20"],"answer":2,"explanation":"“I've visited twelve countries”."},{"difficulty":2,"prompt":"Que continente ela nunca visitou?","options":["América do Sul","Ásia","Europa","África"],"answer":1,"explanation":"“I've never been to Asia”."},{"difficulty":2,"prompt":"Há quanto tempo ela junta dinheiro para o Japão?","options":["Dois meses","Dois anos","Desde 2023","Um ano"],"answer":1,"explanation":"“for two years”."},{"difficulty":3,"prompt":"Por que “I went to Peru” está no simple past?","options":["Porque é uma experiência","Porque tem data definida (2023)","Porque ela ainda está lá","Porque é um plano"],"answer":1,"explanation":"Com data definida, usamos o simple past."}]},"speaking":{"situation":"Um jogo de “Have you ever…?” com colegas de outro país.","vocabulary":["have you ever","never","once","twice"],"phrases":["Have you ever…?","Yes, I have. I … when I was…","No, I've never…"],"example":"Have you ever been to the beach? — Yes, I have. I went to Maceió last year.","challenge":"Faça 3 perguntas com Have you ever… e responda cada uma com um detalhe no simple past.","expected":["have","ever","never","been"]},"writing":{"prompt":"Escreva sobre 3 experiências que você já teve e 2 que nunca teve (e gostaria de ter).","criteria":["Present perfect para experiências","Uma frase com never","Um detalhe com data no simple past"],"model":"I've been to Rio twice. I've seen a whale — it was in 2022, in Bahia. I've never flown in a plane and I've never tried sushi, but I want to!","keywords":["have","never","been"],"minWords":25},"challenge":"Pergunte a alguém “How long have you…?” (lived here, studied at…, known me) e anote a resposta com for ou since."},"games":{"blanks":[{"difficulty":1,"sentence":"I have lived here ___ 2020.","options":["for","since","during","from"],"answer":1,"explanation":"Ponto de início: since."},{"difficulty":1,"sentence":"Have you ever ___ sushi?","options":["eaten","ate","eat","eating"],"answer":0,"explanation":"Particípio: eaten."},{"difficulty":2,"sentence":"She has ___ finished. Look, she's leaving!","options":["just","yet","ever","since"],"answer":0,"explanation":"Acabou de: just."},{"difficulty":2,"sentence":"I ___ to London in 2019.","options":["went","have gone","have been","go"],"answer":0,"explanation":"Data definida: simple past."},{"difficulty":3,"sentence":"They haven't replied to my message ___.","options":["yet","already","just","ever"],"answer":0,"explanation":"Negativa: yet."}],"pairs":[{"a":"go","b":"gone","difficulty":1},{"a":"eat","b":"eaten","difficulty":1},{"a":"write","b":"written","difficulty":2},{"a":"take","b":"taken","difficulty":2},{"a":"break","b":"broken","difficulty":3},{"a":"fly","b":"flown","difficulty":3}],"sequences":[{"difficulty":1,"prompt":"Organize a frase · Put the words in order","items":["I","have","never","seen","snow"],"words":true,"explanation":"have + never + particípio."},{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["Has","she","finished","her","homework","yet"],"words":true,"explanation":"Pergunta: Has + she + particípio + yet."}],"dialogues":[{"difficulty":2,"title":"Na festa","gap":1,"options":["Yes, I have. I went there last year.","Yes, I have went there last year.","Yes, I did been there.","Yes, I go there last year."],"answer":0,"explanation":"Resposta curta com have + detalhe no simple past.","lines":[{"who":"Tom","text":"Have you ever been to Japan?"},{"who":"Aya","text":"Yes, I have. I went there last year."},{"who":"Tom","text":"Wow! How was it?"},{"who":"Aya","text":"It was amazing!"}]}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-b1-conditionals","subject":"ingles","title":"First and second conditional","levels":["fund2","medio"],"grade":"9º ano e Ensino Médio","topic":"Inglês B1 — Experiências e hipóteses","subtopic":"Zero, first e second conditional","aliases":["conditionals","condicionais em ingles","first conditional","second conditional","zero conditional","if clauses","frases com if","would em ingles","if i were"],"summary":"Fale de verdades gerais, consequências prováveis e situações imaginárias com if.","intro":"If you study, you will pass. If I were a bird, I would fly… Vamos aprender a imaginar em inglês.","objective":"Usar o zero conditional para fatos, o first para consequências prováveis no futuro e o second para situações imaginárias, incluindo “If I were…”.","prerequisites":["ing-a2-future","ing-a2-simple-past"],"next":["ing-b1-phrasal-verbs"],"skills":{"g_zero":"Zero conditional (fatos)","g_first":"First conditional (provável)","g_second":"Second conditional (imaginário)","g_choose":"Escolher a condicional"},"blocks":[{"skill":"g_zero","title":"Zero conditional","text":"Para verdades gerais e fatos científicos: If + simple present, simple present. If you heat ice, it melts. If também pode ser trocado por when sem mudar o sentido.","example":"If you mix blue and yellow, you get green. · Plants die if they don't get water.","variants":{"simples":"Se isso acontece, aquilo sempre acontece.","exemplo":"Aula de ciências: “If water reaches 100 °C, it boils.”","passos":"1. If + presente. 2. Vírgula (se o if vier primeiro). 3. Resultado no presente.","compara":"Zero conditional = regra que sempre vale. Não é uma previsão, é um fato."},"id":"b1"},{"skill":"g_first","title":"First conditional","text":"Para uma condição real e provável no futuro: If + simple present, will + verbo. If it rains tomorrow, we'll stay home. Também: unless (a menos que) = if … not: Unless you hurry, you'll be late.","example":"If you study, you'll pass the test. · If I see her, I'll tell her.","variants":{"simples":"Se acontecer (é possível), vai acontecer isto.","exemplo":"Mãe avisando: “If you don't take a coat, you'll get cold.”","passos":"1. If + presente (NÃO will). 2. Vírgula. 3. Will + verbo.","compara":"Em português dizemos “se chover amanhã” (subjuntivo futuro). Em inglês, depois de if vem o PRESENTE: If it rains — nunca “if it will rain”."},"id":"b2"},{"skill":"g_second","title":"Second conditional","text":"Para situações imaginárias, improváveis ou irreais no presente/futuro: If + simple past, would + verbo. If I had a million dollars, I would travel the world. Com to be, o padrão é were para todas as pessoas: If I were you, I'd talk to her.","example":"If I lived near the beach, I would surf every day. · What would you do if you won the lottery?","variants":{"simples":"Se fosse assim (mas não é), seria assim.","exemplo":"Conselho: “If I were you, I would study a little every day.”","passos":"1. If + passado (imaginação). 2. Vírgula. 3. Would + verbo.","compara":"O passado aqui NÃO fala do passado: “If I had time” = se eu tivesse tempo (agora). É o jeito do inglês de mostrar que é imaginário."},"id":"b3"},{"skill":"g_choose","title":"Which conditional?","text":"Pergunte: é sempre verdade? → zero. É possível e provável? → first. É imaginário, improvável ou impossível? → second. Compare: If I win the game, I'll celebrate (acho possível) × If I won the lottery, I'd buy a house (improvável).","example":"If I get a good grade, my parents will be happy. · If I could fly, I would go to school by air.","variants":{"simples":"Provável → will. Imaginário → would.","exemplo":"Duas pessoas falando do mesmo prêmio: uma acha que pode ganhar (first), a outra acha impossível (second).","passos":"1. Avalie a chance. 2. Escolha o tipo. 3. Confira os tempos verbais das duas partes.","compara":"A escolha mostra a OPINIÃO de quem fala: a mesma situação pode ir no first ou no second, dependendo de quanto a pessoa acredita nela."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"g_zero","prompt":"If you heat ice, it ___.","options":["melts","will melt","would melt","melted"],"answer":0,"hints":["É um fato científico.","Zero conditional.","Presente + presente."],"explanation":"If you heat ice, it melts.","id":"q1"},{"type":"mc","difficulty":1,"skill":"g_first","prompt":"If it ___ tomorrow, we'll stay home.","options":["will rain","rains","rained","would rain"],"answer":1,"hints":["First conditional.","Depois de if: presente.","Nunca will depois de if."],"explanation":"If it rains tomorrow…","id":"q2"},{"type":"fill","difficulty":1,"skill":"g_second","prompt":"Complete: If I ___ you, I would apologize. (to be)","answers":["were"],"hints":["Second conditional com to be.","Forma usada para todas as pessoas.","W-e-r-e."],"explanation":"If I were you…","id":"q3"},{"type":"tf","difficulty":1,"skill":"g_first","prompt":"“If you will study, you will pass” está correto.","answer":false,"hints":["Depois de if…","…não usamos will.","If you study…"],"explanation":"Falso: If you study, you'll pass.","id":"q4"},{"type":"match","difficulty":2,"skill":"g_choose","prompt":"Ligue cada frase ao tipo de condicional.","pairs":[["If you heat water to 100 °C, it boils.","zero"],["If it rains, I'll take an umbrella.","first"],["If I had wings, I would fly.","second"]],"hints":["Fato sempre verdadeiro.","Possível no futuro.","Imaginário."],"explanation":"zero · first · second.","id":"q5"},{"type":"mc","difficulty":2,"skill":"g_second","prompt":"If I ___ a lot of money, I would buy a farm.","options":["have","had","will have","would have"],"answer":1,"hints":["Situação imaginária.","Second conditional.","If + passado."],"explanation":"If I had a lot of money…","id":"q6"},{"type":"mc","difficulty":2,"skill":"g_first","prompt":"Unless you hurry, you ___ the bus.","options":["miss","will miss","would miss","missed"],"answer":1,"hints":["Unless = if not.","Futuro provável.","Will + verbo."],"explanation":"Unless you hurry, you'll miss the bus.","id":"q7"},{"type":"mc","difficulty":2,"skill":"g_second","prompt":"What ___ you do if you found a wallet on the street?","options":["will","would","do","did"],"answer":1,"hints":["Situação imaginária.","Pergunta no second.","Would."],"explanation":"What would you do if…?","id":"q8"},{"type":"order","difficulty":3,"skill":"g_first","prompt":"Organize: “Se eu a vir, vou contar para ela.”","items":["If","I","see","her,","I'll","tell","her"],"hints":["If + presente.","Vírgula depois da condição.","I'll + verbo."],"explanation":"If I see her, I'll tell her.","id":"q9"},{"type":"mc","difficulty":3,"skill":"g_choose","prompt":"Você acha que é praticamente impossível ser convidado para o show. Qual frase combina?","options":["If they invite me, I'll go.","If they invited me, I would go.","If they invite me, I go.","If they will invite me, I'll go."],"answer":1,"hints":["Quase impossível = imaginário.","Second conditional.","Past + would."],"explanation":"Improvável → second: If they invited me, I would go.","id":"q10"}],"review":["Zero: if + presente, presente (fatos)","First: if + presente, will (provável)","Second: if + passado, would (imaginário) · If I were you","Nunca will logo depois de if"],"relatedQuestions":["como usar if em inglês","diferença entre first e second conditional","por que if I were"],"equivalentQuestions":["quando usar would","por que se diz if I were e não if I was","o que é first conditional","o que é second conditional","posso usar will depois de if","o que significa unless","como dizer se eu fosse você em inglês","o que é condicionais em inglês","como usar condicionais em inglês","me explica condicionais em inglês","quando usar condicionais em inglês","exemplos de condicionais em inglês","condicionais em inglês em inglês","como funciona condicionais em inglês","regras de condicionais em inglês","exercícios de condicionais em inglês","aula de condicionais em inglês","não entendi condicionais em inglês","condicionais em inglês para iniciantes","resumo de condicionais em inglês","dúvida sobre condicionais em inglês","o que é conditionals","como usar conditionals","me explica conditionals","quando usar conditionals","exemplos de conditionals","conditionals em inglês","como funciona conditionals","regras de conditionals","exercícios de conditionals","aula de conditionals","não entendi conditionals","conditionals para iniciantes","resumo de conditionals","dúvida sobre conditionals"],"commonErrors":["Usar will depois de if.","Usar would nas duas partes (If I would have…).","Achar que o passado do second conditional fala do passado."],"english":{"cefr":"B1","unit":"b1-u2","order":1,"area":"grammar","focus":["grammar","speaking","writing"],"vocabulary":[{"word":"if","translation":"se","pos":"conjunction","definition":"used to talk about a possible situation","example":"If you want, I'll help you.","difficulty":1},{"word":"unless","translation":"a menos que","pos":"conjunction","definition":"except if","example":"I won't go unless you come too.","difficulty":3},{"word":"would","translation":"faria / iria (condicional)","pos":"verb","definition":"used for imaginary situations","example":"I would travel more.","difficulty":2},{"word":"lottery","translation":"loteria","pos":"noun","definition":"a game where you can win money by chance","example":"What would you do if you won the lottery?","difficulty":2},{"word":"melt","translation":"derreter","pos":"verb","definition":"to change from solid to liquid","example":"Ice melts in the sun.","difficulty":2},{"word":"advice","translation":"conselho","pos":"noun","definition":"an opinion about what someone should do","example":"Can I give you some advice?","difficulty":2},{"word":"invite","translation":"convidar","pos":"verb","definition":"to ask someone to come to an event","example":"If they invite me, I'll go.","difficulty":1}],"grammar":{"name":"Conditionals (0, 1, 2)","when":"Fatos, consequências prováveis e situações imaginárias.","structure":"0: if + present, present · 1: if + present, will · 2: if + past, would","affirmative":["If you heat ice, it melts.","If it rains, I'll stay home.","If I had time, I'd learn guitar."],"negative":["If you don't hurry, you'll be late.","If I didn't have homework, I'd go out."],"interrogative":["What will you do if it rains?","What would you do if you were invisible?"],"compare":"If I win (acho possível) × If I won (acho improvável).","context":"Dar conselhos: “If I were you, I'd…”"},"speaking":{"situation":"Um amigo pergunta o que você faria em situações imaginárias.","vocabulary":["would","if I were","if I had"],"phrases":["If I had…, I would…","If I were…, I'd…","I would probably…"],"example":"If I had a superpower, I would be invisible. I'd visit places for free!","challenge":"Responda: What would you do if you won the lottery? (2 ou 3 frases).","expected":["if","would","had"]},"writing":{"prompt":"Escreva um pequeno texto: “If I could change one thing in my city…” usando second conditional e um first conditional sobre o futuro.","criteria":["Second conditional (if + past, would)","Um first conditional (if + present, will)","Conclusão com opinião"],"model":"If I could change one thing in my city, I would build more parks. If there were more trees, people would be healthier. If the mayor listens to us, he will plant trees next year.","keywords":["if","would","will","were"],"minWords":30},"challenge":"Dê um conselho em inglês para um colega começando com “If I were you…”."},"games":{"blanks":[{"difficulty":1,"sentence":"If you mix red and white, you ___ pink.","options":["get","will got","would got","getting"],"answer":0,"explanation":"Fato: zero conditional."},{"difficulty":1,"sentence":"If I see Ana, I ___ her the news.","options":["'ll tell","tell","'d told","told"],"answer":0,"explanation":"Provável: will."},{"difficulty":2,"sentence":"If I ___ taller, I would play basketball.","options":["were","am","will be","be"],"answer":0,"explanation":"Second: were."},{"difficulty":2,"sentence":"She would travel more if she ___ more money.","options":["had","has","will have","would have"],"answer":0,"explanation":"If + passado."},{"difficulty":3,"sentence":"You won't pass ___ you study harder.","options":["unless","if","when","because"],"answer":0,"explanation":"Unless = a menos que."}],"sequences":[{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["If","it","rains","we","will","stay","home"],"words":true,"explanation":"First conditional."},{"difficulty":3,"prompt":"Organize a frase · Put the words in order","items":["If","I","were","you","I","would","call","her"],"words":true,"explanation":"Conselho com second conditional."}],"dialogues":[{"difficulty":2,"title":"Pedindo conselho","gap":1,"options":["If I were you, I'd go to bed earlier.","If I am you, I will go to bed earlier.","If I was you, I go to bed.","If I were you, I will went to bed."],"answer":0,"explanation":"Conselho: If I were you, I'd…","lines":[{"who":"Lia","text":"I'm always tired in class."},{"who":"Téo","text":"If I were you, I'd go to bed earlier."},{"who":"Lia","text":"That's good advice!"}]},{"difficulty":3,"title":"Sonhando acordado","gap":1,"options":["I would go to Iceland to see the northern lights.","I will go to Iceland.","I go to Iceland.","I went to Iceland."],"answer":0,"explanation":"Resposta imaginária: would.","lines":[{"who":"Max","text":"What would you do if you won a trip?"},{"who":"Bia","text":"I would go to Iceland to see the northern lights."},{"who":"Max","text":"Cool! I'd go to Japan."}]}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-b1-phrasal-verbs","subject":"ingles","title":"Everyday phrasal verbs","levels":["fund2","medio"],"grade":"9º ano e Ensino Médio","topic":"Inglês B1 — Inglês que soa natural","subtopic":"Phrasal verbs mais comuns","aliases":["phrasal verbs","verbos frasais","give up","look after","look for","get up","find out","turn down","lista de phrasal verbs","verbo mais preposicao"],"summary":"Entenda e use 21 phrasal verbs do dia a dia pelo contexto — sem traduzir palavra por palavra.","intro":"Don't give up! Phrasal verbs estão em todo lugar: séries, músicas e conversas.","objective":"Reconhecer o significado de phrasal verbs comuns pelo contexto, usá-los em frases naturais e saber quando o objeto pode ficar no meio.","prerequisites":["ing-a2-simple-past"],"next":["ing-b1-false-friends"],"skills":{"v_what":"O que é um phrasal verb","v_daily":"Rotina e relações (get up, get along, look after…)","v_problem":"Problemas e decisões (give up, figure out, put off…)","g_sep":"Separáveis e inseparáveis"},"blocks":[{"skill":"v_what","title":"What is a phrasal verb?","text":"Phrasal verb = verbo + partícula (up, down, out, off, on, after, over…) que forma um sentido NOVO. Look = olhar; look after = cuidar de; look for = procurar; look up = pesquisar (uma palavra). Por isso, traduzir palavra por palavra quase sempre falha: entenda pelo contexto.","example":"Can you look after my dog this weekend? · I'm looking for my keys.","variants":{"simples":"Verbo + pequena palavra = um significado novo. Look after não é “olhar depois”, é “cuidar”.","exemplo":"Numa série: “I'll figure it out” — o personagem vai descobrir/resolver, e não “figurar para fora”.","passos":"1. Veja o verbo e a partícula juntos. 2. Leia a frase inteira. 3. Descubra o sentido pelo contexto.","compara":"É como no português “dar certo”, “dar em nada”, “dar para trás”: o “dar” muda de sentido com as palavras ao lado."},"id":"b1"},{"skill":"v_daily","title":"Routine and relationships","text":"get up (levantar da cama), wake up (acordar), get along (with) (se dar bem com), look after (cuidar de), bring up (criar filhos / mencionar um assunto), carry on (continuar), come across (encontrar por acaso), run into (encontrar alguém por acaso), set up (montar, organizar), take off (decolar / tirar roupa).","example":"I get along well with my cousin. · I ran into my teacher at the mall. · The plane took off at 9.","variants":{"simples":"Get along = se dar bem. Run into = esbarrar com alguém sem esperar.","exemplo":"Contando o dia: “I got up late, ran into Leo on the bus and we carried on talking all the way.”","passos":"1. Agrupe por tema: rotina, pessoas, viagens. 2. Crie uma frase sua para cada um. 3. Revise ouvindo músicas e séries.","compara":"Come across (algo por acaso: um texto, um vídeo) × run into (alguém por acaso: uma pessoa)."},"id":"b2"},{"skill":"v_problem","title":"Problems and decisions","text":"give up (desistir), figure out (entender, resolver), find out (descobrir uma informação), look up (procurar num dicionário/internet), look forward to (aguardar com expectativa), put off (adiar), turn down (recusar / abaixar o volume), turn up (aparecer / aumentar o volume), take over (assumir o controle), work out (malhar / dar certo / calcular).","example":"Don't give up! · I'm looking forward to the trip. · She turned down the job offer.","variants":{"simples":"Give up = desistir. Put off = deixar para depois. Find out = descobrir.","exemplo":"Estudos: “I put off my homework, but then I figured out the answers quickly.”","passos":"1. Veja o problema na frase. 2. Qual ação resolve ou atrasa? 3. Escolha o phrasal verb.","compara":"Look forward to é seguido de -ing: I'm looking forward to seeing you (e não “to see you”)."},"id":"b3"},{"skill":"g_sep","title":"Separable or not?","text":"Alguns phrasal verbs aceitam o objeto no meio (separáveis): turn down the music / turn the music down. Se o objeto for pronome, ele DEVE ficar no meio: turn it down (nunca “turn down it”). Outros não se separam: look after the baby / look after her.","example":"Please turn it off. · Can you look after them?","variants":{"simples":"Com pronome (it, them, her), ele vai no meio: pick it up, turn it off.","exemplo":"Pedindo: “The TV is loud. Can you turn it down?”","passos":"1. O objeto é um pronome? 2. Se o verbo for separável, coloque o pronome no meio. 3. Na dúvida, consulte um dicionário: ele mostra “sth” no meio ou no fim.","compara":"Nos dicionários, “turn sth down” indica separável; “look after sb” indica que o objeto vem depois."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"v_problem","prompt":"“Don't give up!” significa:","options":["Não desista!","Não levante!","Não entregue!","Não suba!"],"answer":0,"hints":["Alguém está quase parando de tentar.","É um incentivo.","Desistir."],"explanation":"Give up = desistir.","id":"q1"},{"type":"mc","difficulty":1,"skill":"v_daily","prompt":"Can you ___ my cat while I travel?","options":["look for","look after","look up","look forward"],"answer":1,"hints":["Alguém vai viajar.","O gato precisa de cuidados.","Cuidar de = look after."],"explanation":"Look after = cuidar de.","id":"q2"},{"type":"fill","difficulty":1,"skill":"v_problem","prompt":"Complete: I don't know this word. I'll look it ___ in the dictionary.","answers":["up"],"hints":["Pesquisar uma palavra.","Look + …","Up."],"explanation":"Look it up = pesquisar.","id":"q3"},{"type":"tf","difficulty":1,"skill":"v_what","prompt":"Phrasal verbs podem ser traduzidos palavra por palavra.","answer":false,"hints":["Pense em look after.","“Olhar depois”?","O sentido muda."],"explanation":"Falso: o sentido é novo e depende do contexto.","id":"q4"},{"type":"match","difficulty":2,"skill":"v_problem","prompt":"Ligue o phrasal verb ao significado.","pairs":[["find out","descobrir"],["put off","adiar"],["turn down","recusar"],["work out","malhar / dar certo"]],"hints":["Find = achar.","Off = para longe (no tempo).","Down = para baixo (dizer não)."],"explanation":"find out descobrir · put off adiar · turn down recusar · work out malhar/dar certo.","id":"q5"},{"type":"mc","difficulty":2,"skill":"v_daily","prompt":"I ___ my old teacher at the supermarket yesterday. What a surprise!","options":["ran into","looked for","set up","took over"],"answer":0,"hints":["Encontro por acaso.","Com uma pessoa.","Run into."],"explanation":"Run into = encontrar alguém por acaso.","id":"q6"},{"type":"mc","difficulty":2,"skill":"g_sep","prompt":"The music is too loud. Please ___.","options":["turn down it","turn it down","turn it up down","down turn it"],"answer":1,"hints":["Pronome it.","Pronome vai no meio.","Turn it down."],"explanation":"Turn it down.","id":"q7"},{"type":"mc","difficulty":2,"skill":"v_problem","prompt":"I'm looking forward ___ you next week!","options":["to see","to seeing","see","seeing to"],"answer":1,"hints":["Look forward to + …","Depois de to aqui vem -ing.","To seeing."],"explanation":"Looking forward to seeing you.","id":"q8"},{"type":"order","difficulty":3,"skill":"v_daily","prompt":"Organize a rotina de viagem na ordem lógica.","items":["I woke up at 5.","I got up and packed my bag.","I set off for the airport.","The plane took off at 8."],"hints":["Primeiro acordar.","Depois levantar e arrumar.","O avião decola por último."],"explanation":"woke up → got up → set off → took off.","id":"q9"},{"type":"mc","difficulty":3,"skill":"v_problem","prompt":"“We had some problems, but in the end everything worked out.” Qual é o sentido?","options":["Tudo foi para a academia","No fim, tudo deu certo","Tudo foi calculado","Tudo saiu de casa"],"answer":1,"hints":["Houve problemas…","“in the end” = no final.","Work out = dar certo."],"explanation":"Work out aqui = dar certo.","id":"q10"}],"review":["Verbo + partícula = sentido novo (entenda pelo contexto)","get up, get along, look after, run into, carry on, set up, take off","give up, figure out, find out, look up, put off, turn down/up, work out","Pronome no meio dos separáveis: turn it down"],"relatedQuestions":["o que são phrasal verbs","lista de phrasal verbs mais usados","o que significa give up"],"equivalentQuestions":["o que significa look after","diferença entre look for e look up","o que significa figure out","o que é run into","por que é looking forward to seeing","o que significa put off","turn down it ou turn it down","como aprender phrasal verbs","o que é phrasal verbs","como usar phrasal verbs","me explica phrasal verbs","quando usar phrasal verbs","exemplos de phrasal verbs","phrasal verbs em inglês","como funciona phrasal verbs","regras de phrasal verbs","exercícios de phrasal verbs","aula de phrasal verbs","não entendi phrasal verbs","phrasal verbs para iniciantes","resumo de phrasal verbs","dúvida sobre phrasal verbs","o que é verbos frasais","como usar verbos frasais","me explica verbos frasais","quando usar verbos frasais","exemplos de verbos frasais","verbos frasais em inglês","como funciona verbos frasais","regras de verbos frasais","exercícios de verbos frasais","aula de verbos frasais","não entendi verbos frasais","verbos frasais para iniciantes","resumo de verbos frasais","dúvida sobre verbos frasais"],"commonErrors":["Traduzir palavra por palavra.","Colocar o pronome depois da partícula (turn off it).","Usar infinitivo depois de look forward to (to see)."],"english":{"cefr":"B1","unit":"b1-u3","order":1,"area":"vocabulary","focus":["vocabulary","reading","listening"],"vocabulary":[{"word":"get up","translation":"levantar (da cama)","pos":"phrasal verb","definition":"to leave your bed after sleeping","example":"I get up at seven.","difficulty":1,"related":["wake up"]},{"word":"get along","translation":"se dar bem","pos":"phrasal verb","definition":"to have a friendly relationship","example":"I get along with my sister.","difficulty":2},{"word":"give up","translation":"desistir","pos":"phrasal verb","definition":"to stop trying","example":"Never give up on your dreams.","difficulty":1},{"word":"look after","translation":"cuidar de","pos":"phrasal verb","definition":"to take care of","example":"She looks after her grandma.","difficulty":1,"synonyms":["take care of"]},{"word":"look for","translation":"procurar","pos":"phrasal verb","definition":"to try to find","example":"I'm looking for my phone.","difficulty":1},{"word":"look forward to","translation":"aguardar ansiosamente","pos":"phrasal verb","definition":"to feel happy about something that will happen","example":"I'm looking forward to the holidays.","difficulty":3},{"word":"put off","translation":"adiar","pos":"phrasal verb","definition":"to do something later than planned","example":"Don't put off your homework.","difficulty":2,"synonyms":["postpone"]},{"word":"turn down","translation":"recusar / abaixar","pos":"phrasal verb","definition":"to say no to an offer; to make quieter","example":"He turned down the invitation.","difficulty":2},{"word":"find out","translation":"descobrir","pos":"phrasal verb","definition":"to get information about something","example":"I found out the truth.","difficulty":2},{"word":"figure out","translation":"entender / resolver","pos":"phrasal verb","definition":"to understand or solve after thinking","example":"I can't figure out this problem.","difficulty":2},{"word":"run into","translation":"encontrar por acaso","pos":"phrasal verb","definition":"to meet someone by chance","example":"I ran into Leo at the mall.","difficulty":2},{"word":"come across","translation":"deparar-se com","pos":"phrasal verb","definition":"to find something by chance","example":"I came across an old photo.","difficulty":3},{"word":"carry on","translation":"continuar","pos":"phrasal verb","definition":"to continue","example":"Carry on, you're doing great!","difficulty":2},{"word":"set up","translation":"montar / organizar","pos":"phrasal verb","definition":"to prepare or start something","example":"We set up a study group.","difficulty":2},{"word":"take off","translation":"decolar / tirar (roupa)","pos":"phrasal verb","definition":"when a plane leaves the ground; to remove clothes","example":"Take off your shoes, please.","difficulty":2},{"word":"take over","translation":"assumir o controle","pos":"phrasal verb","definition":"to take control of something","example":"A new manager took over the team.","difficulty":3},{"word":"turn up","translation":"aparecer / aumentar o volume","pos":"phrasal verb","definition":"to arrive, often unexpectedly; to make louder","example":"He turned up late.","difficulty":3},{"word":"work out","translation":"malhar / dar certo","pos":"phrasal verb","definition":"to exercise; to end well","example":"Everything worked out fine.","difficulty":2},{"word":"bring up","translation":"criar (filhos) / mencionar","pos":"phrasal verb","definition":"to raise a child; to mention a subject","example":"She brought up an interesting point.","difficulty":3},{"word":"look up","translation":"pesquisar (palavra)","pos":"phrasal verb","definition":"to search for information","example":"Look it up online.","difficulty":2},{"word":"wake up","translation":"acordar","pos":"phrasal verb","definition":"to stop sleeping","example":"I woke up late today.","difficulty":1}],"reading":{"title":"Messages from a group chat","genre":"conversa de grupo","text":"Ana: Guys, I found out the concert is on Saturday!\nLeo: Awesome! I'm looking forward to it.\nBia: I can't go 😢 I have to look after my little brother.\nLeo: Don't give up yet! Maybe your aunt can help?\nBia: Good idea, I'll ask her. If it works out, I'll go!\nAna: Let's set up a meeting point near the entrance.","questions":[{"difficulty":1,"prompt":"O que Ana descobriu?","options":["Que o show foi cancelado","Que o show é no sábado","Que Bia não vai","Que o ingresso acabou"],"answer":1,"explanation":"“I found out the concert is on Saturday!”"},{"difficulty":2,"prompt":"Por que Bia não pode ir, a princípio?","options":["Porque vai trabalhar","Porque precisa cuidar do irmão","Porque está doente","Porque não gosta da banda"],"answer":1,"explanation":"“I have to look after my little brother.”"},{"difficulty":2,"prompt":"O que Leo quer dizer com “Don't give up yet”?","options":["Não desista ainda","Não levante ainda","Não entregue ainda","Não saia ainda"],"answer":0,"explanation":"Give up = desistir."},{"difficulty":3,"prompt":"O que Ana propõe no final?","options":["Adiar o show","Combinar um ponto de encontro","Comprar ingressos","Cuidar do irmão de Bia"],"answer":1,"explanation":"“set up a meeting point” = combinar um ponto de encontro."}]},"listening":{"title":"Voice message","kind":"texto","rate":0.92,"script":["Hey, it's me. Sorry, I have to put off our study session.","My mom asked me to look after my grandpa this afternoon.","Can we carry on tomorrow? I still can't figure out exercise five.","Call me back when you get this!"],"questions":[{"difficulty":1,"prompt":"O que a pessoa precisa fazer com o encontro de estudos?","options":["Cancelar para sempre","Adiar","Antecipar","Mudar de lugar"],"answer":1,"explanation":"Put off = adiar."},{"difficulty":2,"prompt":"Por quê?","options":["Vai malhar","Vai cuidar do avô","Vai viajar","Esqueceu"],"answer":1,"explanation":"“look after my grandpa”."},{"difficulty":3,"prompt":"Qual é a dificuldade dela?","options":["Não entende o exercício 5","Perdeu o caderno","Não achou o livro","Não sabe o horário"],"answer":0,"explanation":"“I still can't figure out exercise five.”"}]},"challenge":"Escolha 5 phrasal verbs desta aula e escreva uma frase verdadeira sobre a sua vida com cada um.","tips":["Aprenda phrasal verbs em frases, não em listas soltas.","Quando ouvir um numa série, pause e tente adivinhar o sentido pelo contexto."]},"games":{"blanks":[{"difficulty":1,"sentence":"I'm ___ my glasses. Have you seen them?","options":["looking for","looking after","looking up","giving up"],"answer":0,"explanation":"Procurar: look for."},{"difficulty":1,"sentence":"She never ___. She always tries again.","options":["gives up","gets up","turns up","takes off"],"answer":0,"explanation":"Desistir: give up."},{"difficulty":2,"sentence":"We need to ___ the meeting until next week.","options":["put off","put on","turn up","run into"],"answer":0,"explanation":"Adiar: put off."},{"difficulty":2,"sentence":"I ___ an interesting article about space.","options":["came across","looked after","got along","took over"],"answer":0,"explanation":"Encontrar algo por acaso: come across."},{"difficulty":3,"sentence":"He was offered a job in Canada, but he ___ it ___.","options":["turned / down","turned / up","took / off","looked / after"],"answer":0,"explanation":"Recusar: turn it down."},{"difficulty":3,"sentence":"Do you ___ with your neighbors?","options":["get along","get up","set up","carry on"],"answer":0,"explanation":"Se dar bem: get along."}],"sequences":[{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["Please","turn","it","down"],"words":true,"explanation":"Pronome no meio do phrasal verb separável."},{"difficulty":3,"prompt":"Organize a frase · Put the words in order","items":["I","am","looking","forward","to","seeing","you"],"words":true,"explanation":"Look forward to + -ing."}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-b1-false-friends","subject":"ingles","title":"False friends","levels":["fund2","medio"],"grade":"8º ano ao Ensino Médio","topic":"Inglês B1 — Inglês que soa natural","subtopic":"Falsos cognatos","aliases":["false friends","falsos cognatos","falso cognato","actually significa","pretend significa","push significa","parents significa","library significa","cognatos em ingles"],"summary":"Evite as armadilhas: palavras parecidas com o português que significam outra coisa.","intro":"Actually, “actually” não quer dizer “atualmente”! Vamos desarmar as armadilhas.","objective":"Identificar os falsos cognatos mais comuns, dizer o significado real de cada um e escolher a palavra certa para o que se quer dizer.","prerequisites":["ing-a1-family"],"next":["ing-b1-collocations"],"skills":{"v_what":"O que são falsos cognatos","v_common":"Os mais comuns (actually, pretend, push…)","v_school":"Escola e vida (college, library, lecture…)","v_choose":"Escolher a palavra certa"},"blocks":[{"skill":"v_what","title":"What are false friends?","text":"Cognatos são palavras parecidas nas duas línguas e com o mesmo sentido (hospital, animal, important). Falsos cognatos (false friends) parecem iguais, mas significam OUTRA coisa: pretend não é “pretender”, é “fingir”. Eles causam mal-entendidos em conversas e em provas.","example":"I pretend to be sick = eu finjo estar doente (e não “pretendo”).","variants":{"simples":"Palavra parecida com o português, mas com outro significado.","exemplo":"Numa prova do ENEM, “eventually” pode mudar todo o sentido da frase: não é “eventualmente”, é “no fim das contas”.","passos":"1. Desconfie de palavras “fáceis demais”. 2. Leia o contexto. 3. Confirme no dicionário.","compara":"Cognato verdadeiro: hospital = hospital. Falso cognato: exquisite = requintado (e não “esquisito”)."},"id":"b1"},{"skill":"v_common","title":"The most common traps","text":"actually = na verdade (atualmente = currently/nowadays) · pretend = fingir (pretender = intend) · push = empurrar (puxar = pull) · eventually = no fim, finalmente (eventualmente = occasionally) · sensible = sensato (sensível = sensitive) · realize = perceber (realizar = achieve/carry out) · attend = frequentar/comparecer (atender = answer/serve) · lunch = almoço (lanche = snack).","example":"Actually, I don't agree. · Push the door, don't pull! · She realized she was wrong.","variants":{"simples":"Actually = na verdade. Push = empurrar. Realize = perceber.","exemplo":"Na porta de uma loja: PUSH (empurre). O brasileiro distraído puxa!","passos":"1. Leia a palavra. 2. Lembre o significado REAL. 3. Pense na palavra que você realmente queria.","compara":"Se quiser dizer “atualmente”, use currently ou nowadays. Actually serve para corrigir ou contrastar: “Actually, it's Tuesday.”"},"id":"b2"},{"skill":"v_school","title":"School, work and family traps","text":"college = faculdade (colégio = school) · library = biblioteca (livraria = bookstore) · lecture = palestra/aula expositiva (leitura = reading) · parents = pais (parentes = relatives) · comprehensive = abrangente, completo (compreensivo = understanding) · exquisite = requintado (esquisito = weird) · fabric = tecido (fábrica = factory) · costume = fantasia (costume = habit).","example":"My sister is in college. · I bought a costume for the party.","variants":{"simples":"College = faculdade. Library = biblioteca. Costume = fantasia.","exemplo":"Currículo em inglês: “I attended a lecture about robots” = assisti a uma palestra.","passos":"1. Lembre o par: palavra inglesa → sentido real. 2. Crie uma frase-âncora. 3. Revise com o jogo da memória.","compara":"Costume em inglês é a fantasia de festa; o nosso “costume” (hábito) em inglês é habit."},"id":"b3"},{"skill":"v_choose","title":"Choosing the right word","text":"Na hora de falar ou escrever, parta do que você quer dizer em português e escolha a palavra certa: “Eu pretendo viajar” → I intend to / I'm planning to travel. “Ele é muito sensível” → He's very sensitive. “Atualmente moro em Natal” → Currently, I live in Natal. “Realizei um sonho” → I achieved / made a dream come true.","example":"I intend to study abroad. · She's sensitive, so be kind.","variants":{"simples":"Não use a palavra parecida por instinto: pense no significado.","exemplo":"Mensagem para um professor estrangeiro: “Currently I'm in 9th grade and I intend to study engineering.”","passos":"1. O que quero dizer? 2. A palavra parecida é falso cognato? 3. Troque pela certa.","compara":"Nem toda palavra parecida é armadilha: important, family, animal são cognatos verdadeiros. O truque é conhecer a lista das armadilhas."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"v_common","prompt":"“Actually” significa:","options":["atualmente","na verdade","rapidamente","finalmente"],"answer":1,"hints":["Falso cognato.","Usado para corrigir algo.","Na verdade."],"explanation":"Actually = na verdade.","id":"q1"},{"type":"mc","difficulty":1,"skill":"v_common","prompt":"Na porta está escrito “PUSH”. Você deve:","options":["puxar","empurrar","tocar","esperar"],"answer":1,"hints":["Push ≠ puxar.","Puxar = pull.","Empurrar."],"explanation":"Push = empurrar.","id":"q2"},{"type":"fill","difficulty":1,"skill":"v_school","prompt":"Como se diz “livraria” (loja de livros) em inglês?","answers":["bookstore","bookshop"],"hints":["Não é library.","Book + loja.","Book…"],"explanation":"Livraria = bookstore/bookshop; library = biblioteca.","id":"q3"},{"type":"tf","difficulty":1,"skill":"v_school","prompt":"“Parents” significa “parentes”.","answer":false,"hints":["Falso cognato.","São duas pessoas.","Pai e mãe."],"explanation":"Falso: parents = pais; parentes = relatives.","id":"q4"},{"type":"match","difficulty":2,"skill":"v_common","prompt":"Ligue o falso cognato ao significado real.","pairs":[["pretend","fingir"],["realize","perceber"],["eventually","no fim"],["sensible","sensato"]],"hints":["Pretend ≠ pretender.","Realize ≠ realizar.","Sensible ≠ sensível."],"explanation":"pretend fingir · realize perceber · eventually no fim · sensible sensato.","id":"q5"},{"type":"mc","difficulty":2,"skill":"v_choose","prompt":"Como dizer “Atualmente eu moro em Natal”?","options":["Actually I live in Natal.","Currently I live in Natal.","Actual I live in Natal.","Eventually I live in Natal."],"answer":1,"hints":["Actually é armadilha.","Atualmente = …","Currently."],"explanation":"Currently / nowadays = atualmente.","id":"q6"},{"type":"mc","difficulty":2,"skill":"v_school","prompt":"“My brother is in college” significa:","options":["Meu irmão está no colégio.","Meu irmão está na faculdade.","Meu irmão está na biblioteca.","Meu irmão está na escola primária."],"answer":1,"hints":["College é falso cognato.","Colégio = school.","Faculdade."],"explanation":"College = faculdade.","id":"q7"},{"type":"mc","difficulty":2,"skill":"v_common","prompt":"“He pretended to be asleep.” Ele:","options":["pretendia dormir","fingiu estar dormindo","conseguiu dormir","dormiu cedo"],"answer":1,"hints":["Pretend = …","Não é pretender.","Fingir."],"explanation":"Pretend = fingir.","id":"q8"},{"type":"order","difficulty":3,"skill":"v_choose","prompt":"Organize: “Eu pretendo estudar no exterior.”","items":["I","intend","to","study","abroad"],"hints":["Pretender = intend.","Intend to + verbo.","Abroad no final."],"explanation":"I intend to study abroad.","id":"q9"},{"type":"mc","difficulty":3,"skill":"v_common","prompt":"“After many attempts, she eventually passed the exam.” O sentido é:","options":["Ela passou de vez em quando.","Ela eventualmente passaria.","Depois de muitas tentativas, ela finalmente passou.","Ela nunca passou."],"answer":2,"hints":["Eventually é falso cognato.","Veja “after many attempts”.","Finalmente / no fim."],"explanation":"Eventually = finalmente, no fim.","id":"q10"}],"review":["actually = na verdade · currently = atualmente","pretend fingir · realize perceber · push empurrar · eventually no fim","college faculdade · library biblioteca · parents pais · costume fantasia","Pense no sentido, não na aparência da palavra"],"relatedQuestions":["o que são falsos cognatos","lista de falsos cognatos em inglês","actually significa atualmente"],"equivalentQuestions":["o que significa pretend","push é puxar ou empurrar","o que significa eventually","college é colégio","library é livraria","o que significa realize","o que significa sensible","como dizer atualmente em inglês","o que significa costume em inglês","o que é falsos cognatos","como usar falsos cognatos","me explica falsos cognatos","quando usar falsos cognatos","exemplos de falsos cognatos","falsos cognatos em inglês","como funciona falsos cognatos","regras de falsos cognatos","exercícios de falsos cognatos","aula de falsos cognatos","não entendi falsos cognatos","falsos cognatos para iniciantes","resumo de falsos cognatos","dúvida sobre falsos cognatos","o que é false friends","como usar false friends","me explica false friends","quando usar false friends","exemplos de false friends","false friends em inglês","como funciona false friends","regras de false friends","exercícios de false friends","aula de false friends","não entendi false friends","false friends para iniciantes","resumo de false friends","dúvida sobre false friends"],"commonErrors":["Usar actually como “atualmente”.","Dizer “I pretend to travel” querendo dizer “pretendo viajar”.","Confundir library (biblioteca) com livraria."],"english":{"cefr":"B1","unit":"b1-u4","order":1,"area":"vocabulary","focus":["vocabulary","reading"],"vocabulary":[{"word":"actually","translation":"na verdade","pos":"adverb","definition":"in fact; used to correct or add information","example":"Actually, I'm not hungry.","difficulty":2,"related":["currently"]},{"word":"currently","translation":"atualmente","pos":"adverb","definition":"at the present time","example":"I'm currently in 9th grade.","difficulty":2,"synonyms":["nowadays"]},{"word":"pretend","translation":"fingir","pos":"verb","definition":"to act as if something is true when it is not","example":"He pretended to be sick.","difficulty":2,"related":["intend"]},{"word":"intend","translation":"pretender, ter a intenção","pos":"verb","definition":"to plan to do something","example":"I intend to study medicine.","difficulty":3},{"word":"push","translation":"empurrar","pos":"verb","definition":"to move something away from you","example":"Push the door.","difficulty":1,"antonyms":["pull"]},{"word":"pull","translation":"puxar","pos":"verb","definition":"to move something toward you","example":"Pull the rope.","difficulty":1,"antonyms":["push"]},{"word":"realize","translation":"perceber","pos":"verb","definition":"to understand something suddenly","example":"I realized I was late.","difficulty":2},{"word":"eventually","translation":"finalmente, no fim","pos":"adverb","definition":"after a long time","example":"We eventually found the keys.","difficulty":3},{"word":"sensible","translation":"sensato","pos":"adjective","definition":"showing good judgment","example":"That's a sensible decision.","difficulty":3,"related":["sensitive"]},{"word":"sensitive","translation":"sensível","pos":"adjective","definition":"easily hurt or affected","example":"My skin is very sensitive.","difficulty":3},{"word":"college","translation":"faculdade","pos":"noun","definition":"a place for studies after high school","example":"She goes to college in Porto Alegre.","difficulty":2},{"word":"costume","translation":"fantasia","pos":"noun","definition":"clothes worn to look like someone else","example":"He wore a pirate costume.","difficulty":3,"related":["habit"]},{"word":"relatives","translation":"parentes","pos":"noun","definition":"people in your family","example":"All my relatives came to the party.","difficulty":2},{"word":"lecture","translation":"palestra","pos":"noun","definition":"a talk to teach people about a subject","example":"We attended a lecture about space.","difficulty":3}],"reading":{"title":"Lost in translation","genre":"relato","text":"On my first day in London, I wanted to buy a book, so I asked for the library. A kind woman sent me to a building full of people reading quietly — I had to borrow a book instead of buying one! Later, I told my host family that I “pretended” to visit Oxford. They looked confused. Actually, I meant that I intended to go. Eventually, I realized that some words are traps.","questions":[{"difficulty":1,"prompt":"Aonde a mulher mandou o autor?","options":["A uma livraria","A uma biblioteca","A uma faculdade","A um museu"],"answer":1,"explanation":"Library = biblioteca."},{"difficulty":2,"prompt":"Por que a família ficou confusa?","options":["Porque ele disse que fingiu visitar Oxford","Porque ele não visitou Oxford","Porque ele falou português","Porque Oxford é longe"],"answer":0,"explanation":"Pretend = fingir; ele queria dizer intend."},{"difficulty":3,"prompt":"Qual é a ideia principal do texto?","options":["Londres é cara","Falsos cognatos podem causar mal-entendidos","Bibliotecas são silenciosas","Oxford é uma cidade bonita"],"answer":1,"explanation":"O autor conta os mal-entendidos causados por falsos cognatos."}]},"challenge":"Crie uma frase-armadilha para um colega: use um falso cognato e veja se ele descobre o sentido real.","tips":["Desconfie das palavras que parecem fáceis demais.","Monte um caderno de “armadilhas” com a palavra, o sentido real e uma frase."]},"games":{"blanks":[{"difficulty":1,"sentence":"___ the door to open it. (empurre)","options":["Push","Pull","Press","Put"],"answer":0,"explanation":"Empurrar = push."},{"difficulty":2,"sentence":"___, I think you're right. (na verdade)","options":["Actually","Currently","Eventually","Nowadays"],"answer":0,"explanation":"Na verdade = actually."},{"difficulty":2,"sentence":"I ___ to be a doctor one day. (pretendo)","options":["intend","pretend","attend","realize"],"answer":0,"explanation":"Pretender = intend."},{"difficulty":3,"sentence":"She suddenly ___ that she had left her phone at home. (percebeu)","options":["realized","realized out","achieved","pretended"],"answer":0,"explanation":"Perceber = realize."},{"difficulty":3,"sentence":"Be careful with your words: he's very ___. (sensível)","options":["sensitive","sensible","sensual","sense"],"answer":0,"explanation":"Sensível = sensitive."}],"sequences":[{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["Currently","I","live","in","Natal"],"words":true,"explanation":"Atualmente = currently."}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-b1-collocations","subject":"ingles","title":"Collocations","levels":["fund2","medio"],"grade":"9º ano e Ensino Médio","topic":"Inglês B1 — Inglês que soa natural","subtopic":"Combinações naturais de palavras","aliases":["collocations","colocacoes em ingles","make ou do","make a decision","do homework","take a photo","heavy rain","combinacoes de palavras"],"summary":"Descubra quais palavras “andam juntas” em inglês: make × do, take, pay, heavy, strong e highly.","intro":"Por que “make a decision” e não “do a decision”? Vamos soar natural.","objective":"Usar collocations frequentes com make, do, take e pay e combinações adjetivo + substantivo e advérbio + adjetivo, entendendo por que soam naturais.","prerequisites":["ing-b1-false-friends"],"next":["ing-b1-past-perfect"],"skills":{"v_what":"O que é collocation","v_makedo":"Make × do","v_takepay":"Take, pay, have","v_adj":"Adjetivo + substantivo e advérbio + adjetivo"},"blocks":[{"skill":"v_what","title":"What is a collocation?","text":"Collocation é uma combinação de palavras que os falantes usam juntas com frequência. Não é uma regra lógica: é costume da língua. Dizemos heavy rain (chuva forte), e não “strong rain”, e make a mistake (cometer um erro), e não “do a mistake”. Conhecer collocations faz o inglês soar natural.","example":"fast food (e não “quick food”) · a quick shower (e não “a fast shower”)","variants":{"simples":"Palavras que “andam juntas”. É o jeito que o nativo fala.","exemplo":"Em português falamos “tomar banho” e não “pegar banho”. Em inglês: take a shower.","passos":"1. Aprenda a expressão inteira, não a palavra solta. 2. Anote em blocos: make a decision. 3. Repare nelas em textos e séries.","compara":"Como no português “escovar os dentes” (e não “limpar os dentes com escova”): é o costume que decide."},"id":"b1"},{"skill":"v_makedo","title":"Make or do?","text":"Make costuma indicar criar, produzir: make a decision, make a mistake, make progress, make a plan, make noise, make friends, make money, make an effort. Do costuma indicar tarefas e atividades: do homework, do the dishes, do exercise, do a favor, do your best, do business, do research.","example":"I made a mistake on the test. · Can you do me a favor? · I do my homework after lunch.","variants":{"simples":"Make = criar/fazer algo novo. Do = realizar uma tarefa.","exemplo":"Sábado em casa: “I did the dishes, made a cake and made plans with my friends.”","passos":"1. É criar algo novo? make. 2. É cumprir uma tarefa/atividade? do. 3. Na dúvida, memorize a expressão.","compara":"As duas viram “fazer” em português. A diferença está no tipo de ação: make a cake (criar) × do the cooking (tarefa)."},"id":"b2"},{"skill":"v_takepay","title":"Take, pay and have","text":"Take: take a photo (tirar foto), take a shower, take a break (fazer uma pausa), take responsibility (assumir a responsabilidade), take notes, take a test. Pay: pay attention (prestar atenção), pay a visit (fazer uma visita), pay a compliment (fazer um elogio). Have: have lunch, have fun, have a good time.","example":"Please pay attention. · Let's take a break. · We had fun at the party.","variants":{"simples":"Take a photo = tirar foto. Pay attention = prestar atenção.","exemplo":"Professor: “Take notes and pay attention to the examples.”","passos":"1. Veja o substantivo. 2. Lembre o verbo que o acompanha. 3. Pratique em frases suas.","compara":"Em português: “prestar atenção”; em inglês: PAY attention — como se a atenção fosse um pagamento."},"id":"b3"},{"skill":"v_adj","title":"Adjective + noun, adverb + adjective","text":"Adjetivo + substantivo: heavy rain / heavy traffic (forte, intenso), strong coffee / strong argument, high price, deep sleep, close friend (amigo próximo). Advérbio + adjetivo: highly recommended (altamente recomendado), deeply sorry, bitterly cold, fully aware (totalmente ciente).","example":"There was heavy traffic this morning. · This book is highly recommended.","variants":{"simples":"Heavy rain = chuva forte. Close friend = amigo próximo.","exemplo":"Resenha: “The movie is highly recommended, with a strong story.”","passos":"1. Para intensidade de fenômenos: heavy. 2. Para café/argumento: strong. 3. Para recomendação: highly.","compara":"“Strong” e “heavy” podem ser “forte” em português, mas não são trocáveis: strong coffee × heavy rain."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"v_makedo","prompt":"I need to ___ a decision.","options":["do","make","take","have"],"answer":1,"hints":["Decisão = algo que você cria.","Collocation fixa.","Make a decision."],"explanation":"Make a decision.","id":"q1"},{"type":"mc","difficulty":1,"skill":"v_makedo","prompt":"Did you ___ your homework?","options":["make","do","take","pay"],"answer":1,"hints":["Homework é uma tarefa.","Tarefas usam…","Do."],"explanation":"Do your homework.","id":"q2"},{"type":"fill","difficulty":1,"skill":"v_takepay","prompt":"Complete: Please ___ attention to the teacher.","answers":["pay"],"hints":["Prestar atenção.","É como pagar.","P-a-y."],"explanation":"Pay attention.","id":"q3"},{"type":"tf","difficulty":1,"skill":"v_adj","prompt":"“Strong rain” é a forma mais natural para “chuva forte”.","answer":false,"hints":["Para chuva usamos outro adjetivo.","O mesmo de heavy traffic.","Heavy rain."],"explanation":"Falso: heavy rain.","id":"q4"},{"type":"match","difficulty":2,"skill":"v_takepay","prompt":"Ligue as collocations aos significados.","pairs":[["take a photo","tirar uma foto"],["take a break","fazer uma pausa"],["have fun","se divertir"],["pay a visit","fazer uma visita"]],"hints":["Take = tirar/pegar.","Break = intervalo.","Fun = diversão."],"explanation":"take a photo · take a break · have fun · pay a visit.","id":"q5"},{"type":"mc","difficulty":2,"skill":"v_makedo","prompt":"Qual está correta?","options":["do a mistake","make a mistake","take a mistake","have a mistake"],"answer":1,"hints":["Erro = algo que você cria.","Make…","Make a mistake."],"explanation":"Make a mistake.","id":"q6"},{"type":"mc","difficulty":2,"skill":"v_adj","prompt":"Hotel review: “The staff was friendly. Highly ___!”","options":["recommended","recommend","good","cheap"],"answer":0,"hints":["Advérbio + adjetivo.","Altamente recomendado.","Recommended."],"explanation":"Highly recommended.","id":"q7"},{"type":"mc","difficulty":2,"skill":"v_takepay","prompt":"The manager must ___ responsibility for the problem.","options":["make","do","take","pay"],"answer":2,"hints":["Assumir a responsabilidade.","Take…","Take responsibility."],"explanation":"Take responsibility.","id":"q8"},{"type":"order","difficulty":3,"skill":"v_makedo","prompt":"Organize: “Ela está progredindo muito no inglês.”","items":["She","is","making","great","progress","in","English"],"hints":["Progress usa make.","Present continuous.","Great antes de progress."],"explanation":"She is making great progress in English.","id":"q9"},{"type":"mc","difficulty":3,"skill":"v_adj","prompt":"Escolha a combinação mais natural: “We had a ___ argument about the project, but we are still ___ friends.”","options":["heavy / near","strong / close","high / deep","big / next"],"answer":1,"hints":["Argumento forte: strong.","Amigo próximo: close.","Strong / close."],"explanation":"strong argument · close friends.","id":"q10"}],"review":["Collocation = palavras que andam juntas (costume da língua)","make: decision, mistake, progress, friends · do: homework, the dishes, a favor","take a photo/break/responsibility · pay attention","heavy rain · strong coffee · close friend · highly recommended"],"relatedQuestions":["o que são collocations","diferença entre make e do","como falar inglês natural"],"equivalentQuestions":["quando usar make e quando usar do","como se diz tomar uma decisão em inglês","como dizer prestar atenção em inglês","por que é heavy rain","o que significa highly recommended","como se diz tirar foto em inglês","do homework ou make homework","o que é collocations","como usar collocations","me explica collocations","quando usar collocations","exemplos de collocations","collocations em inglês","como funciona collocations","regras de collocations","exercícios de collocations","aula de collocations","não entendi collocations","collocations para iniciantes","resumo de collocations","dúvida sobre collocations","o que é make e do","como usar make e do","me explica make e do","quando usar make e do","exemplos de make e do","make e do em inglês","como funciona make e do","regras de make e do","exercícios de make e do","aula de make e do","não entendi make e do","make e do para iniciantes","resumo de make e do","dúvida sobre make e do"],"commonErrors":["Do a mistake / make homework.","Strong rain / heavy coffee.","Traduzir “tirar foto” como “remove a photo”."],"english":{"cefr":"B1","unit":"b1-u4","order":2,"area":"vocabulary","focus":["vocabulary","writing"],"vocabulary":[{"word":"make a decision","translation":"tomar uma decisão","pos":"phrase","definition":"to decide something","example":"It's time to make a decision.","difficulty":1},{"word":"make a mistake","translation":"cometer um erro","pos":"phrase","definition":"to do something wrong","example":"Everybody makes mistakes.","difficulty":1},{"word":"make progress","translation":"progredir","pos":"phrase","definition":"to improve over time","example":"You're making progress!","difficulty":2},{"word":"do homework","translation":"fazer a lição de casa","pos":"phrase","definition":"to complete school tasks at home","example":"I do my homework at night.","difficulty":1},{"word":"do a favor","translation":"fazer um favor","pos":"phrase","definition":"to help someone","example":"Can you do me a favor?","difficulty":2},{"word":"take a break","translation":"fazer uma pausa","pos":"phrase","definition":"to stop for a short rest","example":"Let's take a break.","difficulty":1},{"word":"take responsibility","translation":"assumir a responsabilidade","pos":"phrase","definition":"to accept that you must deal with something","example":"He took responsibility for the error.","difficulty":3},{"word":"pay attention","translation":"prestar atenção","pos":"phrase","definition":"to watch or listen carefully","example":"Pay attention to the details.","difficulty":1},{"word":"heavy rain","translation":"chuva forte","pos":"phrase","definition":"a lot of rain","example":"Heavy rain is expected tonight.","difficulty":2},{"word":"strong argument","translation":"argumento forte","pos":"phrase","definition":"a reason that convinces people","example":"She has a strong argument.","difficulty":3},{"word":"highly recommended","translation":"altamente recomendado","pos":"phrase","definition":"praised a lot","example":"This book is highly recommended.","difficulty":2},{"word":"close friend","translation":"amigo próximo","pos":"phrase","definition":"a friend you know very well","example":"Lia is my close friend.","difficulty":2}],"writing":{"prompt":"Escreva uma resenha curta de um filme, série ou jogo usando pelo menos 4 collocations desta aula.","criteria":["4 collocations corretas","Opinião clara","Recomendação no final"],"model":"I watched a series about a detective. He makes a lot of mistakes, but he takes responsibility and makes progress in every episode. Pay attention to the last episode! Highly recommended.","keywords":["make","take","pay","highly"],"minWords":30},"challenge":"Durante um dia, anote 5 collocations que você ouvir ou ler em inglês (música, jogo, série).","tips":["Aprenda a combinação inteira: “make a decision”, não só “decision”.","Dicionários de collocations mostram quais palavras costumam andar juntas."]},"games":{"blanks":[{"difficulty":1,"sentence":"Can you ___ me a favor?","options":["do","make","take","pay"],"answer":0,"explanation":"Do a favor."},{"difficulty":1,"sentence":"Let's ___ a photo!","options":["take","make","do","have"],"answer":0,"explanation":"Take a photo."},{"difficulty":2,"sentence":"There was ___ traffic on the way to school.","options":["heavy","strong","big","high"],"answer":0,"explanation":"Heavy traffic."},{"difficulty":2,"sentence":"I always ___ the dishes after dinner.","options":["do","make","take","have"],"answer":0,"explanation":"Do the dishes."},{"difficulty":3,"sentence":"We are ___ aware of the risks.","options":["fully","heavily","strongly","highly done"],"answer":0,"explanation":"Fully aware = totalmente ciente."}],"pairs":[{"a":"make","b":"a decision","difficulty":1},{"a":"do","b":"homework","difficulty":1},{"a":"take","b":"a break","difficulty":1},{"a":"pay","b":"attention","difficulty":1}],"sequences":[{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["I","made","a","mistake","on","the","test"],"words":true,"explanation":"Make a mistake."}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-b2-passive","subject":"ingles","title":"Passive voice","levels":["medio"],"grade":"Ensino Médio","topic":"Inglês B2 — Como a informação é contada","subtopic":"Voz passiva nos principais tempos","aliases":["passive voice","voz passiva em ingles","passiva","was made","is made","be particípio","by agent","voz passiva ingles enem"],"summary":"Destaque a ação ou o resultado, e não quem fez: be + particípio nos principais tempos verbais.","intro":"The Mona Lisa was painted by Leonardo da Vinci. Quando o foco é o resultado, usamos a voz passiva.","objective":"Transformar frases da voz ativa para a passiva nos principais tempos, decidir quando usar o agente (by…) e reconhecer a passiva em notícias e textos científicos.","prerequisites":["ing-b1-present-perfect","ing-a2-simple-past"],"next":["ing-b2-reported-speech"],"skills":{"g_form":"Be + particípio","g_tenses":"A passiva em vários tempos","g_by":"Quando usar “by”","r_use":"A passiva em notícias e ciência"},"blocks":[{"skill":"g_form","title":"be + past participle","text":"Na voz ativa, o sujeito faz a ação (People speak English here). Na passiva, o foco vai para quem RECEBE a ação: o objeto vira sujeito + be (no tempo certo) + particípio (English is spoken here). O verbo be carrega o tempo; o particípio não muda.","example":"Active: Someone stole my bike. → Passive: My bike was stolen.","variants":{"simples":"Passiva = “foi feito”, “é feito”: The cake was made (o bolo foi feito).","exemplo":"Aviso numa loja: “Credit cards are accepted.”","passos":"1. Pegue o objeto da ativa e coloque como sujeito. 2. Use be no mesmo tempo do verbo original. 3. Coloque o particípio.","compara":"Em português também temos: “O bolo foi feito pela minha avó” (passiva) × “Minha avó fez o bolo” (ativa)."},"id":"b1"},{"skill":"g_tenses","title":"Passive in different tenses","text":"Simple present: is/are made · Simple past: was/were made · Present continuous: is/are being made · Present perfect: has/have been made · Future: will be made · Modais: can/must/should be made. Negativa e pergunta seguem o verbo be: wasn't made, Has it been sent?","example":"The results will be announced tomorrow. · The road is being repaired. · Three new species have been discovered.","variants":{"simples":"O be muda de tempo: is, was, has been, will be… o particípio fica igual.","exemplo":"E-mail de escola: “Your application has been received and will be reviewed this week.”","passos":"1. Descubra o tempo da ativa. 2. Coloque be nesse tempo. 3. Particípio.","compara":"Present continuous na passiva precisa de “being”: The house is being painted (está sendo pintada)."},"id":"b2"},{"skill":"g_by","title":"When do we use “by”?","text":"Usamos by + agente só quando quem fez é importante ou novidade: Hamlet was written by Shakespeare. Omitimos o agente quando ele é óbvio, desconhecido ou irrelevante: My phone was stolen (não sei por quem). Rice is grown in many countries (por agricultores — óbvio).","example":"The telephone was invented by Graham Bell. · The window was broken last night.","variants":{"simples":"By = por (quem fez). Só coloque se for importante.","exemplo":"Manchete: “Thief arrested” (preso — pela polícia, é óbvio).","passos":"1. Quem fez importa? 2. Se sim, by + agente. 3. Se é óbvio ou desconhecido, omita.","compara":"Em português falamos “foi preso” sem dizer “pela polícia” pelo mesmo motivo: é óbvio."},"id":"b3"},{"skill":"r_use","title":"Passive in news and science","text":"A voz passiva é muito comum em notícias (manchetes costumam cortar o be: “Bridge closed after storm”) e em textos científicos e acadêmicos, que valorizam o processo e o resultado: The samples were analyzed… It is believed that… Reconhecer a passiva ajuda a entender quem fez o quê numa prova de interpretação.","example":"The data were collected in 2023. · It is estimated that 1 billion people…","variants":{"simples":"Notícias e ciência usam muito a passiva porque o foco é o fato.","exemplo":"Questão de prova: “According to the text, the vaccine was developed by…” — procure o agente depois de by.","passos":"1. Encontre be + particípio. 2. Pergunte: quem fez? (procure by). 3. Se não houver agente, o texto não diz quem fez.","compara":"“It is said that…” (diz-se que) e “He is believed to be…” (acredita-se que ele seja) são passivas impessoais típicas de textos formais."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"g_form","prompt":"English ___ in many countries.","options":["speaks","is spoken","is speaking","spoken"],"answer":1,"hints":["Quem fala não é o inglês.","Voz passiva.","Is + particípio."],"explanation":"English is spoken…","id":"q1"},{"type":"mc","difficulty":1,"skill":"g_tenses","prompt":"The Mona Lisa ___ by Leonardo da Vinci.","options":["painted","is painting","was painted","has painted"],"answer":2,"hints":["Fato do passado.","Passiva no passado.","Was + particípio."],"explanation":"Was painted.","id":"q2"},{"type":"fill","difficulty":1,"skill":"g_form","prompt":"Complete: My bike was ___ last night. (steal)","answers":["stolen"],"hints":["Particípio de steal.","steal-stole-…","Stolen."],"explanation":"Was stolen.","id":"q3"},{"type":"tf","difficulty":1,"skill":"g_by","prompt":"Na passiva, o agente (by…) sempre precisa aparecer.","answer":false,"hints":["Pense em “my phone was stolen”.","Às vezes não sabemos quem fez.","Só quando é importante."],"explanation":"Falso: omitimos quando é óbvio, desconhecido ou irrelevante.","id":"q4"},{"type":"match","difficulty":2,"skill":"g_tenses","prompt":"Ligue o tempo à forma passiva de “make”.","pairs":[["simple present","is made"],["simple past","was made"],["present perfect","has been made"],["future (will)","will be made"]],"hints":["Presente: is.","Passado: was.","Perfect: has been · futuro: will be."],"explanation":"is made · was made · has been made · will be made.","id":"q5"},{"type":"mc","difficulty":2,"skill":"g_tenses","prompt":"The road is closed because it ___.","options":["is repairing","is being repaired","repairs","has repaired"],"answer":1,"hints":["Está acontecendo agora.","Passiva no present continuous.","Is being + particípio."],"explanation":"Is being repaired.","id":"q6"},{"type":"mc","difficulty":2,"skill":"g_tenses","prompt":"Passe para a passiva: “They will announce the results tomorrow.”","options":["The results will announce tomorrow.","The results will be announced tomorrow.","The results are announced tomorrow.","The results will been announced tomorrow."],"answer":1,"hints":["Futuro com will.","Will be + particípio.","Announced."],"explanation":"The results will be announced tomorrow.","id":"q7"},{"type":"mc","difficulty":2,"skill":"r_use","prompt":"Na manchete “Three suspects arrested in São Paulo”, o que foi omitido?","options":["O verbo be (were)","O particípio","O sujeito","Nada"],"answer":0,"hints":["Manchetes cortam palavras.","Qual verbo falta antes de arrested?","Were."],"explanation":"Manchetes cortam o be: Three suspects (were) arrested.","id":"q8"},{"type":"order","difficulty":3,"skill":"g_tenses","prompt":"Organize: “Novas espécies foram descobertas na Amazônia.”","items":["New","species","have","been","discovered","in","the","Amazon"],"hints":["Present perfect na passiva.","Have been + particípio.","Lugar no final."],"explanation":"New species have been discovered in the Amazon.","id":"q9"},{"type":"mc","difficulty":3,"skill":"r_use","prompt":"“It is believed that the city was founded in 1554.” O que a frase indica?","options":["O autor tem certeza absoluta","É uma crença geral, apresentada de forma impessoal","O autor fundou a cidade","A cidade será fundada"],"answer":1,"hints":["“It is believed” = acredita-se.","Não diz quem acredita.","É impessoal."],"explanation":"Passiva impessoal: acredita-se que…","id":"q10"}],"review":["Passiva = be (no tempo certo) + particípio","is made · was made · is being made · has been made · will be made","By + agente só quando importa","Comum em notícias e textos científicos; manchetes cortam o be"],"relatedQuestions":["como formar a voz passiva em inglês","quando usar a voz passiva","passiva no present perfect"],"equivalentQuestions":["como passar da ativa para a passiva em inglês","quando usar by na passiva","o que é is being made","passiva no futuro em inglês","o que significa it is believed that","por que manchetes não têm verbo to be","voz passiva no enem","o que é voz passiva","como usar voz passiva","me explica voz passiva","quando usar voz passiva","exemplos de voz passiva","voz passiva em inglês","como funciona voz passiva","regras de voz passiva","exercícios de voz passiva","aula de voz passiva","não entendi voz passiva","voz passiva para iniciantes","resumo de voz passiva","dúvida sobre voz passiva","o que é passive voice","como usar passive voice","me explica passive voice","quando usar passive voice","exemplos de passive voice","passive voice em inglês","como funciona passive voice","regras de passive voice","exercícios de passive voice","aula de passive voice","não entendi passive voice","passive voice para iniciantes","resumo de passive voice","dúvida sobre passive voice"],"commonErrors":["Esquecer o be (The cake made by my mom).","Usar o passado no lugar do particípio (was stole).","Colocar sempre o agente, mesmo óbvio."],"english":{"cefr":"B2","unit":"b2-u1","order":1,"area":"grammar","focus":["grammar","reading"],"vocabulary":[{"word":"invent","translation":"inventar","pos":"verb","definition":"to create something new","example":"The telephone was invented in the 19th century.","difficulty":2},{"word":"discover","translation":"descobrir","pos":"verb","definition":"to find something for the first time","example":"A new planet was discovered.","difficulty":2},{"word":"arrest","translation":"prender (polícia)","pos":"verb","definition":"when the police take someone to the station","example":"Two men were arrested.","difficulty":2},{"word":"found","translation":"fundar","pos":"verb","definition":"to start a city or organization","example":"The company was founded in 1998.","difficulty":3},{"word":"announce","translation":"anunciar","pos":"verb","definition":"to tell people officially","example":"The winner will be announced today.","difficulty":2},{"word":"grow","translation":"cultivar / crescer","pos":"verb","definition":"to produce plants","example":"Coffee is grown in Minas Gerais.","difficulty":2},{"word":"survey","translation":"pesquisa (de opinião)","pos":"noun","definition":"a set of questions asked to many people","example":"The survey was answered by 500 students.","difficulty":3},{"word":"data","translation":"dados","pos":"noun","definition":"facts and numbers collected for analysis","example":"The data were analyzed carefully.","difficulty":3}],"grammar":{"name":"Passive voice","when":"Quando o foco é a ação ou o resultado, não quem fez.","structure":"objeto → sujeito + be (tempo) + particípio (+ by agente)","affirmative":["Coffee is grown here.","The bridge was built in 1990.","The results will be published."],"negative":["The email wasn't sent.","It hasn't been decided yet."],"interrogative":["Was it made in Brazil?","Has the package been delivered?"],"compare":"Active: The police arrested him (foco na polícia) × Passive: He was arrested (foco nele).","context":"Ler notícias e artigos científicos."},"reading":{"title":"Ancient city found under the forest","genre":"notícia adaptada","text":"A group of ancient settlements has been identified in the Amazon rainforest. The structures were detected with laser technology from airplanes, which allowed researchers to \"see\" through the trees. It is estimated that the area was occupied for more than a thousand years. The findings were published in a scientific journal and will be studied by teams from several countries.","questions":[{"difficulty":2,"prompt":"Como as estruturas foram detectadas?","options":["Por escavações","Com tecnologia a laser a partir de aviões","Por satélites comuns","Por moradores locais"],"answer":1,"explanation":"“detected with laser technology from airplanes”."},{"difficulty":2,"prompt":"Por quanto tempo se estima que a área foi ocupada?","options":["Menos de cem anos","Mais de mil anos","Dez mil anos exatos","O texto não diz"],"answer":1,"explanation":"“It is estimated that the area was occupied for more than a thousand years.”"},{"difficulty":3,"prompt":"O que vai acontecer com as descobertas?","options":["Serão destruídas","Serão estudadas por equipes de vários países","Serão vendidas","Serão escondidas"],"answer":1,"explanation":"“will be studied by teams from several countries”."},{"difficulty":3,"prompt":"Por que o texto usa tanto a voz passiva?","options":["Porque é uma história de ficção","Porque o foco está nas descobertas, não em quem as fez","Porque é uma carta pessoal","Porque não há verbos"],"answer":1,"explanation":"Textos científicos e notícias focam o fato e o processo."}]},"writing":{"prompt":"Escreva uma pequena notícia (3 a 5 frases) sobre algo que aconteceu na sua escola ou cidade usando pelo menos 3 verbos na voz passiva.","criteria":["Título no estilo manchete","3 passivas em tempos diferentes","Agente só quando importante"],"model":"New library opened downtown. The library was built in two years and was opened yesterday. More than 5,000 books have been donated. Free courses will be offered next month.","keywords":["was","been","will be","opened"],"minWords":30},"challenge":"Encontre 3 exemplos de voz passiva numa notícia em inglês e diga quem fez a ação (se o texto disser)."},"games":{"blanks":[{"difficulty":1,"sentence":"This bread ___ every morning.","options":["is baked","bakes","is baking","baked"],"answer":0,"explanation":"Presente passivo: is baked."},{"difficulty":2,"sentence":"The letter ___ yesterday.","options":["was sent","is sent","has sent","sent"],"answer":0,"explanation":"Passado passivo: was sent."},{"difficulty":2,"sentence":"A new school ___ next year.","options":["will be built","will build","is build","builds"],"answer":0,"explanation":"Futuro passivo: will be built."},{"difficulty":3,"sentence":"The house ___ at the moment.","options":["is being painted","is painting","is painted being","has painting"],"answer":0,"explanation":"Present continuous passivo."},{"difficulty":3,"sentence":"Hamlet was written ___ Shakespeare.","options":["by","for","from","of"],"answer":0,"explanation":"Agente: by."}],"sequences":[{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["The","window","was","broken","last","night"],"words":true,"explanation":"Passiva no passado sem agente."},{"difficulty":3,"prompt":"Organize a frase · Put the words in order","items":["The","results","will","be","announced","tomorrow"],"words":true,"explanation":"Passiva no futuro."}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-b2-reported-speech","subject":"ingles","title":"Reported speech","levels":["medio"],"grade":"Ensino Médio","topic":"Inglês B2 — Como a informação é contada","subtopic":"Discurso indireto: falas, perguntas e pedidos","aliases":["reported speech","discurso indireto em ingles","indirect speech","she said that","told me","reported questions","reported commands","say ou tell"],"summary":"Conte o que outra pessoa disse, perguntou ou pediu, com as mudanças de tempo, pronomes e expressões.","intro":"“I'm tired,” she said. → She said she was tired. Vamos relatar falas como jornalistas.","objective":"Transformar falas, perguntas e pedidos para o discurso indireto, fazendo o recuo dos tempos, as mudanças de pronomes e de expressões de tempo e usando say × tell corretamente.","prerequisites":["ing-b1-present-perfect"],"next":["ing-b2-relative-clauses"],"skills":{"g_back":"Recuo dos tempos (backshift)","g_saytell":"Say × tell e mudanças de pronomes e tempo","g_questions":"Perguntas relatadas","g_commands":"Pedidos e ordens relatados"},"blocks":[{"skill":"g_back","title":"Backshift","text":"Quando relatamos com um verbo no passado (said, told), os tempos da fala original geralmente “recuam” um passo: present → past (“I'm tired” → she said she was tired); present continuous → past continuous; present perfect/past → past perfect (“I saw it” → he said he had seen it); will → would; can → could. Se a fala ainda é verdade, o recuo é opcional: He said the Earth is round.","example":"“I love this song,” Ana said. → Ana said (that) she loved that song.","variants":{"simples":"Contando o que alguém disse, o verbo vai um passo para trás no tempo.","exemplo":"Fofoca do intervalo: “Leo said he was going to the party.”","passos":"1. Veja o tempo da fala original. 2. Recue um passo (am → was, will → would). 3. That é opcional.","compara":"Em português também fazemos: “Estou cansada” → Ela disse que estava cansada. O inglês segue a mesma lógica."},"id":"b1"},{"skill":"g_saytell","title":"Say or tell? Pronouns and time words","text":"Say + (that) + fala: She said (that)… Tell + pessoa + (that): She told me (that)… (tell precisa de quem ouviu). Pronomes e referências mudam conforme quem conta: “I'll call you” → She said she would call me. Tempo e lugar: now → then, today → that day, tomorrow → the next day, yesterday → the day before, here → there, this → that.","example":"“I'll finish it tomorrow,” he said. → He told me he would finish it the next day.","variants":{"simples":"Tell sempre com a pessoa: told me, told her. Say sem a pessoa: said that.","exemplo":"Relato: “My mom told me to be home by ten.”","passos":"1. Escolha say (sem pessoa) ou tell (com pessoa). 2. Ajuste os pronomes. 3. Ajuste as palavras de tempo e lugar.","compara":"“He said me” está errado. Diga “He told me” ou “He said to me” (menos comum)."},"id":"b2"},{"skill":"g_questions","title":"Reported questions","text":"Perguntas relatadas viram frases afirmativas (sem do/did e sem inverter): “Where do you live?” → She asked me where I lived. Perguntas de sim/não usam if ou whether: “Are you coming?” → He asked if I was coming.","example":"“What time is it?” → He asked what time it was. · “Did you like it?” → She asked whether I had liked it.","variants":{"simples":"Pergunta relatada tem a ordem de frase normal: asked where I lived.","exemplo":"Entrevista de emprego: “They asked me why I wanted the job.”","passos":"1. Asked (+ pessoa). 2. Palavra de pergunta ou if/whether. 3. Sujeito + verbo (recuado), sem ponto de interrogação.","compara":"Erro clássico: “She asked where did I live.” O certo é “She asked where I lived” — sem did."},"id":"b3"},{"skill":"g_commands","title":"Reported commands and requests","text":"Ordens e pedidos: tell/ask + pessoa + to + verbo: “Sit down!” → The teacher told us to sit down. “Could you help me?” → She asked me to help her. Negativo: not to: “Don't be late!” → He told me not to be late.","example":"“Please turn off your phones.” → They asked us to turn off our phones.","variants":{"simples":"Pedido relatado = asked me to + verbo. Ordem = told me to + verbo.","exemplo":"Recado: “Your dad asked you to call him back.”","passos":"1. Ordem → told; pedido → asked. 2. Pessoa. 3. To + verbo (ou not to + verbo).","compara":"Não use that nas ordens: “He told me to wait” (e não “He told me that wait”)."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"g_back","prompt":"“I am hungry,” Tom said. → Tom said he ___ hungry.","options":["is","was","has been","will be"],"answer":1,"hints":["Recuo do presente.","Am → …","Was."],"explanation":"Am → was.","id":"q1"},{"type":"mc","difficulty":1,"skill":"g_saytell","prompt":"She ___ me that she was busy.","options":["said","told","asked","spoke"],"answer":1,"hints":["Há uma pessoa depois (me).","Tell + pessoa.","Told."],"explanation":"Told me.","id":"q2"},{"type":"fill","difficulty":1,"skill":"g_back","prompt":"“I will help you.” → He said he ___ help me.","answers":["would"],"hints":["Will recua para…","Condicional.","W-o-u-l-d."],"explanation":"Will → would.","id":"q3"},{"type":"tf","difficulty":1,"skill":"g_questions","prompt":"“She asked me where did I live” está correto.","answer":false,"hints":["Pergunta relatada tem ordem de frase.","Sem did.","Where I lived."],"explanation":"Falso: She asked me where I lived.","id":"q4"},{"type":"match","difficulty":2,"skill":"g_saytell","prompt":"Ligue a expressão da fala original à forma relatada.","pairs":[["today","that day"],["tomorrow","the next day"],["yesterday","the day before"],["here","there"]],"hints":["Hoje → aquele dia.","Amanhã → o dia seguinte.","Ontem → o dia anterior."],"explanation":"today→that day · tomorrow→the next day · yesterday→the day before · here→there.","id":"q5"},{"type":"mc","difficulty":2,"skill":"g_questions","prompt":"“Are you coming to the party?” → She asked ___ I was coming to the party.","options":["that","if","what","did"],"answer":1,"hints":["Pergunta de sim/não.","Usa if ou whether.","If."],"explanation":"She asked if I was coming.","id":"q6"},{"type":"mc","difficulty":2,"skill":"g_commands","prompt":"“Don't touch the painting!” → The guide told us ___ the painting.","options":["don't touch","not to touch","to not touching","that not touch"],"answer":1,"hints":["Ordem negativa.","Not to + verbo.","Not to touch."],"explanation":"Told us not to touch.","id":"q7"},{"type":"mc","difficulty":2,"skill":"g_back","prompt":"“I have finished the project,” Mia said. → Mia said she ___ the project.","options":["has finished","had finished","finished have","was finish"],"answer":1,"hints":["Present perfect recua para…","Past perfect.","Had + particípio."],"explanation":"Had finished.","id":"q8"},{"type":"order","difficulty":3,"skill":"g_questions","prompt":"Organize: “Ele me perguntou por que eu estava triste.”","items":["He","asked","me","why","I","was","sad"],"hints":["Asked + pessoa.","Why + sujeito + verbo.","Sem inversão."],"explanation":"He asked me why I was sad.","id":"q9"},{"type":"mc","difficulty":3,"skill":"g_saytell","prompt":"“I'll call you tomorrow,” Leo told Ana on Monday. Na quarta, Ana conta:","options":["Leo said he will call you tomorrow.","Leo told me he would call me the next day.","Leo told me I would call him tomorrow.","Leo said me he would call."],"answer":1,"hints":["Tell + me.","I → he; you → me.","Will → would; tomorrow → the next day."],"explanation":"Leo told me he would call me the next day.","id":"q10"}],"review":["Recuo: am→was · will→would · can→could · saw/have seen→had seen","Say (that)… · tell + pessoa (that)…","Perguntas: asked where I lived · asked if/whether…","Ordens e pedidos: told/asked me (not) to + verbo"],"relatedQuestions":["como usar reported speech","diferença entre say e tell","como relatar uma pergunta em inglês"],"equivalentQuestions":["como transformar discurso direto em indireto em inglês","quando usar said e told","o que muda no reported speech","como relatar ordens em inglês","asked if ou asked that","will vira would no discurso indireto","tomorrow vira o que no reported speech","o que é reported speech","como usar reported speech","me explica reported speech","quando usar reported speech","exemplos de reported speech","reported speech em inglês","como funciona reported speech","regras de reported speech","exercícios de reported speech","aula de reported speech","não entendi reported speech","reported speech para iniciantes","resumo de reported speech","dúvida sobre reported speech","o que é discurso indireto","como usar discurso indireto","me explica discurso indireto","quando usar discurso indireto","exemplos de discurso indireto","discurso indireto em inglês","como funciona discurso indireto","regras de discurso indireto","exercícios de discurso indireto","aula de discurso indireto","não entendi discurso indireto","discurso indireto para iniciantes","resumo de discurso indireto","dúvida sobre discurso indireto"],"commonErrors":["“He said me…” (o certo é told me).","Manter a ordem de pergunta (asked where did I live).","Esquecer de ajustar pronomes e expressões de tempo."],"english":{"cefr":"B2","unit":"b2-u2","order":1,"area":"grammar","focus":["grammar","listening","writing"],"vocabulary":[{"word":"say","translation":"dizer","pos":"verb","definition":"to speak words (without the listener as object)","example":"She said that she was tired.","difficulty":1},{"word":"tell","translation":"contar / dizer (a alguém)","pos":"verb","definition":"to say something to someone","example":"He told me the truth.","difficulty":1},{"word":"ask","translation":"perguntar / pedir","pos":"verb","definition":"to put a question; to request","example":"She asked me to wait.","difficulty":1},{"word":"whether","translation":"se (em perguntas indiretas)","pos":"conjunction","definition":"used like “if” in reported questions","example":"He asked whether I was ready.","difficulty":3},{"word":"explain","translation":"explicar","pos":"verb","definition":"to make something clear","example":"The teacher explained that the test was easy.","difficulty":2},{"word":"complain","translation":"reclamar","pos":"verb","definition":"to say you are not happy with something","example":"They complained that the room was cold.","difficulty":3},{"word":"warn","translation":"avisar (de perigo)","pos":"verb","definition":"to tell someone about a danger","example":"She warned us not to swim there.","difficulty":3},{"word":"promise","translation":"prometer","pos":"verb","definition":"to say you will certainly do something","example":"He promised he would come.","difficulty":2}],"listening":{"title":"Voice note from a friend","kind":"texto","rate":0.95,"script":["Hi Sam! I talked to Ms. Rivera today.","She said the test was moved to Friday.","She told us to review chapters four and five.","She also asked if anyone needed extra help,","and she promised she would post the answers online."],"questions":[{"difficulty":2,"prompt":"O que aconteceu com a prova?","options":["Foi cancelada","Foi transferida para sexta","Será hoje","Ficou mais difícil"],"answer":1,"explanation":"“the test was moved to Friday”."},{"difficulty":2,"prompt":"O que a professora mandou os alunos fazerem?","options":["Revisar os capítulos 4 e 5","Ler o livro todo","Fazer um trabalho","Faltar à aula"],"answer":0,"explanation":"“told us to review chapters four and five”."},{"difficulty":3,"prompt":"O que a professora prometeu?","options":["Dar aula extra","Publicar as respostas online","Adiar de novo","Corrigir rápido"],"answer":1,"explanation":"“promised she would post the answers online”."}]},"writing":{"prompt":"Relate uma conversa curta que você teve hoje (ou invente uma) usando say, tell e ask no discurso indireto.","criteria":["Uma fala com said/told","Uma pergunta relatada","Um pedido ou ordem com to + verbo"],"model":"My friend told me she was nervous about the test. I asked her if she had studied. She said she had studied a lot. Then she asked me to help her with math.","keywords":["told","said","asked","if"],"minWords":30},"challenge":"Assista a 1 minuto de uma entrevista em inglês e relate duas coisas que a pessoa disse (He said that…)."},"games":{"blanks":[{"difficulty":1,"sentence":"“I'm happy.” → She said she ___ happy.","options":["was","is","were","be"],"answer":0,"explanation":"Am → was."},{"difficulty":2,"sentence":"He ___ me to close the door.","options":["asked","said","spoke","talked"],"answer":0,"explanation":"Pedido: asked me to."},{"difficulty":2,"sentence":"“Can you swim?” → She asked me if I ___ swim.","options":["could","can","will","do"],"answer":0,"explanation":"Can → could."},{"difficulty":3,"sentence":"“Where is the station?” → He asked where the station ___.","options":["was","is it","did be","were it"],"answer":0,"explanation":"Ordem de frase + recuo."},{"difficulty":3,"sentence":"The doctor told me ___ so much sugar.","options":["not to eat","don't eat","to not eating","not eat"],"answer":0,"explanation":"Ordem negativa: not to + verbo."}],"sequences":[{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["She","told","me","she","was","tired"],"words":true,"explanation":"Tell + pessoa + fala recuada."},{"difficulty":3,"prompt":"Organize a frase · Put the words in order","items":["He","asked","me","where","I","lived"],"words":true,"explanation":"Pergunta relatada: ordem de frase."}],"dialogues":[{"difficulty":3,"title":"Recado","gap":3,"options":["He asked me to arrive early.","He asked me arrive early.","He said me to arrive early.","He asked that I to arrive."],"answer":0,"explanation":"Pedido relatado: asked me to + verbo.","lines":[{"who":"Mom","text":"Did your coach call?"},{"who":"Rui","text":"Yes. He told me the game was on Sunday."},{"who":"Mom","text":"What else did he say?"},{"who":"Rui","text":"He asked me to arrive early."}]}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-b2-idioms","subject":"ingles","title":"Idioms","levels":["medio"],"grade":"Ensino Médio","topic":"Inglês B2 — Nuances","subtopic":"Expressões idiomáticas do dia a dia","aliases":["idioms","expressoes idiomaticas em ingles","piece of cake","break the ice","under the weather","once in a blue moon","cost an arm and a leg","hit the nail on the head","girias em ingles"],"summary":"Entenda e use expressões idiomáticas comuns, sabendo o contexto certo — e quando evitá-las.","intro":"This test was a piece of cake! Idioms dizem uma coisa com outras palavras.","objective":"Reconhecer o sentido de idioms comuns pelo contexto, relacioná-los a equivalentes aproximados em português e decidir quando usá-los ou evitá-los.","prerequisites":["ing-b1-phrasal-verbs","ing-b1-collocations"],"next":["ing-b2-modal-perfect"],"skills":{"v_what":"O que é um idiom","v_daily":"Idioms de situações do dia a dia","v_money":"Idioms de dinheiro, tempo e acerto","v_when":"Quando usar e quando evitar"},"blocks":[{"skill":"v_what","title":"What is an idiom?","text":"Idiom é uma expressão cujo sentido NÃO é a soma das palavras. “It's a piece of cake” não fala de bolo: significa que algo é muito fácil. Por isso, idioms são entendidos pelo contexto e, muitas vezes, têm um equivalente aproximado em português (não uma tradução literal).","example":"The exam was a piece of cake. = A prova foi moleza.","variants":{"simples":"Idiom = frase com sentido figurado. Não traduza palavra por palavra.","exemplo":"Na série, alguém diz “Break a leg!” antes de uma peça — é “boa sorte!”, não “quebre a perna”.","passos":"1. Perceba que o sentido literal não faz sentido. 2. Olhe a situação. 3. Procure o equivalente em português.","compara":"O português também tem: “chutar o balde”, “pagar o pato”. Um estrangeiro também não entenderia literalmente."},"id":"b1"},{"skill":"v_daily","title":"Everyday idioms","text":"break the ice = quebrar o gelo (começar uma conversa num clima tenso ou novo) · under the weather = meio doente, indisposto · piece of cake = moleza, muito fácil · once in a blue moon = muito raramente (“uma vez na vida, outra na morte”) · on cloud nine = nas nuvens (muito feliz) · let the cat out of the bag = deixar escapar um segredo.","example":"I'm a bit under the weather today. · We only eat out once in a blue moon.","variants":{"simples":"Under the weather = meio doente. Once in a blue moon = quase nunca.","exemplo":"Primeiro dia no curso: o professor faz um jogo para break the ice.","passos":"1. Aprenda o idiom com uma situação. 2. Diga o equivalente em português. 3. Use numa frase sua.","compara":"Break the ice existe quase igual em português (“quebrar o gelo”), mas under the weather não: seria “estar meio indisposto”."},"id":"b2"},{"skill":"v_money","title":"Money, time and getting it right","text":"cost an arm and a leg = custar os olhos da cara · hit the nail on the head = acertar em cheio, dizer exatamente o ponto certo · beat around the bush = enrolar, fazer rodeios · call it a day = encerrar por hoje · in the same boat = no mesmo barco (na mesma situação) · the ball is in your court = agora é com você (a decisão é sua).","example":"That phone costs an arm and a leg! · You hit the nail on the head. · Let's call it a day.","variants":{"simples":"Cost an arm and a leg = muito caro. Hit the nail on the head = acertou em cheio.","exemplo":"Reunião de grupo: “Stop beating around the bush and tell us your idea!”","passos":"1. Relacione cada idiom a uma imagem mental. 2. Associe ao equivalente em português. 3. Treine com o jogo da memória.","compara":"Cost an arm and a leg (inglês) × custar os olhos da cara (português): as duas línguas usam partes do corpo para falar de algo muito caro."},"id":"b3"},{"skill":"v_when","title":"When to use — and when not to","text":"Idioms deixam a fala natural e expressiva em conversas informais, mensagens, redes sociais e textos criativos. Em textos acadêmicos, formais ou provas de redação, prefira linguagem direta: em vez de “The plan cost an arm and a leg”, escreva “The plan was extremely expensive”. Cuidado também com idioms datados ou muito regionais.","example":"Informal: “That exam was a piece of cake!” · Formal: “The exam was not demanding.”","variants":{"simples":"Conversa com amigos: pode usar. Texto formal: melhor evitar.","exemplo":"E-mail para um professor: “The task was quite easy” (e não “a piece of cake”).","passos":"1. Veja com quem você fala e o tipo de texto. 2. Informal → idiom pode ajudar. 3. Formal → linguagem direta.","compara":"É como no português: “foi moleza” é ótimo com colegas, mas não numa carta formal."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"v_what","prompt":"“The test was a piece of cake” significa que a prova foi:","options":["difícil","muito fácil","longa","deliciosa"],"answer":1,"hints":["Não é sobre comida.","Sentido figurado.","Moleza."],"explanation":"Piece of cake = muito fácil.","id":"q1"},{"type":"mc","difficulty":1,"skill":"v_daily","prompt":"I'm feeling ___ today, so I'll stay home.","options":["on cloud nine","under the weather","a piece of cake","in the same boat"],"answer":1,"hints":["A pessoa vai ficar em casa.","Está meio doente.","Under the weather."],"explanation":"Under the weather = indisposto.","id":"q2"},{"type":"fill","difficulty":1,"skill":"v_daily","prompt":"Complete: Let's play a game to break the ___.","answers":["ice"],"hints":["Quebrar o…","Algo frio.","Ice."],"explanation":"Break the ice.","id":"q3"},{"type":"tf","difficulty":1,"skill":"v_money","prompt":"“It costs an arm and a leg” quer dizer que algo é muito caro.","answer":true,"hints":["Pense em “os olhos da cara”.","Partes do corpo.","Muito caro."],"explanation":"Verdadeiro.","id":"q4"},{"type":"match","difficulty":2,"skill":"v_money","prompt":"Ligue o idiom ao equivalente aproximado em português.","pairs":[["hit the nail on the head","acertar em cheio"],["beat around the bush","enrolar, fazer rodeios"],["call it a day","encerrar por hoje"],["in the same boat","na mesma situação"]],"hints":["Nail = prego: acertar o prego.","Bush = arbusto: dar voltas.","Call it a day = dar o dia por encerrado."],"explanation":"acertar em cheio · enrolar · encerrar por hoje · na mesma situação.","id":"q5"},{"type":"mc","difficulty":2,"skill":"v_daily","prompt":"We go to the theater ___ — maybe once every two years.","options":["on cloud nine","once in a blue moon","under the weather","a piece of cake"],"answer":1,"hints":["Muito raramente.","A cada dois anos.","Once in a blue moon."],"explanation":"Once in a blue moon = muito raramente.","id":"q6"},{"type":"mc","difficulty":2,"skill":"v_when","prompt":"Em qual texto é melhor EVITAR “It cost an arm and a leg”?","options":["Mensagem para um amigo","Post informal","Artigo acadêmico","Conversa no intervalo"],"answer":2,"hints":["Idioms são informais.","Texto formal pede linguagem direta.","Artigo acadêmico."],"explanation":"Em textos acadêmicos, prefira “extremely expensive”.","id":"q7"},{"type":"mc","difficulty":2,"skill":"v_money","prompt":"Ana explicou o problema exatamente como ele era. Você diz: “You ___!”","options":["hit the nail on the head","beat around the bush","let the cat out of the bag","broke the ice"],"answer":0,"hints":["Ela acertou o ponto.","Acertar em cheio.","Hit the nail on the head."],"explanation":"Hit the nail on the head = acertou em cheio.","id":"q8"},{"type":"order","difficulty":3,"skill":"v_money","prompt":"Organize: “Agora é com você.”","items":["The","ball","is","in","your","court"],"hints":["A bola…","…está na sua quadra.","Court no final."],"explanation":"The ball is in your court.","id":"q9"},{"type":"mc","difficulty":3,"skill":"v_daily","prompt":"“Tom let the cat out of the bag about the surprise party.” O que aconteceu?","options":["Tom soltou um gato na festa","Tom deixou escapar o segredo da festa surpresa","Tom organizou a festa","Tom perdeu o gato"],"answer":1,"hints":["Sentido figurado.","Relacionado a um segredo.","Revelou sem querer."],"explanation":"Let the cat out of the bag = deixar escapar um segredo.","id":"q10"}],"review":["Idiom = sentido figurado; entenda pelo contexto","piece of cake · under the weather · break the ice · once in a blue moon","cost an arm and a leg · hit the nail on the head · beat around the bush · call it a day","Informal: sim · textos acadêmicos e formais: evite"],"relatedQuestions":["expressões idiomáticas em inglês","o que significa piece of cake","o que significa under the weather"],"equivalentQuestions":["o que significa break the ice","o que significa once in a blue moon","o que significa cost an arm and a leg","o que significa hit the nail on the head","o que significa beat around the bush","posso usar idioms na redação","o que significa break a leg","o que é idioms","como usar idioms","me explica idioms","quando usar idioms","exemplos de idioms","idioms em inglês","como funciona idioms","regras de idioms","exercícios de idioms","aula de idioms","não entendi idioms","idioms para iniciantes","resumo de idioms","dúvida sobre idioms","o que é expressões idiomáticas","como usar expressões idiomáticas","me explica expressões idiomáticas","quando usar expressões idiomáticas","exemplos de expressões idiomáticas","expressões idiomáticas em inglês","como funciona expressões idiomáticas","regras de expressões idiomáticas","exercícios de expressões idiomáticas","aula de expressões idiomáticas","não entendi expressões idiomáticas","expressões idiomáticas para iniciantes","resumo de expressões idiomáticas","dúvida sobre expressões idiomáticas"],"commonErrors":["Traduzir idioms palavra por palavra.","Usar idioms em textos acadêmicos.","Misturar partes de idioms diferentes."],"english":{"cefr":"B2","unit":"b2-u3","order":1,"area":"vocabulary","focus":["vocabulary","reading","speaking"],"vocabulary":[{"word":"piece of cake","translation":"moleza","pos":"idiom","definition":"something very easy","example":"The quiz was a piece of cake.","difficulty":1},{"word":"break the ice","translation":"quebrar o gelo","pos":"idiom","definition":"to make people feel relaxed in a new situation","example":"He told a joke to break the ice.","difficulty":1},{"word":"under the weather","translation":"indisposto, meio doente","pos":"idiom","definition":"feeling a little sick","example":"I'm a bit under the weather.","difficulty":2},{"word":"once in a blue moon","translation":"muito raramente","pos":"idiom","definition":"very rarely","example":"I eat fast food once in a blue moon.","difficulty":2},{"word":"cost an arm and a leg","translation":"custar os olhos da cara","pos":"idiom","definition":"to be very expensive","example":"Concert tickets cost an arm and a leg.","difficulty":2},{"word":"hit the nail on the head","translation":"acertar em cheio","pos":"idiom","definition":"to describe exactly the right thing","example":"You hit the nail on the head.","difficulty":3},{"word":"beat around the bush","translation":"enrolar, fazer rodeios","pos":"idiom","definition":"to avoid saying something directly","example":"Don't beat around the bush.","difficulty":3},{"word":"call it a day","translation":"encerrar por hoje","pos":"idiom","definition":"to stop working for the day","example":"It's late, let's call it a day.","difficulty":2},{"word":"on cloud nine","translation":"nas nuvens (muito feliz)","pos":"idiom","definition":"extremely happy","example":"She was on cloud nine after the news.","difficulty":2},{"word":"let the cat out of the bag","translation":"deixar escapar um segredo","pos":"idiom","definition":"to reveal a secret by mistake","example":"Who let the cat out of the bag?","difficulty":3},{"word":"in the same boat","translation":"na mesma situação","pos":"idiom","definition":"in the same difficult situation","example":"Don't worry, we're all in the same boat.","difficulty":2}],"reading":{"title":"A group project","genre":"mensagens entre colegas","text":"Kai: Honestly, guys, the research part was a piece of cake. The hard part is the presentation.\nLua: I know. And the poster printing costs an arm and a leg!\nKai: Let's not beat around the bush: who is going to present?\nLua: I can start and break the ice with a quick question to the class.\nKai: You hit the nail on the head — that's a great way to start. OK, let's call it a day and meet tomorrow.","questions":[{"difficulty":2,"prompt":"Segundo Kai, qual parte foi fácil?","options":["A apresentação","A pesquisa","A impressão do pôster","Nenhuma"],"answer":1,"explanation":"“the research part was a piece of cake”."},{"difficulty":2,"prompt":"O que Lua diz sobre imprimir o pôster?","options":["É muito caro","É muito fácil","É rápido","É proibido"],"answer":0,"explanation":"“costs an arm and a leg” = muito caro."},{"difficulty":3,"prompt":"O que Kai quer dizer com “Let's not beat around the bush”?","options":["Vamos sair para passear","Vamos direto ao ponto","Vamos desistir","Vamos adiar"],"answer":1,"explanation":"Beat around the bush = enrolar; ele pede para ir direto ao ponto."},{"difficulty":3,"prompt":"Como Lua pretende começar a apresentação?","options":["Com uma piada","Com uma pergunta para a turma","Com um vídeo","Lendo o pôster"],"answer":1,"explanation":"“break the ice with a quick question to the class”."}]},"speaking":{"situation":"Você conta a um amigo como foi a sua semana usando idioms.","vocabulary":["piece of cake","under the weather","call it a day"],"phrases":["It was a piece of cake.","I was a bit under the weather.","After that, I called it a day."],"example":"On Monday I was under the weather, but the math test was a piece of cake!","challenge":"Use 3 idioms desta aula numa história curta sobre a sua semana.","expected":["piece","cake","weather","day"]},"challenge":"Encontre um idiom novo numa série ou música e descubra o sentido pelo contexto antes de pesquisar.","tips":["Aprenda idioms com uma situação real, não em listas.","Na dúvida sobre o nível de formalidade, prefira a linguagem direta."]},"games":{"blanks":[{"difficulty":1,"sentence":"Don't worry about the quiz, it's a ___ of cake.","options":["piece","slice","part","bit"],"answer":0,"explanation":"Piece of cake."},{"difficulty":2,"sentence":"These sneakers cost an arm and a ___!","options":["leg","foot","hand","head"],"answer":0,"explanation":"Cost an arm and a leg."},{"difficulty":2,"sentence":"I only see my cousins once in a blue ___.","options":["moon","sky","sun","day"],"answer":0,"explanation":"Once in a blue moon."},{"difficulty":3,"sentence":"Stop beating around the ___ and tell me the truth.","options":["bush","tree","house","garden"],"answer":0,"explanation":"Beat around the bush."},{"difficulty":3,"sentence":"We're all in the same ___, so let's help each other.","options":["boat","ship","car","bus"],"answer":0,"explanation":"In the same boat."}],"sequences":[{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["Let's","call","it","a","day"],"words":true,"explanation":"Encerrar por hoje."},{"difficulty":3,"prompt":"Organize a frase · Put the words in order","items":["You","hit","the","nail","on","the","head"],"words":true,"explanation":"Acertar em cheio."}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-c1-conditionals","subject":"ingles","title":"Third and mixed conditionals","levels":["medio"],"grade":"Ensino Médio e preparatório","topic":"Inglês C1 — Hipóteses e ênfase","subtopic":"Third conditional, mixed conditionals e inversão","aliases":["third conditional","mixed conditional","condicional mista","had known","would have","if i had","had i known","inversao condicional","wish past perfect"],"summary":"Imagine passados diferentes e suas consequências, misture tempos nas condicionais e use a inversão formal.","intro":"If I had studied more, I would have passed… Vamos falar do que poderia ter sido.","objective":"Usar o third conditional para passados imaginários, os mixed conditionals para ligar passado e presente, a inversão formal (Had I known…) e expressar arrependimento com wish/if only.","prerequisites":["ing-b1-conditionals","ing-b1-present-perfect"],"next":["ing-c1-inversion-cleft"],"skills":{"g_third":"Third conditional","g_mixed":"Mixed conditionals","g_inv":"Inversão formal (Had I…, Were I…, Should you…)","g_wish":"Wish / if only (arrependimento)"},"blocks":[{"skill":"g_third","title":"Third conditional","text":"Fala de um passado que NÃO aconteceu e sua consequência imaginária no passado: If + past perfect, would have + particípio. If I had left earlier, I wouldn't have missed the bus (mas saí tarde e perdi). Também com could have / might have para possibilidade.","example":"If she had known the answer, she would have said it. · We might have won if we had trained harder.","variants":{"simples":"Se eu tivesse feito, eu teria feito. Tudo no passado imaginário.","exemplo":"Depois do jogo: “If the referee had seen the foul, he would have given a penalty.”","passos":"1. If + had + particípio. 2. Vírgula. 3. Would have + particípio.","compara":"Em português: “Se eu tivesse estudado, teria passado.” A estrutura é parecida: had studied = tivesse estudado; would have passed = teria passado."},"id":"b1"},{"skill":"g_mixed","title":"Mixed conditionals","text":"Misturam tempos. Passado imaginário → resultado no presente: If + past perfect, would + verbo: If I had taken that job, I would be in London now. Presente imaginário → resultado no passado: If + past simple, would have + particípio: If I were more organized, I wouldn't have lost the file.","example":"If you had slept better, you wouldn't be so tired now. · If he spoke English, he would have understood the tour.","variants":{"simples":"Uma parte fala do passado, a outra do presente (ou vice-versa).","exemplo":"Reflexão: “If I had learned to swim as a child, I would be more confident at the beach today.”","passos":"1. Identifique o tempo de cada parte (quando é a condição? quando é o resultado?). 2. Passado imaginário = had + particípio; presente imaginário = past simple. 3. Resultado agora = would + verbo; resultado no passado = would have + particípio.","compara":"A palavra “now” ou “today” no resultado costuma indicar mixed conditional: …I would be rich NOW."},"id":"b2"},{"skill":"g_inv","title":"Formal inversion","text":"Em registro formal, podemos tirar o if e inverter: If I had known → Had I known; If I were → Were I; If you should need → Should you need. É comum em e-mails formais, contratos, discursos e textos acadêmicos.","example":"Had we received the documents, we would have replied. · Should you have any questions, please contact us.","variants":{"simples":"Had I known = Se eu soubesse (antes). Should you need = Caso você precise.","exemplo":"E-mail profissional: “Should you require further information, do not hesitate to contact me.”","passos":"1. Tire o if. 2. Coloque had/were/should antes do sujeito. 3. O resto da frase não muda.","compara":"A inversão não muda o sentido, só o registro: “If you need help” (neutro) × “Should you need help” (formal)."},"id":"b3"},{"skill":"g_wish","title":"Wish and if only","text":"Para arrependimentos sobre o passado: wish/if only + past perfect: I wish I had studied more (queria ter estudado mais). Para desejos sobre o presente: wish + past simple: I wish I had more time. Para irritação com algo que alguém faz: wish + would: I wish you would stop interrupting.","example":"If only I hadn't said that! · She wishes she lived by the sea.","variants":{"simples":"I wish I had… = Eu queria ter… (passado). I wish I had… (presente) = Eu queria ter agora.","exemplo":"Depois de uma prova: “I wish I had read the question more carefully.”","passos":"1. Arrependimento do passado → had + particípio. 2. Desejo no presente → passado simples. 3. If only é mais enfático.","compara":"Wish não é “desejar” no sentido de “I want”: “I want a car” (quero) × “I wish I had a car” (queria ter, mas não tenho)."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"g_third","prompt":"If I had studied more, I ___ the exam.","options":["would pass","would have passed","will pass","passed"],"answer":1,"hints":["Passado imaginário.","Third conditional.","Would have + particípio."],"explanation":"Would have passed.","id":"q1"},{"type":"mc","difficulty":1,"skill":"g_third","prompt":"If she ___ earlier, she wouldn't have missed the train.","options":["left","had left","would leave","has left"],"answer":1,"hints":["Condição no passado imaginário.","Past perfect.","Had left."],"explanation":"If she had left earlier…","id":"q2"},{"type":"fill","difficulty":1,"skill":"g_inv","prompt":"Inversão formal de “If I had known”: ___ I known, I would have helped.","answers":["Had"],"hints":["Tire o if.","Coloque o auxiliar antes do sujeito.","H-a-d."],"explanation":"Had I known…","id":"q3"},{"type":"tf","difficulty":1,"skill":"g_wish","prompt":"“I wish I had studied more” expressa arrependimento sobre o passado.","answer":true,"hints":["Had + particípio.","Refere-se ao passado.","Arrependimento."],"explanation":"Verdadeiro.","id":"q4"},{"type":"match","difficulty":2,"skill":"g_mixed","prompt":"Ligue cada frase ao tipo.","pairs":[["If I had taken the job, I would be in London now.","passado → presente"],["If I were more careful, I wouldn't have broken it.","presente → passado"],["If I had trained, I would have won.","third conditional"]],"hints":["“now” no resultado.","Condição permanente no presente.","Tudo no passado."],"explanation":"passado→presente · presente→passado · third.","id":"q5"},{"type":"mc","difficulty":2,"skill":"g_mixed","prompt":"If I had saved money last year, I ___ a car now.","options":["would have","would have had","will have","had"],"answer":0,"hints":["Resultado AGORA.","Mixed conditional.","Would + verbo."],"explanation":"Would have (a car) now.","id":"q6"},{"type":"mc","difficulty":2,"skill":"g_inv","prompt":"Qual é a forma formal de “If you need assistance, call us”?","options":["Should you need assistance, call us.","Need you assistance, call us.","Had you need assistance, call us.","Were you need assistance, call us."],"answer":0,"hints":["Condição possível no futuro.","Inversão com should.","Should you need…"],"explanation":"Should you need assistance…","id":"q7"},{"type":"mc","difficulty":2,"skill":"g_wish","prompt":"You are late again. I wish you ___ on time for once.","options":["would arrive","arrived yesterday","had arrive","will arrive"],"answer":0,"hints":["Irritação com o comportamento de alguém.","Wish + would.","Would arrive."],"explanation":"I wish you would arrive on time.","id":"q8"},{"type":"order","difficulty":3,"skill":"g_third","prompt":"Organize: “Se nós tivéssemos treinado mais, poderíamos ter ganhado.”","items":["If we","had trained","more,","we might","have won"],"hints":["If + had + particípio.","Vírgula depois da condição.","Might have + particípio."],"explanation":"If we had trained more, we might have won.","id":"q9"},{"type":"mc","difficulty":3,"skill":"g_mixed","prompt":"“Were he a more experienced driver, he wouldn't have had the accident.” O que a frase sugere?","options":["Ele é um motorista experiente","Ele não é muito experiente, e por isso aconteceu o acidente","O acidente não aconteceu","Ele vai dirigir amanhã"],"answer":1,"hints":["Were he = If he were (presente imaginário).","Resultado no passado.","Ele não é experiente."],"explanation":"Mixed com inversão: ele não é experiente → sofreu o acidente.","id":"q10"}],"review":["Third: if + had + particípio, would/could/might have + particípio","Mixed: passado→presente (had done, would be now) · presente→passado (were, would have done)","Inversão formal: Had I known · Were I · Should you need","Wish/if only + past perfect (arrependimento) · wish + would (irritação)"],"relatedQuestions":["como usar o third conditional","o que é mixed conditional","o que significa had I known"],"equivalentQuestions":["como dizer se eu tivesse estudado teria passado em inglês","o que significa would have","diferença entre second e third conditional","o que é inversão nas condicionais","o que significa should you need","como usar I wish I had","if only em inglês","o que é third conditional","como usar third conditional","me explica third conditional","quando usar third conditional","exemplos de third conditional","third conditional em inglês","como funciona third conditional","regras de third conditional","exercícios de third conditional","aula de third conditional","não entendi third conditional","third conditional para iniciantes","resumo de third conditional","dúvida sobre third conditional","o que é mixed conditional","como usar mixed conditional","me explica mixed conditional","quando usar mixed conditional","exemplos de mixed conditional","mixed conditional em inglês","como funciona mixed conditional","regras de mixed conditional","exercícios de mixed conditional","aula de mixed conditional","não entendi mixed conditional","mixed conditional para iniciantes","resumo de mixed conditional","dúvida sobre mixed conditional"],"commonErrors":["Usar would have nas duas partes (If I would have known…).","Confundir mixed com third conditional.","Esquecer o have depois de would (would passed)."],"english":{"cefr":"C1","unit":"c1-u1","order":1,"area":"grammar","focus":["grammar","writing","reading"],"vocabulary":[{"word":"regret","translation":"arrependimento / arrepender-se","pos":"noun","definition":"a feeling of being sorry about something you did","example":"My only regret is not studying abroad.","difficulty":2},{"word":"hindsight","translation":"visão em retrospectiva","pos":"noun","definition":"understanding a situation only after it has happened","example":"In hindsight, I should have left earlier.","difficulty":3},{"word":"otherwise","translation":"caso contrário","pos":"adverb","definition":"if not; in a different situation","example":"Leave now, otherwise you'll miss the bus.","difficulty":3},{"word":"assistance","translation":"assistência, ajuda","pos":"noun","definition":"help (formal)","example":"Should you need assistance, call us.","difficulty":3},{"word":"outcome","translation":"resultado","pos":"noun","definition":"the final result","example":"The outcome would have been different.","difficulty":3},{"word":"opportunity","translation":"oportunidade","pos":"noun","definition":"a chance to do something","example":"I missed a great opportunity.","difficulty":2}],"reading":{"title":"Looking back","genre":"crônica reflexiva","text":"Ten years ago I was offered a scholarship in Portugal, but I turned it down because I was afraid of living far from my family. Had I accepted it, I might be working in Europe now — or I might have missed the chance to open my own business here. People often ask me whether I regret it. The honest answer is complicated: I sometimes wish I had been braver, but if I had left, I wouldn't have met most of the people who matter to me today.","questions":[{"difficulty":2,"prompt":"Por que a autora recusou a bolsa?","options":["Porque era cara","Por medo de morar longe da família","Porque não gostava de Portugal","Porque abriu um negócio"],"answer":1,"explanation":"“because I was afraid of living far from my family”."},{"difficulty":3,"prompt":"“Had I accepted it” equivale a:","options":["If I accepted it","If I had accepted it","If I have accepted it","When I accept it"],"answer":1,"explanation":"Inversão formal do third/mixed conditional."},{"difficulty":3,"prompt":"Qual é a atitude da autora sobre a decisão?","options":["Arrependimento total","Sentimentos mistos","Indiferença","Orgulho sem dúvidas"],"answer":1,"explanation":"Ela diz que a resposta é “complicated”: às vezes queria ter sido mais corajosa, mas valoriza o que ganhou."},{"difficulty":3,"prompt":"O que “I wish I had been braver” expressa?","options":["Um plano para o futuro","Um arrependimento sobre o passado","Uma ordem","Uma certeza"],"answer":1,"explanation":"Wish + past perfect = arrependimento sobre o passado."}]},"writing":{"prompt":"Escreva um parágrafo reflexivo sobre uma escolha do passado e como ela afeta o seu presente, usando third conditional, mixed conditional e wish.","criteria":["Um third conditional","Um mixed conditional (passado → presente)","Uma frase com wish ou if only","Coesão entre as ideias"],"model":"Last year I decided to join the robotics club. If I hadn't joined it, I wouldn't have discovered my passion for programming, and I wouldn't be planning to study engineering now. Sometimes I wish I had started earlier, but in hindsight the timing was right.","keywords":["hadn't","wouldn't have","would","wish"],"minWords":50},"challenge":"Reescreva duas frases de um e-mail formal usando a inversão (Should you…, Had we…)."},"games":{"blanks":[{"difficulty":1,"sentence":"If it hadn't rained, we ___ to the beach.","options":["would have gone","would go","will go","had gone"],"answer":0,"explanation":"Third: would have + particípio."},{"difficulty":2,"sentence":"If I had eaten breakfast, I ___ hungry now.","options":["wouldn't be","wouldn't have been","won't be","hadn't been"],"answer":0,"explanation":"Mixed: resultado agora."},{"difficulty":2,"sentence":"___ I known about the party, I would have come.","options":["Had","Have","Did","Were"],"answer":0,"explanation":"Inversão: Had I known."},{"difficulty":3,"sentence":"I wish I ___ that message. It was a mistake.","options":["hadn't sent","didn't send","wouldn't send","haven't sent"],"answer":0,"explanation":"Arrependimento: wish + past perfect."},{"difficulty":3,"sentence":"___ you require further details, please let us know.","options":["Should","Would","Had","Were"],"answer":0,"explanation":"Inversão formal: Should you…"}],"sequences":[{"difficulty":2,"prompt":"Organize a frase · Put the words in order","items":["If","I","had","known","I","would","have","helped"],"words":true,"explanation":"Third conditional."},{"difficulty":3,"prompt":"Organize a frase · Put the words in order","items":["Had","we","left","earlier","we","would","be","there","now"],"words":true,"explanation":"Inversão + mixed conditional."}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"id":"ing-c1-reading-between-lines","subject":"ingles","title":"Reading between the lines","levels":["medio"],"grade":"Ensino Médio, ENEM e vestibulares","topic":"Inglês C1 — Ler e escrever como especialista","subtopic":"Inferência, tom, ironia e intenção do autor","aliases":["interpretacao de texto em ingles","inferencia em ingles","ironia em ingles","tom do texto","intencao do autor","reading between the lines","enem ingles interpretacao","implicit meaning"],"summary":"Descubra o que o texto diz sem dizer: inferências, tom, ironia, intenção do autor e a função social do texto.","intro":"“Oh, great. Another Monday.” Será que a pessoa está feliz? Vamos ler nas entrelinhas.","objective":"Fazer inferências com base em evidências do texto, identificar tom e ironia, reconhecer a intenção do autor e distinguir fato de opinião — como é cobrado no ENEM e em vestibulares.","prerequisites":["ing-b2-idioms"],"next":["ing-c1-academic-writing"],"skills":{"r_infer":"Inferência a partir de evidências","r_tone":"Tom e ironia","r_intent":"Intenção do autor e função social","r_fact":"Fato × opinião"},"blocks":[{"skill":"r_infer","title":"Inference: what the text suggests","text":"Inferir é tirar uma conclusão que o texto não diz diretamente, mas que as pistas sustentam. Exemplo: “She grabbed her umbrella and sighed as she looked out the window” → provavelmente está chovendo e ela não está animada. Toda inferência precisa de uma evidência no texto; se não há pista, não é inferência, é invenção.","example":"“The fridge was empty and the kids were complaining.” → Alguém precisa fazer compras.","variants":{"simples":"Inferir = entender algo que o texto dá a entender, usando as pistas.","exemplo":"Questão de prova: “It can be inferred from the text that…” — procure a frase que PROVA a resposta.","passos":"1. Leia a pergunta. 2. Encontre as pistas no texto. 3. Escolha a conclusão que as pistas sustentam — e descarte as que exigem imaginar demais.","compara":"Opções que parecem “verdade no mundo real”, mas não estão apoiadas no texto, são armadilhas clássicas de prova."},"id":"b1"},{"skill":"r_tone","title":"Tone and irony","text":"Tom é a atitude do autor: enthusiastic, critical, humorous, neutral, nostalgic, sarcastic… Ironia é dizer o contrário do que se quer dizer, geralmente para criticar ou fazer humor: “Oh, wonderful, the train is late again.” Pistas de ironia: contraste entre as palavras e a situação, exageros, aspas, pontuação e emojis.","example":"“Great job, team. We lost 5–0.” → irônico (crítica).","variants":{"simples":"Tom = o “jeito” do texto. Ironia = dizer o oposto do que se pensa.","exemplo":"Numa charge, um político diz “Education is our priority” ao lado de uma escola caindo: a ironia está no contraste.","passos":"1. Leia as palavras. 2. Compare com a situação descrita. 3. Se houver contradição proposital, provavelmente é ironia.","compara":"Em português a ironia funciona igual: “Que maravilha, choveu no dia do passeio!” O segredo é o contraste."},"id":"b2"},{"skill":"r_intent","title":"Author's purpose and social function","text":"Pergunte: para que o texto foi escrito? Informar (notícia), persuadir (propaganda, artigo de opinião), instruir (manual, receita), entreter (conto, charge), alertar (campanha). O gênero e o público ajudam a descobrir a intenção. O ENEM costuma perguntar a função social do texto ou o objetivo do autor.","example":"Uma campanha diz “Every drop counts. Turn off the tap while brushing your teeth.” → intenção: conscientizar sobre economia de água.","variants":{"simples":"Intenção = o objetivo do autor ao escrever.","exemplo":"Anúncio: “Only today! 50% off!” → persuadir a comprar agora.","passos":"1. Identifique o gênero (anúncio, notícia, poema…). 2. Pense no público. 3. Pergunte o que o autor quer que o leitor faça ou pense.","compara":"Um mesmo tema pode ter intenções diferentes: uma notícia sobre plástico informa; uma campanha sobre plástico quer mudar comportamento."},"id":"b3"},{"skill":"r_fact","title":"Fact or opinion?","text":"Fato pode ser comprovado (The bridge was built in 1974). Opinião expressa julgamento (It is the most beautiful bridge in the city). Pistas de opinião: adjetivos avaliativos (best, terrible, amazing), verbos como believe, think, seem, e modais como should. Textos argumentativos misturam os dois: o autor usa fatos para sustentar opiniões.","example":"Fact: “Over 60% of the students use the library.” Opinion: “The library should open on weekends.”","variants":{"simples":"Fato = dá para provar. Opinião = é o que alguém acha.","exemplo":"Crítica de filme: “The film lasts three hours (fato) and feels endless (opinião).”","passos":"1. Dá para verificar? → fato. 2. Tem julgamento ou sugestão? → opinião. 3. Veja como os fatos sustentam as opiniões.","compara":"Dados podem ser apresentados de forma tendenciosa: “Only 40% agreed” e “Almost half agreed” descrevem o mesmo fato com tons diferentes."},"id":"b4"}],"questions":[{"type":"mc","difficulty":1,"skill":"r_tone","prompt":"“Oh, perfect. My phone died right before the exam started.” O tom é:","options":["entusiasmado","irônico","neutro","científico"],"answer":1,"hints":["“Perfect” combina com a situação?","Há contraste.","Ironia."],"explanation":"O “perfect” diz o contrário: tom irônico.","id":"q1"},{"type":"mc","difficulty":1,"skill":"r_fact","prompt":"Qual frase é uma OPINIÃO?","options":["The museum opened in 1998.","The museum has 3 floors.","The museum is the most exciting place in town.","The museum closes at 6 pm."],"answer":2,"hints":["Qual não dá para provar?","Procure adjetivos avaliativos.","“most exciting”."],"explanation":"“The most exciting” é julgamento: opinião.","id":"q2"},{"type":"tf","difficulty":1,"skill":"r_infer","prompt":"Uma inferência pode ser feita sem nenhuma pista no texto.","answer":false,"hints":["Inferir é usar pistas.","Sem pista, é invenção.","Precisa de evidência."],"explanation":"Falso: toda inferência precisa de evidência no texto.","id":"q3"},{"type":"fill","difficulty":1,"skill":"r_intent","prompt":"Um anúncio que diz “Buy now, only today!” tem a intenção de ______ (convencer = p…).","answers":["persuade","persuadir","convencer"],"hints":["Qual é o objetivo da propaganda?","Fazer o leitor comprar.","Persuadir."],"explanation":"Intenção: persuadir (persuade).","id":"q4"},{"type":"match","difficulty":2,"skill":"r_intent","prompt":"Ligue o gênero à intenção mais comum.","pairs":[["news report","informar"],["advertisement","persuadir"],["recipe","instruir"],["short story","entreter"]],"hints":["Notícia relata fatos.","Propaganda vende.","Receita ensina a fazer."],"explanation":"informar · persuadir · instruir · entreter.","id":"q5"},{"type":"mc","difficulty":2,"skill":"r_infer","prompt":"“Mark checked his watch for the fifth time and tapped his foot on the floor.” Podemos inferir que Mark está:","options":["relaxado","impaciente","dormindo","triste pela família"],"answer":1,"hints":["O que ele faz repetidamente?","Olhar o relógio + bater o pé.","Impaciente."],"explanation":"As ações indicam impaciência.","id":"q6"},{"type":"mc","difficulty":2,"skill":"r_tone","prompt":"Qual pista mais ajuda a reconhecer ironia?","options":["Números exatos","Contraste entre as palavras e a situação","Frases curtas","Letras maiúsculas no título"],"answer":1,"hints":["Ironia = dizer o contrário.","Compare com o contexto.","Contraste."],"explanation":"O contraste entre o que se diz e a situação.","id":"q7"},{"type":"mc","difficulty":2,"skill":"r_fact","prompt":"“Although only 30% of residents recycle, the new program will certainly transform the city.” A segunda parte é:","options":["fato comprovado","opinião/previsão do autor","dado estatístico","citação"],"answer":1,"hints":["“Will certainly transform” pode ser provado hoje?","É uma previsão.","Opinião."],"explanation":"É uma previsão/opinião apresentada com certeza.","id":"q8"},{"type":"order","difficulty":3,"skill":"r_infer","prompt":"Coloque os passos de uma boa inferência na ordem.","items":["Ler a pergunta com atenção","Encontrar as pistas no texto","Formular a conclusão que as pistas sustentam","Descartar opções sem evidência"],"hints":["Primeiro entenda o que se pede.","Depois busque evidências.","Por fim, conclua e elimine."],"explanation":"Pergunta → pistas → conclusão → descartar opções sem evidência.","id":"q9"},{"type":"mc","difficulty":3,"skill":"r_intent","prompt":"Uma campanha mostra uma tartaruga presa num canudo com a frase “Is your drink worth it?”. A intenção é:","options":["vender canudos","informar a temperatura do mar","levar o leitor a repensar o uso de plástico","divulgar um restaurante"],"answer":2,"hints":["Imagem + pergunta retórica.","Qual comportamento ela quer mudar?","Uso de plástico."],"explanation":"Conscientizar: repensar o uso de canudos de plástico.","id":"q10"}],"review":["Inferência = conclusão sustentada por pistas do texto","Tom e ironia: compare as palavras com a situação","Intenção/função social: informar, persuadir, instruir, entreter, alertar","Fato (comprovável) × opinião (julgamento, previsão)"],"relatedQuestions":["como interpretar texto em inglês","como identificar ironia em inglês","como fazer inferência em texto"],"equivalentQuestions":["como identificar o tom de um texto em inglês","o que é intenção do autor","diferença entre fato e opinião em inglês","como saber se o texto é irônico","o que significa it can be inferred","dicas de interpretação de inglês no enem","o que é função social do texto","o que é interpretação de texto em inglês","como usar interpretação de texto em inglês","me explica interpretação de texto em inglês","quando usar interpretação de texto em inglês","exemplos de interpretação de texto em inglês","interpretação de texto em inglês em inglês","como funciona interpretação de texto em inglês","regras de interpretação de texto em inglês","exercícios de interpretação de texto em inglês","aula de interpretação de texto em inglês","não entendi interpretação de texto em inglês","interpretação de texto em inglês para iniciantes","resumo de interpretação de texto em inglês","dúvida sobre interpretação de texto em inglês","o que é inferência em inglês","como usar inferência em inglês","me explica inferência em inglês","quando usar inferência em inglês","exemplos de inferência em inglês","inferência em inglês em inglês","como funciona inferência em inglês","regras de inferência em inglês","exercícios de inferência em inglês","aula de inferência em inglês","não entendi inferência em inglês","inferência em inglês para iniciantes","resumo de inferência em inglês","dúvida sobre inferência em inglês"],"commonErrors":["Escolher a opção “verdadeira no mundo” mas sem apoio no texto.","Ler ironia ao pé da letra.","Confundir opinião apresentada com segurança com fato."],"enem":"Interpretação, intenção comunicativa, ironia e função social de textos verbais e não verbais.","english":{"cefr":"C1","unit":"c1-u2","order":1,"area":"reading","focus":["reading","vocabulary","writing"],"vocabulary":[{"word":"infer","translation":"inferir","pos":"verb","definition":"to reach a conclusion from evidence","example":"We can infer that he was nervous.","difficulty":3},{"word":"imply","translation":"sugerir, dar a entender","pos":"verb","definition":"to suggest something without saying it directly","example":"Her smile implied that she agreed.","difficulty":3},{"word":"tone","translation":"tom","pos":"noun","definition":"the attitude expressed in a text","example":"The tone of the article is critical.","difficulty":2},{"word":"irony","translation":"ironia","pos":"noun","definition":"saying the opposite of what you mean, often for humor or criticism","example":"The irony is that the fire station burned down.","difficulty":3},{"word":"bias","translation":"viés, parcialidade","pos":"noun","definition":"an unfair preference for one side","example":"The report shows a clear bias.","difficulty":3},{"word":"claim","translation":"afirmação / afirmar","pos":"noun","definition":"a statement that something is true","example":"The author's claim is not supported by data.","difficulty":3},{"word":"evidence","translation":"evidência, prova","pos":"noun","definition":"facts that show something is true","example":"There is no evidence for that.","difficulty":2},{"word":"purpose","translation":"propósito, objetivo","pos":"noun","definition":"the reason why something is done","example":"What is the purpose of this ad?","difficulty":2}],"reading":{"title":"The smart city that forgot its citizens","genre":"artigo de opinião adaptado","text":"The mayor proudly announced that our city is now “the smartest in the region”: traffic lights talk to phones, bins report when they are full, and an app answers questions 24 hours a day. Impressive — unless you are one of the thousands of elderly residents who do not own a smartphone. Last week, the only public service office was closed \"to encourage digital access\". Perhaps the next innovation will be a chatbot that explains to grandparents why they can no longer speak to a human being.","questions":[{"difficulty":2,"prompt":"Qual é a posição do autor sobre a “cidade inteligente”?","options":["Totalmente favorável","Crítica, porque a tecnologia exclui parte da população","Neutra","Indiferente"],"answer":1,"explanation":"O autor mostra as inovações e depois o problema dos idosos sem smartphone."},{"difficulty":3,"prompt":"O trecho “Perhaps the next innovation will be a chatbot that explains to grandparents…” tem tom:","options":["elogioso","irônico","científico","nostálgico"],"answer":1,"explanation":"O autor sugere algo absurdo para criticar: ironia."},{"difficulty":3,"prompt":"Por que “to encourage digital access” está entre aspas?","options":["Para citar a justificativa oficial e mostrar desconfiança dela","Porque é o título","Porque é um termo técnico","Porque é uma tradução"],"answer":0,"explanation":"As aspas marcam a fala oficial, que o autor questiona."},{"difficulty":3,"prompt":"Qual é a intenção principal do texto?","options":["Divulgar um aplicativo","Informar horários de ônibus","Criticar políticas que ignoram quem não tem acesso digital","Ensinar a usar smartphones"],"answer":2,"explanation":"É um artigo de opinião que critica a exclusão digital."}]},"writing":{"prompt":"Escolha um anúncio, meme ou charge e escreva um parágrafo analisando: gênero, público, intenção do autor, tom e as pistas que sustentam a sua interpretação.","criteria":["Identifica gênero e público","Explica a intenção com evidências","Comenta o tom (e a ironia, se houver)","Diferencia fato de opinião"],"model":"This advertisement targets teenagers and aims to persuade them to download a study app. The tone is enthusiastic, and the claim that \"everyone is using it\" is an opinion presented as a fact, since no evidence is given.","keywords":["tone","purpose","persuade","evidence","claim"],"minWords":45},"challenge":"Leia uma manchete em inglês e responda: qual é o tom? Que palavra mostra isso? Há fato ou opinião?","tips":["Em provas, sublinhe a frase do texto que justifica a sua resposta.","Desconfie de opções com “always”, “never” e “all”: raramente o texto sustenta generalizações."]},"games":{"blanks":[{"difficulty":2,"sentence":"A ___ can be proved; an opinion cannot.","options":["fact","claim","tone","bias"],"answer":0,"explanation":"Fato pode ser comprovado."},{"difficulty":2,"sentence":"The author's ___ is to persuade readers to recycle.","options":["purpose","irony","evidence","bias"],"answer":0,"explanation":"Purpose = objetivo."},{"difficulty":3,"sentence":"Saying “Nice weather!” during a storm is an example of ___.","options":["irony","evidence","inference","data"],"answer":0,"explanation":"Dizer o contrário: ironia."},{"difficulty":3,"sentence":"From his tired face, we can ___ that he didn't sleep well.","options":["infer","imply to","claim","prove that"],"answer":0,"explanation":"Tirar conclusão a partir de pistas: infer."}],"pairs":[{"a":"infer","b":"inferir","difficulty":2},{"a":"imply","b":"dar a entender","difficulty":3},{"a":"bias","b":"viés","difficulty":3},{"a":"claim","b":"afirmação","difficulty":3},{"a":"tone","b":"tom","difficulty":2}]},"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Língua Inglesa","url":"http://basenacionalcomum.mec.gov.br/","author":"Ministério da Educação (MEC)","kind":"curriculo","accessedAt":"2026-09-28"},{"title":"Common European Framework of Reference for Languages (CEFR) — descritores de nível","url":"https://www.coe.int/en/web/common-european-framework-reference-languages","author":"Council of Europe","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"LearnEnglish — Grammar reference","url":"https://learnenglish.britishcouncil.org/grammar","author":"British Council","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Cambridge Dictionary — definições e exemplos de uso","url":"https://dictionary.cambridge.org/","author":"Cambridge University Press","kind":"instituicao","accessedAt":"2026-09-28"},{"title":"Conteúdo autoral LUMI, revisado com base nas fontes listadas","author":"Equipe LUMI","kind":"autoral","accessedAt":"2026-09-28"},{"title":"Matriz de Referência do ENEM — Linguagens, Códigos e suas Tecnologias","url":"https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem","author":"INEP","kind":"instituicao","accessedAt":"2026-09-28"}],"createdAt":"2026-09-28","reviewedAt":"2026-09-28","origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Dinâmica","subtopic":"Leis de Newton","relatedQuestions":["O que é inércia?","O que diz a segunda lei de Newton?","O que é ação e reação?","Como calcular força?"],"id":"fis-leis-de-newton","subject":"fisica","title":"Leis de Newton","levels":["fund2","medio"],"grade":"9º ano e 1ª série","aliases":["leis de newton","inercia","principio fundamental da dinamica","f = m a","forca","acao e reacao","dinamica","newton"],"summary":"Entenda as três leis que explicam como as forças mudam o movimento dos corpos.","intro":"Por que você vai para a frente quando o ônibus freia? Isaac Newton explicou isso com três leis. Vamos a elas.","skills":{"inercia":"1ª lei — Inércia","fundamental":"2ª lei — F = m · a","acao_reacao":"3ª lei — Ação e reação","unidades":"Unidades de medida"},"blocks":[{"id":"b1","skill":"inercia","title":"1ª lei: Inércia","text":"Um corpo tende a manter seu estado: se está parado, continua parado; se está em movimento retilíneo e uniforme, continua assim — a não ser que uma força resultante atue sobre ele.","example":"Quando o ônibus freia de repente, seu corpo \"quer\" continuar em movimento e é jogado para a frente.","variants":{"simples":"As coisas são \"preguiçosas\" para mudar: o que está parado quer ficar parado, e o que está andando quer continuar andando.","exemplo":"Puxe rápido uma toalha de baixo de um copo: o copo tende a ficar no lugar. É a inércia.","outra":"Para mudar o movimento de algo — acelerar, frear ou fazer uma curva — é preciso uma força. Sem força resultante, nada muda.","detalhado":"Inércia é a tendência de um corpo resistir a mudanças na sua velocidade (vetorial). Força resultante nula implica velocidade constante: repouso ou MRU. Quanto maior a massa, maior a inércia."}},{"id":"b2","skill":"fundamental","title":"2ª lei: F = m · a","text":"A força resultante sobre um corpo é igual à sua massa vezes a aceleração: F = m · a. Com a mesma força, quem tem mais massa acelera menos.","example":"Empurrar um carrinho de supermercado vazio é fácil; cheio, a mesma força gera uma aceleração bem menor.","variants":{"simples":"Força = massa × aceleração. Mais força → mais aceleração. Mais massa → menos aceleração.","exemplo":"Uma força de 20 N empurra uma caixa de 4 kg: a = F ÷ m = 20 ÷ 4 = 5 m/s².","outra":"Pense na fórmula como uma balança: se a massa dobra e a força é a mesma, a aceleração cai pela metade.","detalhado":"A 2ª lei é vetorial: a aceleração tem a mesma direção e sentido da força resultante. Para calcular a aceleração a partir da variação de velocidade: a = Δv ÷ Δt. Ex.: um carro de 1000 kg vai de 0 a 20 m/s em 10 s → a = 2 m/s² → F = 2000 N."}},{"id":"b3","skill":"acao_reacao","title":"3ª lei: Ação e reação","text":"Toda ação tem uma reação de mesma intensidade, mesma direção e sentido oposto. As duas forças atuam em corpos diferentes, por isso não se anulam.","example":"Ao nadar, você empurra a água para trás, e a água empurra você para a frente.","variants":{"simples":"Se você empurra algo, esse algo empurra você de volta com a mesma força.","exemplo":"Um foguete empurra os gases para baixo; os gases empurram o foguete para cima.","outra":"Forças sempre vêm em pares. Se A empurra B, B empurra A. Uma força nunca aparece sozinha.","detalhado":"O par ação-reação atua em corpos diferentes; por isso não faz sentido \"somá-los\" para dizer que se anulam. Já forças que se equilibram (como peso e normal num livro sobre a mesa) atuam no mesmo corpo e não são par ação-reação."}},{"id":"b4","skill":"unidades","title":"Unidades de medida","text":"No Sistema Internacional: força em newton (N), massa em quilograma (kg) e aceleração em metros por segundo ao quadrado (m/s²). 1 N = 1 kg · m/s².","example":"Segurar uma maçã de 100 g exige, aproximadamente, uma força de 1 N.","variants":{"simples":"Força se mede em newton (N). Massa em kg. Aceleração em m/s².","exemplo":"Se a massa está em gramas, converta para kg antes: 500 g = 0,5 kg.","outra":"O \"newton\" é uma homenagem a Isaac Newton. 1 N é a força que acelera 1 kg a 1 m/s².","detalhado":"Não confunda massa (kg, quantidade de matéria) com peso (força, em N). Peso P = m · g, com g ≈ 10 m/s² na Terra: uma pessoa de 50 kg pesa cerca de 500 N."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"inercia","prompt":"Quando o ônibus freia, os passageiros são \"jogados\" para a frente. Isso é explicado pela:","options":["Inércia","Ação e reação","Gravidade","Eletricidade"],"answer":0,"hints":["O corpo \"quer\" continuar como estava.","É a 1ª lei.","Começa com \"I\"."],"explanation":"Pela inércia, o corpo tende a manter o movimento que tinha."},{"id":"q2","type":"mc","difficulty":1,"skill":"fundamental","prompt":"Qual é a fórmula da 2ª lei de Newton?","options":["F = m + a","F = m · a","F = m ÷ a","F = a − m"],"answer":1,"hints":["Relaciona força, massa e aceleração.","Envolve multiplicação.","Massa vezes aceleração."],"explanation":"F = m · a."},{"id":"q3","type":"tf","difficulty":1,"skill":"acao_reacao","prompt":"As forças de ação e reação atuam no mesmo corpo e, por isso, se anulam.","answer":false,"hints":["Pense no nadador e na água.","Uma força está no nadador, outra na água.","São corpos diferentes."],"explanation":"Falso. Ação e reação atuam em corpos diferentes e não se anulam."},{"id":"q4","type":"fill","difficulty":2,"skill":"fundamental","prompt":"Um corpo de 2 kg tem aceleração de 3 m/s². Qual é a força resultante, em newtons?","answers":["6","6 n"],"hints":["Use F = m · a.","m = 2, a = 3.","2 × 3."],"explanation":"F = 2 · 3 = 6 N."},{"id":"q5","type":"mc","difficulty":2,"skill":"fundamental","prompt":"Uma força de 20 N age sobre uma massa de 4 kg. Qual é a aceleração?","options":["80 m/s²","5 m/s²","16 m/s²","24 m/s²"],"answer":1,"hints":["Isole a aceleração: a = F ÷ m.","20 ÷ 4.","Quanto é 20 dividido por 4?"],"explanation":"a = 20 ÷ 4 = 5 m/s²."},{"id":"q6","type":"match","difficulty":2,"skill":"unidades","prompt":"Ligue cada item à descrição.","pairs":[["1ª lei","Inércia"],["2ª lei","F = m · a"],["3ª lei","Ação e reação"],["Newton (N)","Unidade de força"]],"hints":["A 1ª fala de \"preguiça\" para mudar.","A 2ª tem uma fórmula.","A 3ª fala de pares de forças."],"explanation":"1ª → inércia; 2ª → F = m·a; 3ª → ação e reação; N → unidade de força."},{"id":"q7","type":"mc","difficulty":2,"skill":"acao_reacao","prompt":"Ao nadar, a pessoa empurra a água para trás. O que acontece?","options":["A água fica parada","A água empurra a pessoa para a frente","A pessoa afunda","Nada, as forças se anulam"],"answer":1,"hints":["Toda ação tem uma reação.","A reação tem sentido oposto.","Oposto de \"para trás\"?"],"explanation":"Pela 3ª lei, a água empurra a pessoa para a frente."},{"id":"q8","type":"tf","difficulty":2,"skill":"inercia","prompt":"Um corpo em movimento retilíneo uniforme pode ter força resultante nula.","answer":true,"hints":["O que a 1ª lei diz sobre MRU?","Sem força, o movimento se mantém.","MRU = velocidade constante."],"explanation":"Verdadeiro. Com resultante nula, o corpo fica parado ou em MRU."},{"id":"q9","type":"mc","difficulty":3,"skill":"fundamental","prompt":"A mesma força age sobre dois blocos, de 2 kg e de 4 kg. O que se pode dizer das acelerações?","options":["São iguais","A do bloco de 2 kg é o dobro","A do bloco de 4 kg é o dobro","Nenhum acelera"],"answer":1,"hints":["a = F ÷ m.","Mesma força, massas diferentes.","Metade da massa → ?"],"explanation":"Com metade da massa, o bloco de 2 kg acelera o dobro."},{"id":"q10","type":"fill","difficulty":3,"skill":"unidades","prompt":"A unidade de força no Sistema Internacional é o ________.","answers":["newton","n"],"hints":["Homenageia um cientista.","O mesmo das três leis.","Símbolo: N."],"explanation":"O newton (N)."},{"id":"q11","type":"mc","difficulty":3,"skill":"fundamental","prompt":"Um carro de 1000 kg vai de 0 a 20 m/s em 10 s. Qual é a força resultante média?","options":["200 N","2000 N","20000 N","100 N"],"answer":1,"hints":["Calcule a aceleração primeiro.","a = Δv ÷ Δt = 20 ÷ 10.","F = 1000 × 2."],"explanation":"a = 2 m/s² → F = 1000 · 2 = 2000 N."},{"id":"q12","type":"open","difficulty":3,"skill":"inercia","prompt":"Use a 1ª lei de Newton para explicar por que devemos usar o cinto de segurança.","modelAnswer":"Pela inércia, numa freada brusca o corpo tende a continuar em movimento para a frente. O cinto aplica uma força que segura o corpo e impede que ele seja lançado contra o painel ou o para-brisa.","keywords":["inercia","movimento","continuar","frente","freada","forca"],"hints":["O que acontece com o corpo numa freada?","Ele tende a continuar…","Quem \"segura\" o corpo?"],"explanation":"O corpo tende a seguir em frente por inércia; o cinto aplica a força que o segura."}],"review":["1ª lei: inércia — sem força resultante, nada muda","2ª lei: F = m · a","3ª lei: ação e reação em corpos diferentes","Força em newton (N) · massa em kg · aceleração em m/s²"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências da Natureza e suas Tecnologias","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Cinemática","subtopic":"Velocidade média","relatedQuestions":["Como calcular velocidade média?","Como transformar km/h em m/s?","O que é movimento uniforme?"],"id":"fis-velocidade-media","subject":"fisica","title":"Velocidade média","levels":["fund2","medio"],"grade":"9º ano e 1ª série","aliases":["velocidade media","cinematica","movimento uniforme","mru","km/h para m/s","deslocamento e tempo","distancia tempo velocidade"],"summary":"Calcule a velocidade média e converta entre km/h e m/s.","intro":"Se uma viagem de 300 km leva 3 horas, qual foi a velocidade? Vamos descobrir.","skills":{"conceito":"Conceito de velocidade média","calculo":"Calcular v = Δs/Δt","unidades":"Conversão km/h ↔ m/s","mru":"Movimento uniforme"},"blocks":[{"id":"b1","skill":"conceito","title":"O que é velocidade média","text":"Velocidade média é quanto um corpo se desloca, em média, por unidade de tempo. Ela não diz se o carro parou ou acelerou no caminho — só o resultado geral.","example":"Mesmo parando num pedágio, se você percorreu 120 km em 2 h, sua velocidade média foi 60 km/h."},{"id":"b2","skill":"calculo","title":"A fórmula","text":"v = Δs ÷ Δt, em que Δs é o deslocamento (variação da posição) e Δt é o intervalo de tempo. Isolando: Δs = v · Δt e Δt = Δs ÷ v.","example":"300 km em 3 h → v = 300 ÷ 3 = 100 km/h."},{"id":"b3","skill":"unidades","title":"km/h e m/s","text":"No Sistema Internacional, velocidade é medida em m/s. Para passar de km/h para m/s, divida por 3,6; de m/s para km/h, multiplique por 3,6.","example":"72 km/h ÷ 3,6 = 20 m/s · 10 m/s × 3,6 = 36 km/h."},{"id":"b4","skill":"mru","title":"Movimento uniforme","text":"No movimento retilíneo uniforme (MRU), a velocidade é constante: o corpo percorre distâncias iguais em tempos iguais. A posição segue s = s₀ + v·t.","example":"Um carro a 20 m/s constantes, saindo do marco 100 m, estará em s = 100 + 20·5 = 200 m após 5 s."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"calculo","prompt":"Um carro percorre 300 km em 3 horas. Qual foi sua velocidade média?","options":["900 km/h","100 km/h","303 km/h","60 km/h"],"answer":1,"hints":["v = Δs ÷ Δt.","300 ÷ 3.","Resultado em km/h."],"explanation":"v = 300 ÷ 3 = 100 km/h."},{"id":"q2","type":"mc","difficulty":1,"skill":"calculo","prompt":"Qual é a fórmula da velocidade média?","options":["v = Δs × Δt","v = Δs ÷ Δt","v = Δt ÷ Δs","v = Δs + Δt"],"answer":1,"hints":["km/h = quilômetros POR hora.","\"Por\" indica divisão.","Distância dividida por tempo."],"explanation":"v = Δs ÷ Δt."},{"id":"q3","type":"tf","difficulty":1,"skill":"unidades","prompt":"Para converter km/h em m/s, dividimos por 3,6.","answer":true,"hints":["1 km = 1000 m; 1 h = 3600 s.","1000 ÷ 3600 = 1/3,6.","Divide."],"explanation":"Verdadeiro."},{"id":"q4","type":"fill","difficulty":2,"skill":"unidades","prompt":"Converta 72 km/h para m/s.","answers":["20","20 m/s"],"hints":["Divida por 3,6.","72 ÷ 3,6.","Dá um número redondo."],"explanation":"72 ÷ 3,6 = 20 m/s."},{"id":"q5","type":"fill","difficulty":2,"skill":"calculo","prompt":"Um ciclista anda a 15 km/h durante 2 horas. Quantos km ele percorre?","answers":["30","30 km"],"hints":["Δs = v × Δt.","15 × 2.","Resultado em km."],"explanation":"Δs = 15 × 2 = 30 km."},{"id":"q6","type":"match","difficulty":2,"skill":"unidades","prompt":"Ligue cada velocidade à equivalente.","pairs":[["36 km/h","10 m/s"],["72 km/h","20 m/s"],["108 km/h","30 m/s"],["18 km/h","5 m/s"]],"hints":["Divida cada valor por 3,6.","36 ÷ 3,6 = 10.","18 ÷ 3,6 = 5."],"explanation":"36→10 · 72→20 · 108→30 · 18→5."},{"id":"q7","type":"mc","difficulty":2,"skill":"conceito","prompt":"Numa viagem, um carro parou 30 minutos no posto. A velocidade média considera esse tempo parado?","options":["Não, só o tempo em movimento","Sim, conta o tempo total da viagem","Só se a parada for maior que 1 h","Depende do motorista"],"answer":1,"hints":["Δt é o intervalo total.","Do início ao fim.","Inclui as paradas."],"explanation":"Sim: Δt é o tempo total."},{"id":"q8","type":"mc","difficulty":3,"skill":"calculo","prompt":"Quanto tempo leva para percorrer 240 km a 80 km/h?","options":["2 h","3 h","4 h","320 h"],"answer":1,"hints":["Δt = Δs ÷ v.","240 ÷ 80.","Resultado em horas."],"explanation":"Δt = 240 ÷ 80 = 3 h."},{"id":"q9","type":"tf","difficulty":3,"skill":"mru","prompt":"No MRU, o corpo percorre distâncias iguais em intervalos de tempo iguais.","answer":true,"hints":["Uniforme = constante.","A velocidade não muda.","Mesma distância a cada segundo."],"explanation":"Verdadeiro."},{"id":"q10","type":"fill","difficulty":3,"skill":"mru","prompt":"Um corpo em MRU parte de s₀ = 100 m com v = 20 m/s. Qual sua posição, em metros, após 5 s?","answers":["200","200 m"],"hints":["s = s₀ + v·t.","100 + 20·5.","100 + 100."],"explanation":"s = 100 + 100 = 200 m."}],"review":["v = Δs ÷ Δt (tempo total)","Δs = v·Δt · Δt = Δs ÷ v","km/h ÷ 3,6 = m/s","MRU: velocidade constante, s = s₀ + v·t"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências da Natureza e suas Tecnologias","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Estrutura da matéria","subtopic":"Átomo e tabela periódica","relatedQuestions":["Do que o átomo é formado?","O que é número atômico?","Como a tabela periódica é organizada?"],"id":"qui-atomo-tabela","subject":"quimica","title":"Átomo e tabela periódica","levels":["fund2","medio"],"grade":"9º ano e 1ª série","aliases":["atomo","tabela periodica","protons","eletrons","neutrons","numero atomico","numero de massa","elementos quimicos","familias","periodos","gases nobres"],"summary":"Conheça as partes do átomo, número atômico, número de massa e como a tabela periódica é organizada.","intro":"Tudo o que existe é feito de átomos. E a tabela periódica é o \"mapa\" que organiza todos os tipos de átomo.","skills":{"estrutura":"Estrutura do átomo","numeros":"Número atômico e de massa","tabela":"Organização da tabela","classificacao":"Metais, ametais e gases nobres"},"blocks":[{"id":"b1","skill":"estrutura","title":"As partes do átomo","text":"O átomo tem um núcleo, com prótons (carga positiva) e nêutrons (sem carga), e uma região ao redor chamada eletrosfera, onde ficam os elétrons (carga negativa).","example":"Quase toda a massa do átomo está no núcleo, mesmo ele sendo muito pequeno em comparação ao átomo inteiro.","variants":{"simples":"No centro (núcleo): prótons (+) e nêutrons (sem carga). Em volta: elétrons (−).","exemplo":"Se o núcleo fosse do tamanho de uma formiga no meio de um estádio, o átomo inteiro seria o estádio — quase tudo é espaço vazio.","outra":"Um jeito de lembrar: Próton = Positivo. Nêutron = Neutro. Elétron = o que sobra, negativo.","detalhado":"Prótons e nêutrons têm massas parecidas; o elétron tem massa cerca de 1836 vezes menor que a do próton. Por isso a massa se concentra no núcleo. O modelo atual descreve os elétrons em orbitais, regiões de maior probabilidade de encontrá-los."}},{"id":"b2","skill":"numeros","title":"Número atômico (Z) e de massa (A)","text":"O número atômico (Z) é a quantidade de prótons e identifica o elemento. O número de massa (A) é a soma de prótons e nêutrons: A = Z + N. Num átomo neutro, o número de elétrons é igual ao de prótons.","example":"O sódio tem Z = 11 e, em geral, 12 nêutrons: A = 11 + 12 = 23.","variants":{"simples":"Z = número de prótons. A = prótons + nêutrons. Átomo neutro: elétrons = prótons.","exemplo":"O cloro tem A = 35 e Z = 17. Nêutrons: N = 35 − 17 = 18.","outra":"Z é como o \"RG\" do elemento: todo átomo com 6 prótons é carbono, sempre. Já A pode mudar, porque o número de nêutrons pode variar.","detalhado":"Átomos de um mesmo elemento com números de massa diferentes são isótopos (ex.: carbono-12 e carbono-14). Quando um átomo ganha ou perde elétrons, vira um íon: cátion (+, perdeu elétrons) ou ânion (−, ganhou elétrons)."}},{"id":"b3","skill":"tabela","title":"Como a tabela é organizada","text":"Os elementos estão em ordem crescente de número atômico. As linhas horizontais são os períodos (7 no total) e as colunas verticais são os grupos ou famílias (18 no total). Elementos da mesma família têm propriedades químicas parecidas.","example":"Lítio, sódio e potássio estão na mesma família (grupo 1) e reagem de forma parecida com a água.","variants":{"simples":"Linha deitada = período. Coluna em pé = família. Quem está na mesma coluna se parece.","exemplo":"Hélio, neônio e argônio estão na mesma coluna (grupo 18): todos são gases que quase não reagem.","outra":"Pense num prédio: cada andar é um período, e cada coluna de apartamentos \"empilhados\" é uma família com características em comum.","detalhado":"O período indica o número de camadas eletrônicas; nos elementos representativos, o grupo se relaciona com o número de elétrons na camada de valência — por isso a semelhança química dentro da família."}},{"id":"b4","skill":"classificacao","title":"Metais, ametais e gases nobres","text":"A maioria dos elementos é metal (bons condutores de calor e eletricidade, brilhantes). Os ametais ficam à direita da tabela. Os gases nobres (grupo 18), como hélio e neônio, são muito estáveis e quase não reagem.","example":"Ferro, cobre e alumínio são metais. Oxigênio e carbono são ametais. Hélio é gás nobre.","variants":{"simples":"Metais: brilham e conduzem eletricidade (ferro, cobre). Ametais: do lado direito (oxigênio). Gases nobres: última coluna, quase não reagem.","exemplo":"O fio de cobre conduz eletricidade porque o cobre é metal. O hélio enche balões e não pega fogo porque é gás nobre.","outra":"Olhe a tabela como um mapa: a maior parte do território (esquerda e centro) é dos metais; o cantinho da direita é dos ametais; a última coluna é dos gases nobres.","detalhado":"O hidrogênio fica no grupo 1, mas não é metal. Existem ainda os semimetais (ou metaloides), como silício e germânio, com propriedades intermediárias. A estabilidade dos gases nobres está ligada à camada de valência completa."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"estrutura","prompt":"Qual partícula do átomo tem carga negativa?","options":["Próton","Nêutron","Elétron","Núcleo"],"answer":2,"hints":["Próton = positivo.","Nêutron = neutro.","Sobrou qual?"],"explanation":"O elétron tem carga negativa."},{"id":"q2","type":"mc","difficulty":1,"skill":"numeros","prompt":"O número atômico (Z) indica a quantidade de:","options":["Nêutrons","Prótons","Elétrons + nêutrons","Camadas"],"answer":1,"hints":["É o \"RG\" do elemento.","Fica no núcleo e tem carga positiva.","Pró…"],"explanation":"Z é o número de prótons."},{"id":"q3","type":"tf","difficulty":1,"skill":"tabela","prompt":"As linhas horizontais da tabela periódica se chamam períodos.","answer":true,"hints":["Linha deitada ou coluna em pé?","Colunas são famílias.","Então as linhas são…"],"explanation":"Verdadeiro. São 7 períodos."},{"id":"q4","type":"fill","difficulty":2,"skill":"numeros","prompt":"Um átomo tem Z = 11 e 12 nêutrons. Qual é o número de massa (A)?","answers":["23"],"hints":["A = Z + N.","Z = 11, N = 12.","11 + 12."],"explanation":"A = 11 + 12 = 23 (é o sódio)."},{"id":"q5","type":"mc","difficulty":2,"skill":"tabela","prompt":"As colunas verticais da tabela periódica são chamadas de:","options":["Períodos","Grupos ou famílias","Camadas","Séries"],"answer":1,"hints":["As linhas são períodos.","Quem está na mesma coluna \"se parece\".","Como parentes."],"explanation":"Grupos ou famílias (são 18)."},{"id":"q6","type":"match","difficulty":2,"skill":"estrutura","prompt":"Ligue cada parte à sua característica.","pairs":[["Próton","Carga positiva, no núcleo"],["Nêutron","Sem carga, no núcleo"],["Elétron","Carga negativa, na eletrosfera"],["Núcleo","Concentra quase toda a massa"]],"hints":["Próton = Positivo.","Nêutron = Neutro.","Os elétrons ficam em volta."],"explanation":"Próton (+, núcleo), nêutron (0, núcleo), elétron (−, eletrosfera), núcleo (massa)."},{"id":"q7","type":"mc","difficulty":2,"skill":"classificacao","prompt":"Qual destes elementos é um gás nobre?","options":["Oxigênio","Sódio","Hélio","Ferro"],"answer":2,"hints":["Gases nobres quase não reagem.","Ficam na última coluna.","É usado para encher balões."],"explanation":"O hélio (He) é um gás nobre."},{"id":"q8","type":"tf","difficulty":2,"skill":"numeros","prompt":"Em um átomo neutro, o número de elétrons é igual ao número de prótons.","answer":true,"hints":["Neutro = cargas se equilibram.","Prótons são +, elétrons são −.","Quantidades iguais se anulam."],"explanation":"Verdadeiro. As cargas positivas e negativas se equilibram."},{"id":"q9","type":"fill","difficulty":3,"skill":"numeros","prompt":"Um átomo tem A = 35 e Z = 17. Quantos nêutrons ele tem?","answers":["18"],"hints":["A = Z + N.","Isole o N: N = A − Z.","35 − 17."],"explanation":"N = 35 − 17 = 18 (é o cloro-35)."},{"id":"q10","type":"mc","difficulty":3,"skill":"tabela","prompt":"Os elementos da tabela periódica atual estão organizados em ordem crescente de:","options":["Massa","Número atômico","Nêutrons","Descoberta"],"answer":1,"hints":["É o \"RG\" do elemento.","É o número de prótons.","É o Z."],"explanation":"Em ordem crescente de número atômico (Z)."},{"id":"q11","type":"mc","difficulty":3,"skill":"tabela","prompt":"Por que os elementos de uma mesma família têm propriedades químicas parecidas?","options":["Porque têm a mesma massa","Porque têm o mesmo número de elétrons na camada de valência","Porque foram descobertos juntos","Porque têm o mesmo número de nêutrons"],"answer":1,"hints":["Reações químicas envolvem elétrons.","Principalmente os da última camada.","Essa camada se chama valência."],"explanation":"Mesma família → mesmo número de elétrons de valência → comportamento químico parecido."},{"id":"q12","type":"tf","difficulty":3,"skill":"classificacao","prompt":"A maioria dos elementos da tabela periódica é metal.","answer":true,"hints":["Olhe para a esquerda e o centro da tabela.","Ferro, cobre, ouro, alumínio…","Os ametais ficam num canto."],"explanation":"Verdadeiro. Os metais são a grande maioria."}],"review":["Núcleo: prótons (+) e nêutrons (0) · Eletrosfera: elétrons (−)","Z = prótons · A = Z + N","Períodos = linhas (7) · Famílias = colunas (18)","Maioria metais · Gases nobres no grupo 18"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências da Natureza e suas Tecnologias","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Estrutura da matéria","subtopic":"Ligações químicas","relatedQuestions":["O que é ligação iônica?","O que é ligação covalente?","O que é a regra do octeto?","Por que os átomos se ligam?"],"id":"qui-ligacoes-quimicas","subject":"quimica","title":"Ligações químicas","levels":["medio"],"grade":"1ª série","aliases":["ligacoes quimicas","ligacao ionica","ligacao covalente","ligacao metalica","regra do octeto","ions","compartilhamento de eletrons"],"summary":"Entenda por que os átomos se ligam e diferencie as ligações iônica, covalente e metálica.","intro":"Por que o sal é sólido e a água é líquida? A resposta está no jeito como os átomos se ligam.","skills":{"octeto":"Regra do octeto","ionica":"Ligação iônica","covalente":"Ligação covalente","metalica":"Ligação metálica"},"blocks":[{"id":"b1","skill":"octeto","title":"Por que os átomos se ligam","text":"Os átomos tendem a ficar estáveis com 8 elétrons na camada de valência (ou 2, no caso do hidrogênio e do hélio), como os gases nobres. Para isso, eles ganham, perdem ou compartilham elétrons: é a regra do octeto.","example":"O sódio tem 1 elétron de valência e tende a perdê-lo; o cloro tem 7 e tende a ganhar 1."},{"id":"b2","skill":"ionica","title":"Ligação iônica","text":"Ocorre entre um metal e um ametal: o metal perde elétrons (vira cátion, +) e o ametal ganha (vira ânion, −). Os íons de cargas opostas se atraem. Compostos iônicos costumam ser sólidos e conduzir eletricidade quando dissolvidos em água.","example":"NaCl (sal de cozinha): Na perde 1 elétron → Na⁺; Cl ganha → Cl⁻."},{"id":"b3","skill":"covalente","title":"Ligação covalente","text":"Ocorre entre ametais (e hidrogênio), que compartilham pares de elétrons. Forma moléculas. Pode ser simples, dupla ou tripla, conforme o número de pares compartilhados.","example":"H₂O: o oxigênio compartilha um par de elétrons com cada hidrogênio. O₂ tem ligação dupla."},{"id":"b4","skill":"metalica","title":"Ligação metálica","text":"Ocorre entre átomos de metais. Os elétrons de valência ficam livres, formando um \"mar de elétrons\" ao redor dos cátions. Isso explica o brilho e a boa condução de calor e eletricidade dos metais.","example":"Fios de cobre conduzem eletricidade graças à ligação metálica."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"octeto","prompt":"Segundo a regra do octeto, os átomos tendem a ficar estáveis com quantos elétrons na camada de valência?","options":["2","4","8","18"],"answer":2,"hints":["\"Octeto\" lembra qual número?","Octógono tem 8 lados.","Oito."],"explanation":"8 elétrons (2 para H e He)."},{"id":"q2","type":"mc","difficulty":1,"skill":"ionica","prompt":"A ligação iônica ocorre geralmente entre:","options":["Dois metais","Metal e ametal","Dois gases nobres","Dois ametais"],"answer":1,"hints":["Um átomo perde e outro ganha elétrons.","Metais tendem a perder.","Ametais tendem a ganhar."],"explanation":"Entre metal e ametal."},{"id":"q3","type":"tf","difficulty":1,"skill":"covalente","prompt":"Na ligação covalente, os átomos compartilham elétrons.","answer":true,"hints":["Co-valente: valência em conjunto.","Ninguém perde nem ganha.","Dividem."],"explanation":"Verdadeiro."},{"id":"q4","type":"match","difficulty":2,"skill":"metalica","prompt":"Ligue cada substância ao tipo de ligação.","pairs":[["NaCl (sal)","Iônica"],["H₂O (água)","Covalente"],["Fio de cobre","Metálica"]],"hints":["Na é metal e Cl é ametal.","H e O são ametais.","Cobre é metal puro."],"explanation":"NaCl: iônica · H₂O: covalente · Cu: metálica."},{"id":"q5","type":"fill","difficulty":2,"skill":"ionica","prompt":"Um átomo que perde elétrons fica com carga positiva e é chamado de ________.","answers":["cation","cátion"],"hints":["Íon positivo.","O oposto de ânion.","Cát…"],"explanation":"Cátion."},{"id":"q6","type":"mc","difficulty":2,"skill":"octeto","prompt":"O sódio (Na) tem 1 elétron na camada de valência. Para ficar estável, ele tende a:","options":["Ganhar 7 elétrons","Perder 1 elétron","Compartilhar 4 elétrons","Não se ligar"],"answer":1,"hints":["O que é mais fácil: perder 1 ou ganhar 7?","Metais tendem a perder.","Perder 1."],"explanation":"Perde 1 elétron e vira Na⁺."},{"id":"q7","type":"mc","difficulty":2,"skill":"metalica","prompt":"O que explica a boa condução elétrica dos metais?","options":["Elétrons livres (\"mar de elétrons\")","Compartilhamento de pares fixos","Ausência de elétrons","Presença de ânions"],"answer":0,"hints":["Corrente elétrica é movimento de cargas.","Os elétrons precisam se mover.","Nos metais eles ficam livres."],"explanation":"O \"mar de elétrons\" livres."},{"id":"q8","type":"tf","difficulty":3,"skill":"ionica","prompt":"O sal de cozinha dissolvido em água conduz eletricidade.","answer":true,"hints":["Na água, os íons se separam.","Íons têm carga.","Cargas livres conduzem."],"explanation":"Verdadeiro: os íons livres conduzem."},{"id":"q9","type":"mc","difficulty":3,"skill":"covalente","prompt":"Na molécula de O₂, os dois oxigênios compartilham:","options":["1 par de elétrons (ligação simples)","2 pares de elétrons (ligação dupla)","3 pares de elétrons (ligação tripla)","Nenhum elétron"],"answer":1,"hints":["O oxigênio tem 6 elétrons de valência.","Faltam 2 para o octeto.","Cada um \"divide\" 2 elétrons."],"explanation":"Ligação dupla: 2 pares compartilhados."},{"id":"q10","type":"open","difficulty":3,"skill":"octeto","prompt":"Explique a diferença entre ligação iônica e covalente.","modelAnswer":"Na ligação iônica há transferência de elétrons: um átomo (geralmente metal) perde e outro (ametal) ganha, formando íons que se atraem. Na covalente, átomos de ametais compartilham pares de elétrons, formando moléculas.","keywords":["transferencia","perde","ganha","ions","compartilh","metal","ametal","molecula"],"hints":["Em uma, os elétrons mudam de dono.","Na outra, são divididos.","Fale de íons e de compartilhamento."],"explanation":"Iônica: transferência e íons · covalente: compartilhamento."}],"review":["Regra do octeto: 8 elétrons de valência","Iônica: metal + ametal, transferência, íons","Covalente: ametais, compartilhamento","Metálica: mar de elétrons, conduz"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências da Natureza e suas Tecnologias","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Toda Matéria — Ligações Químicas","url":"https://www.todamateria.com.br/ligacoes-quimicas/","kind":"site"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Citologia","subtopic":"Célula e organelas","relatedQuestions":["O que é célula?","Para que serve a mitocôndria?","Qual a diferença entre célula animal e vegetal?"],"id":"bio-celula","subject":"biologia","title":"Célula","levels":["fund2","medio"],"grade":"6º ano e 1ª série","aliases":["celula","celulas","organelas","mitocondria","citologia","celula animal","celula vegetal","procarionte","eucarionte"],"summary":"A célula é a unidade básica da vida. Conheça suas partes e organelas.","intro":"Todo ser vivo é formado por células — de uma bactéria a uma baleia. Vamos olhar lá dentro.","skills":{"conceito":"Célula como unidade da vida","tipos":"Procariontes e eucariontes","estruturas":"Membrana, citoplasma e núcleo","organelas":"Organelas e funções","animal_vegetal":"Célula animal × vegetal"},"blocks":[{"id":"b1","skill":"conceito","title":"A unidade da vida","text":"A célula é a menor unidade viva. Alguns seres têm uma só célula (unicelulares, como bactérias); outros têm trilhões (pluricelulares, como nós).","example":"O corpo humano tem cerca de 30 trilhões de células.","variants":{"simples":"Assim como uma casa é feita de tijolos, os seres vivos são feitos de células.","exemplo":"Uma bactéria é uma célula sozinha fazendo tudo. Você é um \"time\" enorme de células trabalhando juntas.","outra":"Se você dividir um ser vivo em partes cada vez menores, a menor parte que ainda está viva é a célula.","detalhado":"A teoria celular afirma que todos os seres vivos são formados por células, que a célula é a unidade estrutural e funcional da vida, e que toda célula surge de outra célula preexistente. Vírus não têm células."}},{"id":"b2","skill":"estruturas","title":"As três partes básicas","text":"Toda célula tem membrana plasmática (que envolve e controla o que entra e sai), citoplasma (o interior, onde ficam as organelas) e material genético (DNA). Nas células eucariontes, o DNA fica dentro do núcleo.","example":"A membrana funciona como o portão de um condomínio: decide quem entra e quem sai.","variants":{"simples":"Membrana = a \"pele\" da célula. Citoplasma = o recheio. Núcleo = o \"chefe\", que guarda as instruções.","exemplo":"Como um ovo: a casca lembra a membrana, a clara lembra o citoplasma e a gema lembra o núcleo. (É só uma comparação!)","outra":"Pense numa fábrica: os muros (membrana), o galpão com as máquinas (citoplasma) e a sala com os projetos (núcleo com o DNA).","detalhado":"A membrana plasmática é formada por uma bicamada de fosfolipídios com proteínas e tem permeabilidade seletiva. O núcleo é delimitado pela carioteca, e o citoplasma contém o citosol e as organelas."}},{"id":"b3","skill":"tipos","title":"Procariontes e eucariontes","text":"Células procariontes não têm núcleo organizado: o DNA fica solto no citoplasma. É o caso das bactérias. Células eucariontes têm núcleo delimitado por membrana e várias organelas. É o caso de animais, plantas e fungos.","example":"\"Pro\" lembra \"primeiro\": as procariontes são células mais simples.","variants":{"simples":"Procarionte: sem núcleo (bactérias). Eucarionte: com núcleo (animais, plantas, fungos).","exemplo":"A bactéria que estraga o leite é procarionte. As células da sua pele são eucariontes.","outra":"É como uma casa sem quartos (tudo junto num cômodo só) e uma casa com quartos separados. A eucarionte é a com quartos.","detalhado":"Procariontes têm ribossomos, mas não possuem organelas membranosas como mitocôndrias. O DNA fica numa região chamada nucleoide. Eucariontes surgiram depois e têm compartimentos internos especializados."}},{"id":"b4","skill":"organelas","title":"Organelas e suas funções","text":"Mitocôndria: libera energia (respiração celular). Ribossomo: produz proteínas. Cloroplasto: faz fotossíntese (só em plantas e algas). Núcleo: guarda o DNA e controla a célula.","example":"Células dos músculos têm muitas mitocôndrias porque precisam de muita energia.","variants":{"simples":"Mitocôndria = usina de energia. Ribossomo = fábrica de proteínas. Cloroplasto = painel solar da planta.","exemplo":"Quando você corre, as mitocôndrias dos músculos trabalham muito para liberar energia a partir da glicose.","outra":"Cada organela é como um setor de uma empresa: um produz (ribossomo), outro gera energia (mitocôndria), outro guarda os documentos (núcleo).","detalhado":"Na mitocôndria ocorre a respiração celular aeróbica, que produz ATP. Ribossomos podem estar livres ou no retículo endoplasmático rugoso. O complexo golgiense modifica e empacota substâncias, e os lisossomos fazem a digestão intracelular."}},{"id":"b5","skill":"animal_vegetal","title":"Célula animal × vegetal","text":"A célula vegetal tem parede celular (de celulose), cloroplastos e um grande vacúolo. A célula animal não tem essas estruturas. As duas têm membrana, citoplasma, núcleo e mitocôndrias.","example":"A parede celular é o que deixa o talo de uma planta mais firme.","variants":{"simples":"Planta tem três coisas a mais: parede, cloroplasto e um vacúolo grande. O resto é parecido.","exemplo":"Uma folha de alface é crocante por causa da parede celular e da água no vacúolo.","outra":"A célula vegetal é como a animal usando uma \"armadura\" (parede celular) e \"painéis solares\" (cloroplastos).","detalhado":"A parede celular fica por fora da membrana plasmática e dá sustentação. Células animais têm centríolos e lisossomos mais evidentes. As células vegetais também têm mitocôndrias, pois precisam liberar energia pela respiração."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"conceito","prompt":"Qual é a unidade básica da vida?","options":["O átomo","A célula","O órgão","O tecido"],"answer":1,"hints":["É a menor parte que ainda está viva.","Os seres vivos são feitos delas.","Como tijolos de uma casa."],"explanation":"A célula é a menor unidade viva."},{"id":"q2","type":"mc","difficulty":1,"skill":"organelas","prompt":"Qual organela libera energia para a célula?","options":["Ribossomo","Mitocôndria","Núcleo","Membrana"],"answer":1,"hints":["É chamada de \"usina de energia\".","Nela acontece a respiração celular.","Começa com M e não é membrana."],"explanation":"A mitocôndria realiza a respiração celular e libera energia."},{"id":"q3","type":"tf","difficulty":1,"skill":"tipos","prompt":"As bactérias são seres procariontes.","answer":true,"hints":["Bactérias têm núcleo organizado?","Não têm.","Sem núcleo = procarionte."],"explanation":"Verdadeiro. As bactérias não têm núcleo organizado."},{"id":"q4","type":"fill","difficulty":2,"skill":"estruturas","prompt":"A estrutura que envolve a célula e controla o que entra e sai é a membrana ________.","answers":["plasmatica","plasmática"],"hints":["É como o portão de um condomínio.","Toda célula tem uma.","Membrana plas…"],"explanation":"A membrana plasmática tem permeabilidade seletiva."},{"id":"q5","type":"mc","difficulty":2,"skill":"tipos","prompt":"O que diferencia uma célula procarionte de uma eucarionte?","options":["A procarionte não tem núcleo organizado","A procarionte não tem membrana","A eucarionte não tem DNA","A eucarionte não tem citoplasma"],"answer":0,"hints":["As duas têm membrana, citoplasma e DNA.","A diferença está em onde o DNA fica.","Na procarionte o DNA fica solto."],"explanation":"A procarionte não tem núcleo delimitado por membrana; o DNA fica no citoplasma."},{"id":"q6","type":"match","difficulty":2,"skill":"organelas","prompt":"Ligue cada organela à sua função.","pairs":[["Mitocôndria","Respiração celular"],["Ribossomo","Produção de proteínas"],["Cloroplasto","Fotossíntese"],["Núcleo","Guarda o DNA"]],"hints":["Mitocôndria = energia.","Cloroplasto tem clorofila.","O \"chefe\" guarda as instruções."],"explanation":"Mitocôndria → respiração; Ribossomo → proteínas; Cloroplasto → fotossíntese; Núcleo → DNA."},{"id":"q7","type":"mc","difficulty":2,"skill":"animal_vegetal","prompt":"Qual destas estruturas existe na célula vegetal, mas não na animal?","options":["Membrana plasmática","Parede celular","Ribossomo","Mitocôndria"],"answer":1,"hints":["A planta tem uma \"armadura\".","Ela é feita de celulose.","Fica por fora da membrana."],"explanation":"A parede celular de celulose é exclusiva da célula vegetal (entre as opções)."},{"id":"q8","type":"tf","difficulty":2,"skill":"animal_vegetal","prompt":"As células animais possuem cloroplastos.","answer":false,"hints":["Cloroplasto serve para quê?","Animais fazem fotossíntese?","Não fazem."],"explanation":"Falso. Cloroplastos existem em plantas e algas."},{"id":"q9","type":"fill","difficulty":3,"skill":"organelas","prompt":"A organela responsável pela produção de proteínas é o ________.","answers":["ribossomo","ribossomos"],"hints":["Está presente até nas bactérias.","É a \"fábrica de proteínas\".","Ribo…"],"explanation":"O ribossomo produz proteínas."},{"id":"q10","type":"tf","difficulty":3,"skill":"animal_vegetal","prompt":"As células vegetais também possuem mitocôndrias.","answer":true,"hints":["A planta precisa liberar energia?","Plantas também respiram.","A respiração celular ocorre na mitocôndria."],"explanation":"Verdadeiro. Plantas fazem fotossíntese e também respiração celular."},{"id":"q11","type":"mc","difficulty":3,"skill":"estruturas","prompt":"Nas células eucariontes, onde fica a maior parte do DNA?","options":["Na membrana","No núcleo","Na parede celular","No vacúolo"],"answer":1,"hints":["Eucarionte = núcleo verdadeiro.","O núcleo é o \"chefe\".","Ele guarda as instruções."],"explanation":"No núcleo, delimitado pela carioteca."},{"id":"q12","type":"open","difficulty":3,"skill":"organelas","prompt":"Por que as células dos músculos têm muitas mitocôndrias?","modelAnswer":"Porque os músculos precisam de muita energia para se movimentar, e as mitocôndrias são as organelas que liberam energia pela respiração celular.","keywords":["energia","respiracao","movimento","contracao","esforco"],"hints":["O que o músculo faz o tempo todo?","Movimento gasta o quê?","Quem libera isso na célula?"],"explanation":"Músculos gastam muita energia, e a mitocôndria é quem a libera."}],"review":["Célula = unidade da vida","Membrana, citoplasma e DNA (no núcleo nas eucariontes)","Procarionte (sem núcleo) × eucarionte (com núcleo)","Mitocôndria = energia · Ribossomo = proteínas · Cloroplasto = fotossíntese","Vegetal tem parede celular, cloroplasto e vacúolo grande"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências da Natureza","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Ecologia","subtopic":"Cadeias e teias alimentares","relatedQuestions":["O que é cadeia alimentar?","O que são produtores e consumidores?","Quem são os decompositores?","Quem come quem na natureza?"],"id":"bio-cadeias-alimentares","subject":"biologia","title":"Cadeias alimentares","levels":["fund1","fund2","medio"],"grade":"5º ao 7º ano","aliases":["cadeia alimentar","teia alimentar","ecologia","produtores consumidores decompositores","niveis troficos","quem come quem"],"summary":"Entenda como a energia passa dos produtores aos consumidores e o papel dos decompositores.","intro":"Na natureza, todo mundo depende de alguém para se alimentar. Vamos montar essa corrente!","skills":{"produtores":"Produtores","consumidores":"Consumidores","decompositores":"Decompositores","teias":"Teias alimentares e energia"},"blocks":[{"id":"b1","skill":"produtores","title":"Os produtores","text":"Produtores são seres que fabricam o próprio alimento, como as plantas e as algas, usando a luz na fotossíntese. Eles são sempre o começo da cadeia alimentar.","example":"O capim é produtor: faz o próprio alimento com a luz do Sol.","variants":{"simples":"As plantas fazem a própria comida. Por isso ficam no começo da corrente."}},{"id":"b2","skill":"consumidores","title":"Os consumidores","text":"Consumidores se alimentam de outros seres. Os primários comem produtores (herbívoros). Os secundários comem os primários, e assim por diante.","example":"Capim → gafanhoto (primário) → sapo (secundário) → cobra (terciário).","variants":{"simples":"Quem come planta é consumidor primário. Quem come esse bicho é o secundário."}},{"id":"b3","skill":"decompositores","title":"Os decompositores","text":"Fungos e bactérias decompõem restos de seres mortos, fezes e folhas caídas, devolvendo nutrientes ao solo. Eles atuam em todos os níveis da cadeia.","example":"Uma fruta esquecida fica mofada: são fungos decompondo.","variants":{"simples":"Fungos e bactérias \"reciclam\" o que morre e devolvem alimento para a terra."}},{"id":"b4","skill":"teias","title":"Teias e energia","text":"Na natureza as cadeias se cruzam formando teias alimentares, porque um animal come vários tipos de alimento. A cada nível, parte da energia é gasta, por isso há menos energia disponível no topo.","example":"O sapo come gafanhotos e moscas; e pode ser comido por cobras ou garças."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"produtores","prompt":"Qual destes é um produtor?","options":["Gafanhoto","Capim","Cobra","Fungo"],"answer":1,"hints":["Produtor faz o próprio alimento.","Usa a luz do Sol.","É uma planta."],"explanation":"O capim é uma planta, produtor."},{"id":"q2","type":"tf","difficulty":1,"skill":"produtores","prompt":"Toda cadeia alimentar começa com um produtor.","answer":true,"hints":["De onde vem a primeira energia?","Da luz captada pelas plantas.","Plantas são produtoras."],"explanation":"Verdadeiro."},{"id":"q3","type":"mc","difficulty":1,"skill":"decompositores","prompt":"Quem são os decompositores?","options":["Leões e onças","Fungos e bactérias","Plantas","Pássaros"],"answer":1,"hints":["Eles fazem o mofo.","São muito pequenos.","Reciclam restos de seres vivos."],"explanation":"Fungos e bactérias."},{"id":"q4","type":"fill","difficulty":2,"skill":"consumidores","prompt":"Na cadeia capim → gafanhoto → sapo, o gafanhoto é consumidor ________.","answers":["primario","primário"],"hints":["Ele come o produtor.","É o primeiro a consumir.","Primeiro = …"],"explanation":"Consumidor primário."},{"id":"q5","type":"match","difficulty":2,"skill":"consumidores","prompt":"Na cadeia capim → gafanhoto → sapo → cobra, ligue cada ser ao seu papel.","pairs":[["Capim","Produtor"],["Gafanhoto","Consumidor primário"],["Sapo","Consumidor secundário"],["Cobra","Consumidor terciário"]],"hints":["Comece pelo produtor.","Quem come o capim?","Depois conte os níveis."],"explanation":"Produtor → primário → secundário → terciário."},{"id":"q6","type":"tf","difficulty":2,"skill":"decompositores","prompt":"Os decompositores devolvem nutrientes ao solo.","answer":true,"hints":["O que acontece com uma folha caída?","Ela se decompõe.","Vira adubo."],"explanation":"Verdadeiro."},{"id":"q7","type":"mc","difficulty":2,"skill":"consumidores","prompt":"Um animal que se alimenta apenas de plantas é chamado de:","options":["Carnívoro","Herbívoro","Decompositor","Produtor"],"answer":1,"hints":["\"Herba\" lembra erva.","Come plantas.","Herbí…"],"explanation":"Herbívoro."},{"id":"q8","type":"mc","difficulty":3,"skill":"teias","prompt":"Por que há menos energia disponível no topo da cadeia alimentar?","options":["Porque os predadores comem pouco","Porque em cada nível parte da energia é gasta pelos seres","Porque o Sol não chega lá","Porque os decompositores roubam energia"],"answer":1,"hints":["Todo ser vivo gasta energia para viver.","Respirar, se mover…","Nem tudo passa adiante."],"explanation":"Cada nível usa parte da energia; só uma fração passa ao seguinte."},{"id":"q9","type":"tf","difficulty":3,"skill":"teias","prompt":"Uma teia alimentar é formada por várias cadeias alimentares interligadas.","answer":true,"hints":["Um animal come um só tipo de alimento?","Não, come vários.","As cadeias se cruzam."],"explanation":"Verdadeiro."},{"id":"q10","type":"open","difficulty":3,"skill":"teias","prompt":"O que poderia acontecer com uma cadeia alimentar se todos os sapos desaparecessem?","modelAnswer":"Os gafanhotos, que eram comidos pelos sapos, poderiam aumentar muito e comer mais capim. Já as cobras, que comiam sapos, teriam menos alimento e poderiam diminuir. O equilíbrio seria afetado.","keywords":["aumentar","diminuir","gafanhoto","cobra","equilibrio","alimento"],"hints":["Pense em quem os sapos comiam.","E em quem comia os sapos.","Um aumenta, outro diminui."],"explanation":"Presas aumentam, predadores diminuem: desequilíbrio."}],"review":["Produtores fazem o próprio alimento","Consumidores: primário, secundário, terciário","Decompositores reciclam nutrientes","Teias = cadeias interligadas; energia diminui a cada nível"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências da Natureza","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Genética","subtopic":"1ª Lei de Mendel","relatedQuestions":["O que é gene dominante e recessivo?","O que diz a primeira lei de Mendel?","Como fazer o quadro de Punnett?","O que é genótipo e fenótipo?"],"id":"bio-primeira-lei-mendel","subject":"biologia","title":"Genética: 1ª Lei de Mendel","levels":["medio"],"grade":"3ª série","aliases":["genetica","mendel","primeira lei de mendel","lei da segregacao","dominante e recessivo","heranca genetica","alelos","genotipo fenotipo","quadro de punnett"],"summary":"Genes, alelos dominantes e recessivos, genótipo, fenótipo e a proporção 3:1.","intro":"Por que você tem olhos parecidos com os do seu pai ou da sua mãe? Um monge e suas ervilhas ajudaram a explicar.","skills":{"conceitos":"Gene, alelo, genótipo e fenótipo","dominancia":"Dominante e recessivo","mendel":"Experimentos de Mendel","cruzamentos":"Cruzamentos e proporções"},"blocks":[{"id":"b1","skill":"conceitos","title":"Vocabulário básico","text":"Gene é um trecho de DNA que influencia uma característica. Alelos são versões de um gene. Recebemos um alelo da mãe e um do pai. Genótipo é o conjunto de alelos (ex.: Aa); fenótipo é a característica observada (ex.: semente amarela).","example":"Para a cor da semente de ervilha, A = amarelo e a = verde."},{"id":"b2","skill":"dominancia","title":"Dominante e recessivo","text":"O alelo dominante (letra maiúscula) se manifesta mesmo em dose única (AA ou Aa). O recessivo (minúscula) só aparece em dose dupla (aa). Quem tem alelos iguais é homozigoto; diferentes, heterozigoto.","example":"Aa tem semente amarela (A domina), mas carrega o alelo a."},{"id":"b3","skill":"mendel","title":"Mendel e as ervilhas","text":"Gregor Mendel cruzou ervilhas puras amarelas com verdes: todas as filhas (F1) nasceram amarelas. Cruzando as F1 entre si, na F2 surgiram amarelas e verdes na proporção de 3 para 1. Ele concluiu que cada característica depende de um par de fatores, que se separam na formação dos gametas: a Lei da Segregação.","example":"Em cada 4 plantas da F2, cerca de 3 eram amarelas e 1 verde."},{"id":"b4","skill":"cruzamentos","title":"O quadro de Punnett","text":"Para prever os descendentes, cruzamos os gametas num quadro. Aa × Aa dá AA, Aa, Aa, aa: genótipos 1:2:1 e fenótipos 3 dominantes : 1 recessivo (75% e 25%).","example":"Aa × aa dá 50% Aa (amarelas) e 50% aa (verdes)."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"mendel","prompt":"Com que planta Mendel fez seus experimentos?","options":["Feijão","Ervilha","Milho","Rosa"],"answer":1,"hints":["É uma leguminosa.","Tem sementes amarelas ou verdes.","Erv…"],"explanation":"Com ervilhas."},{"id":"q2","type":"tf","difficulty":1,"skill":"conceitos","prompt":"Recebemos um alelo de cada gene da mãe e outro do pai.","answer":true,"hints":["Os genes vêm em pares.","Um de cada genitor.","Metade de cada."],"explanation":"Verdadeiro."},{"id":"q3","type":"mc","difficulty":1,"skill":"dominancia","prompt":"Um alelo recessivo só se manifesta quando:","options":["Está em dose única","Está em dose dupla (aa)","Está junto do dominante","Nunca se manifesta"],"answer":1,"hints":["O dominante \"esconde\" o recessivo.","Então não pode haver dominante.","Os dois alelos precisam ser recessivos."],"explanation":"Só no homozigoto recessivo (aa)."},{"id":"q4","type":"match","difficulty":2,"skill":"conceitos","prompt":"Ligue cada termo ao significado.","pairs":[["Genótipo","Conjunto de alelos (ex.: Aa)"],["Fenótipo","Característica observável"],["Homozigoto","Alelos iguais (AA ou aa)"],["Heterozigoto","Alelos diferentes (Aa)"]],"hints":["\"Geno\" lembra gene.","\"Feno\" lembra o que aparece.","Homo = igual; hetero = diferente."],"explanation":"Genótipo: alelos · fenótipo: característica · homo: iguais · hetero: diferentes."},{"id":"q5","type":"fill","difficulty":2,"skill":"mendel","prompt":"Na geração F2 de Mendel, a proporção entre amarelas e verdes foi de ___ para 1.","answers":["3"],"hints":["Em cada 4 plantas…","…uma era verde.","As outras eram amarelas."],"explanation":"3 : 1."},{"id":"q6","type":"mc","difficulty":2,"skill":"cruzamentos","prompt":"No cruzamento Aa × Aa, qual a porcentagem esperada de descendentes aa?","options":["0%","25%","50%","75%"],"answer":1,"hints":["Monte o quadro: AA, Aa, Aa, aa.","Quantos aa em 4?","1 em 4."],"explanation":"1/4 = 25%."},{"id":"q7","type":"tf","difficulty":2,"skill":"dominancia","prompt":"Uma ervilha Aa tem sementes verdes.","answer":false,"hints":["A (amarelo) é dominante.","Em Aa, quem se manifesta?","O dominante."],"explanation":"Falso. Aa é amarela."},{"id":"q8","type":"mc","difficulty":3,"skill":"cruzamentos","prompt":"No cruzamento Aa × aa, qual a proporção de fenótipos?","options":["100% amarelas","75% amarelas e 25% verdes","50% amarelas e 50% verdes","100% verdes"],"answer":2,"hints":["Gametas: A e a × a e a.","Resultados: Aa, Aa, aa, aa.","Metade de cada."],"explanation":"50% Aa (amarelas) e 50% aa (verdes)."},{"id":"q9","type":"fill","difficulty":3,"skill":"mendel","prompt":"A 1ª Lei de Mendel também é chamada de Lei da ________.","answers":["segregacao","segregação","segregacao dos fatores"],"hints":["Os fatores se separam nos gametas.","Separar = segregar.","Segreg…"],"explanation":"Lei da Segregação."},{"id":"q10","type":"open","difficulty":3,"skill":"dominancia","prompt":"Explique como dois pais de sementes amarelas podem ter descendentes com sementes verdes.","modelAnswer":"Se os dois pais forem heterozigotos (Aa), cada um pode passar o alelo recessivo a. O descendente que receber a de cada um será aa e terá semente verde, o que acontece em cerca de 25% dos casos.","keywords":["heterozigot","aa","recessivo","25","alelo","cada"],"hints":["Qual o genótipo dos pais?","Eles \"escondem\" um alelo.","O filho recebe um de cada."],"explanation":"Pais Aa podem gerar filhos aa (25%)."}],"review":["Gene, alelo, genótipo (Aa) e fenótipo (característica)","Dominante aparece em AA/Aa; recessivo só em aa","Mendel: F1 toda dominante; F2 3:1","Aa × Aa → 1:2:1 (genótipos), 3:1 (fenótipos)"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências da Natureza e suas Tecnologias","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Toda Matéria — Primeira Lei de Mendel","url":"https://www.todamateria.com.br/primeira-lei-de-mendel/","kind":"site"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Escolas literárias","subtopic":"Modernismo brasileiro","relatedQuestions":["O que foi a Semana de Arte Moderna?","Quais são as fases do Modernismo?","Quem foi Mário de Andrade?"],"id":"lit-modernismo","subject":"literatura","title":"Modernismo brasileiro","levels":["medio"],"grade":"3ª série","aliases":["modernismo","semana de arte moderna","semana de 22","mario de andrade","oswald de andrade","antropofagia","geracao de 30","literatura modernista"],"summary":"A Semana de Arte Moderna de 1922, as fases do Modernismo e seus principais autores.","intro":"Em 1922, um grupo de artistas decidiu romper com as regras e criar uma arte \"com a cara do Brasil\".","skills":{"semana":"Semana de Arte Moderna","ideias":"Propostas modernistas","fases":"Fases do Modernismo","autores":"Autores e obras"},"blocks":[{"id":"b1","skill":"semana","title":"A Semana de 1922","text":"A Semana de Arte Moderna aconteceu no Theatro Municipal de São Paulo, de 13 a 17 de fevereiro de 1922, com exposições, conferências e concertos. Participaram Mário de Andrade, Oswald de Andrade, Anita Malfatti, Di Cavalcanti, Heitor Villa-Lobos, Menotti Del Picchia, entre outros.","example":"Coincidiu com o centenário da Independência, e muitos artistas queriam uma \"independência cultural\"."},{"id":"b2","skill":"ideias","title":"O que os modernistas queriam","text":"Romper com o academicismo e o Parnasianismo, usar verso livre, linguagem coloquial e humor, e valorizar a cultura e a identidade brasileiras de forma crítica.","example":"O \"Manifesto Antropófago\" (1928), de Oswald, propunha \"devorar\" a cultura estrangeira e transformá-la em algo brasileiro."},{"id":"b3","skill":"fases","title":"As fases","text":"1ª fase (1922–1930): heroica, de ruptura e experimentação. 2ª fase (1930–1945): Geração de 30, com o romance regionalista de denúncia social e poesia mais madura. 3ª fase (a partir de 1945): Geração de 45, com experimentação da linguagem, como em Guimarães Rosa e Clarice Lispector.","example":"\"Vidas Secas\" (1938), de Graciliano Ramos, retrata a seca no sertão nordestino."},{"id":"b4","skill":"autores","title":"Autores e obras","text":"Mário de Andrade (Macunaíma), Oswald de Andrade (Manifesto Antropófago), Manuel Bandeira, Carlos Drummond de Andrade, Cecília Meireles, Graciliano Ramos (Vidas Secas), Rachel de Queiroz (O Quinze), Jorge Amado, Guimarães Rosa (Grande Sertão: Veredas) e Clarice Lispector.","example":"Macunaíma é o \"herói sem nenhum caráter\", que mistura lendas e culturas brasileiras."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"semana","prompt":"Em que ano aconteceu a Semana de Arte Moderna?","options":["1822","1922","1930","1945"],"answer":1,"hints":["Foi no centenário da Independência.","A Independência foi em 1822.","100 anos depois."],"explanation":"Em 1922."},{"id":"q2","type":"mc","difficulty":1,"skill":"semana","prompt":"Onde foi realizada a Semana de Arte Moderna?","options":["Theatro Municipal do Rio de Janeiro","Theatro Municipal de São Paulo","Salvador","Brasília"],"answer":1,"hints":["Na maior cidade do país.","Num teatro.","Em São Paulo."],"explanation":"No Theatro Municipal de São Paulo."},{"id":"q3","type":"tf","difficulty":1,"skill":"ideias","prompt":"Os modernistas defendiam o uso do verso livre e da linguagem coloquial.","answer":true,"hints":["Eles queriam romper regras.","Rimas e métricas rígidas eram regra de quem?","Dos parnasianos."],"explanation":"Verdadeiro."},{"id":"q4","type":"match","difficulty":2,"skill":"autores","prompt":"Ligue cada obra ao autor.","pairs":[["Macunaíma","Mário de Andrade"],["Vidas Secas","Graciliano Ramos"],["O Quinze","Rachel de Queiroz"],["Grande Sertão: Veredas","Guimarães Rosa"]],"hints":["Macunaíma é de um dos organizadores da Semana.","O Quinze fala da seca de 1915.","Grande Sertão é da 3ª fase."],"explanation":"Mário · Graciliano · Rachel · Guimarães Rosa."},{"id":"q5","type":"fill","difficulty":2,"skill":"ideias","prompt":"O manifesto de Oswald de Andrade que propunha \"devorar\" a cultura estrangeira é o Manifesto ________.","answers":["antropofago","antropófago"],"hints":["Lembra canibalismo.","Antropo = homem; fago = comer.","Antropó…"],"explanation":"Manifesto Antropófago (1928)."},{"id":"q6","type":"mc","difficulty":2,"skill":"fases","prompt":"A 2ª fase do Modernismo (Geração de 30) se destacou pelo:","options":["Romance regionalista de denúncia social","Retorno às formas parnasianas","Fim da prosa","Teatro medieval"],"answer":0,"hints":["Pense em Vidas Secas.","Retrata problemas sociais.","Em regiões do Brasil."],"explanation":"Romance regionalista e crítica social."},{"id":"q7","type":"tf","difficulty":2,"skill":"fases","prompt":"Clarice Lispector é uma autora da primeira fase do Modernismo.","answer":false,"hints":["Ela estreou em 1943.","A 1ª fase vai até 1930.","É associada à Geração de 45."],"explanation":"Falso. É associada à 3ª fase."},{"id":"q8","type":"mc","difficulty":3,"skill":"ideias","prompt":"Qual escola literária os modernistas mais criticavam?","options":["Parnasianismo","Barroco","Arcadismo","Trovadorismo"],"answer":0,"hints":["Era a escola \"oficial\" no início do século XX.","Valorizava rima rica e métrica perfeita.","\"Arte pela arte\"."],"explanation":"O Parnasianismo."},{"id":"q9","type":"mc","difficulty":3,"skill":"semana","prompt":"Qual pintora teve uma exposição em 1917 considerada precursora do Modernismo e participou da Semana?","options":["Tarsila do Amaral","Anita Malfatti","Cecília Meireles","Pagu"],"answer":1,"hints":["Sua exposição foi criticada por Monteiro Lobato.","Participou da Semana de 22.","Anita…"],"explanation":"Anita Malfatti. (Tarsila não participou da Semana.)"},{"id":"q10","type":"open","difficulty":3,"skill":"ideias","prompt":"Por que a Semana de 1922 foi importante para a cultura brasileira?","modelAnswer":"Porque rompeu com os modelos acadêmicos e europeus, trouxe liberdade de forma, linguagem coloquial e a valorização crítica da identidade e da cultura brasileiras, abrindo caminho para o Modernismo.","keywords":["romp","identidade","brasileira","liberdade","academic","europ","cultura","verso livre"],"hints":["Com o que ela rompeu?","O que passou a ser valorizado?","Fale de identidade brasileira."],"explanation":"Ruptura com o academicismo e valorização da identidade nacional."}],"review":["Semana de 1922: Theatro Municipal de SP, 13 a 17/2","Ruptura: verso livre, coloquialismo, identidade","3 fases: heroica, Geração de 30, Geração de 45","Mário, Oswald, Drummond, Graciliano, Rachel, Rosa, Clarice"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Linguagens","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Agência Brasil — Centenário: conheça os artistas e o que queriam os modernistas de 1922","url":"https://agenciabrasil.ebc.com.br/geral/noticia/2022-02/centenario-conheca-os-artistas-e-o-que-queriam-os-modernistas-de-22","kind":"site"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Filosofia antiga","subtopic":"Período clássico","relatedQuestions":["Quem foi Sócrates?","O que é o mito da caverna?","O que Aristóteles pensava sobre a virtude?","O que é maiêutica?"],"id":"fil-socrates-platao-aristoteles","subject":"filosofia","title":"Sócrates, Platão e Aristóteles","levels":["medio"],"grade":"1ª série","aliases":["socrates","platao","aristoteles","filosofia grega","filosofia antiga","maieutica","mito da caverna","alegoria da caverna","so sei que nada sei"],"summary":"O método de Sócrates, a teoria das ideias de Platão e a ética de Aristóteles.","intro":"Três pensadores gregos, mestre e alunos, influenciam o jeito como pensamos até hoje.","skills":{"socrates":"Sócrates e a maiêutica","platao":"Platão e o mundo das ideias","aristoteles":"Aristóteles e a ética","relacao":"Relações entre os três"},"blocks":[{"id":"b1","skill":"socrates","title":"Sócrates: perguntar para pensar","text":"Sócrates (c. 470–399 a.C.) não deixou nada escrito. Ele conversava fazendo perguntas: primeiro mostrava que a pessoa não sabia tanto quanto pensava (ironia) e depois a ajudava a \"dar à luz\" as próprias ideias (maiêutica). É associado à frase \"só sei que nada sei\".","example":"Em vez de dizer o que é justiça, Sócrates perguntava: \"O que você entende por justo?\""},{"id":"b2","skill":"platao","title":"Platão: o mundo das ideias","text":"Platão (c. 428–348 a.C.), discípulo de Sócrates, dividiu a realidade em mundo sensível (das coisas que percebemos, que mudam) e mundo das ideias (verdadeiro e eterno). Na Alegoria da Caverna, prisioneiros veem só sombras e as tomam como realidade. Fundou a Academia.","example":"Existem muitos cavalos diferentes, mas todos lembram a ideia perfeita de \"cavalo\"."},{"id":"b3","skill":"aristoteles","title":"Aristóteles: observar e o meio-termo","text":"Aristóteles (384–322 a.C.), aluno de Platão, valorizava a observação do mundo real. Organizou a lógica e escreveu sobre ética, política e ciências. Para ele, a virtude é o meio-termo entre dois extremos, e o fim da vida humana é a felicidade (eudaimonia). Fundou o Liceu.","example":"A coragem é o meio-termo entre a covardia (falta) e a imprudência (excesso)."},{"id":"b4","skill":"relacao","title":"Mestre e alunos","text":"Sócrates foi mestre de Platão, que foi mestre de Aristóteles. Aristóteles, por sua vez, foi tutor de Alexandre, o Grande. Sócrates foi condenado à morte em Atenas, acusado de corromper a juventude e desrespeitar os deuses.","example":"Conhecemos as ideias de Sócrates principalmente pelos diálogos escritos por Platão."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"socrates","prompt":"A frase \"só sei que nada sei\" é associada a:","options":["Aristóteles","Sócrates","Platão","Tales"],"answer":1,"hints":["Ele fazia muitas perguntas.","Não deixou nada escrito.","Mestre de Platão."],"explanation":"Sócrates."},{"id":"q2","type":"mc","difficulty":1,"skill":"platao","prompt":"A Alegoria da Caverna foi escrita por:","options":["Sócrates","Platão","Aristóteles","Descartes"],"answer":1,"hints":["Fala do mundo das ideias.","Discípulo de Sócrates.","Fundou a Academia."],"explanation":"Platão, na obra A República."},{"id":"q3","type":"tf","difficulty":1,"skill":"relacao","prompt":"Aristóteles foi aluno de Platão.","answer":true,"hints":["Pense na sequência mestre → aluno.","Sócrates → Platão → …","Aristóteles."],"explanation":"Verdadeiro."},{"id":"q4","type":"fill","difficulty":2,"skill":"socrates","prompt":"O método socrático de ajudar o outro a \"dar à luz\" as ideias se chama ________.","answers":["maieutica","maiêutica"],"hints":["Vem da ideia de parto.","A mãe de Sócrates era parteira.","Maiêu…"],"explanation":"Maiêutica."},{"id":"q5","type":"match","difficulty":2,"skill":"relacao","prompt":"Ligue cada filósofo a uma ideia.","pairs":[["Sócrates","Maiêutica e ironia"],["Platão","Mundo das ideias"],["Aristóteles","Virtude como meio-termo"]],"hints":["O das perguntas.","O da caverna.","O da ética do equilíbrio."],"explanation":"Sócrates: maiêutica · Platão: ideias · Aristóteles: meio-termo."},{"id":"q6","type":"mc","difficulty":2,"skill":"aristoteles","prompt":"Para Aristóteles, a coragem é o meio-termo entre:","options":["Alegria e tristeza","Covardia e imprudência","Riqueza e pobreza","Razão e emoção"],"answer":1,"hints":["Um extremo é faltar coragem.","O outro é ter coragem demais.","Sem medo nenhum = imprudente."],"explanation":"Entre a covardia (falta) e a imprudência (excesso)."},{"id":"q7","type":"tf","difficulty":2,"skill":"socrates","prompt":"Sócrates escreveu vários livros com suas ideias.","answer":false,"hints":["Como conhecemos suas ideias?","Por meio de outra pessoa.","Pelos diálogos de Platão."],"explanation":"Falso. Sócrates não deixou nada escrito."},{"id":"q8","type":"mc","difficulty":3,"skill":"platao","prompt":"Na Alegoria da Caverna, as sombras vistas pelos prisioneiros representam:","options":["O mundo das ideias","As aparências do mundo sensível tomadas como verdade","A felicidade","A lógica"],"answer":1,"hints":["Os prisioneiros acham que as sombras são reais.","Mas são só aparências.","Mundo sensível."],"explanation":"As aparências do mundo sensível confundidas com a realidade."},{"id":"q9","type":"fill","difficulty":3,"skill":"aristoteles","prompt":"A escola fundada por Aristóteles em Atenas se chamava ________.","answers":["liceu"],"hints":["Platão fundou a Academia.","A de Aristóteles tem outro nome.","Lic…"],"explanation":"O Liceu."},{"id":"q10","type":"open","difficulty":3,"skill":"socrates","prompt":"Por que fazer perguntas, como Sócrates, pode ajudar alguém a aprender?","modelAnswer":"Porque as perguntas fazem a pessoa examinar o que pensa, perceber contradições e o que não sabe, e chegar por conta própria a ideias mais claras, em vez de só receber respostas prontas.","keywords":["pensar","refletir","contradic","propria","descobrir","nao sabe","examinar"],"hints":["O que acontece quando alguém te pergunta algo difícil?","Você precisa pensar.","E descobre sozinho."],"explanation":"Perguntar leva a pessoa a refletir e descobrir."}],"review":["Sócrates: ironia, maiêutica, \"só sei que nada sei\"","Platão: mundo das ideias × sensível; caverna; Academia","Aristóteles: observação, lógica, virtude como meio-termo; Liceu","Sócrates → Platão → Aristóteles"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências Humanas e Sociais Aplicadas","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Filosofia em Resumo — Sócrates, Platão e Aristóteles","url":"https://filosofiaemresumo.com.br/pt/sinteses/02_socrates-platao-aristoteles/","kind":"site"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Teoria sociológica","subtopic":"Clássicos da Sociologia","relatedQuestions":["O que é fato social?","O que é ação social para Weber?","O que é luta de classes?","O que é mais-valia?"],"id":"soc-classicos-sociologia","subject":"sociologia","title":"Clássicos da Sociologia: Durkheim, Weber e Marx","levels":["medio"],"grade":"1ª série","aliases":["sociologia","durkheim","weber","marx","fato social","acao social","luta de classes","classicos da sociologia"],"summary":"Fato social (Durkheim), ação social (Weber) e luta de classes (Marx).","intro":"Como a sociedade influencia o que fazemos? Três pensadores deram respostas diferentes.","skills":{"durkheim":"Durkheim e o fato social","weber":"Weber e a ação social","marx":"Marx e a luta de classes","comparacao":"Comparando os três"},"blocks":[{"id":"b1","skill":"durkheim","title":"Durkheim: o fato social","text":"Émile Durkheim definiu fato social como as formas de agir, pensar e sentir que existem fora do indivíduo e se impõem a ele. Tem três características: coercitividade (pressiona o indivíduo), exterioridade (já existia antes dele) e generalidade (atinge a todos).","example":"A língua que falamos já existia antes de nascermos e somos pressionados a usá-la corretamente."},{"id":"b2","skill":"weber","title":"Weber: a ação social","text":"Max Weber estudou a ação social: toda ação que o indivíduo orienta levando em conta o comportamento dos outros. Para entender a sociedade, é preciso compreender o sentido que as pessoas dão às suas ações.","example":"Cumprimentar alguém na rua é uma ação social: considera o outro e tem um sentido."},{"id":"b3","skill":"marx","title":"Marx: luta de classes","text":"Karl Marx analisou o capitalismo a partir das relações de produção. A burguesia é dona dos meios de produção; o proletariado vende sua força de trabalho. O conflito entre essas classes — a luta de classes — seria o motor das transformações históricas.","example":"Para Marx, o lucro vem em parte do trabalho não pago ao operário (mais-valia)."},{"id":"b4","skill":"comparacao","title":"Três olhares","text":"Durkheim enfatiza como a sociedade molda o indivíduo; Weber, o sentido das ações individuais; Marx, os conflitos econômicos entre classes. São perspectivas complementares para entender a vida social.","example":"Um mesmo tema, como o trabalho, pode ser estudado pelos três ângulos."}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"durkheim","prompt":"O conceito de \"fato social\" foi formulado por:","options":["Karl Marx","Émile Durkheim","Max Weber","Auguste Comte"],"answer":1,"hints":["Sociólogo francês.","Fala de coercitividade.","Émile…"],"explanation":"Émile Durkheim."},{"id":"q2","type":"match","difficulty":2,"skill":"comparacao","prompt":"Ligue cada pensador ao conceito central.","pairs":[["Durkheim","Fato social"],["Weber","Ação social"],["Marx","Luta de classes"]],"hints":["O francês: fato social.","O alemão da \"compreensão\": ação social.","O do Manifesto Comunista: classes."],"explanation":"Durkheim: fato social · Weber: ação social · Marx: luta de classes."},{"id":"q3","type":"tf","difficulty":1,"skill":"durkheim","prompt":"A generalidade é uma das características do fato social.","answer":true,"hints":["São três características.","Coercitividade, exterioridade e…","Atinge a todos."],"explanation":"Verdadeiro."},{"id":"q4","type":"mc","difficulty":2,"skill":"durkheim","prompt":"A língua que falamos já existia antes de nascermos. Isso ilustra qual característica do fato social?","options":["Exterioridade","Ação social","Mais-valia","Luta de classes"],"answer":0,"hints":["Existe fora e antes do indivíduo.","Não fomos nós que criamos.","Exter…"],"explanation":"Exterioridade."},{"id":"q5","type":"fill","difficulty":2,"skill":"marx","prompt":"Para Marx, a classe dona dos meios de produção é a ________.","answers":["burguesia"],"hints":["A outra é o proletariado.","Donos das fábricas.","Burgu…"],"explanation":"A burguesia."},{"id":"q6","type":"mc","difficulty":2,"skill":"weber","prompt":"Para Weber, uma ação é social quando:","options":["É obrigatória por lei","É orientada levando em conta o comportamento de outras pessoas","É feita por muitas pessoas ao mesmo tempo","Envolve dinheiro"],"answer":1,"hints":["Considera os outros.","Tem um sentido.","Não basta ser coletiva."],"explanation":"Quando é orientada pela ação de outros."},{"id":"q7","type":"tf","difficulty":2,"skill":"marx","prompt":"Para Marx, a luta de classes é o motor das transformações históricas.","answer":true,"hints":["Conflito entre burguesia e proletariado.","Isso mudaria a história.","É a tese central."],"explanation":"Verdadeiro."},{"id":"q8","type":"mc","difficulty":3,"skill":"durkheim","prompt":"A coercitividade do fato social significa que ele:","options":["Só existe em pequenos grupos","Exerce pressão sobre o indivíduo para que se comporte de certa forma","Depende da vontade de cada um","Não muda nunca"],"answer":1,"hints":["Coerção = pressão.","O indivíduo sente essa força.","Ex.: regras de conduta."],"explanation":"Exerce pressão sobre o indivíduo."},{"id":"q9","type":"fill","difficulty":3,"skill":"marx","prompt":"O valor produzido pelo trabalhador e não pago a ele, segundo Marx, é a ________.","answers":["mais-valia","mais valia","maisvalia"],"hints":["Explica o lucro.","Mais-…","…valia."],"explanation":"Mais-valia."},{"id":"q10","type":"open","difficulty":3,"skill":"comparacao","prompt":"Dê um exemplo de fato social do seu dia a dia e explique por quê.","modelAnswer":"O uso de uniforme na escola é um fato social: a regra já existia antes de o aluno chegar (exterioridade), vale para todos (generalidade) e quem não usa sofre alguma sanção (coercitividade).","keywords":["exterior","geral","coerc","todos","regra","antes","pressao","sancao"],"hints":["Pense numa regra ou costume.","Ele já existia antes de você?","Vale para todos? Há pressão?"],"explanation":"Um bom exemplo mostra exterioridade, generalidade e coercitividade."}],"review":["Durkheim: fato social (coercitivo, exterior, geral)","Weber: ação social e seu sentido","Marx: burguesia × proletariado, mais-valia","Olhares complementares sobre a sociedade"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Ciências Humanas e Sociais Aplicadas","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Toda Matéria — O que é Fato Social?","url":"https://www.todamateria.com.br/o-que-e-fato-social/","kind":"site"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
select public.admin_save_lesson($lumi${"topic":"Artes visuais","subtopic":"Teoria das cores","relatedQuestions":["Quais são as cores primárias?","Que cor dá azul com amarelo?","O que são cores quentes e frias?","O que são cores complementares?"],"id":"art-cores","subject":"artes","title":"Cores primárias, secundárias e complementares","levels":["fund1","fund2"],"grade":"2º ao 6º ano","aliases":["cores primarias","cores secundarias","circulo cromatico","cores quentes e frias","cores complementares","misturar cores","teoria das cores"],"summary":"Descubra como as cores se misturam, o círculo cromático e as cores quentes e frias.","intro":"Com só três cores de tinta dá para fazer muitas outras. Vamos misturar!","skills":{"primarias":"Cores primárias","secundarias":"Cores secundárias","quentes_frias":"Cores quentes e frias","complementares":"Cores complementares"},"blocks":[{"id":"b1","skill":"primarias","title":"As cores primárias","text":"Nas tintas escolares, as cores primárias são vermelho, amarelo e azul. Elas não podem ser obtidas misturando outras cores de tinta — e a partir delas fazemos muitas outras.","example":"Com uma caixinha de vermelho, amarelo e azul já dá para pintar um arco-íris inteiro.","variants":{"simples":"Vermelho, amarelo e azul são as cores \"mães\": misturando elas, nascem as outras."}},{"id":"b2","skill":"secundarias","title":"As cores secundárias","text":"Misturando duas primárias em partes iguais, obtemos as secundárias: vermelho + amarelo = laranja; amarelo + azul = verde; azul + vermelho = roxo (violeta).","example":"Para pintar uma folha de árvore, misture amarelo com azul.","variants":{"simples":"Vermelho + amarelo = laranja. Amarelo + azul = verde. Azul + vermelho = roxo."}},{"id":"b3","skill":"quentes_frias","title":"Quentes e frias","text":"Cores quentes (vermelho, laranja, amarelo) lembram fogo e sol e passam sensação de calor e energia. Cores frias (azul, verde, roxo) lembram água e gelo e passam calma.","example":"Um pôr do sol é pintado com cores quentes; o fundo do mar, com cores frias.","variants":{"simples":"Quentes lembram o sol: vermelho, laranja, amarelo. Frias lembram a água: azul, verde, roxo."}},{"id":"b4","skill":"complementares","title":"Cores complementares","text":"No círculo cromático, as cores que ficam uma de frente para a outra são complementares: vermelho e verde, azul e laranja, amarelo e roxo. Juntas, uma destaca a outra.","example":"Muitos logotipos usam azul com laranja para chamar atenção.","variants":{"simples":"Algumas cores são \"opostas\" e combinam para chamar atenção: azul e laranja, vermelho e verde, amarelo e roxo."}}],"questions":[{"id":"q1","type":"mc","difficulty":1,"skill":"primarias","prompt":"Quais são as cores primárias das tintas escolares?","options":["Verde, laranja e roxo","Vermelho, amarelo e azul","Preto, branco e cinza","Rosa, azul e verde"],"answer":1,"hints":["São as cores \"mães\".","Não dá para fazê-las misturando outras.","Uma delas é o amarelo."],"explanation":"Vermelho, amarelo e azul."},{"id":"q2","type":"mc","difficulty":1,"skill":"secundarias","prompt":"Amarelo + azul dá:","options":["Laranja","Roxo","Verde","Marrom"],"answer":2,"hints":["É a cor das folhas.","Também é cor da grama.","Começa com V."],"explanation":"Amarelo + azul = verde."},{"id":"q3","type":"tf","difficulty":1,"skill":"quentes_frias","prompt":"O vermelho é uma cor quente.","answer":true,"hints":["Lembra fogo ou água?","Lembra fogo.","Fogo → quente."],"explanation":"Verdadeiro."},{"id":"q4","type":"fill","difficulty":1,"skill":"secundarias","prompt":"Vermelho + amarelo dá a cor ________.","answers":["laranja"],"hints":["É a cor de uma fruta.","Também é o nome da fruta.","Laran…"],"explanation":"Laranja."},{"id":"q5","type":"match","difficulty":2,"skill":"secundarias","prompt":"Ligue cada mistura à cor que ela forma.","pairs":[["Vermelho + amarelo","Laranja"],["Amarelo + azul","Verde"],["Azul + vermelho","Roxo"]],"hints":["Pense no sol se pondo: vermelho e amarelo.","Folhas: amarelo e azul.","Uva: azul e vermelho."],"explanation":"Laranja, verde e roxo."},{"id":"q6","type":"mc","difficulty":2,"skill":"quentes_frias","prompt":"Qual destas é uma cor fria?","options":["Laranja","Amarelo","Azul","Vermelho"],"answer":2,"hints":["Cores frias lembram água.","Qual é a cor do mar?","Azul."],"explanation":"Azul é fria."},{"id":"q7","type":"tf","difficulty":2,"skill":"primarias","prompt":"Dá para fazer tinta amarela misturando outras duas cores de tinta.","answer":false,"hints":["O amarelo é primário ou secundário?","Primário.","Primárias não são feitas por mistura."],"explanation":"Falso. O amarelo é primário."},{"id":"q8","type":"mc","difficulty":3,"skill":"complementares","prompt":"Qual é a cor complementar do azul?","options":["Verde","Roxo","Laranja","Amarelo"],"answer":2,"hints":["É a cor oposta no círculo.","Ela é quente.","É secundária, feita com vermelho e amarelo."],"explanation":"Azul e laranja são complementares."},{"id":"q9","type":"mc","difficulty":3,"skill":"quentes_frias","prompt":"Para pintar um quadro que passe calma e tranquilidade, o mais indicado é usar:","options":["Cores quentes","Cores frias","Só preto","Só vermelho"],"answer":1,"hints":["Pense no mar e no céu.","Essas cores acalmam.","São as frias."],"explanation":"Cores frias passam calma."},{"id":"q10","type":"tf","difficulty":3,"skill":"complementares","prompt":"Vermelho e verde são cores complementares.","answer":true,"hints":["Verde é feito com amarelo e azul.","Falta qual primária?","A que falta é a complementar."],"explanation":"Verdadeiro."}],"review":["Primárias: vermelho, amarelo, azul","Secundárias: laranja, verde, roxo","Quentes (sol) × frias (água)","Complementares ficam opostas no círculo"],"sources":[{"title":"Base Nacional Comum Curricular (BNCC) — Arte","url":"http://basenacionalcomum.mec.gov.br/","kind":"curriculo"},{"title":"Conteúdo autoral LUMI","kind":"autoral"}],"origin":"base"}$lumi$::jsonb, 'published');
